def log(msg=""):
    print(f"[XDZR8 Sabershader] {msg}")

def _xdzr8_build_progress_redraw(context, force=False):
    """Request lightweight UI redraws so progress is visible during synchronous builds."""
    try:
        wm = context.window_manager
        for window in getattr(wm, 'windows', []):
            screen = getattr(window, 'screen', None)
            if screen is None:
                continue
            for area in getattr(screen, 'areas', []):
                if getattr(area, 'type', '') == 'VIEW_3D':
                    area.tag_redraw()
    except Exception:
        pass
    if force and not getattr(bpy.app, 'background', False):
        try:
            if getattr(context, 'window', None) is not None:
                bpy.ops.wm.redraw_timer(type='DRAW_WIN_SWAP', iterations=1)
        except Exception:
            pass

def _xdzr8_build_progress_update(context, percent, stage, force_redraw=False):
    """Publish one progress checkpoint to Blender UI, status bar and scene telemetry."""
    pct = max(0.0, min(100.0, float(percent)))
    stage = str(stage or 'Working')
    try:
        context.scene['XDZR8_BuildRunning'] = True
        context.scene['XDZR8_BuildProgress'] = pct
        context.scene['XDZR8_BuildStage'] = stage
    except Exception:
        pass
    try:
        context.window_manager.progress_update(pct)
    except Exception:
        pass
    try:
        if getattr(context, 'workspace', None) is not None:
            context.workspace.status_text_set(f'XDZR8 Build Shaders • {pct:.0f}% • {stage}')
    except Exception:
        pass
    log(f'Build progress: {pct:.0f}% • {stage}')
    _xdzr8_build_progress_redraw(context, force=bool(force_redraw))

def _xdzr8_build_progress_begin(context):
    try:
        context.window_manager.progress_begin(0.0, 100.0)
    except Exception:
        pass
    try:
        context.scene['XDZR8_BuildRunning'] = True
        context.scene['XDZR8_BuildProgress'] = 0.0
        context.scene['XDZR8_BuildStage'] = 'Starting'
        context.scene['XDZR8_BuildLastResult'] = 'RUNNING'
    except Exception:
        pass
    _xdzr8_build_progress_update(context, 0.0, 'Starting', force_redraw=True)

def _xdzr8_build_progress_finish(context, success=True, stage=None):
    final_stage = str(stage or ('Complete' if success else 'Stopped'))
    try:
        if success:
            context.scene['XDZR8_BuildProgress'] = 100.0
        context.scene['XDZR8_BuildStage'] = final_stage
        context.scene['XDZR8_BuildRunning'] = False
        context.scene['XDZR8_BuildLastResult'] = 'FINISHED' if success else 'CANCELLED'
    except Exception:
        pass
    try:
        if success:
            context.window_manager.progress_update(100.0)
        context.window_manager.progress_end()
    except Exception:
        pass
    try:
        if getattr(context, 'workspace', None) is not None:
            context.workspace.status_text_set(None)
    except Exception:
        pass
    log(f'Build progress: {100 if success else float(context.scene.get("XDZR8_BuildProgress", 0.0)):.0f}% • {final_stage}')
    _xdzr8_build_progress_redraw(context, force=True)

def norm(value):
    return re.sub(r"[\s_.]+", "", str(value).lower())

def safe_name(value):
    return re.sub(r"[^\w\u0080-\uffff.-]+", "_", str(value))

def find_material(name):
    exact = bpy.data.materials.get(name)
    if exact:
        return exact

    backup = bpy.data.materials.get(f"SaberShader_BACKUP_{name}")
    if backup:
        return backup

    target = norm(name)
    for mat in bpy.data.materials:
        if norm(mat.name) == target:
            return mat

    return None

def users_of(mat):
    if not mat:
        return []
    out = []
    for obj in bpy.context.scene.objects:
        if obj.type != "MESH":
            continue
        if any(slot.material == mat for slot in obj.material_slots):
            out.append(obj)
    return out

def image_nodes(mat):
    if not mat or not mat.use_nodes or not mat.node_tree:
        return []
    return [n for n in mat.node_tree.nodes if n.bl_idname == "ShaderNodeTexImage"]


def _sabershader_image_storage_status(image):
    """Return how Blender can currently supply pixels for an image datablock."""
    if image is None:
        return "UNAVAILABLE"

    try:
        if getattr(image, "source", "") == 'GENERATED':
            return "GENERATED"
    except Exception:
        pass

    try:
        if getattr(image, "packed_file", None) is not None:
            return "PACKED"
    except Exception:
        pass
    try:
        if len(getattr(image, "packed_files", ()) or ()) > 0:
            return "PACKED"
    except Exception:
        pass

    try:
        if bool(getattr(image, "has_data", False)):
            return "IN_MEMORY"
    except Exception:
        pass
    try:
        if bool(getattr(image, "is_dirty", False)):
            return "IN_MEMORY"
    except Exception:
        pass

    raw_path = ""
    try:
        raw_path = str(getattr(image, "filepath_raw", "") or getattr(image, "filepath", "") or "")
    except Exception:
        raw_path = ""
    if raw_path:
        try:
            resolved = Path(bpy.path.abspath(raw_path)).expanduser()
            if resolved.is_file():
                return "EXTERNAL_FILE"
        except Exception:
            pass

    return "UNAVAILABLE"


def _sabershader_image_is_usable(image):
    """Accept packed or loaded pixels even when no external texture path exists."""
    return _sabershader_image_storage_status(image) != "UNAVAILABLE"


def _sabershader_iter_node_trees(root_tree, max_depth=8):
    """Yield a node tree and nested group trees without revisiting shared groups."""
    if root_tree is None:
        return
    stack = [(root_tree, 0, "ROOT")]
    visited = set()
    while stack:
        tree, depth, path = stack.pop()
        if tree is None or depth > max_depth:
            continue
        try:
            key = int(tree.as_pointer())
        except Exception:
            key = id(tree)
        if key in visited:
            continue
        visited.add(key)
        yield tree, path
        if depth == max_depth:
            continue
        try:
            nodes = list(tree.nodes)
        except Exception:
            nodes = []
        for node in reversed(nodes):
            if getattr(node, "bl_idname", "") != "ShaderNodeGroup":
                continue
            child = getattr(node, "node_tree", None)
            if child is None:
                continue
            label = str(getattr(node, "label", "") or getattr(node, "name", "") or "Group")
            stack.append((child, depth + 1, f"{path}/{label}"))


def _sabershader_recursive_image_nodes(mat):
    """Return image nodes from the material and all nested shader node groups."""
    if not mat or not getattr(mat, "use_nodes", False) or not getattr(mat, "node_tree", None):
        return []
    rows = []
    for tree, path in _sabershader_iter_node_trees(mat.node_tree):
        try:
            nodes = list(tree.nodes)
        except Exception:
            nodes = []
        for node in nodes:
            if getattr(node, "bl_idname", "") == "ShaderNodeTexImage" and getattr(node, "image", None):
                rows.append((node, path))
    return rows


def images_in_material(mat):
    return [node.image for node, _path in _sabershader_recursive_image_nodes(mat) if node.image]


def find_image_by_name_candidates(names, require_usable=False):
    for name in names:
        img = bpy.data.images.get(name)
        if img and (not require_usable or _sabershader_image_is_usable(img)):
            return img
    normalized = {norm(n): n for n in names}
    for img in bpy.data.images:
        if norm(img.name) in normalized and (not require_usable or _sabershader_image_is_usable(img)):
            return img
    return None


def _sabershader_image_downstream_score(node):
    """Estimate whether an image feeds visible color rather than a data channel."""
    try:
        start = node.outputs.get('Color') or (node.outputs[0] if node.outputs else None)
    except Exception:
        start = None
    if start is None:
        return 0

    positive = ('base color', 'basecolor', 'diffuse', 'albedo', 'color', 'colour', 'emission')
    negative = ('normal', 'rough', 'metal', 'specular', 'ao', 'ambient occlusion', 'height', 'bump')
    best = 0
    queue = [(start, 0)]
    visited = set()
    while queue:
        socket, depth = queue.pop(0)
        if depth > 5:
            continue
        try:
            key = int(socket.as_pointer())
        except Exception:
            key = id(socket)
        if key in visited:
            continue
        visited.add(key)
        try:
            links = list(socket.links)
        except Exception:
            links = []
        for link in links:
            target_socket = getattr(link, 'to_socket', None)
            target_node = getattr(link, 'to_node', None)
            socket_name = str(getattr(target_socket, 'name', '') or '').casefold()
            node_type = str(getattr(target_node, 'bl_idname', '') or '')
            if any(token in socket_name for token in negative):
                best = min(best, -90)
            if any(token in socket_name for token in positive):
                best = max(best, 70 - depth * 7)
            if node_type in {'ShaderNodeBsdfPrincipled', 'ShaderNodeBsdfDiffuse', 'ShaderNodeEmission'}:
                if 'color' in socket_name or 'emission' in socket_name:
                    best = max(best, 80 - depth * 7)
            if target_node is None:
                continue
            try:
                for out_socket in target_node.outputs:
                    if getattr(out_socket, 'is_linked', False):
                        queue.append((out_socket, depth + 1))
            except Exception:
                pass
    return best


def _sabershader_base_image_score(node, path):
    image = getattr(node, 'image', None)
    if image is None or not _sabershader_image_is_usable(image):
        return -10000

    node_name = str(getattr(node, 'name', '') or '')
    node_label = str(getattr(node, 'label', '') or '')
    image_name = str(getattr(image, 'name', '') or '')
    haystack = f"{node_name} {node_label} {image_name}".casefold()

    score = 0
    if node_name.casefold() == 'mmd_base_tex':
        score += 180
    elif 'mmd_base_tex' in haystack:
        score += 120

    positive = ('base', 'albedo', 'diffuse', 'diff', 'color', 'colour', 'maintex', 'main tex')
    negative = ('normal', ' nrm', '_nrm', 'rough', 'metal', 'spec', 'mask', 'ambient', ' occlusion',
                'toon', 'sphere', 'matcap', 'height', 'bump', 'lightmap')
    if any(token in haystack for token in positive):
        score += 36
    if any(token in haystack for token in negative):
        score -= 95

    try:
        colorspace = str(image.colorspace_settings.name or '').casefold()
    except Exception:
        colorspace = ''
    if 'srgb' in colorspace:
        score += 18
    elif 'non-color' in colorspace or 'non color' in colorspace:
        score -= 28

    score += _sabershader_image_downstream_score(node)
    if path == 'ROOT':
        score += 8
    return score


def _sabershader_best_graph_base_image(mat):
    candidates = []
    for node, path in _sabershader_recursive_image_nodes(mat):
        image = getattr(node, 'image', None)
        if not _sabershader_image_is_usable(image):
            continue
        score = _sabershader_base_image_score(node, path)
        candidates.append((score, node, image, path))
    if not candidates:
        return None, "none"

    candidates.sort(key=lambda row: (-row[0], str(getattr(row[2], 'name', ''))))
    score, node, image, path = candidates[0]
    if score <= 0:
        return None, "unresolved:data-only-images"

    storage = _sabershader_image_storage_status(image)
    if str(getattr(node, 'name', '') or '').casefold() == 'mmd_base_tex':
        source = 'mmd_base_tex' if path == 'ROOT' else 'nested_mmd_base_tex'
    elif _sabershader_image_downstream_score(node) > 0:
        source = 'shader_graph'
    else:
        source = 'recursive_image'
    return image, f"source:{source}:{path}:{storage}:score={score}"


def first_source_image(mat):
    image, _reason = _sabershader_best_graph_base_image(mat)
    return image


def resolve_base_image(source_mat, category, source_name):
    """Resolve a usable base image without requiring an external file path."""

    known_name = KNOWN_FACE_BASE_IMAGE.get(source_name) or KNOWN_MASK_BASE_IMAGE.get(source_name)
    if known_name:
        img = find_image_by_name_candidates((known_name,), require_usable=True)
        if img:
            storage = _sabershader_image_storage_status(img)
            return img, f"confirmed:{known_name}:{storage}"
        log(
            f"  Confirmed texture '{known_name}' for '{source_name}' is unavailable; "
            f"falling back to material graph resolution"
        )

    if source_mat:
        try:
            recovered_name = str(source_mat.get("SaberShader_V8_BaseImage", "") or "")
        except Exception:
            recovered_name = ""
        if recovered_name:
            img = find_image_by_name_candidates((recovered_name,), require_usable=True)
            if img:
                storage = _sabershader_image_storage_status(img)
                return img, f"recovered:SaberShader_V8_BaseImage:{recovered_name}:{storage}"

    img, reason = _sabershader_best_graph_base_image(source_mat)
    if img:
        return img, reason

    if source_name == "Face" and category == "face":
        img = find_image_by_name_candidates(DOLORIS_FACE_FALLBACKS, require_usable=True)
        if img:
            storage = _sabershader_image_storage_status(img)
            return img, f"fallback:Doloris Face2/expression texture:{storage}"

    return None, reason or "none"

def duplicate_group(template_name, suffix):
    source = bpy.data.node_groups.get(template_name)
    if not source:
        log(f"MISSING NODE GROUP: {template_name}")
        return None

    local_name = f"{template_name}__V8_{safe_name(suffix)}"
    old = bpy.data.node_groups.get(local_name)
    if old:

        bpy.data.node_groups.remove(old)

    local = source.copy()
    local.name = local_name
    return local

def clean_face_master_contamination():
    """Keep the Face master neutral by clearing character-specific base images.

    Material copies resolve and assign their own confirmed face textures, so the
    master should not retain a texture from a previous character. Shared toon
    textures are preserved.
    """
    group = bpy.data.node_groups.get("Face_XDZR8EndfieldShader")
    if not group:
        return []

    cleaned = []
    for node_name in ("mmd_base_tex", "mmd_base_tex.001"):
        node = group.nodes.get(node_name)
        if node and node.bl_idname == "ShaderNodeTexImage" and node.image:
            log(f"Face master cleanup: clearing {node_name} image '{node.image.name}'")
            node.image = None
            cleaned.append(node_name)
    return cleaned

def clear_and_make_material(mat_name):
    old = bpy.data.materials.get(mat_name)
    if old:
        bpy.data.materials.remove(old, do_unlink=True)

    mat = bpy.data.materials.new(mat_name)
    mat.use_nodes = True
    nodes = mat.node_tree.nodes
    nodes.clear()
    return mat

def _relink(links, from_socket, to_socket):
    for l in list(to_socket.links):
        links.remove(l)
    links.new(from_socket, to_socket)

def fix_face_master_emission_routing():
    """Ensure Face groups finish through Emission without a redundant shader mix.

    The toon color chain already reacts to light direction before Emission.
    Emission is therefore kept as the final output stage so unlit facial areas
    do not collapse to black. The fix is idempotent and applies to both the
    master group and existing per-material copies.
    """
    template_name = GROUPS["face"]
    fixed, skipped = [], []

    master = bpy.data.node_groups.get(template_name)
    if master:
        ok, why = _apply_face_output_fix(master)
        (fixed if ok else skipped).append((template_name, why))
    else:
        log(f"Face output fix: master not found: {template_name}")

    prefix = f"{template_name}__V8_"
    for g in list(bpy.data.node_groups):
        if g is master or not g.name.startswith(prefix):
            continue
        ok, why = _apply_face_output_fix(g)
        (fixed if ok else skipped).append((g.name, why))

    for name, why in fixed:
        log(f"Face output fix: {name}: {why}")
    for name, why in skipped:
        log(f"Face output fix: {name}: unchanged ({why})")
    return fixed

def _apply_face_output_fix(g):
    """Connect Emission directly to the Face group output and remove stale BSDFs."""
    nodes, links = g.nodes, g.links
    emission = nodes.get("Emission")
    group_output = nodes.get("Group Output")
    if not (emission and group_output):
        return False, "required Emission / Group Output nodes are missing"

    shader_out = next((s for s in group_output.inputs if s.type == 'SHADER'), None)
    if not shader_out:
        return False, "Group Output has no SHADER input"

    stray_principled = nodes.get("Principled BSDF")
    if stray_principled:
        nodes.remove(stray_principled)

    rim_add = nodes.get("SaberShader Rim Add")
    feeder = shader_out.links[0].from_node if shader_out.is_linked else None
    already_ok = (
        not stray_principled
        and feeder is not None
        and (feeder == emission or feeder == rim_add)
    )
    if already_ok:
        return False, "already routed through Emission"

    _relink(links, emission.outputs["Emission"], shader_out)

    mix_shader = nodes.get("Mix Shader.001")
    if mix_shader:
        mix_shader.label = "Unused"
    emission.label = ""

    return True, (
        "removed stale Principled BSDF and restored direct Emission output"
        if stray_principled
        else "connected Emission directly to Group Output"
    )

def add_face_rim_highlight():
    template_name = GROUPS["face"]
    changed, skipped = [], []

    master = bpy.data.node_groups.get(template_name)
    if master:
        ok, why = _apply_rim_highlight(master)
        (changed if ok else skipped).append((template_name, why))
    else:
        log(f"V8.17 rim: no se encontró el master {template_name}")

    prefix = f"{template_name}__V8_"
    for g in list(bpy.data.node_groups):
        if g is master or not g.name.startswith(prefix):
            continue
        ok, why = _apply_rim_highlight(g)
        (changed if ok else skipped).append((g.name, why))

    for name, why in changed:
        log(f"V8.17 rim: {name}: {why}")
    for name, why in skipped:
        log(f"V8.17 rim: {name} sin cambios ({why})")

    return changed

def _apply_rim_highlight(g):
    nodes, links = g.nodes, g.links

    if nodes.get("SaberShader Rim Glossy"):
        return False, "ya tiene el rim highlight"

    emission = nodes.get("Emission")
    group_output = nodes.get("Group Output")
    if not (emission and group_output):
        return False, "faltan nodos esperados (Emission / Group Output)"

    shader_out = next((s for s in group_output.inputs if s.type == 'SHADER'), None)
    if not shader_out or not shader_out.is_linked or shader_out.links[0].from_node != emission:
        return False, "Group Output no cuelga de Emission (correr fix_face_master_emission_routing primero)"

    glossy = nodes.new("ShaderNodeBsdfGlossy")
    glossy.name = "SaberShader Rim Glossy"
    glossy.label = "Rim (V8.17, encima de Emission)"
    glossy.location = (emission.location.x, emission.location.y - 200)
    glossy.inputs["Color"].default_value = (0.8, 0.8, 0.8, 1.0)
    glossy.inputs["Roughness"].default_value = 0.35

    add_shader = nodes.new("ShaderNodeAddShader")
    add_shader.name = "SaberShader Rim Add"
    add_shader.location = (emission.location.x + 180, emission.location.y - 100)

    links.new(emission.outputs["Emission"], add_shader.inputs[0])
    links.new(glossy.outputs["BSDF"], add_shader.inputs[1])
    _relink(links, add_shader.outputs["Shader"], shader_out)

    return True, "Glossy (rim) sumado sobre Emission via Add Shader"

def protect_master_templates():
    """Keep template node groups available even when no material uses them directly."""
    protected = []
    for template_name in GROUPS.values():
        g = bpy.data.node_groups.get(template_name)
        if g and not g.use_fake_user:
            g.use_fake_user = True
            protected.append(template_name)
    if protected:
        log(f"Protected {len(protected)} template node groups: {protected}")
    return protected

def connect_group_output(mat, group_node):
    nodes = mat.node_tree.nodes
    links = mat.node_tree.links
    output = nodes.new("ShaderNodeOutputMaterial")
    output.name = "Material Output"
    output.location = (420, 0)

    if group_node.outputs.get("Shader"):
        links.new(group_node.outputs["Shader"], output.inputs["Surface"])
    elif group_node.outputs.get("BSDF"):
        links.new(group_node.outputs["BSDF"], output.inputs["Surface"])
    else:
        raise RuntimeError(f"XDZR8 group '{group_node.name}' has no Shader/BSDF output")

    for node in nodes:
        if node.bl_idname == "ShaderNodeOutputMaterial":
            node.is_active_output = (node is output)

    return output

def connect_group_uv(mat, group_node):
    """Connect the mesh UVs to the XDZR8 group Vector input.

    This is critical for Cloth/Face/Eyes/Body groups whose internal
    mmd_base_tex nodes explicitly read Group Input.Vector. Without this
    connection Blender feeds the unconnected vector default (0,0,0), so
    the texture is sampled at a single point instead of the mesh UVs.
    """
    if not mat or not mat.node_tree or not group_node:
        return False

    vector_in = group_node.inputs.get("Vector")
    if not vector_in:
        return False

    nodes = mat.node_tree.nodes
    links = mat.node_tree.links

    texcoord = nodes.get("SaberShader_V8_UV")
    if not texcoord:
        texcoord = nodes.new("ShaderNodeTexCoord")
        texcoord.name = "SaberShader_V8_UV"
        texcoord.label = "SaberShader V8 UV (UVMap)"
        texcoord.location = (-360, -220)

    for link in list(vector_in.links):
        links.remove(link)

    links.new(texcoord.outputs["UV"], vector_in)
    return True

def remove_external_face_uv(mat):
    """Remove the external Face Texture Coordinate helper."""
    if not mat or not mat.node_tree:
        return False
    nodes = mat.node_tree.nodes
    links = mat.node_tree.links
    changed = False
    group_node = nodes.get("XDZR8_V8")
    if group_node:
        vector_in = group_node.inputs.get("Vector")
        if vector_in:
            for link in list(vector_in.links):
                links.remove(link)
                changed = True
    texcoord = nodes.get("SaberShader_V8_UV")
    if texcoord:
        nodes.remove(texcoord)
        changed = True
    return changed

def connect_face_mmdtexuv(mat, group_node):
    """Reproduce the MMD Face UV routing:

        MMDTexUV.Base UV -> first Vector input of Face_XDZR8
        MMDTexUV.Toon UV -> second Vector input of Face_XDZR8 (when present)

    The exact Face master uses two UV streams. Do not feed the Face group from
    Blender's raw Texture Coordinate node. We resolve the vector inputs by
    interface order first, then by common names for robustness across copies.
    """
    if not mat or not mat.node_tree or not group_node:
        return False

    mmd_group = bpy.data.node_groups.get("MMDTexUV")
    if not mmd_group:
        target = norm("MMDTexUV")
        for ng in bpy.data.node_groups:
            if norm(ng.name) == target:
                mmd_group = ng
                break
    if not mmd_group:
        log("  [face-mmdtexuv] MISSING node group 'MMDTexUV'")
        return False

    nodes = mat.node_tree.nodes
    links = mat.node_tree.links
    node = nodes.get("SaberShader_MMDTexUV")
    if not node:
        node = nodes.new("ShaderNodeGroup")
        node.name = "SaberShader_MMDTexUV"
        node.label = "MMDTexUV • Face Base/Toon UV"
        node.location = (-360, -80)
    node.node_tree = mmd_group

    base_out = node.outputs.get("Base UV")
    toon_out = node.outputs.get("Toon UV")

    vector_inputs = [sock for sock in group_node.inputs if sock.type == 'VECTOR']
    if not vector_inputs:
        log("  [face-mmdtexuv] Face group has no VECTOR inputs")
        return False

    first = group_node.inputs.get("Vector")
    if not first or first.type != 'VECTOR':
        first = vector_inputs[0]

    second = None
    for candidate_name in ("Toon UV", "Vector.001", "Vector 2", "ToonVector", "Toon"):
        candidate = group_node.inputs.get(candidate_name)
        if candidate and candidate.type == 'VECTOR' and candidate != first:
            second = candidate
            break
    if second is None and len(vector_inputs) >= 2:
        second = vector_inputs[1]

    changed = False

    if base_out:
        for link in list(first.links):
            links.remove(link)
        links.new(base_out, first)
        log(f"  [face-mmdtexuv] {node.name}.Base UV -> {group_node.name}.{first.name}")
        changed = True
    else:
        log("  [face-mmdtexuv] MMDTexUV has no 'Base UV' output")

    if toon_out and second:
        for link in list(second.links):
            links.remove(link)
        links.new(toon_out, second)
        log(f"  [face-mmdtexuv] {node.name}.Toon UV -> {group_node.name}.{second.name}")
        changed = True
    elif toon_out and not second:
        log("  [face-mmdtexuv] MMDTexUV has 'Toon UV', but Face exposes no second VECTOR input")
    else:
        log("  [face-mmdtexuv] MMDTexUV has no 'Toon UV' output; skipping that route")

    return changed

def connect_face_secondary_uv(group):
    """Face XDZR8 has mmd_base_tex.001 with no Vector link in the master.
    It participates in the face logic, so make it sample the same UV as the
    main mmd_base_tex instead of sampling its default (0,0,0)."""
    if not group:
        return False
    base1 = group.nodes.get("mmd_base_tex")
    base2 = group.nodes.get("mmd_base_tex.001")
    gin = group.nodes.get("Group Input")
    if not base1 or not base2 or not gin:
        return False
    src = gin.outputs.get("Vector")
    dst = base2.inputs.get("Vector")
    if not src or not dst:
        return False
    for link in list(dst.links):
        group.links.remove(link)
    group.links.new(src, dst)
    return True

def set_group_image(group, node_name, image):
    if not image:
        return False
    node = group.nodes.get(node_name)
    if not node or node.bl_idname != "ShaderNodeTexImage":
        return False
    node.image = image
    return True

def disconnect_input(node, socket_name):
    socket = node.inputs.get(socket_name)
    if not socket:
        return False
    for link in list(socket.links):
        node.id_data.links.remove(link)
    return True

def disconnect_outputs(node_tree, node):
    for link in list(node_tree.links):
        if link.from_node == node:
            node_tree.links.remove(link)

def force_principled_value(group, socket_name, value):
    pb = group.nodes.get("Principled BSDF")
    if not pb:
        return False
    sock = pb.inputs.get(socket_name)
    if not sock:
        return False
    disconnect_input(pb, socket_name)
    sock.default_value = value
    return True

def neutralize_cloth_aux(group):
    """Remove source-specific auxiliary maps from Cloth without touching
    the Base Color branch. Replace them with stable scalar settings."""
    if not group:
        return

    for node_name, role in CLOTH_AUX_NODES.items():
        node = group.nodes.get(node_name)
        if node:
            disconnect_outputs(group, node)
            log(f"  Cloth aux neutralized: {node_name} ({role})")

    force_principled_value(group, "Roughness", 0.48)
    force_principled_value(group, "Specular IOR Level", 0.5)
    force_principled_value(group, "Metallic", 0.0)

    pb = group.nodes.get("Principled BSDF")
    if pb and pb.inputs.get("Normal"):
        disconnect_input(pb, "Normal")

def neutralize_hair_aux(group):
    """Remove source HN/P/ST/RS and keep a clean Hair base-color path.
    V8.1 deliberately does not invent replacement normal/P/ST/RS maps."""
    if not group:
        return

    for node_name, role in HAIR_AUX_NODES.items():
        node = group.nodes.get(node_name)
        if node:
            disconnect_outputs(group, node)
            log(f"  Hair aux neutralized: {node_name} ({role})")

    force_principled_value(group, "Roughness", 0.43)
    force_principled_value(group, "Specular IOR Level", 0.5)
    force_principled_value(group, "Metallic", 0.0)

    pb = group.nodes.get("Principled BSDF")
    if pb and pb.inputs.get("Normal"):
        disconnect_input(pb, "Normal")

def configure_alpha(mat, group, category):
    """Use the source base texture alpha for transparent categories."""
    if category not in TRANSPARENT_CATEGORIES:
        return

    mat.surface_render_method = 'DITHERED'

    pb = group.nodes.get("Principled BSDF")
    base = group.nodes.get("mmd_base_tex")
    if pb and base and base.image and pb.inputs.get("Alpha"):

        disconnect_input(pb, "Alpha")
        group.links.new(base.outputs["Alpha"], pb.inputs["Alpha"])
        log(f"  Alpha enabled from mmd_base_tex for {category}")
    else:
        log(f"  Alpha could not be connected for {category}")

def get_pmx_alpha_factor(source_mat):
    """
    Lee el factor de opacidad horneado en el PMX original (el input
    'Alpha' del grupo mmd_shader del material MMD de origen), NO el
    canal alfa de ninguna textura. Devuelve 1.0 (opaco) si no se
    encuentra nada, para que el llamador pueda ignorarlo con
    seguridad.
    """
    if not source_mat:
        return 1.0

    try:
        if source_mat.get("SaberShader_V8_PMXAlphaFactor") is not None:
            return float(source_mat.get("SaberShader_V8_PMXAlphaFactor"))
    except Exception:
        pass

    if not source_mat.node_tree:
        return 1.0
    shader = source_mat.node_tree.nodes.get("mmd_shader")
    if not shader:
        return 1.0
    sock = shader.inputs.get("Alpha")
    if not sock:
        return 1.0
    try:
        return float(sock.default_value)
    except Exception:
        return 1.0

MASK_SKIN_COLOR = {
    "Doloris": (0.9961, 0.9294, 0.8902, 1.0),
    "Oblivionis": (0.9961, 0.9294, 0.8902, 1.0),
}

def configure_mask_texture_alpha(mat, group, base_image):
    """Use the real texture alpha channel for supported mask materials."""
    if not group or not base_image:
        return False
    base_tex = group.nodes.get("mmd_base_tex")
    pb = group.nodes.get("Principled BSDF")
    if not base_tex or not pb:
        return False
    base_tex.image = base_image
    alpha_in = pb.inputs.get("Alpha")
    if not alpha_in:
        return False
    disconnect_input(pb, "Alpha")
    group.links.new(base_tex.outputs["Alpha"], alpha_in)
    try:
        mat.surface_render_method = 'DITHERED'
    except Exception:
        pass
    mat["SaberShader_V8_MaskTextureAlpha"] = base_image.name
    return True

def reinforce_face_direct_texture(group, base_image):
    """Ensure the confirmed face texture reaches the final Base Color.

    El grupo Face XDZR8 sigue siendo el shader usado; solo se evita que una
    This prevents stale auxiliary master branches from overriding it.
    """
    if not group or not base_image:
        return False
    tex = group.nodes.get("mmd_base_tex")
    pb = group.nodes.get("Principled BSDF")
    if not tex or not pb:
        return False
    tex.image = base_image
    base = pb.inputs.get("Base Color")
    color = tex.outputs.get("Color")
    if not base or not color:
        return False
    for link in list(base.links):
        group.links.remove(link)
    group.links.new(color, base)
    return True

def configure_alpha_from_pmx_factor(mat, group, source_mat, category):
    """
    Fix V8.2. Sustituye/complementa a configure_alpha() para todo lo
    que no sea 'mask'. En vez de asumir qué categorías son
    transparentes, comprueba el valor real por-material y solo actúa
    si de verdad hace falta (factor < 1.0). Así Clothes4 queda
    cubierto automáticamente sin tener que enumerarlo a mano, y
    Clothes/Clothes2/Clothes3/丝袜 no se tocan porque su factor real es
    1.0.
    """
    if category == "mask":
        return

    factor = get_pmx_alpha_factor(source_mat)

    if factor >= 0.995:
        return

    pb = group.nodes.get("Principled BSDF")
    if not pb or not pb.inputs.get("Alpha"):
        log(f"  PMX alpha could not be applied to {source_mat.name} ({category}): no Alpha socket")
        return

    disconnect_input(pb, "Alpha")
    pb.inputs["Alpha"].default_value = factor

    smooth_transparency = bool(group.get("SaberShader_V10_6C1_ClothFinalPolish", False)) and \
        str(group.get("SaberShader_V10_6B_Family", "")) == "transparent"
    try:
        mat.surface_render_method = 'BLENDED' if smooth_transparency else 'DITHERED'
    except Exception:
        try:
            mat.surface_render_method = 'DITHERED'
        except Exception:
            pass

    mat["SaberShader_V8_PMXAlphaFactor"] = factor
    mat["SaberShader_V10_6C1_SmoothTransparency"] = bool(smooth_transparency)
    log(f"  PMX alpha applied: {source_mat.name} -> {factor:.3f} ({category}) render={'BLENDED' if smooth_transparency else 'DITHERED'}")

def configure_face(group, base_image):
    """Configure the Face XDZR8 group.

    The Face group uses three Image Texture nodes in this order:
        1) base face texture
        2) toon texture
        3) second face texture

    Only the 1st and 3rd Image Texture nodes receive ``base_image``.
    The middle/toon texture is deliberately preserved.

    This fixes Oblivionis ``SaberShader_V8_Oblivionis_表情2`` by resolving its
    confirmed base image to ``face.png`` instead of ``BQ_2.png``.
    """
    if not group or not base_image:
        return False

    changed = False

    for node_name in ("mmd_base_tex", "mmd_base_tex.002"):
        node = group.nodes.get(node_name)
        if node and node.bl_idname == "ShaderNodeTexImage":
            if node.image != base_image:
                node.image = base_image
                changed = True

    image_tex_nodes = [n for n in group.nodes if n.bl_idname == "ShaderNodeTexImage"]

    if len(image_tex_nodes) >= 1 and image_tex_nodes[0].image != base_image:
        image_tex_nodes[0].image = base_image
        changed = True

    if len(image_tex_nodes) >= 3 and image_tex_nodes[2].image != base_image:
        image_tex_nodes[2].image = base_image
        changed = True

    return changed

def audit_face_image_slots(group, base_image, label="Face"):
    if not group or not base_image:
        return
    tex_nodes = [n for n in group.nodes if n.bl_idname == "ShaderNodeTexImage"]
    slots = []
    for i, node in enumerate(tex_nodes, start=1):
        slots.append(f"#{i}:{node.name}={node.image.name if node.image else 'NONE'}")
    log(f"  [face-image-slots] {label}: " + " | ".join(slots))

def configure_simple_base(group, base_image):
    node = group.nodes.get("mmd_base_tex")
    if node and base_image:
        node.image = base_image

def template_for_category(category):
    if category in {"face", "mouth", "expression", "expression2"}:
        return GROUPS["face"]
    if category == "eyes":
        return GROUPS["eyes"]
    if category == "eyes3":
        return GROUPS["eyes3"]
    if category == "eyes5":
        return GROUPS["eyes5"]
    if category == "hair":
        return GROUPS["hair"]
    if category == "body":
        return GROUPS["body"]
    if category in {
        "cloth", "cloth1", "cloth2", "cloth3", "cloth4",
        "stockings", "transparent_cloth", "mask", "accessory", "skirt",
        "tie", "glove", "bow", "boots",
    }:
        return GROUPS["cloth"]
    return None

