def _sabershader109b37_quarantine_stray_doloris_strokes(settings=None):
    """Hide old renderable line helpers that can masquerade as outline spikes.

    Nothing is deleted. Safe Silhouette objects are MESH and are untouched.
    """
    if settings and not bool(getattr(settings, 'quarantine_stray_strokes_v109b37', True)):
        return 0
    changed = 0
    for obj in bpy.data.objects:
        if not obj or obj.type not in {'CURVE', 'GREASEPENCIL', 'GPENCIL'}:
            continue
        name = str(getattr(obj, 'name', ''))
        lname = name.lower()
        char_tag = str(obj.get('SaberShader_V9_1_Character', obj.get('SaberShader_V10_7B_Character', ''))).lower()
        is_doloris = ('doloris' in lname) or char_tag.startswith('doloris')
        if not is_doloris:
            continue
        is_line_helper = (
            bool(obj.get('SaberShader_V10_7B_InternalAccent', False))
            or bool(obj.get('SaberShader_V9_1_Tertiary', False))
            or bool(obj.get('SaberShader_V9_3_Tertiary', False))
            or bool(obj.get('SaberShader_V9_4_TertiaryArtist2', False))
            or 'lineart' in lname
            or 'tertiary' in lname
            or 'accent' in lname
        )
        if not is_line_helper:
            continue
        try:
            if not obj.hide_viewport:
                obj.hide_viewport = True
                changed += 1
        except Exception:
            pass
        try:
            if not obj.hide_render:
                obj.hide_render = True
                changed += 1
        except Exception:
            pass
        try:
            obj.hide_set(True)
        except Exception:
            pass
        try:
            obj['SaberShader_V10_9B3_7_StrayStrokeQuarantined'] = True
        except Exception:
            pass
    return changed

def _sabershader109b38_oblivionis_final_multiplier(char_name, settings):
    if not settings or not bool(getattr(settings, 'build_final_series_cleanup_v109b38', True)):
        return 1.0
    if not str(char_name).lower().startswith('oblivionis'):
        return 1.0
    return max(0.70, min(1.00, float(getattr(settings, 'oblivionis_final_outline_trim_v109b38', 0.94))))

def _sabershader109b38_quarantine_internal_accents(settings=None):
    """Hide every SaberShader V10.7B internal-accent Curve in viewport and render.

    These are procedural Curve strokes, not native Grease Pencil Line Art.
    They are kept in the .blend for reversibility but are not part of the
    final Ave Mujica-style ink pass.
    """
    if settings and not bool(getattr(settings, 'quarantine_all_internal_accents_v109b38', True)):
        return 0
    changed = 0
    for obj in bpy.data.objects:
        if not obj:
            continue
        is_internal = bool(obj.get('SaberShader_V10_7B_InternalAccent', False)) or str(getattr(obj, 'name', '')).startswith(SABERSHADER107B_OBJECT_PREFIX)
        if not is_internal:
            continue
        try:
            if not obj.hide_viewport:
                obj.hide_viewport = True
                changed += 1
        except Exception:
            pass
        try:
            if not obj.hide_render:
                obj.hide_render = True
                changed += 1
        except Exception:
            pass
        try:
            obj.hide_set(True)
        except Exception:
            pass
        try:
            obj['SaberShader_V10_9B3_8_FinalAccentQuarantine'] = True
        except Exception:
            pass

    for col in bpy.data.collections:
        if not col.name.startswith(SABERSHADER107B_COLLECTION_PREFIX):
            continue
        try:
            if not col.hide_viewport:
                col.hide_viewport = True
                changed += 1
        except Exception:
            pass
        try:
            if not col.hide_render:
                col.hide_render = True
                changed += 1
        except Exception:
            pass
    return changed

def _sabershader109b35_apply_clean_preview(settings=None):
    """Hide viewport-only clutter without deleting rigs, cameras or helpers.

    This is intentionally a presentation toggle. It only changes 3D View
    overlays/gizmos and viewport visibility of SaberShader tertiary guide helpers.
    Rendering and source rig data are untouched.
    """
    enabled = bool(getattr(settings, 'clean_preview_viewport_v109b35', True)) if settings else True
    changed = 0

    wm = getattr(bpy.context, 'window_manager', None)
    if wm:
        for win in getattr(wm, 'windows', []):
            screen = getattr(win, 'screen', None)
            if not screen:
                continue
            for area in screen.areas:
                if area.type != 'VIEW_3D':
                    continue
                for space in area.spaces:
                    if space.type != 'VIEW_3D':
                        continue
                    overlay = getattr(space, 'overlay', None)
                    if overlay:
                        targets = {
                            'show_relationship_lines': not enabled,
                            'show_extras': not enabled,
                            'show_bones': not enabled,
                            'show_motion_paths': not enabled,
                            'show_object_origins': not enabled,
                            'show_object_origins_all': not enabled,
                            'show_outline_selected': not enabled,
                            'show_wireframes': not enabled,
                            'show_text': not enabled,
                        }
                        for attr, value in targets.items():
                            if hasattr(overlay, attr):
                                try:
                                    if bool(getattr(overlay, attr)) != bool(value):
                                        setattr(overlay, attr, bool(value))
                                        changed += 1
                                except Exception:
                                    pass
                    if hasattr(space, 'show_gizmo'):
                        try:
                            desired = not enabled
                            if bool(space.show_gizmo) != desired:
                                space.show_gizmo = desired
                                changed += 1
                        except Exception:
                            pass

    show_guides = bool(getattr(settings, 'show_tertiary_guides_v107c1', True)) if settings else True
    for col in bpy.data.collections:
        if col.name.startswith('SaberShader_V10_7C_Tertiary_'):
            desired_hide = bool(enabled) or (not show_guides)
            try:
                if bool(col.hide_viewport) != desired_hide:
                    col.hide_viewport = desired_hide
                    changed += 1
            except Exception:
                pass

    for obj in bpy.data.objects:
        is_tertiary = (
            obj.name.startswith('SaberShader_V10_7C_Marker__')
            or bool(obj.get('SaberShader_V9_4_TertiaryGuide', False))
        )
        if not is_tertiary:
            continue
        desired_hide = bool(enabled) or (not show_guides)
        try:
            if bool(obj.hide_viewport) != desired_hide:
                obj.hide_viewport = desired_hide
                changed += 1
        except Exception:
            pass

    return changed

def _sabershader109b34_cleanup_viewport_relationship_lines(settings=None):
    if settings and not bool(getattr(settings, 'hide_relationship_lines_v109b34', True)):
        return 0
    changed = 0
    wm = getattr(bpy.context, 'window_manager', None)
    if not wm:
        return 0
    for win in getattr(wm, 'windows', []):
        screen = getattr(win, 'screen', None)
        if not screen:
            continue
        for area in screen.areas:
            if area.type != 'VIEW_3D':
                continue
            for space in area.spaces:
                if space.type != 'VIEW_3D':
                    continue
                overlay = getattr(space, 'overlay', None)
                if overlay and hasattr(overlay, 'show_relationship_lines'):
                    if overlay.show_relationship_lines:
                        overlay.show_relationship_lines = False
                        changed += 1
    return changed

def _sabershader109b310_make_sanitized_shell_mesh(src_obj, settings=None):
    """Return (mesh, info) with current shape deformation baked and no Key data.

    Primary path: evaluate a temporary copy with every modifier removed. This
    applies Shape Keys/drivers in local mesh space but does not bake Armature or
    topology-changing modifiers. The real shell object later keeps only Armature
    modifiers, so it remains pose-aware without inheriting unsafe modifier stacks.
    """
    info = {
        'mode': 'raw_copy',
        'shape_keys': 0,
        'source_modifiers': [],
        'kept_modifiers': [],
        'stripped_modifiers': [],
    }
    if not src_obj or getattr(src_obj, 'type', None) != 'MESH' or not getattr(src_obj, 'data', None):
        return None, info

    try:
        keys = getattr(src_obj.data, 'shape_keys', None)
        if keys and getattr(keys, 'key_blocks', None):
            info['shape_keys'] = max(0, len(keys.key_blocks) - 1)
    except Exception:
        pass
    try:
        info['source_modifiers'] = [f'{m.name}:{m.type}' for m in src_obj.modifiers]
    except Exception:
        pass

    enabled = bool(getattr(settings, 'build_shell_geometry_sanitation_v109b310', True)) if settings else True
    if not enabled:
        return src_obj.data.copy(), info

    temp = None
    temp_mesh = None
    try:
        temp = src_obj.copy()
        temp.data = src_obj.data.copy()
        temp.name = f'SaberShader_TEMP_B310__{src_obj.name}'
        temp_mesh = temp.data

        for mod in list(temp.modifiers):
            temp.modifiers.remove(mod)
        bpy.context.scene.collection.objects.link(temp)
        depsgraph = bpy.context.evaluated_depsgraph_get()
        try:
            depsgraph.update()
        except Exception:
            pass
        eval_temp = temp.evaluated_get(depsgraph)
        mesh = bpy.data.meshes.new_from_object(
            eval_temp,
            preserve_all_data_layers=True,
            depsgraph=depsgraph,
        )
        mesh.name = f'SaberShader_B310_Sanitized__{src_obj.data.name}'
        info['mode'] = 'shape_baked_local'

        return mesh, info
    except Exception as exc:
        log(f'  [V10.9B3.10 sanitize fallback] {src_obj.name}: local shape bake failed: {exc}')

        try:
            depsgraph = bpy.context.evaluated_depsgraph_get()
            eval_src = src_obj.evaluated_get(depsgraph)
            mesh = bpy.data.meshes.new_from_object(
                eval_src,
                preserve_all_data_layers=True,
                depsgraph=depsgraph,
            )
            mesh.name = f'SaberShader_B310_FrozenEval__{src_obj.data.name}'
            info['mode'] = 'full_eval_fallback'
            return mesh, info
        except Exception as exc2:
            log(f'  [V10.9B3.10 sanitize fallback] {src_obj.name}: full eval failed: {exc2}')
            info['mode'] = 'raw_copy_fallback'
            return src_obj.data.copy(), info
    finally:
        if temp is not None:
            try:
                bpy.data.objects.remove(temp, do_unlink=True)
            except Exception:
                pass
        if temp_mesh is not None and getattr(temp_mesh, 'users', 1) == 0:
            try:
                bpy.data.meshes.remove(temp_mesh)
            except Exception:
                pass

def _sabershader109b310_sanitize_shell_modifiers(dup, info, settings=None):
    """Keep only Armature on shape-baked shells; full-eval fallback keeps none."""
    enabled = bool(getattr(settings, 'build_shell_geometry_sanitation_v109b310', True)) if settings else True
    if not enabled or not dup:
        return
    mode = str(info.get('mode', 'raw_copy'))
    keep_armature = bool(getattr(settings, 'shell_sanitation_keep_armature_v109b310', True)) if settings else True
    for mod in list(dup.modifiers):
        keep = keep_armature and mode == 'shape_baked_local' and mod.type == 'ARMATURE'
        if keep:
            info['kept_modifiers'].append(f'{mod.name}:{mod.type}')
            continue
        info['stripped_modifiers'].append(f'{mod.name}:{mod.type}')
        try:
            dup.modifiers.remove(mod)
        except Exception:
            pass

def _sabershader109b311_post_eval_hard_cull(mesh, settings=None):
    if not mesh or not getattr(mesh, 'polygons', None):
        return 0, 0
    bm = bmesh.new()
    removed_faces = 0
    removed_edges = 0
    try:
        bm.from_mesh(mesh)
        verts = [v for v in bm.verts if v.link_faces]
        if len(verts) < 8:
            return 0, 0
        xs = sorted(float(v.co.x) for v in verts)
        ys = sorted(float(v.co.y) for v in verts)
        zs = sorted(float(v.co.z) for v in verts)
        mid = len(verts) // 2
        center = Vector((xs[mid], ys[mid], zs[mid]))
        dists = sorted(float((v.co - center).length) for v in verts)
        q90 = max(1e-8, _sabershader109b39_percentile(dists, 0.90))
        lengths_all = sorted(float(e.calc_length()) for e in bm.edges if e.calc_length() > 1e-9)
        if not lengths_all:
            return 0, 0
        median_edge = max(1e-9, lengths_all[len(lengths_all)//2])
        long_ratio = float(getattr(settings, 'post_eval_long_edge_ratio_v109b311', 16.0)) if settings else 16.0
        radius_factor = float(getattr(settings, 'post_eval_remote_radius_v109b311', 2.35)) if settings else 2.35
        long_limit = max(median_edge * max(10.0, long_ratio), q90 * 0.82)
        radius_limit = max(q90 * max(1.8, radius_factor), median_edge * 70.0)
        bad_faces = set()
        for f in list(bm.faces):
            fd = [float((v.co - center).length) for v in f.verts]
            fl = [float(e.calc_length()) for e in f.edges]
            if not fd or not fl:
                continue
            longest = max(fl)
            centroid_d = float((f.calc_center_median() - center).length)
            if longest > long_limit or (max(fd) > radius_limit and centroid_d > radius_limit * 0.72):
                bad_faces.add(f)
        if bad_faces:
            removed_faces = len(bad_faces)
            bmesh.ops.delete(bm, geom=list(bad_faces), context='FACES')
        loose_edges = [e for e in bm.edges if not e.link_faces]
        if loose_edges:
            removed_edges = len(loose_edges)
            bmesh.ops.delete(bm, geom=loose_edges, context='EDGES')
        loose_verts = [v for v in bm.verts if not v.link_faces and not v.link_edges]
        if loose_verts:
            bmesh.ops.delete(bm, geom=loose_verts, context='VERTS')
        bm.to_mesh(mesh)
    finally:
        bm.free()
    mesh.update()
    try:
        mesh.validate(clean_customdata=False)
    except Exception:
        pass
    return removed_faces, removed_edges

def _sabershader109b311_freeze_shell_after_armature(dup, char_name, settings=None):
    info = {'frozen': False, 'faces_removed': 0, 'edges_removed': 0, 'mode': 'off'}
    enabled = bool(getattr(settings, 'build_post_armature_shell_freeze_v109b311', True)) if settings else True
    if not enabled or not dup or not str(char_name).lower().startswith('doloris'):
        return info
    depsgraph = bpy.context.evaluated_depsgraph_get()
    old_mesh = getattr(dup, 'data', None)
    try:
        try:
            depsgraph.update()
        except Exception:
            pass
        eval_dup = dup.evaluated_get(depsgraph)
        frozen = bpy.data.meshes.new_from_object(eval_dup, preserve_all_data_layers=True, depsgraph=depsgraph)
        frozen.name = f'SaberShader_B311_PostArmature__{old_mesh.name if old_mesh else dup.name}'
        dup.data = frozen
        for mod in list(dup.modifiers):
            try:
                dup.modifiers.remove(mod)
            except Exception:
                pass
        rf, re_ = _sabershader109b311_post_eval_hard_cull(frozen, settings)
        info.update({'frozen': True, 'faces_removed': int(rf), 'edges_removed': int(re_), 'mode': 'post_armature_frozen'})
        if old_mesh is not None and getattr(old_mesh, 'users', 1) == 0:
            try:
                bpy.data.meshes.remove(old_mesh)
            except Exception:
                pass
    except Exception as exc:
        info['mode'] = 'freeze_failed'
        log(f'  [V10.9B3.11 freeze warning] {dup.name}: {exc}')
    return info

def _sabershader109b312_character_world_envelope(items, settings=None):
    points = []
    for entry in (items or []):
        try:
            obj = entry[0]
        except Exception:
            continue
        if not obj or getattr(obj, 'type', None) != 'MESH':
            continue
        try:
            for corner in obj.bound_box:
                points.append(obj.matrix_world @ Vector(corner))
        except Exception:
            pass
    if not points:
        return None
    mn = Vector((min(p.x for p in points), min(p.y for p in points), min(p.z for p in points)))
    mx = Vector((max(p.x for p in points), max(p.y for p in points), max(p.z for p in points)))
    span = mx - mn
    margin = float(getattr(settings, 'post_solidify_envelope_margin_v109b312', 0.16)) if settings else 0.16

    pad = Vector((
        max(0.015, abs(span.x) * margin),
        max(0.015, abs(span.y) * margin),
        max(0.015, abs(span.z) * margin),
    ))
    return (mn - pad, mx + pad)

def _sabershader109b312_world_outside(co_world, envelope):
    if not envelope:
        return False
    mn, mx = envelope
    return (
        co_world.x < mn.x or co_world.x > mx.x or
        co_world.y < mn.y or co_world.y > mx.y or
        co_world.z < mn.z or co_world.z > mx.z
    )

def _sabershader109b312_bake_solidify_and_clip(dup, char_name, family, envelope, settings=None):
    info = {
        'baked': False,
        'faces_removed': 0,
        'edges_removed': 0,
        'verts_removed': 0,
        'outside_before': 0,
        'mode': 'off',
    }
    enabled = bool(getattr(settings, 'build_post_solidify_envelope_clamp_v109b312', True)) if settings else True
    if not enabled or not dup or not str(char_name).lower().startswith('doloris') or not envelope:
        return info

    depsgraph = bpy.context.evaluated_depsgraph_get()
    old_mesh = getattr(dup, 'data', None)
    try:
        try:
            depsgraph.update()
        except Exception:
            pass
        eval_dup = dup.evaluated_get(depsgraph)
        baked = bpy.data.meshes.new_from_object(
            eval_dup,
            preserve_all_data_layers=True,
            depsgraph=depsgraph,
        )
        baked.name = f'SaberShader_B312_PostSolidify__{old_mesh.name if old_mesh else dup.name}'
        dup.data = baked
        for mod in list(dup.modifiers):
            try:
                dup.modifiers.remove(mod)
            except Exception:
                pass

        bm = bmesh.new()
        try:
            bm.from_mesh(baked)
            mw = dup.matrix_world.copy()
            bad_faces = set()
            outside_verts = set()
            for f in list(bm.faces):
                face_outside = False
                for v in f.verts:
                    try:
                        wco = mw @ v.co
                    except Exception:
                        wco = v.co
                    if _sabershader109b312_world_outside(wco, envelope):
                        outside_verts.add(v)
                        face_outside = True
                if face_outside:
                    bad_faces.add(f)
            info['outside_before'] = len(outside_verts)
            if bad_faces:
                info['faces_removed'] = len(bad_faces)
                bmesh.ops.delete(bm, geom=list(bad_faces), context='FACES')

            loose_edges = [e for e in bm.edges if not e.link_faces]
            if loose_edges:
                info['edges_removed'] = len(loose_edges)
                bmesh.ops.delete(bm, geom=loose_edges, context='EDGES')
            loose_verts = [v for v in bm.verts if not v.link_faces and not v.link_edges]
            if loose_verts:
                info['verts_removed'] = len(loose_verts)
                bmesh.ops.delete(bm, geom=loose_verts, context='VERTS')
            bm.to_mesh(baked)
        finally:
            bm.free()

        baked.update()
        try:
            baked.validate(clean_customdata=False)
        except Exception:
            pass
        info['baked'] = True
        info['mode'] = 'post_solidify_envelope_clamped'
        if old_mesh is not None and getattr(old_mesh, 'users', 1) == 0:
            try:
                bpy.data.meshes.remove(old_mesh)
            except Exception:
                pass
        if info['faces_removed'] or info['outside_before']:
            log(
                f"  [V10.9B3.12 clamp] {dup.name}: family={family} "
                f"outsideVerts={info['outside_before']} facesRemoved={info['faces_removed']} "
                f"edgesRemoved={info['edges_removed']} vertsRemoved={info['verts_removed']}"
            )
    except Exception as exc:
        info['mode'] = 'post_solidify_clamp_failed'
        log(f'  [V10.9B3.12 clamp warning] {dup.name}: {exc}')
    return info

def _sabershader107a_shell_thickness(profile, family, obj, settings, char_scale, char_name=None):
    base = SABERSHADER107A_FAMILY_BASE.get(profile, SABERSHADER107A_FAMILY_BASE['AVE']).get(family, 0.0022)
    strength = float(getattr(settings, 'safe_silhouette_strength', 1.0)) if settings else 1.0
    equalize = _sabershader109b3_doloris_outline_multiplier(char_name, family, settings)
    tuning = _sabershader109b33_doloris_outline_tuning_multiplier(char_name, family, settings)
    series_match = _sabershader109b36_ultrafine_series_multiplier(char_name, family, settings)
    artifact_trim = _sabershader109b37_doloris_artifact_multiplier(char_name, family, settings)
    oblivionis_match = _sabershader109b37_oblivionis_match_multiplier(char_name, family, settings)
    oblivionis_final = _sabershader109b38_oblivionis_final_multiplier(char_name, settings)
    return base * char_scale * _sabershader107a_camera_factor(obj) * strength * equalize * tuning * series_match * artifact_trim * oblivionis_match * oblivionis_final

def _sabershader107a_build_shell_object(src_obj, char_name, family, profile, settings, target_collection, char_scale, material_indices=None, source_label=None, character_envelope=None):
    dup = src_obj.copy()
    sanitized_mesh, sanitation_info = _sabershader109b310_make_sanitized_shell_mesh(src_obj, settings)
    if sanitized_mesh is None:
        return None
    dup.data = sanitized_mesh
    dup.animation_data_clear()
    source_tag = source_label or src_obj.name
    dup.name = f"{SABERSHADER107A_OBJECT_PREFIX}{char_name}__{src_obj.name}__{family}"
    dup.matrix_world = src_obj.matrix_world.copy()
    dup.parent = src_obj.parent
    dup.parent_type = src_obj.parent_type
    dup.parent_bone = src_obj.parent_bone
    target_collection.objects.link(dup)

    _sabershader109b310_sanitize_shell_modifiers(dup, sanitation_info, settings)

    mesh = dup.data
    if material_indices:
        ok = _sabershader107a_prune_mesh_to_material_indices(mesh, material_indices, settings)
        if not ok:
            bpy.data.objects.remove(dup, do_unlink=True)
            return None

    freeze311 = _sabershader109b311_freeze_shell_after_armature(dup, char_name, settings)
    mesh = dup.data

    inv = _sabershader107a_get_material(char_name, invisible=True, settings=settings)
    outline = _sabershader107a_get_material(char_name, family=family, invisible=False, settings=settings)
    try:
        mesh.materials.clear()
    except Exception:
        while len(mesh.materials):
            mesh.materials.pop(index=len(mesh.materials)-1)
    mesh.materials.append(inv)
    mesh.materials.append(outline)
    for poly in mesh.polygons:
        poly.material_index = 0

    for mod in list(dup.modifiers):
        if mod.type in {'LINEART', 'GREASEPENCIL_LINEART'}:
            dup.modifiers.remove(mod)

    solid = dup.modifiers.new(name='SaberShader V10.7A.1 • Safe Silhouette Cleanup', type='SOLIDIFY')
    solid.thickness = _sabershader107a_shell_thickness(profile, family, src_obj, settings, char_scale, char_name=char_name)
    solid.offset = 1.0
    solid.material_offset = 1
    if hasattr(solid, 'use_flip_normals'):
        solid.use_flip_normals = True
    b37_skin_cleanup = (
        settings
        and bool(getattr(settings, 'build_outline_artifact_cleanup_v109b37', True))
        and str(char_name).lower().startswith('doloris')
        and str(family) == 'skin'
    )
    if hasattr(solid, 'use_even_offset'):

        solid.use_even_offset = not bool(b37_skin_cleanup)
    if hasattr(solid, 'use_quality_normals'):
        solid.use_quality_normals = True
    if hasattr(solid, 'use_rim'):
        solid.use_rim = False
    if hasattr(solid, 'thickness_clamp'):
        solid.thickness_clamp = float(getattr(settings, 'doloris_skin_solidify_clamp_v109b37', 0.55)) if b37_skin_cleanup else 0.0

    solid_thickness = float(solid.thickness)
    clamp312 = _sabershader109b312_bake_solidify_and_clip(
        dup, char_name, family, character_envelope, settings
    )
    mesh = dup.data

    dup.hide_select = True
    dup.show_name = False
    dup.show_in_front = False
    try:
        dup.visible_shadow = False
    except Exception:
        pass
    dup['SaberShader_V10_7A_SafeSilhouette'] = True
    dup['SaberShader_V10_7A_Character'] = char_name
    dup['SaberShader_V10_7A_Family'] = family
    dup['SaberShader_V10_7A_SourceObject'] = src_obj.name
    dup['SaberShader_V10_7A_SourceGroup'] = source_tag
    dup['SaberShader_V10_7A_SourceMaterialIndices'] = ','.join(str(int(i)) for i in (material_indices or []))
    dup['SaberShader_V10_7A_Thickness'] = solid_thickness
    dup['SaberShader_V10_9B3_OutlineEqualization'] = float(_sabershader109b3_doloris_outline_multiplier(char_name, family, settings))
    dup['SaberShader_V10_9B3_3_ThicknessTuning'] = float(_sabershader109b33_doloris_outline_tuning_multiplier(char_name, family, settings))
    dup['SaberShader_V10_9B3_4_SeriesOutlineMatch'] = float(_sabershader109b34_series_outline_multiplier(char_name, family, settings))
    dup['SaberShader_V10_9B3_5_SeriesInkFinal'] = float(_sabershader109b35_series_ink_multiplier(char_name, family, settings))
    dup['SaberShader_V10_9B3_6_UltraFineSeries'] = float(_sabershader109b36_ultrafine_series_multiplier(char_name, family, settings))
    dup['SaberShader_V10_9B3_7_DolorisArtifactTrim'] = float(_sabershader109b37_doloris_artifact_multiplier(char_name, family, settings))
    dup['SaberShader_V10_9B3_7_OblivionisMatch'] = float(_sabershader109b37_oblivionis_match_multiplier(char_name, family, settings))
    dup['SaberShader_V10_9B3_8_OblivionisFinalTrim'] = float(_sabershader109b38_oblivionis_final_multiplier(char_name, settings))
    dup['SaberShader_V10_9B3_9_RemoteSpikeFacesRemoved'] = int(mesh.get('SaberShader_V10_9B3_9_RemoteSpikeFacesRemoved', 0))
    dup['SaberShader_V10_9B3_7_PathologicalFacesRemoved'] = int(mesh.get('SaberShader_V10_9B3_7_PathologicalFacesRemoved', 0))
    dup['SaberShader_V10_9B3_10_ShellSanitation'] = True
    dup['SaberShader_V10_9B3_10_SanitationMode'] = str(sanitation_info.get('mode', 'unknown'))
    dup['SaberShader_V10_9B3_10_SourceShapeKeys'] = int(sanitation_info.get('shape_keys', 0))
    dup['SaberShader_V10_9B3_10_KeptModifiers'] = ' | '.join(sanitation_info.get('kept_modifiers', []))
    dup['SaberShader_V10_9B3_10_StrippedModifiers'] = ' | '.join(sanitation_info.get('stripped_modifiers', []))
    dup['SaberShader_V10_9B3_11_PostArmatureFreeze'] = bool(freeze311.get('frozen', False))
    dup['SaberShader_V10_9B3_11_FreezeMode'] = str(freeze311.get('mode', 'off'))
    dup['SaberShader_V10_9B3_11_PostFacesRemoved'] = int(freeze311.get('faces_removed', 0))
    dup['SaberShader_V10_9B3_11_PostEdgesRemoved'] = int(freeze311.get('edges_removed', 0))
    dup['SaberShader_V10_9B3_12_PostSolidifyClamp'] = bool(clamp312.get('baked', False))
    dup['SaberShader_V10_9B3_12_ClampMode'] = str(clamp312.get('mode', 'off'))
    dup['SaberShader_V10_9B3_12_OutsideVerts'] = int(clamp312.get('outside_before', 0))
    dup['SaberShader_V10_9B3_12_FacesRemoved'] = int(clamp312.get('faces_removed', 0))
    dup['SaberShader_V10_9B3_12_EdgesRemoved'] = int(clamp312.get('edges_removed', 0))
    dup['SaberShader_V10_9B3_12_VertsRemoved'] = int(clamp312.get('verts_removed', 0))
    return dup

def apply_v107a_safe_silhouette(char_name, settings=None, enabled=True):
    if not enabled:
        _sabershader107a_cleanup(char_name)
        return 0, 0
    removed = _sabershader107a_cleanup(char_name)
    if removed:
        log(f"V10.7A.1 Safe Silhouette Cleanup {char_name}: removed {removed} previous shell objects")
    items = _sabershader107a_collect_source_meshes(char_name)
    if not items:
        log(f"V10.7A.1 Safe Silhouette Cleanup {char_name}: no source meshes found")
        return 0, 0
    target = _sabershader107a_get_collection(char_name)
    profile = getattr(settings, 'shot_profile', 'AVE') if settings else 'AVE'
    char_scale = _sabershader107a_character_scale(items)
    character_envelope = _sabershader109b312_character_world_envelope(items, settings)
    built = 0
    skipped = 0
    for src_obj, mats, catset, cats in items:
        groups = _sabershader107a_material_groups_for_object(src_obj, mats, settings)
        used_per_material = False
        if groups:
            for group in groups:
                used_per_material = True
                family = group.get('family', 'cloth')
                if group.get('skip'):
                    skipped += 1
                    log(f"  [V10.9B3.2 skip] {char_name}/{src_obj.name}: group={group.get('label', family)} family={family} why={group.get('skip_reason', '')}")
                    continue
                dup = _sabershader107a_build_shell_object(
                    src_obj,
                    char_name,
                    family,
                    profile,
                    settings,
                    target,
                    char_scale,
                    material_indices=group.get('material_indices', []),
                    source_label=group.get('label', family),
                    character_envelope=character_envelope,
                )
                if dup is None:
                    skipped += 1
                    log(f"  [V10.9B3.2 skip] {char_name}/{src_obj.name}: group={group.get('label', family)} family={family} why=empty mesh after per-material prune")
                    continue
                built += 1
                log(
                    f"  [V10.9B3.2 shell] {char_name}/{src_obj.name}: group={group.get('label', family)} "
                    f"family={family} faces={group.get('poly_count', 0)} thickness={dup.get('SaberShader_V10_7A_Thickness', 0.0):.5f} "
                    f"eq={dup.get('SaberShader_V10_9B3_OutlineEqualization', 1.0):.2f}x trim={dup.get('SaberShader_V10_9B3_3_ThicknessTuning', 1.0):.2f}x series={dup.get('SaberShader_V10_9B3_4_SeriesOutlineMatch', 1.0):.2f}x ink35={dup.get('SaberShader_V10_9B3_5_SeriesInkFinal', 1.0):.2f}x ultra36={dup.get('SaberShader_V10_9B3_6_UltraFineSeries', 1.0):.2f}x art37={dup.get('SaberShader_V10_9B3_7_DolorisArtifactTrim', 1.0):.2f}x O37={dup.get('SaberShader_V10_9B3_7_OblivionisMatch', 1.0):.2f}x O38={dup.get('SaberShader_V10_9B3_8_OblivionisFinalTrim', 1.0):.2f}x removed37={int(dup.get('SaberShader_V10_9B3_7_PathologicalFacesRemoved', 0))} removed39={int(dup.get('SaberShader_V10_9B3_9_RemoteSpikeFacesRemoved', 0))} san310={dup.get('SaberShader_V10_9B3_10_SanitationMode', 'off')} keys310={int(dup.get('SaberShader_V10_9B3_10_SourceShapeKeys', 0))}"
                )
        if used_per_material:
            continue

        family = _sabershader107a_family_from_categories(src_obj, mats, catset, cats)
        skip, why = _sabershader107a_should_skip(src_obj, mats, family, catset, cats, settings)
        if skip:
            skipped += 1
            log(f"  [V10.7A.1 skip] {char_name}/{src_obj.name}: family={family} why={why}")
            continue
        dup = _sabershader107a_build_shell_object(src_obj, char_name, family, profile, settings, target, char_scale, character_envelope=character_envelope)
        if dup is None:
            skipped += 1
            log(f"  [V10.9B3.2 skip] {char_name}/{src_obj.name}: family={family} why=empty mesh in fallback build")
            continue
        built += 1
        log(f"  [V10.9B3.2 fallback shell] {char_name}/{src_obj.name}: family={family} thickness={dup.get('SaberShader_V10_7A_Thickness', 0.0):.5f} eq={dup.get('SaberShader_V10_9B3_OutlineEqualization', 1.0):.2f}x trim={dup.get('SaberShader_V10_9B3_3_ThicknessTuning', 1.0):.2f}x series={dup.get('SaberShader_V10_9B3_4_SeriesOutlineMatch', 1.0):.2f}x ink35={dup.get('SaberShader_V10_9B3_5_SeriesInkFinal', 1.0):.2f}x ultra36={dup.get('SaberShader_V10_9B3_6_UltraFineSeries', 1.0):.2f}x art37={dup.get('SaberShader_V10_9B3_7_DolorisArtifactTrim', 1.0):.2f}x O37={dup.get('SaberShader_V10_9B3_7_OblivionisMatch', 1.0):.2f}x O38={dup.get('SaberShader_V10_9B3_8_OblivionisFinalTrim', 1.0):.2f}x removed37={int(dup.get('SaberShader_V10_9B3_7_PathologicalFacesRemoved', 0))} removed39={int(dup.get('SaberShader_V10_9B3_9_RemoteSpikeFacesRemoved', 0))} san310={dup.get('SaberShader_V10_9B3_10_SanitationMode', 'off')} keys310={int(dup.get('SaberShader_V10_9B3_10_SourceShapeKeys', 0))}")
    target.hide_viewport = False
    target.hide_render = False
    return built, skipped

SABERSHADER109B31_AUDIT_TEXT = "SaberShader V10.9B3.1 • Outline Pipeline Audit"
SABERSHADER109B31_AUDIT_FILENAME = "SaberShader_V10_9B3_1_OutlinePipelineAudit.txt"

def _sabershader109b31_fmt_vec(vec, digits=5):
    try:
        return '(' + ', '.join(f'{float(v):.{digits}f}' for v in vec[:3]) + ')'
    except Exception:
        try:
            return str(tuple(vec))
        except Exception:
            return str(vec)

def _sabershader109b31_world_scale(obj):
    try:
        sc = obj.matrix_world.to_scale()
        vals = [abs(float(sc.x)), abs(float(sc.y)), abs(float(sc.z))]
    except Exception:
        try:
            vals = [abs(float(v)) for v in obj.scale[:3]]
        except Exception:
            vals = [1.0, 1.0, 1.0]
    vals = [max(1e-8, v) for v in vals]
    return vals

def _sabershader109b31_det(obj):
    try:
        return float(obj.matrix_world.to_3x3().determinant())
    except Exception:
        return 0.0

def _sabershader109b31_eval_poly_count(obj):
    try:
        depsgraph = bpy.context.evaluated_depsgraph_get()
        eo = obj.evaluated_get(depsgraph)
        mesh = eo.to_mesh()
        try:
            return len(mesh.polygons)
        finally:
            eo.to_mesh_clear()
    except Exception:
        try:
            return len(obj.data.polygons)
        except Exception:
            return -1

def _sabershader109b31_collection_flags(obj):
    flags = []
    try:
        for col in obj.users_collection:
            flags.append(
                f"{col.name}[viewport={getattr(col, 'hide_viewport', False)}, render={getattr(col, 'hide_render', False)}]"
            )
    except Exception:
        pass
    return ', '.join(flags) if flags else '<no collection>'

def _sabershader109b31_mat_summary(mat):
    if mat is None:
        return '<None>'
    bits = [mat.name]
    try:
        bits.append(f"cat={mat.get('SaberShader_V8_Category', '')}")
    except Exception:
        pass
    try:
        bits.append(f"cull={bool(getattr(mat, 'use_backface_culling', False))}")
    except Exception:
        pass
    try:
        bits.append(f"blend={getattr(mat, 'surface_render_method', getattr(mat, 'blend_method', 'n/a'))}")
    except Exception:
        pass
    return '{' + ', '.join(bits) + '}'

def _sabershader109b31_modifier_summary(obj):
    rows = []
    for mod in getattr(obj, 'modifiers', []):
        try:
            row = f"{mod.name}:{mod.type}[viewport={mod.show_viewport}, render={mod.show_render}]"
            if mod.type == 'SOLIDIFY':
                row += (
                    f" thickness={float(mod.thickness):.7f} offset={float(mod.offset):.3f}"
                    f" matOff={int(mod.material_offset)} flip={bool(getattr(mod, 'use_flip_normals', False))}"
                    f" even={bool(getattr(mod, 'use_even_offset', False))} rim={bool(getattr(mod, 'use_rim', True))}"
                )
            rows.append(row)
        except Exception as exc:
            rows.append(f"<modifier read error: {exc}>")
    return rows

def _sabershader109b31_shells_for_source(char_name, source_name):
    out = []
    for obj in bpy.data.objects:
        if obj.type != 'MESH':
            continue
        if not bool(obj.get('SaberShader_V10_7A_SafeSilhouette', False)):
            continue
        if str(obj.get('SaberShader_V10_7A_Character', '')) != str(char_name):
            continue
        if str(obj.get('SaberShader_V10_7A_SourceObject', '')) == str(source_name):
            out.append(obj)
    return out

def _sabershader109b31_find_solidify(shell):
    for mod in getattr(shell, 'modifiers', []):
        if mod.type == 'SOLIDIFY' and ('Safe Silhouette' in mod.name or 'Silhouette' in mod.name):
            return mod
    for mod in getattr(shell, 'modifiers', []):
        if mod.type == 'SOLIDIFY':
            return mod
    return None

def _sabershader109b31_outline_material(shell):
    try:
        for slot in shell.material_slots:
            mat = slot.material
            if mat and bool(mat.get('SaberShader_V10_7A_SafeSilhouette', False)) and str(mat.get('SaberShader_V10_7A_Family', '')) != 'invisible':
                return mat
    except Exception:
        pass
    try:
        return shell.material_slots[1].material if len(shell.material_slots) > 1 else None
    except Exception:
        return None

def _sabershader109b31_source_edge_candidates(src_obj):
    hits = []
    for mod in getattr(src_obj, 'modifiers', []):
        name = str(getattr(mod, 'name', '')).lower()
        if mod.type == 'SOLIDIFY' or 'edge' in name or 'outline' in name or 'toon' in name:
            hits.append(f"modifier:{mod.name}:{mod.type}")
    for slot in getattr(src_obj, 'material_slots', []):
        mat = slot.material
        if not mat:
            continue
        n = mat.name.lower()
        if 'edge' in n or 'outline' in n or 'toon' in n:
            hits.append(f"material:{mat.name}")
    return hits

def _sabershader109b31_text_datablock(report):
    txt = bpy.data.texts.get(SABERSHADER109B31_AUDIT_TEXT)
    if txt is None:
        txt = bpy.data.texts.new(SABERSHADER109B31_AUDIT_TEXT)
    try:
        txt.clear()
        txt.write(report)
    except Exception:
        try:
            txt.from_string(report)
        except Exception:
            pass
    return txt

def _sabershader109b31_write_report_file(report, settings):
    if not bool(getattr(settings, 'outline_audit_write_file_v109b31', True)):
        return None
    if not bpy.data.filepath:
        return None
    try:
        out = Path(bpy.data.filepath).with_name(SABERSHADER109B31_AUDIT_FILENAME)
        out.write_text(report, encoding='utf-8')
        return out
    except Exception as exc:
        log(f"V10.9B3.1 audit file warning: {exc}")
        return None

def _sabershader109b31_outline_pipeline_audit(settings, write_disk=True):
    verbose = bool(getattr(settings, 'outline_audit_verbose_v109b31', True)) if settings else True
    lines = []
    warnings = []
    metrics = {}

    def add(s=''):
        lines.append(str(s))

    add('=' * 100)
    add('SaberShader SABERSHADER — V10.9B3.1 OUTLINE PIPELINE AUDIT')
    add('READ-ONLY DIAGNOSTIC: no thickness / normals / material / UV fixes are applied here')
    add(f'Blender: {bpy.app.version_string}')
    add(f'Blend: {bpy.data.filepath or "<unsaved>"}')
    try:
        cam = bpy.context.scene.camera
        add(f'Camera: {cam.name if cam else "<none>"}')
    except Exception:
        add('Camera: <error>')
    if settings:
        add(
            'Current silhouette settings: '
            f'strength={float(getattr(settings, "safe_silhouette_strength", 1.0)):.3f}, '
            f'props={bool(getattr(settings, "safe_silhouette_include_props", False))}, '
            f'B3_equalize={bool(getattr(settings, "build_doloris_outline_equalization_v109b3", True))}, '
            f'D_global={float(getattr(settings, "doloris_outline_gain_v109b3", 1.0)):.3f}, '
            f'B3_3_tune={bool(getattr(settings, "build_doloris_outline_thickness_tuning_v109b33", True))}, '
            f'D_trim={float(getattr(settings, "doloris_outline_global_trim_v109b33", 1.0)):.3f}, ' f'B3_4_series={bool(getattr(settings, "build_ave_outline_reference_match_v109b34", True))}, ' f'B3_5_ink={bool(getattr(settings, "build_series_ink_clean_preview_v109b35", True))}, ' f'B3_6_ultrafine={bool(getattr(settings, "build_ultrafine_series_outline_v109b36", True))}, ' f'B3_7_cleanup={bool(getattr(settings, "build_outline_artifact_cleanup_v109b37", True))}, ' f'B3_7_Oblivionis={bool(getattr(settings, "build_oblivionis_outline_match_v109b37", True))}'
        )
    add('=' * 100)

    for char_name in ('Doloris', 'Oblivionis'):
        items = _sabershader107a_collect_source_meshes(char_name)
        char_scale = _sabershader107a_character_scale(items) if items else 1.0
        profile = getattr(settings, 'shot_profile', 'AVE') if settings else 'AVE'
        all_shells = [
            obj for obj in bpy.data.objects
            if obj.type == 'MESH'
            and bool(obj.get('SaberShader_V10_7A_SafeSilhouette', False))
            and str(obj.get('SaberShader_V10_7A_Character', '')) == char_name
        ]
        col = bpy.data.collections.get(f"{SABERSHADER107A_COLLECTION_PREFIX}{char_name}")
        add()
        add(f'### {char_name.upper()} ###')
        add(f'source_items={len(items)} shell_objects={len(all_shells)} char_scale={char_scale:.6f}')
        add(
            'silhouette_collection=' + (
                f'{col.name} viewport={getattr(col, "hide_viewport", False)} render={getattr(col, "hide_render", False)}'
                if col else '<MISSING>'
            )
        )
        if col is None:
            warnings.append(f'{char_name}: Safe Silhouette collection missing')

        family_counts = {}
        expected_shells = 0
        actual_expected_shells = 0
        thickness_rows = []
        missing = []

        for idx, (src_obj, mats, catset, cats) in enumerate(items, 1):
            family = _sabershader107a_family_from_categories(src_obj, mats, catset, cats)
            family_counts[family] = family_counts.get(family, 0) + 1
            skip, why = _sabershader107a_should_skip(src_obj, mats, family, catset, cats, settings)
            expected_local = _sabershader107a_shell_thickness(profile, family, src_obj, settings, char_scale, char_name=char_name)
            shells = _sabershader109b31_shells_for_source(char_name, src_obj.name)
            if not skip:
                expected_shells += 1
                if shells:
                    actual_expected_shells += 1
                else:
                    missing.append(src_obj.name)
                    warnings.append(f'{char_name}/{src_obj.name}: expected shell is missing')

            sc = _sabershader109b31_world_scale(src_obj)
            det = _sabershader109b31_det(src_obj)
            try:
                dims = tuple(float(v) for v in src_obj.dimensions[:3])
            except Exception:
                dims = (0.0, 0.0, 0.0)
            try:
                loc = tuple(float(v) for v in src_obj.matrix_world.translation[:3])
            except Exception:
                loc = (0.0, 0.0, 0.0)
            poly_count = len(src_obj.data.polygons) if getattr(src_obj, 'data', None) else -1
            eval_polys = _sabershader109b31_eval_poly_count(src_obj)

            add('-' * 100)
            add(
                f'[{idx:02d}] SOURCE {src_obj.name} | family={family} | '
                f'skip={skip}{(" (" + why + ")") if why else ""} | expected_local_thickness={expected_local:.7f}'
            )
            add(
                f'     local_scale={_sabershader109b31_fmt_vec(src_obj.scale)} world_scale={_sabershader109b31_fmt_vec(sc)} '
                f'det={det:.8f} mirrored={det < 0.0}'
            )
            add(f'     world_loc={_sabershader109b31_fmt_vec(loc)} dimensions={_sabershader109b31_fmt_vec(dims)} polys={poly_count} eval_polys={eval_polys}')
            add(
                f'     visible: hide_viewport={src_obj.hide_viewport} hide_render={src_obj.hide_render} '
                f'hide_get={src_obj.hide_get()} collections={_sabershader109b31_collection_flags(src_obj)}'
            )
            add(f'     parent={src_obj.parent.name if src_obj.parent else "<none>"} parent_type={getattr(src_obj, "parent_type", "") or "<none>"}')
            add(f'     categories={sorted(catset)}')
            if verbose:
                add('     materials=' + ', '.join(_sabershader109b31_mat_summary(m) for m in mats))
                mods = _sabershader109b31_modifier_summary(src_obj)
                add('     source_modifiers=' + (' | '.join(mods) if mods else '<none>'))
                edges = _sabershader109b31_source_edge_candidates(src_obj)
                add('     preexisting_edge_candidates=' + (' | '.join(edges) if edges else '<none>'))

            if not shells:
                add('     SHELL: <none>')
            for shell in shells:
                solid = _sabershader109b31_find_solidify(shell)
                outline_mat = _sabershader109b31_outline_material(shell)
                ssc = _sabershader109b31_world_scale(shell)
                sdet = _sabershader109b31_det(shell)
                local_th = float(solid.thickness) if solid else float(shell.get('SaberShader_V10_7A_Thickness', 0.0))
                world_min = abs(local_th) * min(ssc)
                world_avg = abs(local_th) * (sum(ssc) / 3.0)
                world_max = abs(local_th) * max(ssc)
                thickness_rows.append((family, local_th, world_min, world_avg, world_max))
                add(f'     SHELL {shell.name}')
                add(
                    f'       family_tag={shell.get("SaberShader_V10_7A_Family", "")} source_tag={shell.get("SaberShader_V10_7A_SourceObject", "")} '
                    f'B3_eq={float(shell.get("SaberShader_V10_9B3_OutlineEqualization", 1.0)):.3f}, ' f'B3_3_trim={float(shell.get("SaberShader_V10_9B3_3_ThicknessTuning", 1.0)):.3f}, ' f'B3_4_series={float(shell.get("SaberShader_V10_9B3_4_SeriesOutlineMatch", 1.0)):.3f}, ' f'B3_5_ink={float(shell.get("SaberShader_V10_9B3_5_SeriesInkFinal", 1.0)):.3f}, ' f'B3_6_ultra={float(shell.get("SaberShader_V10_9B3_6_UltraFineSeries", 1.0)):.3f}, ' f'B3_7_Dart={float(shell.get("SaberShader_V10_9B3_7_DolorisArtifactTrim", 1.0)):.3f}, ' f'B3_7_Omatch={float(shell.get("SaberShader_V10_9B3_7_OblivionisMatch", 1.0)):.3f}, ' f'B3_7_removed={int(shell.get("SaberShader_V10_9B3_7_PathologicalFacesRemoved", 0))}'
                )
                add(
                    f'       local_scale={_sabershader109b31_fmt_vec(shell.scale)} world_scale={_sabershader109b31_fmt_vec(ssc)} '
                    f'det={sdet:.8f} mirrored={sdet < 0.0}'
                )
                add(
                    f'       visibility: hide_viewport={shell.hide_viewport} hide_render={shell.hide_render} '
                    f'hide_get={shell.hide_get()} collections={_sabershader109b31_collection_flags(shell)}'
                )
                if solid:
                    add(
                        f'       SOLIDIFY thickness={local_th:.7f} offset={float(solid.offset):.3f} '
                        f'matOff={int(solid.material_offset)} flip={bool(getattr(solid, "use_flip_normals", False))} '
                        f'even={bool(getattr(solid, "use_even_offset", False))} rim={bool(getattr(solid, "use_rim", True))} '
                        f'viewport={solid.show_viewport} render={solid.show_render}'
                    )
                else:
                    add('       SOLIDIFY: <MISSING>')
                    warnings.append(f'{char_name}/{src_obj.name}: shell exists but Solidify modifier missing')
                add(
                    f'       approx_world_thickness[min/avg/max]={world_min:.7f}/{world_avg:.7f}/{world_max:.7f} '
                    f'(diagnostic range; non-uniform scale is normal-direction dependent)'
                )
                add(f'       outline_material={_sabershader109b31_mat_summary(outline_mat)}')
                if outline_mat is None:
                    warnings.append(f'{char_name}/{src_obj.name}: outline material missing')
                else:
                    if not bool(getattr(outline_mat, 'use_backface_culling', False)):
                        warnings.append(f'{char_name}/{src_obj.name}: outline material backface culling is OFF')
                if verbose:
                    smods = _sabershader109b31_modifier_summary(shell)
                    add('       shell_modifiers=' + (' | '.join(smods) if smods else '<none>'))
                    try:
                        slot_names = [slot.material.name if slot.material else '<None>' for slot in shell.material_slots]
                        add('       shell_material_slots=' + repr(slot_names))
                        dist = {}
                        for poly in shell.data.polygons:
                            dist[poly.material_index] = dist.get(poly.material_index, 0) + 1
                        add('       source_face_material_index_distribution=' + repr(dist))
                    except Exception as exc:
                        add(f'       material distribution read error: {exc}')

        metrics[char_name] = {
            'source_items': len(items),
            'shell_objects': len(all_shells),
            'expected_shells': expected_shells,
            'actual_expected_shells': actual_expected_shells,
            'family_counts': family_counts,
            'thickness_rows': thickness_rows,
            'missing': missing,
        }
        add('-' * 100)
        add(f'{char_name} FAMILY COUNTS: {family_counts}')
        add(f'{char_name} EXPECTED SHELLS: {expected_shells} | PRESENT: {actual_expected_shells} | MISSING: {missing or "none"}')
        if thickness_rows:
            av_local = sum(abs(r[1]) for r in thickness_rows) / len(thickness_rows)
            av_world = sum(r[3] for r in thickness_rows) / len(thickness_rows)
            add(f'{char_name} AVG SHELL THICKNESS: local={av_local:.7f} approx_world_avg={av_world:.7f}')
            metrics[char_name]['avg_local'] = av_local
            metrics[char_name]['avg_world'] = av_world

    add()
    add('=' * 100)
    add('CROSS-CHARACTER COMPARISON')
    d = metrics.get('Doloris', {})
    o = metrics.get('Oblivionis', {})
    add(f'Doloris source/shell/expected-present: {d.get("source_items",0)}/{d.get("shell_objects",0)}/{d.get("actual_expected_shells",0)}')
    add(f'Oblivionis source/shell/expected-present: {o.get("source_items",0)}/{o.get("shell_objects",0)}/{o.get("actual_expected_shells",0)}')
    if d.get('avg_world') is not None and o.get('avg_world') not in (None, 0.0):
        ratio = d['avg_world'] / o['avg_world']
        add(f'Approx average world-thickness ratio D/O = {ratio:.4f}')
        if ratio < 0.80:
            warnings.append(f'Doloris approx world shell thickness is substantially lower than Oblivionis (ratio={ratio:.3f})')
        elif ratio > 1.25:
            add('NOTE: Doloris approx shell thickness is already larger than Oblivionis; lack of visible outline is unlikely to be solved by more raw thickness alone.')
    add(f'Doloris families: {d.get("family_counts", {})}')
    add(f'Oblivionis families: {o.get("family_counts", {})}')

    add()
    add('=' * 100)
    add('WARNINGS / HIGH-VALUE CLUES')
    if warnings:
        for w in warnings:
            add('WARN: ' + w)
    else:
        add('No structural warning was detected by the audit. Compare source/shell family mapping and material/visibility rows above.')
    add('=' * 100)

    report = '\n'.join(lines) + '\n'
    _sabershader109b31_text_datablock(report)
    path = _sabershader109b31_write_report_file(report, settings) if write_disk else None
    scene = bpy.context.scene
    scene['SaberShader_V10_9B3_1_OutlineAudit'] = True
    scene['SaberShader_V10_9B3_1_AuditText'] = SABERSHADER109B31_AUDIT_TEXT
    scene['SaberShader_V10_9B3_1_AuditWarnings'] = len(warnings)
    if path:
        scene['SaberShader_V10_9B3_1_AuditFile'] = str(path)
    log(f'V10.9B3.1 Outline Pipeline Audit: report={SABERSHADER109B31_AUDIT_TEXT} warnings={len(warnings)} file={path if path else "Text datablock only"}')
    return {
        'report': report,
        'warnings': warnings,
        'metrics': metrics,
        'path': path,
        'text_name': SABERSHADER109B31_AUDIT_TEXT,
    }

SABERSHADER107B_COLLECTION_PREFIX = "SaberShader_V10_7B_Internal_"
SABERSHADER107B_OBJECT_PREFIX = "SaberShader_V10_7B_Accent__"
SABERSHADER107B_MAT_PREFIX = "SaberShader_V10_7B_Line_"
SABERSHADER107B_ELIGIBLE = {'hair', 'cloth', 'hand'}
SABERSHADER107B_ANGLE_DEG = {'hair': 34.0, 'cloth': 48.0, 'hand': 42.0}
SABERSHADER107B_BASE_CAP = {'hair': 48, 'cloth': 40, 'hand': 20}
SABERSHADER107B_BEVEL = {
    'AVE':  {'hair': 0.00034, 'cloth': 0.00038, 'hand': 0.00030},
    'MYGO': {'hair': 0.00030, 'cloth': 0.00033, 'hand': 0.00027},
}

def _sabershader107b_cleanup(char_name=None):
    removed = 0
    for obj in list(bpy.data.objects):
        if not obj or obj.type != 'CURVE':
            continue
        if not bool(obj.get('SaberShader_V10_7B_InternalAccent', False)):
            continue
        if char_name and str(obj.get('SaberShader_V10_7B_Character', '')) != str(char_name):
            continue
        bpy.data.objects.remove(obj, do_unlink=True)
        removed += 1
    for col in list(bpy.data.collections):
        if not col.name.startswith(SABERSHADER107B_COLLECTION_PREFIX):
            continue
        if char_name and col.name != f"{SABERSHADER107B_COLLECTION_PREFIX}{char_name}":
            continue
        try:
            bpy.data.collections.remove(col)
        except Exception:
            pass
    return removed

def _sabershader107b_get_collection(char_name):
    name = f"{SABERSHADER107B_COLLECTION_PREFIX}{char_name}"
    col = bpy.data.collections.get(name)
    if not col:
        col = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(col)
    col['SaberShader_V10_7B_InternalAccent'] = True
    col['SaberShader_V10_7B_Character'] = char_name
    return col

def _sabershader107b_material_family(mat):
    if not mat:
        return 'skip'
    cat = str(mat.get('SaberShader_V8_Category', '')).lower()
    name = mat.name.lower()
    blob = f"{cat} {name}"

    if any(tok in blob for tok in ('face', 'face2', 'eyes', 'mouth', 'expression', '表情', '面具')):
        return 'face'
    if 'hair' in blob:
        return 'hair'
    if any(tok in blob for tok in ('clothes4', '裙透', 'transparent', 'sheer', 'lace')):
        return 'transparent'
    if any(tok in blob for tok in ('stockings', 'stocks', '靴下', 'hosiery')):
        return 'stockings'
    if any(tok in blob for tok in ('guitar', 'instrument', 'deco1', 'deco2')):
        return 'prop'
    if any(tok in blob for tok in ('glove', 'hands', 'hand')):
        return 'hand'
    if any(tok in blob for tok in ('cloth', 'clothes', 'skirt', 'bow', 'tie', 'accessory', 'boots', '服', '裙')):
        return 'cloth'
    return 'skip'

def _sabershader107b_poly_family(src_obj, poly):
    try:
        idx = int(poly.material_index)
        if idx < 0 or idx >= len(src_obj.material_slots):
            return 'skip'
        return _sabershader107b_material_family(src_obj.material_slots[idx].material)
    except Exception:
        return 'skip'

def _sabershader107b_view_dir(world_point):
    cam = getattr(bpy.context.scene, 'camera', None)
    if not cam:
        return Vector((0.0, 0.0, 1.0))
    try:
        if getattr(cam.data, 'type', '') == 'ORTHO':
            return (cam.matrix_world.to_quaternion() @ Vector((0.0, 0.0, 1.0))).normalized()
    except Exception:
        pass
    try:
        return (cam.matrix_world.translation - world_point).normalized()
    except Exception:
        return Vector((0.0, 0.0, 1.0))

def _sabershader107b_line_color(char_name, family):
    base = _sabershader9_outline_color(char_name)

    mul = {'hair': 1.75, 'cloth': 1.60, 'hand': 1.55}.get(family, 1.6)
    rgb = tuple(max(0.0, min(0.08, float(c) * mul)) for c in base[:3])
    return rgb + (1.0,)

def _sabershader107b_get_material(char_name, family):
    name = f"{SABERSHADER107B_MAT_PREFIX}{char_name}_{family}"
    mat = bpy.data.materials.get(name)
    if not mat:
        mat = bpy.data.materials.new(name)
    mat.use_nodes = True
    nodes = mat.node_tree.nodes
    links = mat.node_tree.links
    nodes.clear()
    out = nodes.new('ShaderNodeOutputMaterial')
    em = nodes.new('ShaderNodeEmission')
    out.location = (220, 0)
    em.location = (0, 0)
    color = _sabershader107b_line_color(char_name, family)
    em.inputs['Color'].default_value = color
    em.inputs['Strength'].default_value = {'hair': 0.92, 'cloth': 0.95, 'hand': 0.90}.get(family, 0.92)
    links.new(em.outputs['Emission'], out.inputs['Surface'])
    mat.diffuse_color = color
    if hasattr(mat, 'blend_method'):
        mat.blend_method = 'OPAQUE'
    if hasattr(mat, 'use_backface_culling'):
        mat.use_backface_culling = True
    mat['SaberShader_V10_7B_InternalAccent'] = True
    mat['SaberShader_V10_7B_Character'] = char_name
    mat['SaberShader_V10_7B_Family'] = family
    mat['SaberShader_V10_7B_NoLineArt'] = True
    return mat

def _sabershader107b_edge_face_map(mesh):
    mapping = [[] for _ in mesh.edges]
    for p in mesh.polygons:
        for li in p.loop_indices:
            try:
                ei = mesh.loops[li].edge_index
                mapping[ei].append(p.index)
            except Exception:
                pass
    return mapping

def _sabershader107b_candidate_segments(src_obj, char_scale, profile, settings):
    """Returns {family: [(score, p1, p2), ...]} from evaluated shot mesh."""
    deps = bpy.context.evaluated_depsgraph_get()
    eval_obj = src_obj.evaluated_get(deps)
    mesh = None
    out = {k: [] for k in SABERSHADER107B_ELIGIBLE}
    try:
        mesh = eval_obj.to_mesh()
        if not mesh or len(mesh.edges) == 0:
            return out
        face_map = _sabershader107b_edge_face_map(mesh)
        mw = eval_obj.matrix_world
        normal_mx = mw.to_3x3().inverted().transposed()
        min_len = 0.012 * char_scale
        depth_offset = 0.00055 * char_scale

        for edge in mesh.edges:
            faces = face_map[edge.index] if edge.index < len(face_map) else []

            if len(faces) != 2:
                continue
            p1 = mesh.polygons[faces[0]]
            p2 = mesh.polygons[faces[1]]
            f1 = _sabershader107b_poly_family(src_obj, p1)
            f2 = _sabershader107b_poly_family(src_obj, p2)

            if f1 not in SABERSHADER107B_ELIGIBLE or f2 not in SABERSHADER107B_ELIGIBLE:
                continue

            if f1 == 'hair' or f2 == 'hair':
                if f1 != 'hair' or f2 != 'hair':
                    continue
                family = 'hair'
            elif f1 == 'hand' and f2 == 'hand':
                family = 'hand'
            else:
                family = 'cloth'

            v0, v1 = edge.vertices
            a = mw @ mesh.vertices[v0].co
            b = mw @ mesh.vertices[v1].co
            length = (b - a).length
            if length < min_len:
                continue

            n1 = (normal_mx @ p1.normal).normalized()
            n2 = (normal_mx @ p2.normal).normalized()
            try:
                angle = math.degrees(n1.angle(n2))
            except Exception:
                continue
            material_boundary = int(p1.material_index) != int(p2.material_index)
            sharp = bool(getattr(edge, 'use_edge_sharp', False))
            threshold = float(SABERSHADER107B_ANGLE_DEG.get(family, 48.0))

            if not material_boundary and angle < threshold:
                continue
            if material_boundary and angle < 7.0:
                continue

            mid = (a + b) * 0.5
            view = _sabershader107b_view_dir(mid)
            d1 = max(-1.0, min(1.0, n1.dot(view)))
            d2 = max(-1.0, min(1.0, n2.dot(view)))

            if max(d1, d2) < 0.10:
                continue

            score = angle
            if material_boundary:
                score += 34.0
            if sharp:
                score += 12.0
            score += min(14.0, length * 45.0)

            score += max(0.0, min(d1, d2)) * 10.0

            va = (a + _sabershader107b_view_dir(a) * depth_offset).copy()
            vb = (b + _sabershader107b_view_dir(b) * depth_offset).copy()
            out[family].append((score, va, vb))
        return out
    finally:
        if mesh is not None:
            try:
                eval_obj.to_mesh_clear()
            except Exception:
                pass

def _sabershader107b_make_curve(char_name, family, segments, profile, settings, target_collection, char_scale):
    if not segments:
        return None
    curve_data = bpy.data.curves.new(f"{SABERSHADER107B_OBJECT_PREFIX}{char_name}_{family}_DATA", type='CURVE')
    curve_data.dimensions = '3D'
    curve_data.resolution_u = 1
    curve_data.resolution_v = 0
    curve_data.bevel_resolution = 0
    curve_data.fill_mode = 'FULL'
    if hasattr(curve_data, 'use_fill_caps'):
        curve_data.use_fill_caps = True
    strength = float(getattr(settings, 'internal_accent_strength', 1.0)) if settings else 1.0
    base = SABERSHADER107B_BEVEL.get(profile, SABERSHADER107B_BEVEL['AVE']).get(family, 0.00034)
    curve_data.bevel_depth = base * char_scale * strength
    curve_data.materials.append(_sabershader107b_get_material(char_name, family))

    for _score, a, b in segments:
        spline = curve_data.splines.new('POLY')
        spline.points.add(1)
        spline.points[0].co = (a.x, a.y, a.z, 1.0)
        spline.points[1].co = (b.x, b.y, b.z, 1.0)

    obj = bpy.data.objects.new(f"{SABERSHADER107B_OBJECT_PREFIX}{char_name}_{family}", curve_data)
    target_collection.objects.link(obj)
    obj.hide_select = True
    obj.show_in_front = False
    obj['SaberShader_V10_7B_InternalAccent'] = True
    obj['SaberShader_V10_7B_Character'] = char_name
    obj['SaberShader_V10_7B_Family'] = family
    obj['SaberShader_V10_7B_Segments'] = len(segments)
    obj['SaberShader_V10_7B_Bevel'] = float(curve_data.bevel_depth)
    obj['SaberShader_V10_7B_Frame'] = int(bpy.context.scene.frame_current)
    return obj

def apply_v107b_internal_accents(char_name, settings=None, enabled=True):
    if not enabled:
        _sabershader107b_cleanup(char_name)
        return 0, 0, 0
    removed = _sabershader107b_cleanup(char_name)
    if removed:
        log(f"V10.7B Internal {char_name}: removed {removed} previous curve objects")

    items = _sabershader107a_collect_source_meshes(char_name)
    if not items:
        log(f"V10.7B Internal {char_name}: no source meshes found")
        return 0, 0, 0
    profile = getattr(settings, 'shot_profile', 'AVE') if settings else 'AVE'
    density = float(getattr(settings, 'internal_accent_density', 0.62)) if settings else 0.62
    char_scale = _sabershader107a_character_scale(items)
    candidates = {k: [] for k in SABERSHADER107B_ELIGIBLE}
    source_count = 0

    for src_obj, _mats, _catset, _cats in items:
        source_count += 1
        try:
            found = _sabershader107b_candidate_segments(src_obj, char_scale, profile, settings)
        except Exception as exc:
            log(f"  [V10.7B skip source] {char_name}/{src_obj.name}: {exc}")
            continue
        for family, vals in found.items():
            candidates[family].extend(vals)

    target = _sabershader107b_get_collection(char_name)
    built_objects = 0
    total_segments = 0
    for family in ('hair', 'cloth', 'hand'):
        vals = candidates.get(family, [])
        vals.sort(key=lambda item: item[0], reverse=True)
        cap = max(1, int(round(SABERSHADER107B_BASE_CAP[family] * density)))
        selected = vals[:cap]
        if not selected:
            continue
        obj = _sabershader107b_make_curve(char_name, family, selected, profile, settings, target, char_scale)
        if obj:
            built_objects += 1
            total_segments += len(selected)
            log(f"  [V10.7B internal] {char_name}/{family}: candidates={len(vals)} kept={len(selected)} bevel={obj.get('SaberShader_V10_7B_Bevel', 0.0):.6f}")

    target.hide_viewport = False
    target.hide_render = False
    return built_objects, total_segments, source_count

SABERSHADER107C_COLLECTION_PREFIX = "SaberShader_V10_7C_Tertiary_"
SABERSHADER107C_OBJECT_PREFIX = "SaberShader_V10_7C_Marker__"

def _sabershader107c_cleanup(char_name=None):
    removed = 0
    for obj in list(bpy.data.objects):
        if not obj or not bool(obj.get('SaberShader_V10_7C_TertiaryFinish', False)):
            continue
        if char_name and str(obj.get('SaberShader_V10_7C_Character', '')) != str(char_name):
            continue
        bpy.data.objects.remove(obj, do_unlink=True)
        removed += 1
    for col in list(bpy.data.collections):
        if not col.name.startswith(SABERSHADER107C_COLLECTION_PREFIX):
            continue
        if char_name and col.name != f"{SABERSHADER107C_COLLECTION_PREFIX}{char_name}":
            continue
        try:
            bpy.data.collections.remove(col)
        except Exception:
            pass
    return removed

def _sabershader107c_collection(char_name):
    name = f"{SABERSHADER107C_COLLECTION_PREFIX}{char_name}"
    col = bpy.data.collections.get(name)
    if col is None:
        col = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(col)
    col['SaberShader_V10_7C_TertiaryFinish'] = True
    col['SaberShader_V10_7C_Character'] = char_name
    return col

def _sabershader107c_obj_world_bounds(obj):
    try:
        pts = [obj.matrix_world @ Vector(v) for v in obj.bound_box]
    except Exception:
        return None
    if not pts:
        return None
    mn = Vector((min(p.x for p in pts), min(p.y for p in pts), min(p.z for p in pts)))
    mx = Vector((max(p.x for p in pts), max(p.y for p in pts), max(p.z for p in pts)))
    return mn, mx

def _sabershader107c_family_bounds(char_name, target_family):
    items = _sabershader107a_collect_source_meshes(char_name)
    bounds = []
    for src_obj, mats, catset, cats in items:
        family = _sabershader107a_family_from_categories(src_obj, mats, catset, cats)
        if target_family == 'clothing':
            ok = family in {'cloth', 'stockings', 'transparent'}
        else:
            ok = family == target_family
        if not ok:
            continue
        bb = _sabershader107c_obj_world_bounds(src_obj)
        if bb is not None:
            bounds.append(bb)
    if not bounds:
        allb = _sabershader94_character_world_bounds(char_name)
        return allb
    mn = Vector((min(b[0].x for b in bounds), min(b[0].y for b in bounds), min(b[0].z for b in bounds)))
    mx = Vector((max(b[1].x for b in bounds), max(b[1].y for b in bounds), max(b[1].z for b in bounds)))
    return mn, mx

def _sabershader107c_zone_location(char_name, zone):
    all_bounds = _sabershader94_character_world_bounds(char_name)
    if all_bounds is None:
        return Vector((0.0, 0.0, 0.0))
    mn, mx = all_bounds
    center = (mn + mx) * 0.5
    span = mx - mn
    if zone == 'Face':
        bb = _sabershader107c_family_bounds(char_name, 'face') or all_bounds
        fmn, fmx = bb
        return Vector(((fmn.x + fmx.x) * 0.5, (fmn.y + fmx.y) * 0.5, fmn.z * 0.28 + fmx.z * 0.72))
    if zone == 'Hair':
        bb = _sabershader107c_family_bounds(char_name, 'hair') or all_bounds
        hmn, hmx = bb
        return Vector(((hmn.x + hmx.x) * 0.5, (hmn.y + hmx.y) * 0.5, hmn.z * 0.20 + hmx.z * 0.80))
    if zone == 'Clothing':
        bb = _sabershader107c_family_bounds(char_name, 'clothing') or all_bounds
        cmn, cmx = bb
        return Vector(((cmn.x + cmx.x) * 0.5, (cmn.y + cmx.y) * 0.5, cmn.z * 0.55 + cmx.z * 0.45))
    if zone == 'Silhouette':
        return Vector((center.x, center.y, mn.z * 0.40 + mx.z * 0.60))
    if zone == 'Skirt':
        bb = _sabershader107c_family_bounds(char_name, 'clothing') or all_bounds
        cmn, cmx = bb
        return Vector(((cmn.x + cmx.x) * 0.5, (cmn.y + cmx.y) * 0.5, cmn.z * 0.72 + cmx.z * 0.28))
    return center

def _sabershader107c_marker_size(char_name, zone, strength, guide_scale=0.35):
    bounds = _sabershader94_character_world_bounds(char_name)
    if bounds is None:
        base = 0.08
    else:
        span = bounds[1] - bounds[0]
        base = max(0.05, min(0.16, max(span.x, span.z) * 0.08))

    mul = {'Face': 0.72, 'Hair': 0.78, 'Clothing': 0.84, 'Silhouette': 0.90, 'Skirt': 0.82}.get(zone, 0.82)
    scale = max(0.10, min(1.00, float(guide_scale)))
    return base * mul * max(0.7, min(1.4, float(strength))) * scale

def _sabershader107c_make_marker(col, char_name, zone, location, size, strength, profile, visible=True):

    bpy.ops.object.empty_add(type='CIRCLE', location=location)
    obj = bpy.context.view_layer.objects.active
    if obj is None:
        return None
    obj.name = f"{SABERSHADER107C_OBJECT_PREFIX}{char_name}__{zone}"
    try:
        obj.empty_display_size = size
        obj.show_in_front = False
        obj.hide_render = True
        obj.hide_viewport = not bool(visible)
    except Exception:
        pass

    for c in list(obj.users_collection):
        try:
            c.objects.unlink(obj)
        except Exception:
            pass
    col.objects.link(obj)
    obj['SaberShader_V10_7C_TertiaryFinish'] = True
    obj['SaberShader_V10_7C_Character'] = char_name
    obj['SaberShader_V10_7C_Zone'] = zone
    obj['SaberShader_V10_7C_Profile'] = profile
    obj['SaberShader_V10_7C_Strength'] = float(strength)
    obj['SaberShader_V10_7C_GuideVisible'] = bool(visible)
    obj['SaberShader_V10_7C_GuideSize'] = float(size)
    instruction_map = {
        'Face': 'Face: prioriza pequeños lift/shadow en mejilla, puente nasal y borde inferior del flequillo. Mantén el dibujo mínimo.',
        'Hair': 'Hair: acentos ligeros en flequillo, separación de mechones clave y brillo de cinta; evita convertir todo el pelo en líneas.',
        'Clothing': 'Clothing: diseña sombra/luz en corsé, mangas y unión de capas. Prioriza lectura clara por planos.',
        'Skirt': 'Skirt: enfatiza sólo pliegues principales y transición entre capa opaca y tul transparente.',
        'Silhouette': 'Silhouette: revisa contorno general del plano; usa el shell como base y sólo corrige si algo se pierde contra el fondo.',
    }
    obj['SaberShader_V10_7C_Instruction'] = instruction_map.get(zone, 'Tertiary zone marker')
    return obj

def _sabershader107c_tag_gp_objects(char_name, settings):
    profile = getattr(settings, 'shot_profile', 'AVE') if settings else 'AVE'
    strength = float(getattr(settings, 'tertiary_finish_strength', 1.0)) if settings else 1.0
    tagged = 0
    kind_defaults = {
        'Light':  {'hint': 0.72 if profile == 'MYGO' else 0.86, 'zones': 'Face/Hair/Clothing'},
        'Shadow': {'hint': 0.74 if profile == 'MYGO' else 0.90, 'zones': 'Face/Clothing/Silhouette'},
        'Accent': {'hint': 0.58 if profile == 'MYGO' else 0.72, 'zones': 'Hair/Clothing/Silhouette'},
    }
    for kind in ('Light', 'Shadow', 'Accent'):
        obj = bpy.data.objects.get(f'{SABERSHADER93_TERT_PREFIX}{char_name} • {kind}')
        if not obj or obj.type != 'GREASEPENCIL':
            continue
        cfg = kind_defaults[kind]
        obj['SaberShader_V10_7C_TertiaryFinish'] = True
        obj['SaberShader_V10_7C_Character'] = char_name
        obj['SaberShader_V10_7C_Kind'] = kind
        obj['SaberShader_V10_7C_Profile'] = profile
        obj['SaberShader_V10_7C_Strength'] = strength
        obj['SaberShader_V10_7C_OpacityHint'] = float(max(0.20, min(1.0, cfg['hint'] * strength)))
        obj['SaberShader_V10_7C_Zones'] = cfg['zones']
        obj['SaberShader_V10_7C_Instruction'] = f'V10.7C {kind}: draw sparse, camera-specific tertiary accents. Prioritize {cfg["zones"]}.'
        tagged += 1
    return tagged

def apply_v107c_tertiary_finish(char_name, settings=None, enabled=True):
    if not enabled:
        _sabershader107c_cleanup(char_name)
        return 0, 0
    removed = _sabershader107c_cleanup(char_name)
    if removed:
        log(f"V10.7C Tertiary Finish {char_name}: removed {removed} previous markers")

    old = None
    created_layers = 0
    if settings is not None:
        try:
            old = bool(settings.build_tertiary_artist)
            settings.build_tertiary_artist = True
        except Exception:
            old = None
    try:
        created_layers = build_v94_tertiary_artist(char_name, settings)
    finally:
        if settings is not None and old is not None:
            try:
                settings.build_tertiary_artist = old
            except Exception:
                pass
    tagged = _sabershader107c_tag_gp_objects(char_name, settings)
    profile = getattr(settings, 'shot_profile', 'AVE') if settings else 'AVE'
    strength = float(getattr(settings, 'tertiary_finish_strength', 1.0)) if settings else 1.0
    guide_scale = float(getattr(settings, 'tertiary_guide_scale_v107c1', 0.35)) if settings else 0.35
    show_guides = bool(getattr(settings, 'show_tertiary_guides_v107c1', True)) if settings else True
    col = _sabershader107c_collection(char_name)
    try:
        col.hide_render = True
        col.hide_viewport = False
    except Exception:
        pass
    markers = 0
    for zone in ('Face', 'Hair', 'Clothing', 'Skirt', 'Silhouette'):
        loc = _sabershader107c_zone_location(char_name, zone)
        size = _sabershader107c_marker_size(char_name, zone, strength, guide_scale)
        obj = _sabershader107c_make_marker(col, char_name, zone, loc, size, strength, profile, show_guides)
        if obj is not None:
            markers += 1
            log(f"  [V10.7C.1 marker] {char_name}/{zone}: size={size:.4f} visible={show_guides}")
    scene = bpy.context.scene
    scene[f'SaberShader_V10_7C_{char_name}_Profile'] = profile
    scene[f'SaberShader_V10_7C_{char_name}_Strength'] = strength
    scene[f'SaberShader_V10_7C_{char_name}_Markers'] = markers
    scene[f'SaberShader_V10_7C_{char_name}_TaggedGP'] = tagged
    scene[f'SaberShader_V10_7C_{char_name}_GuideScale'] = guide_scale
    scene[f'SaberShader_V10_7C_{char_name}_GuidesVisible'] = show_guides
    return markers, created_layers + tagged

def save_copy():
    if not bpy.data.filepath:
        log("No copy saved: the current .blend has no filepath")
        return None
    src = Path(bpy.data.filepath)
    out = src.with_name("SaberShader_V1_1_3_7_2_1_Happy_Size_Recovery.blend")
    bpy.ops.wm.save_as_mainfile(filepath=str(out), copy=True)
    log(f"SAVED COPY: {out}")
    return out

