def _xdzr8_v1181_slot_role(slot_name):
    key = _sabershader11_key(str(slot_name or ''))
    if not key:
        return None
    role = _XDZR8_V1181_SLOT_ROLE_MAP.get(key)
    if role:
        return role

    tests = (
        ('sdflight', 'sdf_lightmap'), ('sdfmask', 'sdf_mask'),
        ('outlinemask', 'outline_mask'), ('difframp', 'diffuse_ramp'),
        ('specramp', 'specular_ramp'), ('splitnormal', 'split_normal'),
        ('shadowlut', 'shadow_lut'), ('highlight', 'highlight'),
        ('emotion', 'emotion'), ('matcap', 'matcap'), ('strokemap', 'stroke_map'),
        ('linemap', 'line_map'), ('furmap', 'fur_map'), ('vertexanimation', 'vertex_noise'),
        ('emission', 'emission'), ('normal', 'normal'), ('opacity', 'opacity'),
        ('alpha', 'opacity'), ('reflection', 'reflection'), ('environment', 'reflection'),
    )
    for token, candidate in tests:
        if token in key:
            return candidate
    return None

def _xdzr8_v1181_material_json_bindings(meta_files):
    """Read declarative texture-slot bindings from nearby material JSON files.

    Supports the common ``m_SavedProperties.m_TexEnvs`` representation emitted
    by asset exporters.  Unknown JSON is ignored.  Texture filename semantics are
    exported only when all source records agree on one role, preventing a shared
    atlas from being force-labelled when it feeds different slots.
    """
    records = []
    texture_role_sets = {}
    evidence = []
    for path in meta_files or []:
        if getattr(path, 'suffix', '').lower() != '.json':
            continue
        try:
            if path.stat().st_size > 16 * 1024 * 1024:
                continue
            data = json.loads(path.read_text(encoding='utf-8', errors='ignore'))
        except Exception:
            continue
        if not isinstance(data, dict):
            continue
        saved = data.get('m_SavedProperties') or data.get('SavedProperties') or {}
        texenvs = saved.get('m_TexEnvs') if isinstance(saved, dict) else None
        floats = saved.get('m_Floats') if isinstance(saved, dict) else {}
        if not isinstance(texenvs, dict):
            continue
        if not isinstance(floats, dict):
            floats = {}
        gray_as_alpha = False
        try:
            gray_as_alpha = float(floats.get('_UseGrayAsAlpha', 0.0) or 0.0) >= 0.5
        except Exception:
            gray_as_alpha = False
        mat_name = str(data.get('m_Name') or data.get('Name') or path.stem)
        slots = {}
        roles = {}
        for slot_name, payload in texenvs.items():
            if not isinstance(payload, dict):
                continue
            tex = payload.get('m_Texture') or payload.get('Texture') or {}
            tex_name = str(tex.get('Name') or tex.get('name') or '') if isinstance(tex, dict) else ''
            tex_name = Path(tex_name.replace('\\', '/')).name
            if not tex_name:
                continue
            role = _xdzr8_v1181_slot_role(slot_name)

            if gray_as_alpha and role == 'base':
                role = 'mask'
            slots[str(slot_name)] = tex_name
            if role:
                roles.setdefault(role, []).append(tex_name)
                texture_role_sets.setdefault(tex_name.casefold(), set()).add(role)
                evidence.append(f'{path.name}: {slot_name} -> {tex_name} = {role}')
        if slots:
            records.append({
                'material_name': mat_name,
                'source_file': path.name,
                'slots': slots,
                'roles': roles,
                'flags': {'gray_as_alpha': bool(gray_as_alpha)},
            })
    texture_roles = {}
    ambiguous = {}
    for tex_name, role_set in texture_role_sets.items():
        if len(role_set) == 1:
            texture_roles[tex_name] = next(iter(role_set))
        elif role_set:
            ambiguous[tex_name] = sorted(role_set)
    return records, texture_roles, ambiguous, evidence

def _xdzr8_v1181_build_binding_lookup(records):
    lookup = {}
    for rec in records or []:
        name = str(rec.get('material_name') or '')
        variants = {name.casefold(), re.sub(r'\.\d{3}$', '', name).casefold(), _sabershader11_key(name)}
        for key in variants:
            if key:
                lookup.setdefault(key, []).append(rec)
    return lookup

def _xdzr8_v1181_match_binding_records(mat, source_ref, intelligence=None):
    lookup = (intelligence or {}).get('binding_material_lookup') or {}
    names = []
    for candidate in (mat, source_ref):
        if candidate is None:
            continue
        try:
            name = str(candidate.get('SaberShader_V11_SourceMaterial', candidate.name) or candidate.name)
        except Exception:
            try: name = str(candidate.name)
            except Exception: name = ''
        if name:
            names.extend((name.casefold(), re.sub(r'\.\d{3}$', '', name).casefold(), _sabershader11_key(name)))
    found = []
    seen = set()
    for key in names:
        for rec in lookup.get(key, []):
            marker = (rec.get('source_file',''), rec.get('material_name',''))
            if marker not in seen:
                seen.add(marker); found.append(rec)
    return found

def _xdzr8_v1182_split_trailing_id(stem):
    """Return (prefix, id_token) only for a trailing separator-delimited 3–6 digit token."""
    raw = str(stem or '').casefold()
    m = re.match(r'^(.*[_\-.])(\d{3,6})$', raw)
    return (m.group(1), m.group(2)) if m else (raw, '')

def _xdzr8_v1181_detect_companion_dialects(image_paths):
    """Infer bundle-level conventions, shared-ID companions and exporter provenance.

    A shared auxiliary texture (for example an ID 0000 Base/Ctrl map) is NOT
    collapsed into one global family with every character-specific Diff texture.
    Instead we keep each primary family distinct and publish explicit per-family
    alias bindings. This prevents a texture directory containing many characters
    from turning into one giant ambiguous family.
    """
    groups = {}
    overrides = {}
    roots = {}
    evidence = []
    suffixes = (('_shad_c', 'shadow_color'), ('_diff', 'base'), ('_ctrl', 'control_map'), ('_base', 'region_map'), ('_rfl', 'reflection'))
    suffix_role = dict(suffixes)
    for path in image_paths or []:
        stem = path.stem.casefold()
        for suffix, role in suffixes:
            if stem.endswith(suffix):
                exact_root = stem[:-len(suffix)]
                groups.setdefault(exact_root, {})[suffix] = path
                overrides[path.name.casefold()] = role
                roots[path.name.casefold()] = _sabershader11_key(exact_root)
                break

    dialects = []
    family_rows = []
    cross_id_rows = []
    cross_aliases = {}
    qualified_any = False

    for root, members in groups.items():
        present = set(members)
        if '_diff' in present and '_base' in present and ({'_ctrl','_shad_c'} & present):
            qualified_any = True
            family_rows.append({'root': root, 'exact_roots': [root], 'cross_id': False, 'members': sorted(present)})
            evidence.append(f'{root}: companion bundle ' + '/'.join(sorted(present)))

    by_prefix = {}
    for root,members in groups.items():
        prefix, ident = _xdzr8_v1182_split_trailing_id(root)
        if ident:
            by_prefix.setdefault(prefix, []).append((root, ident, members))
    for prefix, rows in by_prefix.items():
        aux_rows = [(r,i,m) for r,i,m in rows if ('_base' in m or '_ctrl' in m)]
        primary_rows = [(r,i,m) for r,i,m in rows if '_diff' in m]
        for primary_root, primary_id, primary_members in primary_rows:
            missing = [s for s in ('_base','_ctrl') if s not in primary_members]
            if not missing:
                continue
            candidates=[]
            for aux_root,aux_id,aux_members in aux_rows:
                if aux_root == primary_root:
                    continue
                coverage=sum(1 for s in missing if s in aux_members)
                if coverage:
                    zero_bonus = 2 if set(aux_id) == {'0'} else 0
                    candidates.append((coverage, zero_bonus, aux_root, aux_id, aux_members))
            if not candidates:
                continue
            candidates.sort(key=lambda x:(-x[0],-x[1],x[2]))
            best=candidates[0]

            if len(candidates) > 1 and candidates[1][:2] == best[:2] and best[1] == 0:
                continue
            coverage,zero_bonus,aux_root,aux_id,aux_members=best
            aliases={}
            for suffix in missing:
                path=aux_members.get(suffix)
                if path is not None:
                    role=suffix_role[suffix]
                    aliases[role]=path
            if not aliases:
                continue
            qualified_any=True
            key=_sabershader11_key(primary_root)
            cross_aliases.setdefault(key, {}).update(aliases)
            all_members=set(primary_members)
            all_members.update(s for s in missing if s in aux_members)
            family_rows.append({
                'root': primary_root,
                'exact_roots': [primary_root, aux_root],
                'cross_id': True,
                'members': sorted(all_members),
                'shared_aux_root': aux_root,
            })
            row=f'{primary_root} <= {aux_root}: ' + ', '.join(f'{role}={path.name}' for role,path in sorted(aliases.items()))
            cross_id_rows.append(row)
            evidence.append(f'{primary_root}: cross-ID companion aliases from {aux_root}')

    if qualified_any:
        dialects.append('diff/base/ctrl/shad-c companion maps')
    if cross_id_rows:
        dialects.append('cross-ID companion families')

    derived_rows=[]
    eye_highlights=[]
    for path in image_paths or []:
        stem=path.stem.casefold()
        if re.search(r'(?:^|[_\-.])eye0$', stem) or re.search(r'_eye0$', stem):
            overrides.setdefault(path.name.casefold(), 'base')
            evidence.append(f'{path.name}: Uma eye0 base texture')
        if re.search(r'(?:^|[_\-.])eye\w*hi\d+$', stem) or re.search(r'eyehi\d+$', stem):
            overrides.setdefault(path.name.casefold(), 'highlight')
            eye_highlights.append(path.name)
            evidence.append(f'{path.name}: eye-highlight companion')
        elif re.search(r'eye\d*_all$', stem):
            overrides[path.name.casefold()]='derived_eye_atlas'
            derived_rows.append(f'{path.name}: exporter/full-eye atlas provenance')
            evidence.append(f'{path.name}: derived/full eye-atlas companion')
    if eye_highlights:
        dialects.append('eye-highlight companion maps')
    if derived_rows:
        dialects.append('derived eye-atlas provenance')
    meta={
        'families': family_rows,
        'cross_id_rows': cross_id_rows,
        'cross_id_count': len(cross_id_rows),
        'cross_id_aliases': cross_aliases,
        'derived_rows': derived_rows,
        'derived_count': len(derived_rows),
        'eye_highlights': sorted(eye_highlights),
    }
    return dialects, overrides, roots, evidence, meta

