def _sabershader_v101_fgo_scene_cluster(context):
    """Recover the visible/base FGO Arcade character from fragmented Noesis meshes."""
    sig = _sabershader_v101_fgo_scene_signature(context)
    if not sig.get('enabled', False):
        return [], 'LOW', 'FGO Arcade scene signature not detected'
    scene = getattr(context, 'scene', None)
    if scene is None:
        return [], 'LOW', 'missing scene'

    selected = {}
    reasons = {}
    def add(obj, why):
        if obj is None or getattr(obj, 'type', '') != 'MESH' or _sabershader11_is_helper_object(obj):
            return
        try:
            ptr = obj.as_pointer()
        except Exception:
            return
        selected[ptr] = obj
        reasons.setdefault(ptr, why)

    for obj in sig.get('model_meshes', []) or []:
        add(obj, 'FGO MODEL| base mesh block')
    for obj in sig.get('base_expression_meshes', []) or []:
        add(obj, 'FGO facial base mesh')

    safe_names = {'eye_l_geo', 'eye_r_geo', 'eye_l', 'eye_r', 'chest'}
    for obj in scene.objects:
        name = str(getattr(obj, 'name', '') or '').casefold()
        if name in safe_names:
            add(obj, 'FGO named base mesh')

    alt_expr = re.compile(
        r'^(?:face|cheek|eyebrow|eyehole|eyelashes|eyelid|oral|tooth)_(?!base(?:_0)?$)', re.I
    )
    for obj in scene.objects:
        if getattr(obj, 'type', '') != 'MESH':
            continue
        name = str(getattr(obj, 'name', '') or '')
        if alt_expr.match(name):
            continue
        try:
            if obj.hide_get() or bool(getattr(obj, 'hide_viewport', False)):
                continue
        except Exception:
            pass
        fgo_slots = 0
        for slot in getattr(obj, 'material_slots', []) or []:
            mat = getattr(slot, 'material', None)
            mname = str(getattr(mat, 'name', '') or '').casefold() if mat else ''
            if mname.startswith('mt_') and any(tok in mname for tok in ('face','hair','skin','cloth','armor','chestarm','eye','oral','cheek','gold')):
                fgo_slots += 1
        if fgo_slots:
            add(obj, f'visible FGO material mesh ({fgo_slots} slots)')

    result = list(selected.values())

    if len(result) < 4 or len(result) > 64:
        return [], 'LOW', f'FGO cluster unsafe size={len(result)}'
    return result, 'HIGH', f'FGO Arcade fragmented base cluster ({len(result)} meshes; score={sig.get("score",0.0):.1f})'

def _sabershader111_active_hierarchy_cluster(context):
    active = context.view_layer.objects.active if context and context.view_layer else None
    if not active:
        return [], 'LOW', 'no active object'
    arm = _sabershader111_armature_for_object(active)
    if arm:
        meshes, cluster_conf, cluster_note = _sabershader121_expand_armature_cluster(context.scene, arm)
        if meshes:
            return meshes, cluster_conf, f'active hierarchy resolved through armature {arm.name}; {cluster_note}'
    root = _sabershader111_root_parent(active)
    meshes = _sabershader111_descendant_meshes(root)

    if 1 < len(meshes) <= 80:
        return meshes, 'MEDIUM', f'active parent hierarchy {root.name}'
    if active.type == 'MESH' and not _sabershader11_is_helper_object(active):
        return [active], 'LOW', 'active mesh only; select the full character for a safer result'
    return [], 'LOW', 'active hierarchy did not contain a safe mesh cluster'

def _sabershader111_visible_meshes(scene):
    out = []
    for obj in scene.objects:
        if obj.type != 'MESH' or _sabershader11_is_helper_object(obj):
            continue
        try:
            if obj.hide_get() or obj.hide_viewport:
                continue
        except Exception:
            pass
        out.append(obj)
    return out

def _sabershader111_exclusion_reason(obj, target_armature=None):
    name = _sabershader11_key(getattr(obj, 'name', ''))
    if _sabershader1164_is_mmd_physics_helper(obj):
        return 'excluded MMD physics helper (rigid body / joint)'
    if _sabershader11_is_helper_object(obj):
        return 'SaberShader helper/generated object'
    stage_tokens = ('stage','floor','ground','wall','background','backdrop','sky','room','set','terrain','building','scenery')
    if any(token in name for token in stage_tokens):
        return 'scene/stage name heuristic'
    if target_armature and not _sabershader11_bound_to_armature(obj, target_armature):
        return 'outside expanded rig/root character cluster'
    return 'outside detected character cluster'

def _sabershader111_detection_result(objects, source, confidence, note, context, armature=None):

    unique, seen = [], set()
    for obj in objects or []:
        try:
            if not obj or obj.type != 'MESH' or _sabershader11_is_helper_object(obj):
                continue
            ptr = obj.as_pointer()
        except (ReferenceError, RuntimeError):
            continue
        if ptr not in seen:
            seen.add(ptr)
            unique.append(obj)
    excluded = []
    physics_helpers_excluded = 0
    for obj in context.scene.objects:
        if obj.type != 'MESH' or obj.as_pointer() in seen:
            continue
        reason = _sabershader111_exclusion_reason(obj, armature)
        if 'MMD physics helper' in reason:
            physics_helpers_excluded += 1
        excluded.append((obj, reason))
    return {
        'objects': unique,
        'source': source,
        'confidence': confidence,
        'note': note,
        'armature': armature,
        'excluded': excluded,
        'physics_helpers_excluded': physics_helpers_excluded,
    }

def _sabershader11_target_objects(context, settings):
    """V11.2.1 character detector with MMD/FBX multi-mesh cluster expansion."""
    mode = str(getattr(settings, 'universal_character_source', 'AUTO') or 'AUTO')
    col = getattr(settings, 'universal_target_collection', None)

    if mode == 'COLLECTION':
        if not col:
            return _sabershader111_detection_result([], 'Collection', 'LOW', 'Character Collection is not set', context)
        objs = _sabershader11_collection_meshes(col)
        return _sabershader111_detection_result(objs, f'Collection: {col.name}', 'HIGH', 'explicit character collection', context)

    if mode == 'ACTIVE_ARMATURE':
        active = context.view_layer.objects.active if context and context.view_layer else None
        arm = _sabershader111_armature_for_object(active)
        if not arm:
            selected_arms = [o for o in context.selected_objects if o.type == 'ARMATURE']
            arm = selected_arms[0] if len(selected_arms) == 1 else None
        if not arm:
            return _sabershader111_detection_result([], 'Active Armature', 'LOW', 'no active/unique selected armature found', context)
        objs, cluster_conf, cluster_note = _sabershader121_expand_armature_cluster(context.scene, arm)
        return _sabershader111_detection_result(objs, f'Active Armature: {arm.name}', cluster_conf, cluster_note, context, arm)

    if mode == 'SELECTED_OBJECTS':
        objs, confidence, note = _sabershader111_selected_mesh_cluster(context)
        arm = _sabershader111_armature_for_object(objs[0]) if objs else None
        return _sabershader111_detection_result(objs, 'Selected Objects', confidence, note, context, arm)

    if col:
        objs = _sabershader11_collection_meshes(col)
        if objs:
            return _sabershader111_detection_result(objs, f'Auto → Collection: {col.name}', 'HIGH', 'optional collection override', context)

    fgo_cluster, fgo_conf, fgo_note = _sabershader_v101_fgo_scene_cluster(context)
    if fgo_cluster:
        return _sabershader111_detection_result(fgo_cluster, 'Auto → Fate Grand Order Arcade Cluster', fgo_conf, fgo_note, context)

    arm, confidence, note = _sabershader111_scene_armature_guess(context)
    if arm:
        objs, cluster_conf, cluster_note = _sabershader121_expand_armature_cluster(context.scene, arm)
        if objs:
            rank = {'LOW': 0, 'MEDIUM': 1, 'HIGH': 2}
            final_conf = confidence if rank.get(confidence, 0) <= rank.get(cluster_conf, 0) else cluster_conf
            combined_note = f'{note}; {cluster_note}'
            return _sabershader111_detection_result(objs, f'Auto → Armature: {arm.name}', final_conf, combined_note, context, arm)

    selected, s_conf, s_note = _sabershader111_selected_mesh_cluster(context)
    if selected:
        arm = _sabershader111_armature_for_object(selected[0])
        return _sabershader111_detection_result(selected, 'Auto → Selection', s_conf, s_note, context, arm)

    hierarchy, h_conf, h_note = _sabershader111_active_hierarchy_cluster(context)
    if hierarchy:
        arm = _sabershader111_armature_for_object(hierarchy[0])
        return _sabershader111_detection_result(hierarchy, 'Auto → Active Hierarchy', h_conf, h_note, context, arm)

    _xdzr8_build_progress_update(context, 12, 'Reference scene preflight', force_redraw=True)
    visible = _sabershader111_visible_meshes(context.scene)
    if len(visible) == 1:
        return _sabershader111_detection_result(visible, 'Auto → Single Visible Mesh', 'MEDIUM', 'only one visible non-helper mesh exists', context)

    return _sabershader111_detection_result(
        [], 'Auto', 'LOW',
        f'could not isolate one character safely ({len(visible)} visible meshes); select the character or its armature',
        context,
    )

def _sabershader11_materials_from_objects(objects):
    mats, seen = [], set()
    for obj in objects:
        for slot in getattr(obj, 'material_slots', []):
            mat = slot.material
            if mat and mat.as_pointer() not in seen:
                seen.add(mat.as_pointer())
                mats.append(mat)
    return mats

def _sabershader11_principled(mat):
    if not mat or not mat.use_nodes or not mat.node_tree:
        return None
    for n in mat.node_tree.nodes:
        if n.bl_idname == 'ShaderNodeBsdfPrincipled':
            return n
    return None

def _sabershader11_socket_default(node, name, fallback=None):
    if not node:
        return fallback
    sock = node.inputs.get(name) if hasattr(node, 'inputs') else None
    return sock.default_value if sock is not None else fallback

def _sabershader11_image_from_socket(socket, visited=None):
    if socket is None or not getattr(socket, 'is_linked', False):
        return None
    visited = visited or set()
    for link in socket.links:
        node = link.from_node
        if not node or node.as_pointer() in visited:
            continue
        visited.add(node.as_pointer())
        if node.bl_idname == 'ShaderNodeTexImage' and getattr(node, 'image', None):
            return node.image
        for inp in getattr(node, 'inputs', []):
            img = _sabershader11_image_from_socket(inp, visited)
            if img:
                return img
    return None

def _sabershader11_existing_role_images(mat):
    result = {}
    principled = _sabershader11_principled(mat)
    if principled:
        mapping = {
            'base': 'Base Color', 'normal': 'Normal', 'roughness': 'Roughness',
            'metallic': 'Metallic', 'specular': 'Specular IOR Level',
            'emission': 'Emission Color', 'opacity': 'Alpha',
        }
        for role, socket_name in mapping.items():
            img = _sabershader11_image_from_socket(principled.inputs.get(socket_name))
            if img:
                result[role] = img
    if mat and mat.use_nodes and mat.node_tree:
        for node in mat.node_tree.nodes:
            if node.bl_idname != 'ShaderNodeTexImage' or not node.image:
                continue
            role = _sabershader11_role_from_text(' '.join((node.name, node.label, node.image.name)))
            result.setdefault(role, node.image)
    return result

def _sabershader11_role_from_text(text):
    raw = str(text or '').lower()
    compact = _sabershader11_key(raw)

    if 'mmdbasetex' in compact:
        return 'base'
    if 'mmdtoontex' in compact or 'toon' in compact or 'lightmap' in compact:
        return 'toon'
    if compact.endswith('imagetexture001') and 'hair' in compact:
        return 'hn'
    for role, suffixes in SABERSHADER11_ROLE_SUFFIXES.items():
        for suffix in suffixes:
            if raw.rsplit('.', 1)[0].endswith(suffix) or compact.endswith(_sabershader11_key(suffix)):
                return role
    words = {
        'normal': 'normal', 'rough': 'roughness', 'metal': 'metallic', 'spec': 'specular',
        'emit': 'emission', 'alpha': 'opacity', 'opacity': 'opacity', 'diffuse': 'base',
        'albedo': 'base', 'basecolor': 'base', 'ambientocclusion': 'ao', 'occlusion': 'ao',
        'mask': 'mask', 'reflection': 'reflection', 'envmap': 'reflection', 'environment': 'reflection',
    }
    for token, role in words.items():
        if token in compact:
            return role
    return 'base'

_XDZR8_V1122_META_EXTS = {'.pmx', '.pmd', '.fx', '.fxsub', '.fxh', '.json'}
_XDZR8_V1122_MMD_SUFFIX_ROLES = (
    ('_light', 'light_aux'),
    ('_al', 'auxiliary'),
    ('_c', 'base'),
    ('_h', 'toon_control'),
    ('_s', 'shadow_color'),

    ('_a', 'auxiliary'),
)
_XDZR8_V1122_GENERAL_PATTERNS = (
    ('otherdatatex2', 'packed_aux'),
    ('otherdatatex', 'packed_material'),
    ('materialmaskstex', 'packed_material'),
    ('materialmasks', 'packed_material'),
    ('customemissiontex', 'emission'),
    ('emissiontex', 'emission'),
    ('facemaptex', 'face_map'),
    ('facemap', 'face_map'),
    ('lightmaptex', 'toon_control'),
    ('lightmap', 'toon_control'),
    ('lighttex', 'toon_control'),
    ('maintex', 'base'),
    ('basemap', 'base'),
    ('diffusetex', 'base'),
)

def _xdzr8_v1122_nearby_roots(folder):
    """Return safe metadata-search roots around a user-selected texture folder."""
    try:
        root = Path(bpy.path.abspath(str(folder or '')).strip())
    except Exception:
        root = Path(str(folder or '').strip())
    if not str(root):
        return []
    out = []
    for candidate in (root, root.parent, root.parent.parent):
        try:
            if candidate.exists() and candidate.is_dir() and candidate not in out:
                out.append(candidate)
        except Exception:
            pass
    return out

def _xdzr8_v1122_metadata_files(folder):
    files = []
    seen = set()
    for root in _xdzr8_v1122_nearby_roots(folder):
        try:

            candidates = list(root.iterdir())
        except Exception:
            continue
        for path in candidates:
            try:
                if path.is_file() and path.suffix.lower() in _XDZR8_V1122_META_EXTS:
                    key = str(path.resolve()).lower()
                    if key not in seen:
                        seen.add(key); files.append(path)
            except Exception:
                pass

        json_dirs = []
        direct = root / 'Materials'
        if direct.exists() and direct.is_dir():
            json_dirs.append(direct)
        try:
            for child in list(root.iterdir())[:128]:
                if child.is_dir():
                    candidate = child / 'Materials'
                    if candidate.exists() and candidate.is_dir():
                        json_dirs.append(candidate)
        except Exception:
            pass
        json_count = 0
        for jdir in json_dirs:
            try:
                for path in jdir.glob('*.json'):
                    if json_count >= 512:
                        break
                    key = str(path.resolve()).lower()
                    if key not in seen:
                        seen.add(key); files.append(path); json_count += 1
            except Exception:
                pass
    return files

def _xdzr8_v1122_fx_texture_defines(meta_files):
    """Parse simple FX #define NAME_Texture \"file.ext\" semantics.

    This deliberately parses only declarative filename references. It does not
    attempt to execute or fully understand FX/HLSL code.
    """
    overrides = {}
    evidence = []
    for path in meta_files or []:
        if path.suffix.lower() not in {'.fx', '.fxsub', '.fxh'}:
            continue
        try:
            text = path.read_text(encoding='utf-8', errors='ignore')
        except Exception:
            continue
        for match in re.finditer(r'#define\s+([A-Za-z0-9_]+)\s+[\"<]([^\">]+\.(?:png|jpg|jpeg|tga|bmp|webp|exr))[\">]', text, re.I):
            macro, filename = match.group(1), Path(match.group(2)).name
            mkey = _sabershader11_key(macro)
            role = None
            if 'shadowcolor' in mkey:
                role = 'shadow_color'
            elif 'sekaimap' in mkey or 'toon' in mkey or 'lightmap' in mkey:
                role = 'toon_control'
            elif 'facemap' in mkey:
                role = 'face_map'
            elif 'emission' in mkey:
                role = 'emission'
            elif 'normal' in mkey:
                role = 'normal'
            elif 'maintex' in mkey or 'base' in mkey or 'diffuse' in mkey:
                role = 'base'
            if role:
                overrides[filename.lower()] = role
                evidence.append(f'{path.name}: {macro} -> {filename} = {role}')
    return overrides, evidence

def _xdzr8_v1123_pmx_read_text(stream, encoding):
    raw = stream.read(4)
    if len(raw) != 4:
        raise EOFError('PMX text length')
    length = struct.unpack('<i', raw)[0]
    if length < 0 or length > 64 * 1024 * 1024:
        raise ValueError('PMX text length out of range')
    data = stream.read(length)
    if len(data) != length:
        raise EOFError('PMX text data')
    return data.decode(encoding, errors='ignore')

def _xdzr8_v1123_pmx_read_index(stream, size, signed=True):
    fmt = {
        (1, True): '<b', (1, False): '<B',
        (2, True): '<h', (2, False): '<H',
        (4, True): '<i', (4, False): '<I',
    }.get((int(size), bool(signed)))
    if not fmt:
        raise ValueError(f'unsupported PMX index size {size}')
    raw = stream.read(size)
    if len(raw) != size:
        raise EOFError('PMX index')
    return struct.unpack(fmt, raw)[0]

def _xdzr8_v1123_parse_pmx_materials(path):
    """Read only the PMX header/texture/material tables needed for metadata.

    This is deliberately a bounded partial parser, not a PMX importer. It never
    mutates the source file and ignores bones/morphs/physics after materials.
    """
    records = []
    try:
        if path.suffix.lower() != '.pmx' or path.stat().st_size > 512 * 1024 * 1024:
            return records
        with path.open('rb') as stream:
            if stream.read(4) != b'PMX ':
                return records
            version_raw = stream.read(4)
            if len(version_raw) != 4:
                return records
            _version = struct.unpack('<f', version_raw)[0]
            hraw = stream.read(1)
            if not hraw:
                return records
            hsize = hraw[0]
            if hsize < 8 or hsize > 32:
                return records
            header = list(stream.read(hsize))
            if len(header) < 8:
                return records
            encoding = 'utf-16-le' if header[0] == 0 else 'utf-8'
            add_uv = int(header[1])
            vsize, tsize, _msize, bsize, _mosize, _rsize = map(int, header[2:8])
            if add_uv > 4 or any(x not in (1,2,4) for x in (vsize,tsize,bsize)):
                return records

            for _ in range(4):
                _xdzr8_v1123_pmx_read_text(stream, encoding)
            raw = stream.read(4)
            if len(raw) != 4:
                return records
            vcount = struct.unpack('<i', raw)[0]
            if vcount < 0 or vcount > 5_000_000:
                return records
            base_vertex_bytes = (3 + 3 + 2 + 4 * add_uv) * 4
            for _ in range(vcount):
                stream.seek(base_vertex_bytes, 1)
                wraw = stream.read(1)
                if not wraw:
                    raise EOFError('PMX vertex weight')
                wt = wraw[0]
                if wt == 0: stream.seek(bsize, 1)
                elif wt == 1: stream.seek(bsize * 2 + 4, 1)
                elif wt in (2, 4): stream.seek(bsize * 4 + 16, 1)
                elif wt == 3: stream.seek(bsize * 2 + 4 + 36, 1)
                else: raise ValueError('unsupported PMX vertex weight type')
                stream.seek(4, 1)
            raw = stream.read(4)
            if len(raw) != 4: return records
            index_count = struct.unpack('<i', raw)[0]
            if index_count < 0 or index_count > 50_000_000: return records

            face_indices = tuple(_xdzr8_v1123_pmx_read_index(stream, vsize, False) for _ in range(index_count))
            raw = stream.read(4)
            if len(raw) != 4: return records
            tex_count = struct.unpack('<i', raw)[0]
            if tex_count < 0 or tex_count > 100_000: return records
            textures = [_xdzr8_v1123_pmx_read_text(stream, encoding) for _ in range(tex_count)]
            raw = stream.read(4)
            if len(raw) != 4: return records
            mat_count = struct.unpack('<i', raw)[0]
            if mat_count < 0 or mat_count > 100_000: return records
            occurrence_counts = {}
            surface_cursor = 0
            model_local_name = ''
            model_english_name = ''

            try:
                with path.open('rb') as _name_stream:
                    if _name_stream.read(4) == b'PMX ':
                        _name_stream.read(4)
                        _hsraw = _name_stream.read(1)
                        if _hsraw:
                            _hsize = _hsraw[0]
                            _header = list(_name_stream.read(_hsize))
                            _enc = 'utf-16-le' if _header and _header[0] == 0 else 'utf-8'
                            model_local_name = _xdzr8_v1123_pmx_read_text(_name_stream, _enc)
                            model_english_name = _xdzr8_v1123_pmx_read_text(_name_stream, _enc)
            except Exception:
                pass
            for material_index in range(mat_count):
                local_name = _xdzr8_v1123_pmx_read_text(stream, encoding)
                english_name = _xdzr8_v1123_pmx_read_text(stream, encoding)
                stream.seek(16 + 12 + 4 + 12, 1)
                stream.seek(1 + 16 + 4, 1)
                tex_idx = _xdzr8_v1123_pmx_read_index(stream, tsize, True)
                _sphere_idx = _xdzr8_v1123_pmx_read_index(stream, tsize, True)
                stream.seek(1, 1)
                toon_shared_raw = stream.read(1)
                if not toon_shared_raw: raise EOFError('PMX toon flag')
                if toon_shared_raw[0] == 0:
                    _xdzr8_v1123_pmx_read_index(stream, tsize, True)
                else:
                    stream.seek(1, 1)
                memo = _xdzr8_v1123_pmx_read_text(stream, encoding)
                surf_raw = stream.read(4)
                if len(surf_raw) != 4: raise EOFError('PMX surface count')
                surface_count = struct.unpack('<i', surf_raw)[0]
                texture = textures[tex_idx] if 0 <= tex_idx < len(textures) else ''
                occurrence = int(occurrence_counts.get(local_name, 0))
                occurrence_counts[local_name] = occurrence + 1
                records.append({
                    'local_name': local_name,
                    'english_name': english_name,
                    'memo': memo,
                    'texture': texture,
                    'surface_count': surface_count,
                    'surface_start': int(surface_cursor),
                    'surface_end': int(surface_cursor + max(0, surface_count)),
                    'material_index': int(material_index),
                    'local_occurrence': int(occurrence),
                    'source_file': path.name,
                    'source_path': str(path),
                    'source_texture_table': tuple(textures),
                    'source_vertex_count': int(vcount),
                    'source_index_count': int(index_count),
                    'source_face_indices': face_indices,
                    'model_local_name': model_local_name,
                    'model_english_name': model_english_name,
                })
                surface_cursor += max(0, surface_count)
    except Exception:
        return []
    return records

def _xdzr8_v1123_name_keys(name):
    raw = str(name or '').strip()
    if not raw:
        return set()

    bare = re.sub(r'\.\d{3}$', '', raw)
    keys = {raw.lower(), bare.lower(), _sabershader11_key(raw), _sabershader11_key(bare)}
    return {k for k in keys if k}

def _xdzr8_v1171_pmx_bare_name(name):
    """Return the import-stable material name used for PMX identity checks."""
    raw = str(name or '').strip()
    if not raw:
        return ''

    return re.sub(r'\.\d{3}$', '', raw).strip()

def _xdzr8_v1171_pmx_norm_name(name):
    return _sabershader11_key(_xdzr8_v1171_pmx_bare_name(name))

def _xdzr8_v1123_build_pmx_lookup(records):
    """V11.7.1 identity-aware PMX lookup.

    Older builds put local_name and english_name into one shared key space. Some
    game exports reuse the same English alias for several distinct PMX materials
    (some imported packs reuse one English alias across several local materials), which allowed
    Eye/Highlight/Accessory metadata to contaminate another material. Keep the
    two namespaces separate and only permit an English alias when it is unique.
    """
    lookup = {
        'local_exact': {}, 'local_norm': {}, 'local_structural': {},
        'english_exact': {}, 'english_norm': {},
        'ambiguous_english_exact': set(), 'ambiguous_english_norm': set(),
    }
    for rec in records or []:
        local = _xdzr8_v1171_pmx_bare_name(rec.get('local_name', ''))
        english = _xdzr8_v1171_pmx_bare_name(rec.get('english_name', ''))
        if local:
            lookup['local_exact'].setdefault(local.casefold(), []).append(rec)
            nkey = _xdzr8_v1171_pmx_norm_name(local)
            if nkey:
                lookup['local_norm'].setdefault(nkey, []).append(rec)
            skey = _xdzr8_v11831_structural_material_signature(local)
            if skey:
                lookup['local_structural'].setdefault(skey, []).append(rec)
        if english:
            lookup['english_exact'].setdefault(english.casefold(), []).append(rec)
            nkey = _xdzr8_v1171_pmx_norm_name(english)
            if nkey:
                lookup['english_norm'].setdefault(nkey, []).append(rec)
    for key, rows in lookup['english_exact'].items():
        identities = {(r.get('source_file',''), r.get('local_name','')) for r in rows}
        if len(identities) != 1:
            lookup['ambiguous_english_exact'].add(key)
    for key, rows in lookup['english_norm'].items():
        identities = {(r.get('source_file',''), r.get('local_name','')) for r in rows}
        if len(identities) != 1:
            lookup['ambiguous_english_norm'].add(key)
    return lookup

def _xdzr8_v11831_structural_material_signature(name):
    """Return a creator-agnostic material-name structure with numeric IDs erased."""
    raw = _xdzr8_v1171_pmx_bare_name(name).casefold()
    if not raw:
        return ''
    raw = re.sub(r'\d+', '#', raw)
    raw = re.sub(r'[^a-z0-9#\u0080-\uffff]+', '_', raw)
    raw = re.sub(r'_+', '_', raw).strip('_')
    return raw

def _xdzr8_v11831_material_occurrence_from_name(name):
    raw = str(name or '').strip()
    match = re.search(r'\.(\d{3})$', raw)
    return int(match.group(1)) if match else 0

def _xdzr8_v11831_image_basename(image):
    if image is None:
        return ''
    try:
        path = bpy.path.abspath(str(getattr(image, 'filepath', '') or '')).strip()
        if path:
            name = Path(path).name
            if name:
                return name.casefold()
    except Exception:
        pass
    try:
        name = Path(str(getattr(image, 'name', '') or '')).name

        name = re.sub(r'(\.[A-Za-z0-9]{2,5})\.\d{3}$', r'\1', name)
        return name.casefold()
    except Exception:
        return ''

def _xdzr8_v11831_material_bound_texture_names(mat, source_ref=None):
    names = set()
    for candidate in (source_ref, mat):
        if candidate is None:
            continue
        try:
            if getattr(candidate, 'use_nodes', False) and getattr(candidate, 'node_tree', None):
                for node in candidate.node_tree.nodes:
                    if node.bl_idname == 'ShaderNodeTexImage' and getattr(node, 'image', None):
                        name = _xdzr8_v11831_image_basename(node.image)
                        if name:
                            names.add(name)
        except Exception:
            pass
        try:
            for image in (_sabershader11_existing_role_images(candidate) or {}).values():
                name = _xdzr8_v11831_image_basename(image)
                if name:
                    names.add(name)
        except Exception:
            pass
    return names

def _xdzr8_v11831_source_bound_texture_names(materials):
    names = set()
    rows = []
    for mat in materials or []:
        if mat is None:
            continue
        try:
            source_ref = _sabershader111_resolve_original_source_material(mat) or mat
        except Exception:
            source_ref = mat
        bound = _xdzr8_v11831_material_bound_texture_names(mat, source_ref)
        names.update(bound)
        if bound:
            try:
                mname = str(mat.get('SaberShader_V11_SourceMaterial', mat.name) or mat.name)
            except Exception:
                mname = getattr(mat, 'name', 'Material')
            rows.append((mname, sorted(bound)))
    return names, rows

def _xdzr8_v11831_object_surface_index_count(objects):
    count = 0
    polygon_count = 0
    for obj in objects or []:
        if not obj or getattr(obj, 'type', '') != 'MESH' or not getattr(obj, 'data', None):
            continue
        try:
            for poly in obj.data.polygons:
                count += len(poly.vertices)
                polygon_count += 1
        except Exception:
            pass
    return int(count), int(polygon_count)

def _xdzr8_v11831_scope_pmx_sources(records, objects=None, materials=None):
    """Choose the PMX source structurally matching the active Blender character.

    Character/model names are deliberately not scored. Evidence is based on:
      * exact mesh surface-index count vs PMX material surface-count total;
      * overlap between actually bound Blender images and the PMX texture table;
      * structural material-name signatures with numeric IDs erased.
    """
    groups = {}
    for rec in records or []:
        key = str(rec.get('source_path') or rec.get('source_file') or '')
        groups.setdefault(key, []).append(rec)
    if not groups:
        return {'selected': [], 'all': list(records or []), 'selected_file': '', 'selected_path': '', 'confidence': 'NONE', 'reason': 'no PMX metadata', 'candidates': []}

    bound_textures, bound_rows = _xdzr8_v11831_source_bound_texture_names(materials)
    object_surface_indices, object_polygons = _xdzr8_v11831_object_surface_index_count(objects)
    material_signatures = set()
    for mat in materials or []:
        try:
            source_ref = _sabershader111_resolve_original_source_material(mat) or mat
        except Exception:
            source_ref = mat
        names = _xdzr8_v1171_pmx_candidate_names(mat, source_ref)
        for name in names:
            sig = _xdzr8_v11831_structural_material_signature(name)
            if sig:
                material_signatures.add(sig)

    candidates = []
    for source_key, rows in groups.items():
        rows = sorted(rows, key=lambda r: int(r.get('material_index', 10**9)))
        first = rows[0] if rows else {}
        texture_table = {
            Path(str(tex or '').replace('\\', '/')).name.casefold()
            for tex in (first.get('source_texture_table') or ())
            if tex
        }
        material_textures = {
            Path(str(rec.get('texture') or '').replace('\\', '/')).name.casefold()
            for rec in rows if rec.get('texture')
        }
        source_sigs = {
            _xdzr8_v11831_structural_material_signature(rec.get('local_name', ''))
            for rec in rows
        }
        source_sigs.discard('')
        table_hits = len(bound_textures & texture_table)
        material_tex_hits = len(bound_textures & material_textures)
        sig_hits = len(material_signatures & source_sigs)
        pmx_surface_indices = sum(max(0, int(rec.get('surface_count', 0))) for rec in rows)
        surface_ratio = 0.0
        surface_exact = False
        if object_surface_indices > 0 and pmx_surface_indices > 0:
            diff = abs(object_surface_indices - pmx_surface_indices)
            surface_ratio = diff / max(object_surface_indices, pmx_surface_indices, 1)
            surface_exact = diff == 0

        score = 0.0
        evidence = []
        if surface_exact:
            score += 1200.0
            evidence.append(f'exact surface-index count {pmx_surface_indices}')
        elif surface_ratio <= 0.0025:
            score += 600.0 * (1.0 - surface_ratio / 0.0025)
            evidence.append(f'near-exact surface count delta={surface_ratio:.4f}')
        elif surface_ratio <= 0.02:
            score += 180.0 * (1.0 - surface_ratio / 0.02)
            evidence.append(f'close surface count delta={surface_ratio:.3f}')
        if table_hits:
            score += min(700.0, table_hits * 42.0)
            evidence.append(f'{table_hits} bound texture-table hits')
        if material_tex_hits:
            score += min(360.0, material_tex_hits * 72.0)
            evidence.append(f'{material_tex_hits} PMX material-texture hits')
        if sig_hits:
            score += min(220.0, sig_hits * 28.0)
            evidence.append(f'{sig_hits} structural material-signature hits')
        candidates.append({
            'source_path': source_key,
            'source_file': str(first.get('source_file') or Path(source_key).name),
            'rows': rows,
            'score': float(score),
            'surface_indices': int(pmx_surface_indices),
            'surface_ratio': float(surface_ratio),
            'surface_exact': bool(surface_exact),
            'texture_table_hits': int(table_hits),
            'material_texture_hits': int(material_tex_hits),
            'material_signature_hits': int(sig_hits),
            'evidence': evidence,
        })

    candidates.sort(key=lambda row: (-row['score'], row['source_file'].casefold()))
    best = candidates[0]
    second_score = candidates[1]['score'] if len(candidates) > 1 else -1.0
    margin = best['score'] - second_score
    strong = bool(best['surface_exact'] or best['texture_table_hits'] >= 2 or best['material_texture_hits'] >= 1)
    if len(candidates) == 1:
        selected = best
        confidence = 'HIGH'
        reason = 'single PMX source candidate'
    elif strong and (best['surface_exact'] or margin >= 90.0):
        selected = best
        confidence = 'HIGH' if (best['surface_exact'] or best['texture_table_hits'] >= 4) else 'MEDIUM'
        reason = '; '.join(best['evidence']) + f'; margin={margin:.1f}'
    else:
        selected = None
        confidence = 'LOW'
        reason = f'PMX source ambiguous; best={best["source_file"]}:{best["score"]:.1f}, margin={margin:.1f}'

    return {
        'selected': list(selected['rows']) if selected else [],
        'all': list(records or []),
        'selected_file': selected['source_file'] if selected else '',
        'selected_path': selected['source_path'] if selected else '',
        'confidence': confidence,
        'reason': reason,
        'candidates': [
            {k: v for k, v in row.items() if k != 'rows'} for row in candidates
        ],
        'bound_textures': sorted(bound_textures),
        'bound_material_rows': bound_rows,
        'object_surface_indices': int(object_surface_indices),
        'object_polygons': int(object_polygons),
    }

def _xdzr8_v11831_choose_pmx_occurrence(rows, blender_name, mat=None, source_ref=None):
    rows = sorted(_xdzr8_v1171_dedupe_pmx_records(rows), key=lambda r: (int(r.get('local_occurrence', 0)), int(r.get('material_index', 0))))
    if not rows:
        return None, 'no PMX occurrence candidates'
    if len(rows) == 1:
        return rows[0], 'single PMX occurrence'

    bound = _xdzr8_v11831_material_bound_texture_names(mat, source_ref)
    if bound:
        matching = []
        for rec in rows:
            tex = Path(str(rec.get('texture') or '').replace('\\', '/')).name.casefold()
            if tex and tex in bound:
                matching.append(rec)
        if len(matching) == 1:
            return matching[0], 'unique bound-texture occurrence match'
        if matching:
            rows = matching

    occurrence = _xdzr8_v11831_material_occurrence_from_name(blender_name)
    exact_occ = [r for r in rows if int(r.get('local_occurrence', 0)) == occurrence]
    if len(exact_occ) == 1:
        return exact_occ[0], f'Blender duplicate suffix occurrence={occurrence}'
    if 0 <= occurrence < len(rows):
        return rows[occurrence], f'ordered PMX occurrence index={occurrence}'
    return None, f'ambiguous PMX occurrences={len(rows)}'

def _xdzr8_v11831_slot_usage_audit(objects):
    rows = []
    used_indices = set()
    used_materials = set()
    for obj in objects or []:
        if not obj or getattr(obj, 'type', '') != 'MESH' or not getattr(obj, 'data', None):
            continue
        counts = {}
        try:
            for poly in obj.data.polygons:
                idx = int(poly.material_index)
                counts[idx] = counts.get(idx, 0) + 1
        except Exception:
            pass
        slots = list(getattr(obj, 'material_slots', []) or [])
        for index, count in sorted(counts.items()):
            mat = slots[index].material if 0 <= index < len(slots) else None
            try:
                source_name = str(mat.get('SaberShader_V11_SourceMaterial', mat.name) or mat.name) if mat else '<none>'
            except Exception:
                source_name = getattr(mat, 'name', '<none>') if mat else '<none>'
            rows.append(f'{obj.name}: slot={index} polys={count} material={source_name}')
            used_indices.add((obj.as_pointer(), index))
            if mat:
                try: used_materials.add(mat.as_pointer())
                except Exception: used_materials.add(source_name)
    return {'rows': rows, 'used_slot_count': len(used_indices), 'used_material_count': len(used_materials)}

def _xdzr8_v11832_slot_entries(obj):
    """Describe material slots without treating authored outline/helper slots as surfaces."""
    entries = []
    structural_occ = {}
    material_occ = {}
    slots = list(getattr(obj, 'material_slots', []) or []) if obj else []
    for slot_index, slot in enumerate(slots):
        mat = getattr(slot, 'material', None)
        if mat is None:
            entries.append({
                'slot_index': slot_index, 'mat': None, 'source_ref': None,
                'source_name': '<none>', 'helper': True, 'helper_reason': 'empty slot',
                'structural': '', 'structural_occurrence': -1,
                'material_occurrence': -1, 'bound_textures': set(),
            })
            continue
        try:
            source_ref = _sabershader111_resolve_original_source_material(mat) or mat
        except Exception:
            source_ref = mat
        try:
            source_name = str(mat.get('SaberShader_V11_SourceMaterial', mat.name) or mat.name)
        except Exception:
            source_name = getattr(mat, 'name', 'Material')
        helper_flag, helper_reason = _xdzr8_v11822_is_source_helper_material(mat)
        structural = _xdzr8_v11831_structural_material_signature(source_name)
        so = structural_occ.get(structural, 0) if structural else 0
        if structural:
            structural_occ[structural] = so + 1
        try:
            mp = mat.as_pointer()
        except Exception:
            mp = source_name
        mo = material_occ.get(mp, 0)
        material_occ[mp] = mo + 1
        entries.append({
            'slot_index': int(slot_index),
            'mat': mat,
            'source_ref': source_ref,
            'source_name': source_name,
            'helper': bool(helper_flag),
            'helper_reason': str(helper_reason),
            'structural': structural,
            'structural_occurrence': int(so),
            'material_occurrence': int(mo),
            'bound_textures': _xdzr8_v11831_material_bound_texture_names(mat, source_ref),
        })
    return entries

def _xdzr8_v11832_texture_family_root_from_name(name, intelligence=None):
    if not name:
        return ''
    try:
        role = _xdzr8_v1122_semantic_role(name, intelligence)
        return _xdzr8_v1122_texture_family_root(name, role, intelligence)
    except Exception:
        return ''

def _xdzr8_v11832_score_row_to_slot(rec, entry, nonhelper_ordinal, intelligence=None):
    """Score one PMX material row against one visible Blender material slot."""
    if not entry or entry.get('helper') or entry.get('mat') is None:
        return -1e9, ['helper/empty slot']
    score = 0.0
    evidence = []
    pmx_name = str(rec.get('local_name', '') or '')
    pmx_bare = _xdzr8_v1171_pmx_bare_name(pmx_name)
    pmx_norm = _xdzr8_v1171_pmx_norm_name(pmx_name)
    pmx_struct = _xdzr8_v11831_structural_material_signature(pmx_name)
    source_name = str(entry.get('source_name', '') or '')
    slot_bare = _xdzr8_v1171_pmx_bare_name(source_name)
    slot_norm = _xdzr8_v1171_pmx_norm_name(source_name)
    slot_struct = str(entry.get('structural', '') or '')

    if pmx_bare and slot_bare and pmx_bare.casefold() == slot_bare.casefold():
        score += 840.0; evidence.append('exact local name')
    elif pmx_norm and slot_norm and pmx_norm == slot_norm:
        score += 720.0; evidence.append('normalized local name')
    if pmx_struct and slot_struct and pmx_struct == slot_struct:
        score += 470.0; evidence.append('structural local-name match')

    pmx_tex = Path(str(rec.get('texture') or '').replace('\\', '/')).name.casefold()
    bound = set(entry.get('bound_textures') or set())
    if pmx_tex and pmx_tex in bound:
        score += 1400.0; evidence.append('exact bound texture')
    pmx_root = _xdzr8_v11832_texture_family_root_from_name(pmx_tex, intelligence)
    if pmx_root:
        slot_roots = {
            _xdzr8_v11832_texture_family_root_from_name(name, intelligence)
            for name in bound if name
        }
        slot_roots.discard('')
        if pmx_root in slot_roots:
            score += 680.0; evidence.append(f'bound texture family {pmx_root}')

    pmx_occ = int(rec.get('local_occurrence', 0))
    if pmx_struct and slot_struct == pmx_struct and int(entry.get('structural_occurrence', -1)) == pmx_occ:
        score += 180.0; evidence.append(f'structural occurrence {pmx_occ}')

    pmx_role = _sabershader11_role_from_text(' '.join([
        pmx_name,
        str(rec.get('english_name', '') or ''),
        Path(str(rec.get('texture') or '').replace('\\', '/')).stem,
    ]))
    slot_role = _sabershader11_role_from_text(' '.join([source_name] + sorted(bound)))
    if pmx_role in XDZR8_V112_VALID_ROLES and pmx_role == slot_role:
        score += 150.0; evidence.append(f'role compatibility {pmx_role}')

    rec_index = int(rec.get('material_index', 0))
    ordinal_delta = abs(int(nonhelper_ordinal) - rec_index)
    order_bonus = max(0.0, 72.0 - 9.0 * float(ordinal_delta))
    if order_bonus > 0.0:
        score += order_bonus; evidence.append(f'ordered-slot delta={ordinal_delta}')
    return score, evidence

def _xdzr8_v11832_map_pmx_rows_to_slots(obj, pmx_rows, intelligence=None):
    entries = _xdzr8_v11832_slot_entries(obj)
    visible = [e for e in entries if not e.get('helper') and e.get('mat') is not None]
    ordinal_by_slot = {e['slot_index']: i for i, e in enumerate(visible)}
    mappings = []
    ambiguous = []
    unresolved = []
    for rec in sorted(pmx_rows or [], key=lambda r: int(r.get('material_index', 10**9))):
        if int(rec.get('surface_count', 0)) <= 0:
            continue
        ranked = []
        for entry in visible:
            score, evidence = _xdzr8_v11832_score_row_to_slot(
                rec, entry, ordinal_by_slot.get(entry['slot_index'], 0), intelligence
            )
            ranked.append((float(score), entry, evidence))
        ranked.sort(key=lambda row: (-row[0], int(row[1].get('slot_index', 10**9))))
        if not ranked or ranked[0][0] < 360.0:
            unresolved.append({
                'material_index': int(rec.get('material_index', -1)),
                'local_name': rec.get('local_name', ''),
                'texture': rec.get('texture', ''),
                'best_score': ranked[0][0] if ranked else -1.0,
            })
            continue
        top_score, top_entry, top_evidence = ranked[0]
        second = ranked[1] if len(ranked) > 1 else None
        if second and (top_score - second[0]) <= 42.0:

            try:
                same_mat = top_entry['mat'].as_pointer() == second[1]['mat'].as_pointer()
            except Exception:
                same_mat = top_entry.get('source_name') == second[1].get('source_name')
            if not same_mat:
                ambiguous.append({
                    'material_index': int(rec.get('material_index', -1)),
                    'local_name': rec.get('local_name', ''),
                    'top_slot': int(top_entry['slot_index']), 'top_score': float(top_score),
                    'second_slot': int(second[1]['slot_index']), 'second_score': float(second[0]),
                })
                continue
        mappings.append({
            'record': rec,
            'slot_index': int(top_entry['slot_index']),
            'source_name': str(top_entry.get('source_name', 'Material')),
            'score': float(top_score),
            'evidence': list(top_evidence),
        })
    return {
        'entries': entries,
        'visible_slots': len(visible),
        'mappings': mappings,
        'ambiguous': ambiguous,
        'unresolved': unresolved,
    }

def _xdzr8_v11832_topology_match(obj, pmx_rows):
    """Verify that Blender polygon order matches the scoped PMX triangle stream."""
    result = {
        'available': False, 'vertex_count_match': False, 'index_count_match': False,
        'all_triangles': False, 'face_order_match_ratio': 0.0,
        'matched_faces': 0, 'checked_faces': 0,
    }
    if not obj or getattr(obj, 'type', '') != 'MESH' or not getattr(obj, 'data', None) or not pmx_rows:
        return result
    first = sorted(pmx_rows, key=lambda r: int(r.get('material_index', 10**9)))[0]
    face_indices = first.get('source_face_indices') or ()
    source_v = int(first.get('source_vertex_count', 0) or 0)
    source_i = int(first.get('source_index_count', len(face_indices)) or 0)
    polys = list(obj.data.polygons)
    result['available'] = bool(face_indices)
    result['vertex_count_match'] = source_v > 0 and source_v == len(obj.data.vertices)
    result['index_count_match'] = source_i > 0 and source_i == sum(len(p.vertices) for p in polys)
    result['all_triangles'] = bool(polys) and all(len(p.vertices) == 3 for p in polys)
    if not face_indices or not result['all_triangles'] or len(face_indices) != len(polys) * 3:
        return result
    matched = 0
    checked = len(polys)
    for pi, poly in enumerate(polys):
        source_tri = face_indices[pi * 3: pi * 3 + 3]
        if tuple(sorted(int(v) for v in poly.vertices)) == tuple(sorted(int(v) for v in source_tri)):
            matched += 1
    result['matched_faces'] = int(matched)
    result['checked_faces'] = int(checked)
    result['face_order_match_ratio'] = float(matched) / max(checked, 1)
    return result

def _xdzr8_v11832_backup_material_indices(mesh):
    """Create a one-time FACE-domain backup of source material indices."""
    name = 'XDZR8_SourceMaterialIndexBackup'
    polys = list(getattr(mesh, 'polygons', []) or [])
    if not polys:
        return False, 'empty mesh'
    try:
        attr = mesh.attributes.get(name)
    except Exception:
        attr = None
    if attr is not None:
        try:
            if getattr(attr, 'domain', '') == 'FACE' and len(attr.data) == len(polys):
                return False, 'existing backup preserved'
        except Exception:
            pass

        return False, 'backup attribute exists but is incompatible'
    try:
        attr = mesh.attributes.new(name=name, type='INT', domain='FACE')
        for i, poly in enumerate(polys):
            attr.data[i].value = int(poly.material_index)
        return True, 'backup created'
    except Exception as exc:
        return False, f'backup creation failed: {exc}'

def _xdzr8_v11832_recover_surface_material_assignments(objects, intelligence=None):
    """Recover collapsed Blender material indices from scoped PMX surface ranges.

    Recovery is intentionally gated very tightly: one mesh, HIGH PMX scope,
    exact vertex/index counts, triangulated topology, >=98% ordered triangle
    identity, one collapsed material slot before recovery, and unambiguous PMX
    row -> visible-slot bindings. No outline/helper slot is ever targeted.
    """
    info = intelligence if isinstance(intelligence, dict) else {}
    rows = sorted(info.get('pmx_materials', []) or [], key=lambda r: int(r.get('material_index', 10**9)))
    scope = info.get('pmx_scope', {}) or {}
    result = {
        'eligible': False, 'applied': False, 'reason': '',
        'pmx_material_ranges': len([r for r in rows if int(r.get('surface_count', 0)) > 0]),
        'mapped_ranges': 0, 'reassigned_polygons': 0, 'changed_polygons': 0,
        'backup_created': False, 'backup_status': '',
        'topology': {}, 'mapping_rows': [], 'ambiguous': [], 'unresolved': [],
        'used_slots_before': 0, 'used_materials_before': 0,
        'used_slots_after': 0, 'used_materials_after': 0,
    }
    meshes = [o for o in (objects or []) if o and getattr(o, 'type', '') == 'MESH' and getattr(o, 'data', None)]
    if len(meshes) != 1:
        result['reason'] = f'requires one mesh; got {len(meshes)}'
        return result
    obj = meshes[0]
    before = _xdzr8_v11831_slot_usage_audit([obj])
    result['used_slots_before'] = int(before.get('used_slot_count', 0))
    result['used_materials_before'] = int(before.get('used_material_count', 0))
    if str(scope.get('confidence', '')).upper() != 'HIGH' or not scope.get('selected_file'):
        result['reason'] = 'PMX scope is not HIGH confidence'
        return result
    if len(rows) < 2:
        result['reason'] = 'scoped PMX has fewer than two material ranges'
        return result
    if result['used_slots_before'] > 1:
        result['reason'] = f'polygon material assignment is not collapsed (usedSlots={result["used_slots_before"]})'
        return result

    total_surface = sum(max(0, int(r.get('surface_count', 0))) for r in rows)
    blender_indices = sum(len(p.vertices) for p in obj.data.polygons)
    if total_surface != blender_indices:
        result['reason'] = f'PMX/Blender surface-index mismatch {total_surface}!={blender_indices}'
        return result
    if any(int(r.get('surface_count', 0)) % 3 != 0 for r in rows):
        result['reason'] = 'one or more PMX surface ranges are not divisible by 3'
        return result

    topo = _xdzr8_v11832_topology_match(obj, rows)
    result['topology'] = topo
    if not (topo.get('vertex_count_match') and topo.get('index_count_match') and topo.get('all_triangles')):
        result['reason'] = 'PMX/Blender topology dimensions do not match exactly'
        return result
    if topo.get('face_order_match_ratio', 0.0) < 0.98:
        result['reason'] = f'ordered triangle topology match too low ({topo.get("face_order_match_ratio",0.0):.3f})'
        return result

    mapping = _xdzr8_v11832_map_pmx_rows_to_slots(obj, rows, info)
    result['ambiguous'] = list(mapping.get('ambiguous', []))
    result['unresolved'] = list(mapping.get('unresolved', []))
    result['mapped_ranges'] = len(mapping.get('mappings', []))
    positive_ranges = len([r for r in rows if int(r.get('surface_count', 0)) > 0])
    if result['ambiguous'] or result['unresolved'] or result['mapped_ranges'] != positive_ranges:
        result['reason'] = (
            f'PMX range -> slot mapping incomplete: mapped={result["mapped_ranges"]}/{positive_ranges} '
            f'ambiguous={len(result["ambiguous"])} unresolved={len(result["unresolved"])}'
        )
        return result

    target = [None] * len(obj.data.polygons)
    for item in mapping.get('mappings', []):
        rec = item['record']
        start = int(rec.get('surface_start', 0)) // 3
        end = int(rec.get('surface_end', 0)) // 3
        if start < 0 or end < start or end > len(target):
            result['reason'] = f'invalid PMX polygon range {start}:{end}'
            return result
        for pi in range(start, end):
            target[pi] = int(item['slot_index'])
        result['mapping_rows'].append({
            'material_index': int(rec.get('material_index', -1)),
            'local_occurrence': int(rec.get('local_occurrence', -1)),
            'local_name': str(rec.get('local_name', '') or ''),
            'texture': Path(str(rec.get('texture') or '').replace('\\', '/')).name,
            'surface_count': int(rec.get('surface_count', 0)),
            'polygon_start': int(start), 'polygon_end': int(end),
            'slot_index': int(item['slot_index']),
            'source_name': str(item.get('source_name', 'Material')),
            'score': float(item.get('score', 0.0)),
            'evidence': list(item.get('evidence', [])),
        })
    if any(v is None for v in target):
        result['reason'] = 'target material assignment has uncovered polygons'
        return result

    result['eligible'] = True
    backup_created, backup_status = _xdzr8_v11832_backup_material_indices(obj.data)
    result['backup_created'] = bool(backup_created)
    result['backup_status'] = str(backup_status)
    if 'failed' in str(backup_status).lower() or 'incompatible' in str(backup_status).lower():
        result['eligible'] = False
        result['reason'] = 'material-index backup could not be guaranteed: ' + str(backup_status)
        return result

    changed = 0
    try:
        for pi, poly in enumerate(obj.data.polygons):
            desired = int(target[pi])
            if int(poly.material_index) != desired:
                poly.material_index = desired
                changed += 1
        try:
            obj.data.update()
        except Exception:
            pass
        obj.data['XDZR8_V11_8_3_3_SurfaceRangeRecovery'] = True
        obj.data['XDZR8_V11_8_3_3_PMXSource'] = str(scope.get('selected_file') or '')
        obj.data['XDZR8_V11_8_3_3_TopologyMatch'] = float(topo.get('face_order_match_ratio', 0.0))
        obj.data['XDZR8_V11_8_3_3_ReassignedPolygons'] = int(changed)
    except Exception as exc:
        result['reason'] = f'polygon material assignment failed: {exc}'
        return result

    after = _xdzr8_v11831_slot_usage_audit([obj])
    result['changed_polygons'] = int(changed)
    result['reassigned_polygons'] = int(len(target))
    result['used_slots_after'] = int(after.get('used_slot_count', 0))
    result['used_materials_after'] = int(after.get('used_material_count', 0))
    result['applied'] = True
    result['reason'] = (
        f'PMX surface ranges restored across {result["mapped_ranges"]} ranges; '
        f'changed={changed}, usedSlots {result["used_slots_before"]}->{result["used_slots_after"]}'
    )
    return result

def _xdzr8_v11833_mat_pointer(mat):
    if mat is None:
        return None
    try:
        return int(mat.as_pointer())
    except Exception:
        try:
            return str(mat.name)
        except Exception:
            return None

def _xdzr8_v11833_source_surface_fidelity(objects):
    """Audit the incoming Blender polygon->material assignment as authoritative source data.

    V11.8.3.3 does not infer that PMX material ranges are the desired Blender
    assignment. Imported/exported setups may intentionally merge PMX materials,
    split one PMX range between several visual shaders, or reserve neighboring
    slots for an authored inverted-hull outline. Rich Blender-side surface data
    is therefore preserved and becomes the primary material-usage signal.
    """
    result = {
        'rows': [], 'objects': 0, 'polygons': 0, 'slot_capacity': 0,
        'used_slots': 0, 'used_materials': 0, 'used_nonhelper_slots': 0,
        'used_helper_slots': 0, 'rich_assignment': False,
        'collapsed_suspicious': False, 'fidelity_score': 0.0,
        'used_material_ptrs': set(), 'used_nonhelper_material_ptrs': set(),
        'used_slot_keys': set(), 'used_nonhelper_slot_keys': set(),
        'polygon_counts': {},
    }
    for obj in objects or []:
        if not obj or getattr(obj, 'type', '') != 'MESH' or not getattr(obj, 'data', None):
            continue
        result['objects'] += 1
        slots = list(getattr(obj, 'material_slots', []) or [])
        result['slot_capacity'] += len(slots)
        counts = {}
        try:
            for poly in obj.data.polygons:
                idx = int(poly.material_index)
                counts[idx] = counts.get(idx, 0) + 1
                result['polygons'] += 1
        except Exception:
            continue
        for idx, count in sorted(counts.items()):
            mat = slots[idx].material if 0 <= idx < len(slots) else None
            helper, helper_reason = _xdzr8_v11822_is_source_helper_material(mat) if mat else (True, 'empty/out-of-range slot')
            ptr = _xdzr8_v11833_mat_pointer(mat)
            key = (int(obj.as_pointer()), int(idx))
            result['used_slot_keys'].add(key)
            result['polygon_counts'][key] = int(count)
            if ptr is not None:
                result['used_material_ptrs'].add(ptr)
            if helper:
                result['used_helper_slots'] += 1
            else:
                result['used_nonhelper_slots'] += 1
                result['used_nonhelper_slot_keys'].add(key)
                if ptr is not None:
                    result['used_nonhelper_material_ptrs'].add(ptr)
            try:
                name = str(mat.get('SaberShader_V11_SourceMaterial', mat.name) or mat.name) if mat else '<none>'
            except Exception:
                name = getattr(mat, 'name', '<none>') if mat else '<none>'
            result['rows'].append({
                'object': str(getattr(obj, 'name', 'Mesh')), 'slot': int(idx),
                'polygons': int(count), 'material': str(name),
                'helper': bool(helper), 'helper_reason': str(helper_reason),
            })
    result['used_slots'] = len(result['used_slot_keys'])
    result['used_materials'] = len(result['used_material_ptrs'])
    visible = int(result['used_nonhelper_slots'])
    capacity = int(result['slot_capacity'])

    result['rich_assignment'] = bool(visible >= 3 and result['polygons'] > 0)
    result['collapsed_suspicious'] = bool(capacity >= 4 and visible <= 1 and result['polygons'] > 0)
    if result['polygons'] > 0:
        result['fidelity_score'] = min(1.0, visible / max(1.0, min(6.0, float(capacity))))
    return result

def _xdzr8_v11833_detect_light_attribute_pipeline(objects, materials=None):
    """Detect authored geometry-node light attributes structurally, never by node-group name."""
    written = set()
    modifiers = []
    for obj in objects or []:
        for mod in getattr(obj, 'modifiers', []) or []:
            try:
                if str(getattr(mod, 'type', '')) != 'NODES':
                    continue
            except Exception:
                continue
            group = getattr(mod, 'node_group', None)
            if group is None:
                continue
            local = set()
            for node in getattr(group, 'nodes', []) or []:
                if getattr(node, 'bl_idname', '') != 'GeometryNodeStoreNamedAttribute':
                    continue
                sock = getattr(node, 'inputs', None)
                sock = sock.get('Name') if sock and hasattr(sock, 'get') else None
                try:
                    name = str(sock.default_value or '').strip() if sock else ''
                except Exception:
                    name = ''
                if name:
                    local.add(name); written.add(name)
            if local:
                modifiers.append({'object': getattr(obj, 'name', 'Mesh'), 'modifier': getattr(mod, 'name', 'GeometryNodes'), 'attributes': sorted(local)})
    read = set()
    consumer_materials = set()

    def scan_tree(tree, owner_name, visited):
        if tree is None:
            return
        try:
            ptr = int(tree.as_pointer())
        except Exception:
            ptr = id(tree)
        if ptr in visited:
            return
        visited.add(ptr)
        for node in getattr(tree, 'nodes', []) or []:
            if getattr(node, 'bl_idname', '') == 'ShaderNodeAttribute':
                try:
                    name = str(getattr(node, 'attribute_name', '') or '').strip()
                except Exception:
                    name = ''
                if name:
                    read.add(name)
                    consumer_materials.add(owner_name)

            child = getattr(node, 'node_tree', None)
            if child is not None:
                scan_tree(child, owner_name, visited)

    for mat in materials or []:
        if not mat or not getattr(mat, 'use_nodes', False) or not getattr(mat, 'node_tree', None):
            continue
        scan_tree(mat.node_tree, _sabershader111_safe_material_name(mat, 'Material'), set())
    important = {'LightDirectionWS', 'LightColor', 'Head_Rotation'}
    return {
        'detected': bool(written & important), 'written': sorted(written),
        'read': sorted(read), 'important_written': sorted(written & important),
        'modifiers': modifiers, 'consumer_materials': sorted(consumer_materials),
    }

def _xdzr8_v11833_detect_authored_outline_pipeline(objects):
    """Detect a source inverted-hull pipeline from Solidify + helper target slots.

    No creator/model names are used. Strong detection requires a nonzero
    Solidify material offset plus multiple visible source surfaces whose offset
    targets behave like authored backface/transparent outline helper materials.
    """
    result = {
        'detected': False, 'preserve': False, 'confidence': 'NONE',
        'pairs': [], 'modifiers': [], 'helper_material_ptrs': set(),
        'paired_visible_slots': 0, 'visible_used_slots': 0,
        'pair_ratio': 0.0, 'reason': '',
    }
    surface = _xdzr8_v11833_source_surface_fidelity(objects)
    result['visible_used_slots'] = int(surface.get('used_nonhelper_slots', 0))
    for obj in objects or []:
        if not obj or getattr(obj, 'type', '') != 'MESH':
            continue
        slots = list(getattr(obj, 'material_slots', []) or [])
        used_counts = {}
        try:
            for poly in obj.data.polygons:
                used_counts[int(poly.material_index)] = used_counts.get(int(poly.material_index), 0) + 1
        except Exception:
            pass
        for mod in getattr(obj, 'modifiers', []) or []:
            if str(getattr(mod, 'type', '')) != 'SOLIDIFY':
                continue
            try: offset = int(getattr(mod, 'material_offset', 0) or 0)
            except Exception: offset = 0
            try: thickness = float(getattr(mod, 'thickness', 0.0) or 0.0)
            except Exception: thickness = 0.0
            if offset == 0 or abs(thickness) <= 1e-9:
                continue
            mrow = {'object': getattr(obj, 'name', 'Mesh'), 'modifier': getattr(mod, 'name', 'Solidify'), 'offset': offset, 'thickness': thickness, 'pairs': 0}
            for src_idx, poly_count in sorted(used_counts.items()):
                if not (0 <= src_idx < len(slots)):
                    continue
                src_mat = slots[src_idx].material
                src_helper, _ = _xdzr8_v11822_is_source_helper_material(src_mat) if src_mat else (True, 'empty')
                if src_helper:
                    continue
                dst_idx = src_idx + offset
                if not (0 <= dst_idx < len(slots)):
                    continue
                dst_mat = slots[dst_idx].material
                dst_helper, dst_reason = _xdzr8_v11822_is_source_helper_material(dst_mat) if dst_mat else (True, 'empty target slot')

                if dst_mat is None or not dst_helper:
                    continue
                mrow['pairs'] += 1
                ptr = _xdzr8_v11833_mat_pointer(dst_mat)
                if ptr is not None:
                    result['helper_material_ptrs'].add(ptr)
                result['pairs'].append({
                    'object': getattr(obj, 'name', 'Mesh'), 'source_slot': int(src_idx),
                    'target_slot': int(dst_idx), 'source_material': _sabershader111_safe_material_name(src_mat, 'Material'),
                    'target_material': _sabershader111_safe_material_name(dst_mat, 'Material'),
                    'polygons': int(poly_count), 'reason': str(dst_reason),
                    'offset': int(offset), 'thickness': float(thickness),
                })
            result['modifiers'].append(mrow)
    result['paired_visible_slots'] = len({(p['object'], p['source_slot']) for p in result['pairs']})
    visible = max(1, int(result.get('visible_used_slots', 0)))
    result['pair_ratio'] = float(result['paired_visible_slots']) / float(visible)
    if result['paired_visible_slots'] >= 2 and result['pair_ratio'] >= 0.50:
        result['detected'] = True; result['preserve'] = True; result['confidence'] = 'HIGH'
        result['reason'] = f'Solidify material-offset outline pairs={result["paired_visible_slots"]}/{visible}'
    elif result['paired_visible_slots'] >= 1 and result['pair_ratio'] >= 0.75:
        result['detected'] = True; result['confidence'] = 'MEDIUM'
        result['reason'] = f'probable authored Solidify outline pair={result["paired_visible_slots"]}/{visible}'
    else:
        result['reason'] = 'no strong Solidify + helper-slot outline pattern'
    return result

def _xdzr8_v11833_surface_recovery_preserved_result(objects, reason):
    audit = _xdzr8_v11831_slot_usage_audit(objects)
    used_slots = int(audit.get('used_slot_count', 0))
    used_mats = int(audit.get('used_material_count', 0))
    return {
        'eligible': False, 'applied': False, 'reason': str(reason),
        'pmx_material_ranges': 0, 'mapped_ranges': 0,
        'reassigned_polygons': 0, 'changed_polygons': 0,
        'backup_created': False, 'backup_status': 'not needed; source assignment preserved',
        'topology': {}, 'mapping_rows': [], 'ambiguous': [], 'unresolved': [],
        'used_slots_before': used_slots, 'used_materials_before': used_mats,
        'used_slots_after': used_slots, 'used_materials_after': used_mats,
    }

