def _xdzr8_v1171_pmx_candidate_names(mat, source_ref=None):
    """Prefer preserved original source names over generated datablock names."""
    preferred, fallback = [], []
    for candidate in (mat, source_ref):
        if not candidate:
            continue
        try:
            src = str(candidate.get('SaberShader_V11_SourceMaterial', '') or '').strip()
        except Exception:
            src = ''
        if src and src not in preferred:
            preferred.append(src)
        try:
            name = str(candidate.name or '').strip()
        except Exception:
            name = ''
        if name and not name.startswith('SaberShader_V11_') and name not in fallback:
            fallback.append(name)
    return preferred + [n for n in fallback if n not in preferred]

def _xdzr8_v1171_dedupe_pmx_records(rows):
    out, seen = [], set()
    for rec in rows or []:

        ident = (
            rec.get('source_path','') or rec.get('source_file',''),
            int(rec.get('material_index', -1)),
            int(rec.get('local_occurrence', -1)),
            rec.get('local_name',''), rec.get('english_name',''),
        )
        if ident in seen:
            continue
        seen.add(ident)
        out.append(rec)
    return out

def _xdzr8_v1171_record_pmx_binding_audit(intelligence, audit_name, mode, records, alias_rejected=''):
    if not isinstance(intelligence, dict):
        return
    try:
        audit = intelligence.setdefault('_v1171_pmx_binding_audit', {})
        audit[str(audit_name or 'Material')] = {
            'mode': str(mode),
            'records': [str(r.get('local_name','') or r.get('english_name','')) for r in records or []],
            'count': len(records or []),
            'alias_rejected': str(alias_rejected or ''),
        }
    except Exception:
        pass

def _xdzr8_v1123_match_pmx_records(mat, source_ref, intelligence):
    """V11.8.3.1 source-scoped, occurrence-aware PMX material binding.

    Resolution order inside the already-selected PMX source:
      1. exact local_name + bound texture/occurrence resolution;
      2. normalized local_name + bound texture/occurrence resolution;
      3. structural local-name signature (numeric IDs erased) + occurrence;
      4. unique English aliases only.
    """
    info = intelligence if isinstance(intelligence, dict) else {}
    lookup = info.get('pmx_lookup') or {}
    if not lookup:
        return []
    names = _xdzr8_v1171_pmx_candidate_names(mat, source_ref)
    audit_name = names[0] if names else getattr(source_ref or mat, 'name', 'Material')

    def choose(mode, rows, raw_name):
        rows = _xdzr8_v1171_dedupe_pmx_records(rows)
        if not rows:
            return []
        picked, why = _xdzr8_v11831_choose_pmx_occurrence(rows, raw_name, mat, source_ref)
        if picked is not None:
            _xdzr8_v1171_record_pmx_binding_audit(
                info, audit_name, mode, [picked]
            )
            try:
                occ_audit = info.setdefault('_v11831_pmx_occurrence_audit', {})
                occ_audit[str(audit_name)] = {
                    'mode': mode,
                    'why': why,
                    'source_file': picked.get('source_file',''),
                    'material_index': int(picked.get('material_index', -1)),
                    'local_occurrence': int(picked.get('local_occurrence', -1)),
                    'local_name': picked.get('local_name',''),
                    'texture': picked.get('texture',''),
                }
            except Exception:
                pass
            return [picked]
        return []

    for name in names:
        bare = _xdzr8_v1171_pmx_bare_name(name)
        rows = (lookup.get('local_exact') or {}).get(bare.casefold(), []) if bare else []
        chosen = choose('local-exact', rows, name)
        if chosen:
            return chosen

    for name in names:
        key = _xdzr8_v1171_pmx_norm_name(name)
        rows = (lookup.get('local_norm') or {}).get(key, []) if key else []
        chosen = choose('local-normalized', rows, name)
        if chosen:
            return chosen

    for name in names:
        key = _xdzr8_v11831_structural_material_signature(name)
        rows = (lookup.get('local_structural') or {}).get(key, []) if key else []
        chosen = choose('local-structural', rows, name)
        if chosen:
            return chosen

    rejected = []
    for name in names:
        bare = _xdzr8_v1171_pmx_bare_name(name)
        exact_key = bare.casefold()
        if exact_key:
            rows = _xdzr8_v1171_dedupe_pmx_records((lookup.get('english_exact') or {}).get(exact_key, []))
            if exact_key not in (lookup.get('ambiguous_english_exact') or set()) and len(rows) == 1:
                _xdzr8_v1171_record_pmx_binding_audit(info, audit_name, 'english-exact-unique', rows)
                return rows
            if rows:
                rejected.append(f'{bare}:english-exact={len(rows)}')
        norm_key = _xdzr8_v1171_pmx_norm_name(name)
        if norm_key:
            rows = _xdzr8_v1171_dedupe_pmx_records((lookup.get('english_norm') or {}).get(norm_key, []))
            if norm_key not in (lookup.get('ambiguous_english_norm') or set()) and len(rows) == 1:
                _xdzr8_v1171_record_pmx_binding_audit(info, audit_name, 'english-normalized-unique', rows)
                return rows
            if rows:
                rejected.append(f'{bare}:english-normalized={len(rows)}')

    _xdzr8_v1171_record_pmx_binding_audit(info, audit_name, 'unresolved', [], '; '.join(dict.fromkeys(rejected)))
    return []

def _xdzr8_v1123_add_score(scores, evidence, role, value, reason):
    if role not in scores or not value:
        return
    scores[role] += float(value)
    evidence.setdefault(role, []).append(f'{reason} +{float(value):.1f}')

def _xdzr8_v11231_head_usage_bias(objects, mat=None):
    """Return conservative anatomical hints for a generic MMD Face-family material.

    The PMX memo ``Face`` describes a shader family in many MMD/game exports and
    may cover face skin, hair, lashes, eyes and accessories.  We therefore look
    at the actual Blender users of the material plus per-material vertex groups.
    This helper only supplies a tie-breaker; it never overrides exact names.
    """

    text_bits = []
    try:
        vg_text = _xdzr8_v112_material_vertex_group_text(mat, objects) if mat else ''
    except Exception:
        vg_text = ''
    if vg_text:
        text_bits.append(vg_text)
    text = _sabershader11_key(' '.join(text_bits))

    hair_tokens = ('hair','bang','bangs','fringe','ponytail','twintail','ahoge','kami','髪','发','髮')
    eye_tokens = ('eye','eyes','iris','pupil','hitomi','lash','lashes','brow','mayu','目','瞳','眉')
    face_tokens = ('face','head','skin','cheek','nose','chin','mouth','lip','顔','頭','肌')

    hair = sum(1 for t in hair_tokens if t and _sabershader11_key(t) in text)
    eyes = sum(1 for t in eye_tokens if t and _sabershader11_key(t) in text)
    face = sum(1 for t in face_tokens if t and _sabershader11_key(t) in text)
    return {'hair': hair, 'eyes': eyes, 'face': face, 'text': text}

def _xdzr8_v1123_metadata_assist(scores, evidence, mat, source_ref, objects, intelligence):
    """Apply source-metadata evidence to V11.2 role scores.

    V11.2.3.1 rule: PMX memo values such as Body/Face identify source shader
    families, not literal Blender material roles.  ``Face`` is therefore treated
    as *head-family context*. Exact names still decide Eye/Lash/Hair/Accessory;
    otherwise object and per-material vertex-group evidence breaks the tie.
    """
    assist = []
    info = intelligence or {}
    contextual = _xdzr8_v1122_contextual_existing_images(source_ref, _sabershader11_existing_role_images(source_ref) if source_ref else {}, info)
    if contextual.get('face_map'):
        _xdzr8_v1123_add_score(scores, evidence, 'face', 5.6, 'semantic FaceMap')
        assist.append('FaceMap→face')
    if contextual.get('opacity'):
        _xdzr8_v1123_add_score(scores, evidence, 'transparent_cloth', 1.5, 'semantic opacity')
        assist.append('opacity→transparent')

    records = _xdzr8_v1123_match_pmx_records(mat, source_ref, info)
    for rec in records:
        local_name = rec.get('local_name','')
        english_name = rec.get('english_name','')
        memo = rec.get('memo','')
        texture = rec.get('texture','')
        combined_name = ' '.join(x for x in (local_name, english_name) if x)
        _xdzr8_v112_score_text(scores, evidence, combined_name, 5.4, 'pmx-name')
        key = _sabershader11_key(combined_name)
        local_key = _sabershader11_key(local_name)
        memo_key = _sabershader11_key(memo)
        tex_key = _sabershader11_key(Path(texture.replace('\\','/')).stem if texture else '')

        structural = _xdzr8_v11831_structural_material_signature(local_name or english_name)
        if 'bdy' in structural or structural.startswith('body'):
            _xdzr8_v1123_add_score(scores, evidence, 'body', 4.0, 'scoped PMX body-family structural stem')
            _xdzr8_v1123_add_score(scores, evidence, 'cloth', 1.6, 'scoped PMX body-family clothing possibility')
            assist.append(f'{local_name or english_name}:ScopedPMX→body-family')
        if 'tail' in structural:
            _xdzr8_v1123_add_score(scores, evidence, 'hair', 4.2, 'scoped PMX tail/hair-like structural stem')
            assist.append(f'{local_name or english_name}:ScopedPMX→tail/hair')

        if 'face' in memo_key:

            if any(t in key for t in ('eye','iris','pupil','highlight','eyelight','hitomi')):
                _xdzr8_v1123_add_score(scores, evidence, 'eyes', 6.2, 'PMX head-family eye material')
                assist.append(f'{local_name or english_name}:Head-family→eyes')
            elif any(t in key for t in ('lash','brow','mayu')):
                _xdzr8_v1123_add_score(scores, evidence, 'eyes5', 5.8, 'PMX head-family lash/brow material')
                assist.append(f'{local_name or english_name}:Head-family→eyes5')
            elif any(t in key for t in ('hair','bang','fringe','kami')):
                _xdzr8_v1123_add_score(scores, evidence, 'hair', 5.2, 'PMX head-family hair material')
                assist.append(f'{local_name or english_name}:Head-family→hair')
            elif local_key in {'acc','accessory'} or key in {'acc','accessory'} or 'accessory' in key:
                _xdzr8_v1123_add_score(scores, evidence, 'accessory', 5.0, 'PMX head-family accessory material')
                assist.append(f'{local_name or english_name}:Head-family→accessory')
            else:
                usage = _xdzr8_v11231_head_usage_bias(objects, mat)
                best = max(('hair','eyes','face'), key=lambda r: usage[r])
                best_n = usage[best]
                ordered = sorted((usage[r], r) for r in ('hair','eyes','face'))
                runner_n = ordered[-2][0]

                if best_n > 0 and best_n > runner_n:
                    boost = 3.0 + min(1.6, 0.55 * float(best_n))
                    _xdzr8_v1123_add_score(scores, evidence, best, boost, f'PMX head-family Blender usage ({best})')
                    assist.append(f'{local_name or english_name}:Head-family usage→{best}')
                else:
                    _xdzr8_v1123_add_score(scores, evidence, 'face', 0.8, 'PMX head-family neutral context')
                    _xdzr8_v1123_add_score(scores, evidence, 'hair', 0.8, 'PMX head-family neutral context')
                    _xdzr8_v1123_add_score(scores, evidence, 'eyes', 0.5, 'PMX head-family neutral context')
                    assist.append(f'{local_name or english_name}:Head-family neutral context')
        elif 'body' in memo_key:
            if any(t in key for t in ('skin','body','hand','arm','leg','neck','ear')):
                _xdzr8_v1123_add_score(scores, evidence, 'body', 5.0, 'PMX Body-family skin/body material')
                assist.append(f'{local_name or english_name}:Body-family→body')
            elif any(t in key for t in ('tie','cloth','dress','shirt','skirt','jacket','coat','sleeve','uniform')):
                _xdzr8_v1123_add_score(scores, evidence, 'cloth', 4.8, 'PMX Body-family clothing material')
                assist.append(f'{local_name or english_name}:Body-family→cloth')
            elif local_key in {'acc','accessory'} or key in {'acc','accessory'} or 'accessory' in key:
                _xdzr8_v1123_add_score(scores, evidence, 'accessory', 4.5, 'PMX Body-family accessory material')
                assist.append(f'{local_name or english_name}:Body-family→accessory')
            else:
                _xdzr8_v1123_add_score(scores, evidence, 'body', 2.4, 'PMX Body shader-family memo')
                _xdzr8_v1123_add_score(scores, evidence, 'cloth', 2.1, 'PMX Body shader-family memo')
                assist.append(f'{local_name or english_name}:Body-family context')
        else:
            _xdzr8_v112_score_text(scores, evidence, memo, 3.8, 'pmx-memo')

        if 'chr' in tex_key and 'face' in memo_key:
            _xdzr8_v1123_add_score(scores, evidence, 'face', 0.30, 'PMX chr/head texture family')
            _xdzr8_v1123_add_score(scores, evidence, 'hair', 0.30, 'PMX chr/head texture family')
            _xdzr8_v1123_add_score(scores, evidence, 'eyes', 0.15, 'PMX chr/head texture family')
        if 'bdy' in tex_key and 'body' in memo_key:
            _xdzr8_v1123_add_score(scores, evidence, 'body', 0.5, 'PMX bdy texture family')
            _xdzr8_v1123_add_score(scores, evidence, 'cloth', 0.4, 'PMX bdy texture family')
    return assist, records

def _xdzr8_v1122_general_signature(stems):
    joined = ' '.join(_sabershader11_key(s) for s in stems)
    tags = []

    if 'otherdatatex' in joined or ('lighttex' in joined and 'facemap' in joined):
        tags.append('packed toon data')
    if 'materialmaskstex' in joined or 'materialmasks' in joined:
        tags.append('material-mask data')
    if 'facemaptex' in joined or 'facemap' in joined:
        tags.append('face-map data')
    if 'lightmaptex' in joined or 'lightmap' in joined or 'lighttex' in joined:
        tags.append('light/toon map data')
    return tags

def _sabershader_v1_detect_fgo_arcade_profile(image_paths=None, objects=None, materials=None):
    """Detect Fate/Grand Order Arcade without depending on a configured texture root."""
    names = [Path(str(p)).name.casefold() for p in (image_paths or [])]

    try:
        for img in bpy.data.images:
            iname = Path(str(getattr(img, 'name', '') or '')).name.casefold()
            if iname:
                names.append(iname)
            fp = str(getattr(img, 'filepath', '') or '')
            if fp:
                names.append(Path(fp.replace('\\', '/')).name.casefold())
    except Exception:
        pass

    score = 0.0
    evidence = []
    svt = sum(1 for n in names if n.startswith('svt_'))
    ramps = sum(1 for n in names if n.startswith('_ramp01'))
    normals = sum(1 for n in names if re.search(r'_n0?\.(?:dds|png|tga|jpg|jpeg|bmp)$', n))
    specs = sum(1 for n in names if re.search(r'_s\.(?:dds|png|tga|jpg|jpeg|bmp)$', n))
    alpha = sum(1 for n in names if n.startswith('_a_') and re.search(r'_a\.(?:dds|png|tga|jpg|jpeg|bmp)$', n))
    if svt >= 4: score += 4.0; evidence.append(f'SVT texture family={svt}')
    elif svt >= 2: score += 2.2; evidence.append(f'partial SVT texture family={svt}')
    if ramps >= 4: score += 4.0; evidence.append(f'_ramp01 LUT family={ramps}')
    elif ramps >= 2: score += 2.0; evidence.append(f'partial _ramp01 LUT family={ramps}')
    if any('face_bs' in n for n in names): score += 1.8; evidence.append('face_bs map')
    if any('facebase' in n for n in names): score += 1.5; evidence.append('facebase map')
    if any('cheek' in n for n in names): score += 1.0; evidence.append('cheek map')
    if any('envmap_eye' in n or 'envmap_divaeye' in n for n in names): score += 1.4; evidence.append('eye environment map')
    if any('eye_left_h' in n or 'eye_right_h' in n for n in names): score += 1.2; evidence.append('eye highlight map')
    if normals >= 2: score += 1.0; evidence.append(f'normal derivative family={normals}')
    if specs >= 2: score += 1.0; evidence.append(f'specular derivative family={specs}')
    if alpha >= 1: score += 0.8; evidence.append(f'alpha derivative family={alpha}')

    mat_names = []
    for mat in materials or []:
        try: mat_names.append(str(getattr(mat, 'name', '') or '').casefold())
        except Exception: pass

    try:
        mat_names.extend(str(getattr(mat, 'name', '') or '').casefold() for mat in bpy.data.materials)
    except Exception:
        pass
    fgo_mats = [n for n in mat_names if n.startswith('mt_') and any(t in n for t in ('face','hair','skin','cloth','armor','chestarm','eye','oral','cheek','gold'))]
    if len(set(fgo_mats)) >= 4:
        score += 4.0; evidence.append(f'mt_* FGO material family={len(set(fgo_mats))}')
    if any('mt_face_bs' in n for n in fgo_mats): score += 1.0; evidence.append('mt_face_bs material')
    if any('mt_hair' in n for n in fgo_mats): score += 0.8; evidence.append('mt_hair material')
    if any('mt_skin' in n for n in fgo_mats): score += 0.8; evidence.append('mt_skin material')

    object_names = []
    try:
        object_names = [str(getattr(o, 'name', '') or '').casefold() for o in (objects or [])]
        if len(object_names) < 4:
            object_names.extend(str(getattr(o, 'name', '') or '').casefold() for o in bpy.context.scene.objects)
    except Exception:
        pass
    model_blocks = sum(1 for n in object_names if n.startswith('model|-'))
    if model_blocks >= 4:
        score += 3.0; evidence.append(f'MODEL| mesh blocks={model_blocks}')
    object_blob = ' '.join(object_names)
    if all(tok in object_blob for tok in ('face_gp','hair_gp','skin_gp')):
        score += 1.5; evidence.append('face_gp/hair_gp/skin_gp object structure')

    enabled = score >= 7.0
    confidence = 'HIGH' if score >= 11.0 else ('MEDIUM' if enabled else 'LOW')
    return {'enabled': bool(enabled), 'score': float(score), 'confidence': confidence, 'evidence': list(dict.fromkeys(evidence))}

def _sabershader_v1022_dds_header(path):
    """Read only the DDS header needed by the FGO Arcade source profiler.

    No pixels are decoded here. The goal is to distinguish ordinary 2D ARGB/RGBA
    surfaces from DDS cubemaps before Blender's Image loader/GPU path sees them.
    """
    import struct
    result = {
        'valid': False, 'path': str(path or ''), 'name': '', 'width': 0, 'height': 0,
        'mipmaps': 0, 'depth': 0, 'rgb_bits': 0, 'fourcc': '', 'pixel_format': '',
        'caps2': 0, 'cubemap': False, 'cubemap_faces': 0, 'surface_count': 1,
        'r_mask': 0, 'g_mask': 0, 'b_mask': 0, 'a_mask': 0, 'error': '',
    }
    try:
        p = Path(path)
        result['name'] = p.name
        with p.open('rb') as fh:
            data = fh.read(128)
        if len(data) < 128 or data[:4] != b'DDS ':
            result['error'] = 'not a DDS header'
            return result
        header_size = struct.unpack_from('<I', data, 4)[0]
        if header_size != 124:
            result['error'] = f'unexpected DDS header size {header_size}'
            return result
        height = struct.unpack_from('<I', data, 12)[0]
        width = struct.unpack_from('<I', data, 16)[0]
        depth = struct.unpack_from('<I', data, 24)[0]
        mipmaps = struct.unpack_from('<I', data, 28)[0]
        pf_flags = struct.unpack_from('<I', data, 80)[0]
        fourcc_raw = data[84:88]
        rgb_bits = struct.unpack_from('<I', data, 88)[0]
        r_mask, g_mask, b_mask, a_mask = struct.unpack_from('<IIII', data, 92)
        caps2 = struct.unpack_from('<I', data, 112)[0]
        is_cube = bool(caps2 & 0x00000200)
        face_bits = (0x00000400, 0x00000800, 0x00001000, 0x00002000, 0x00004000, 0x00008000)
        face_count = sum(1 for bit in face_bits if caps2 & bit) if is_cube else 0
        try:
            fourcc = fourcc_raw.decode('ascii', errors='ignore').rstrip('\x00 ')
        except Exception:
            fourcc = ''
        pixel_format = 'UNKNOWN'
        if fourcc:
            pixel_format = f'FOURCC:{fourcc}'
        elif rgb_bits == 32 and (pf_flags & 0x40):
            if (r_mask, g_mask, b_mask, a_mask) == (0x00FF0000, 0x0000FF00, 0x000000FF, 0xFF000000):
                pixel_format = 'ARGB8888'
            else:
                pixel_format = 'RGB32'
        elif rgb_bits:
            pixel_format = f'RGB{rgb_bits}'
        result.update({
            'valid': True, 'width': int(width), 'height': int(height), 'depth': int(depth),
            'mipmaps': int(mipmaps), 'rgb_bits': int(rgb_bits), 'fourcc': fourcc,
            'pixel_format': pixel_format, 'caps2': int(caps2), 'cubemap': bool(is_cube),
            'cubemap_faces': int(face_count), 'surface_count': int(max(1, face_count if is_cube else 1)),
            'r_mask': int(r_mask), 'g_mask': int(g_mask), 'b_mask': int(b_mask), 'a_mask': int(a_mask),
        })
    except Exception as exc:
        result['error'] = str(exc)
    return result

def _sabershader_v1023_fgo_dds_cache_from_path(path, colorspace=None):
    """Decode source-scoped FGO Arcade uncompressed ARGB8888 DDS into a generated Blender image.

    The reviewed FGO Arcade pack stores its ordinary 2D textures as uncompressed
    32-bit DDS surfaces. Blender 5.1 can discover these files but may fail when
    creating a GPU texture. This decoder reads the source bytes directly and
    creates a packed Blender image, bypassing Blender's DDS loader completely.

    Cubemaps and unsupported DDS pixel formats fail closed. Ramps are technically
    decodable too, but association remains a separate semantic decision.
    """
    import struct
    from array import array
    if not path:
        return None, False, 'missing DDS path'
    try:
        p = Path(path).resolve()
    except Exception as exc:
        return None, False, f'invalid DDS path: {exc}'
    lname = p.name.casefold()
    if p.suffix.casefold() != '.dds' or not lname.startswith(('svt_', '_a_svt_', '_ramp01')):
        return None, False, 'not source-scoped FGO DDS'

    hdr = _sabershader_v1022_dds_header(p)
    if not hdr.get('valid', False):
        return None, False, f'invalid DDS header: {hdr.get("error", "unknown")}'
    if hdr.get('cubemap', False):
        return None, False, 'DDS cubemap intentionally excluded from 2D cache'
    if str(hdr.get('pixel_format', '')) != 'ARGB8888' or int(hdr.get('rgb_bits', 0)) != 32:
        return None, False, f'unsupported DDS pixel format {hdr.get("pixel_format", "UNKNOWN")}'

    width = int(hdr.get('width', 0)); height = int(hdr.get('height', 0))
    if width <= 0 or height <= 0:
        return None, False, 'invalid DDS dimensions'
    if width * height > 16_777_216:
        return None, False, f'DDS too large for safe cache ({width}x{height})'

    source_key = os.path.normcase(str(p))
    cache_name = 'SaberShader - DDS Cache - ' + p.stem
    for existing in bpy.data.images:
        try:
            if bool(existing.get('SaberShader_V1023_FGONativeDDSCache', False)) and str(existing.get('SaberShader_V1023_DDSSource', '')) == source_key:
                if colorspace:
                    try: existing.colorspace_settings.name = str(colorspace)
                    except Exception: pass
                return existing, False, 'native ARGB8888 cache reused'
        except Exception:
            pass

    try:
        raw = p.read_bytes()
        expected = width * height * 4
        if len(raw) < 128 + expected:
            return None, False, f'DDS payload truncated ({len(raw)-128} < {expected})'
        payload = memoryview(raw)[128:128+expected]

        r_mask = int(hdr.get('r_mask', 0)); g_mask = int(hdr.get('g_mask', 0))
        b_mask = int(hdr.get('b_mask', 0)); a_mask = int(hdr.get('a_mask', 0))
        masks = (r_mask, g_mask, b_mask, a_mask)

        def shift_and_max(mask):
            if not mask:
                return 0, 0
            shift = (mask & -mask).bit_length() - 1
            maximum = mask >> shift
            return shift, maximum
        channels = [shift_and_max(m) for m in masks]

        pixels = array('f', [0.0]) * (width * height * 4)

        dst = 0
        for y in range(height-1, -1, -1):
            row_off = y * width * 4
            for x in range(width):
                off = row_off + x * 4
                value = int.from_bytes(payload[off:off+4], 'little', signed=False)
                for ci, mask in enumerate(masks):
                    if ci == 3 and not mask:
                        pixels[dst+ci] = 1.0
                        continue
                    shift, maximum = channels[ci]
                    comp = ((value & mask) >> shift) if mask and maximum else 0
                    pixels[dst+ci] = float(comp) / float(maximum) if maximum else (1.0 if ci == 3 else 0.0)
                dst += 4

        image = bpy.data.images.new(cache_name, width=width, height=height, alpha=True, float_buffer=False)
        image.pixels.foreach_set(pixels)
        image.update()
        if colorspace:
            try: image.colorspace_settings.name = str(colorspace)
            except Exception: pass
        try: image.alpha_mode = 'STRAIGHT'
        except Exception: pass
        try: image.pack()
        except Exception: pass
        image['SaberShader_V1023_FGONativeDDSCache'] = True
        image['SaberShader_V1023_DDSSource'] = source_key
        image['SaberShader_V1023_DDSSourceName'] = p.name
        image['SaberShader_V1023_DDSWidth'] = width
        image['SaberShader_V1023_DDSHeight'] = height
        image['SaberShader_V1023_DDSPixelFormat'] = str(hdr.get('pixel_format', ''))
        image['SaberShader_V1023_DDSVerticalFlip'] = True
        return image, True, f'native ARGB8888 cache {width}x{height}'
    except Exception as exc:
        return None, False, f'native DDS decode failed: {exc}'

def _sabershader_v1023_role_colorspace(role):
    role = str(role or '').strip().lower()
    if role in {'base', 'emission', 'emotion'}:
        return 'sRGB'
    return 'Non-Color'

def _sabershader_v1022_fgo_source_scope(folder=None):
    """Resolve one direct FGO Arcade Servant/stage texture directory.

    V1.0.2.1 recursively scanned around the .blend and could absorb ramps from
    neighboring Servants. V1.0.2.2 deliberately scores *direct* directories and
    never recursively merges multiple character folders. The authoritative source
    directory is preferably the configured texture folder or the active .blend's
    own directory.
    """
    candidates = []
    seen_dirs = set()

    def add_dir(value, priority):
        if not value:
            return
        try:
            p = Path(value)
            if p.is_file():
                p = p.parent
            p = p.resolve()
        except Exception:
            return
        if not p.is_dir():
            return
        key = os.path.normcase(str(p))
        if key in seen_dirs:
            return
        seen_dirs.add(key)
        candidates.append((int(priority), p))

    add_dir(folder, 120)
    try:
        if bpy.data.filepath:
            add_dir(Path(bpy.data.filepath).resolve().parent, 140)
    except Exception:
        pass

    for priority, root in list(candidates):
        try:
            for child in root.iterdir():
                if child.is_dir():
                    add_dir(child, priority - 35)
        except Exception:
            pass

    best = None
    audits = []
    for priority, root in candidates:
        try:
            direct = sorted(
                [p for p in root.iterdir() if p.is_file() and p.suffix.casefold() == '.dds'],
                key=lambda p: p.name.casefold(),
            )
        except Exception:
            direct = []
        fgo = [p for p in direct if p.name.casefold().startswith(('svt_', '_a_svt_', '_ramp01'))]
        ramps = [p for p in fgo if p.name.casefold().startswith('_ramp01')]
        svt = [p for p in fgo if p.name.casefold().startswith(('svt_', '_a_svt_'))]
        semantic_hits = sum(1 for p in svt if any(tok in p.name.casefold() for tok in ('facebase','face_bs','hair','skin','clothall','chestarm','eye_left')))
        score = priority + min(len(svt), 50) * 3 + min(len(ramps), 64) + semantic_hits * 7
        audits.append({'dir': str(root), 'dds': len(direct), 'fgo': len(fgo), 'svt': len(svt), 'ramps': len(ramps), 'score': score})
        if len(svt) < 4:
            continue
        row = (score, len(fgo), -len(str(root)), root, fgo)
        if best is None or row[:3] > best[:3]:
            best = row

    result = {
        'resolved': False, 'root': '', 'paths': [], 'renderable_paths': [],
        'cubemap_paths': [], 'ramp_paths': [], 'mask_rgb_paths': [], 'dds_metadata': {},
        'dds_count': 0, 'renderable_count': 0, 'cubemap_count': 0, 'ramp_count': 0,
        'mask_rgb_count': 0, 'audit': audits,
    }
    if best is None:
        return result

    root = best[3]
    paths = list(best[4])
    metadata = {}
    cubemaps = []
    ramps = []
    masks = []
    renderable = []
    for p in paths:
        hdr = _sabershader_v1022_dds_header(p)
        metadata[p.name.casefold()] = hdr
        lname = p.name.casefold()
        if lname.startswith('_ramp01'):
            ramps.append(p)
        if lname.startswith('_a_svt_') and lname.endswith('_a.dds'):
            masks.append(p)
        if hdr.get('cubemap', False):
            cubemaps.append(p)
        else:
            renderable.append(p)

    result.update({
        'resolved': True, 'root': str(root), 'paths': paths,
        'renderable_paths': renderable, 'cubemap_paths': cubemaps,
        'ramp_paths': ramps, 'mask_rgb_paths': masks, 'dds_metadata': metadata,
        'dds_count': len(paths), 'renderable_count': len(renderable),
        'cubemap_count': len(cubemaps), 'ramp_count': len(ramps),
        'mask_rgb_count': len(masks),
    })
    return result

def _sabershader_v101_fgo_local_image_paths(folder=None):
    """Compatibility wrapper returning the single source-scoped FGO DDS set."""
    return list(_sabershader_v1022_fgo_source_scope(folder).get('paths', []) or [])

def _sabershader_v1022_is_fgo_cubemap_name(name, intelligence=None):
    key = Path(str(name or '')).name.casefold()
    if not key:
        return False
    info = intelligence or {}
    names = {Path(str(p)).name.casefold() for p in (info.get('fgo_cubemap_paths') or [])}
    if key in names:
        return True
    meta = (info.get('fgo_dds_metadata') or {}).get(key, {})
    return bool(meta.get('cubemap', False))

def _sabershader_v1022_is_fgo_rgb_mask(image, intelligence=None):
    if image is None or not bool(((intelligence or {}).get('fgo_arcade_profile') or {}).get('enabled', False)):
        return False
    try:
        name = Path(str(getattr(image, 'name', '') or getattr(image, 'filepath', '') or '')).name.casefold()
    except Exception:
        return False
    return bool(name.startswith('_a_svt_') and name.endswith('_a.dds'))

def _sabershader_v1021_fgo_native_binding_records(materials, image_paths, dds_metadata=None):
    """Build conservative FGO Arcade bindings from semantic filename suffixes.

    FGO Arcade textures carry a character/stage prefix (SVT_####_S##_*) so the
    V1.0.2 exact-name matcher could detect the bundle but not bind e.g. "hair"
    to "SVT_0001_S02_hair.dds". V1.0.2.1 treats the suffix after the SVT prefix
    as authoritative, keeps normal/spec/alpha companions in the same family,
    and deliberately leaves anonymous _ramp01 LUTs unbound until their material
    association can be proven from source data.
    """
    materials = [m for m in (materials or []) if m is not None]
    paths = [Path(p) for p in (image_paths or []) if p is not None]
    if not materials or not paths:
        return [], {}, {}, [], {}

    def norm(text):
        return str(text or '').casefold().replace('\\', '/')

    def semantic_suffix(stem):
        s = norm(stem)

        s = re.sub(r'^svt_\d+_s\d+_', '', s)
        return s

    rows = []
    for p in paths:
        try:
            name = p.name
            stem = p.stem
        except Exception:
            continue
        if not name:
            continue
        lower = norm(name)
        suffix = semantic_suffix(stem)
        role = _xdzr8_v1122_semantic_role(name, {'fgo_arcade_profile': {'enabled': True}})
        stage = 0
        m = re.search(r'_s(\d+)_', lower)
        if m:
            try: stage = int(m.group(1))
            except Exception: stage = 0
        rows.append({
            'path': p, 'name': name, 'stem': norm(stem), 'suffix': suffix,
            'key': _sabershader11_key(stem), 'role': role, 'stage': stage,
        })

    def find_suffix(token, role=None, allow_alpha=False):
        token = norm(token).strip('_')
        if not token:
            return ''
        candidates = []
        for row in rows:
            suffix = row['suffix'].strip('_')
            if not allow_alpha and suffix.startswith('_a_'):
                continue
            if role and row['role'] != role:
                continue

            exact = suffix == token
            keyed = _sabershader11_key(suffix).endswith(_sabershader11_key(token))
            if not (exact or keyed):
                continue
            score = (20 if exact else 10) + min(int(row.get('stage', 0)), 9)
            candidates.append((score, row['name']))
        candidates.sort(key=lambda item: (-item[0], item[1].casefold()))
        return candidates[0][1] if candidates else ''

    def find_alpha_for(token):

        wanted = norm(token).strip('_')
        candidates = []
        for row in rows:
            stem = row['stem']
            if not stem.startswith('_a_svt_') or not stem.endswith('_a'):
                continue
            inner = re.sub(r'^_a_svt_\d+_s\d+_', '', stem)
            inner = re.sub(r'_a$', '', inner)
            if inner != wanted:
                continue
            score = 20 + min(int(row.get('stage', 0)), 9)
            candidates.append((score, row['name']))
        candidates.sort(key=lambda item: (-item[0], item[1].casefold()))
        return candidates[0][1] if candidates else ''

    known = {
        'face_base': find_suffix('facebase', 'base') or find_suffix('face', 'base'),
        'face_shadow': find_suffix('face_bs', 'shadow_color'),
        'cheek': find_suffix('cheek', 'emotion'),
        'cheek_alpha': find_alpha_for('cheek'),
        'skin': find_suffix('skin', 'base'),
        'hair': find_suffix('hair', 'base'),
        'hair_n': find_suffix('hair_n0', 'normal') or find_suffix('hair_n', 'normal'),
        'hair_s': find_suffix('hair_s', 'specular'),
        'cloth': find_suffix('clothall', 'base'),
        'cloth_n': find_suffix('clothall_n0', 'normal') or find_suffix('clothall_n', 'normal'),
        'cloth_s': find_suffix('clothall_s', 'specular'),
        'armor': find_suffix('chestarm', 'base'),
        'armor_n': find_suffix('chestarm_n0', 'normal') or find_suffix('chestarm_n', 'normal'),
        'armor_s': find_suffix('chestarm_s', 'specular'),
        'white': find_suffix('white', 'base'),
        'white_n': find_suffix('white_n0', 'normal') or find_suffix('white_n', 'normal'),
        'white_s': find_suffix('white_s', 'specular'),
        'white_alpha': find_alpha_for('white'),
        'gold': find_suffix('alfa_gold', 'base'),
        'gold_n': find_suffix('alfa_gold_n', 'normal'),
        'gold_s': find_suffix('alfa_gold_s', 'specular'),
        'gold_alpha': find_alpha_for('alfa_gold'),
        'eye_left': find_suffix('eye_left', 'base'),
        'eye_right': find_suffix('eye_right', 'base'),
        'eye_left_n': find_suffix('eye_left_n', 'normal'),
        'eye_right_n': find_suffix('eye_right_n', 'normal'),
        'eye_left_h': find_suffix('eye_left_h', 'highlight'),
        'eye_right_h': find_suffix('eye_right_h', 'highlight'),
        'eye_spec': find_suffix('eye_s', 'specular'),
        'eye_env': find_suffix('envmap_eye', 'reflection'),
        'eye_env_diva': find_suffix('envmap_divaeye10', 'reflection'),
    }

    records = []
    texture_role_sets = {}
    evidence = []

    def note_role(tex_name, role):
        if tex_name and role:
            texture_role_sets.setdefault(Path(tex_name).name.casefold(), set()).add(role)

    for mat in materials:
        try:
            mat_name = str(mat.get('SaberShader_V11_SourceMaterial', mat.name) or mat.name)
        except Exception:
            mat_name = str(getattr(mat, 'name', '') or '')
        lower = norm(mat_name)
        if not lower.startswith('mt_'):
            continue
        slots = {}
        roles = {}

        def bind(slot_name, role, tex_name):
            if not tex_name:
                return
            tex_name = Path(tex_name).name
            slots[slot_name] = tex_name
            roles.setdefault(role, []).append(tex_name)
            note_role(tex_name, role)

        if any(t in lower for t in ('mt_face_bs', 'mt_faceback', 'mt_faceparts')):
            bind('BaseMap', 'base', known['face_base'])
            bind('ShadowColorMap', 'shadow_color', known['face_shadow'])
            bind('EmotionMap', 'emotion', known['cheek'])
        elif 'mt_cheek' in lower:
            bind('BaseMap', 'base', known['cheek'] or known['face_base'])
            bind('OpacityMap', 'opacity', known['cheek_alpha'])
        elif 'mt_hair' in lower:
            bind('BaseMap', 'base', known['hair'])
            bind('NormalMap', 'normal', known['hair_n'])
            bind('SpecularMap', 'specular', known['hair_s'])
        elif re.search(r'(^|\W)mt_skin(?:\W|$)', lower):
            bind('BaseMap', 'base', known['skin'])
        elif 'mt_eye_l' in lower or 'mt_eye_left' in lower:
            bind('BaseMap', 'base', known['eye_left'])
            bind('NormalMap', 'normal', known['eye_left_n'])
            bind('HighlightMap', 'highlight', known['eye_left_h'])
            bind('SpecularMap', 'specular', known['eye_spec'])

        elif 'mt_eye_r' in lower or 'mt_eye_right' in lower:
            bind('BaseMap', 'base', known['eye_right'] or known['eye_left'])
            bind('NormalMap', 'normal', known['eye_right_n'] or known['eye_left_n'])
            bind('HighlightMap', 'highlight', known['eye_right_h'] or known['eye_left_h'])
            bind('SpecularMap', 'specular', known['eye_spec'])

        elif any(t in lower for t in ('mt_eyehole', 'mt_eyelash', 'mt_eyebrow', 'mt_eyelid')):

            pass
        elif any(t in lower for t in ('mt_oral', 'mt_tooth')):
            bind('BaseMap', 'base', known['face_base'] or known['skin'])
        elif 'mt_cloth' in lower:
            bind('BaseMap', 'base', known['cloth'])
            bind('NormalMap', 'normal', known['cloth_n'])
            bind('SpecularMap', 'specular', known['cloth_s'])
        elif any(t in lower for t in ('mt_moon_gold', 'mt_alfa_gold')):
            bind('BaseMap', 'base', known['gold'] or known['white'] or known['armor'])
            bind('NormalMap', 'normal', known['gold_n'] or known['white_n'] or known['armor_n'])
            bind('SpecularMap', 'specular', known['gold_s'] or known['white_s'] or known['armor_s'])
            bind('OpacityMap', 'opacity', known['gold_alpha'])
        elif 'mt_white' in lower:
            bind('BaseMap', 'base', known['white'] or known['cloth'])
            bind('NormalMap', 'normal', known['white_n'] or known['cloth_n'])
            bind('SpecularMap', 'specular', known['white_s'] or known['cloth_s'])
            bind('OpacityMap', 'opacity', known['white_alpha'])
        elif any(t in lower for t in ('mt_armora', 'mt_chestarm', 'mt_gauntlet', 'mt_guntlet')):
            bind('BaseMap', 'base', known['armor'] or known['white'] or known['cloth'])
            bind('NormalMap', 'normal', known['armor_n'] or known['white_n'] or known['cloth_n'])
            bind('SpecularMap', 'specular', known['armor_s'] or known['white_s'] or known['cloth_s'])

        if slots:
            cubemap_refs = {}
            if ('mt_eye_l' in lower or 'mt_eye_left' in lower or 'mt_eye_r' in lower or 'mt_eye_right' in lower):
                if known.get('eye_env'):
                    cubemap_refs['reflection'] = known.get('eye_env')
                if known.get('eye_env_diva'):
                    cubemap_refs['reflection_alt'] = known.get('eye_env_diva')
            records.append({
                'material_name': mat_name,
                'source_file': 'native_fgo_arcade_suffix_bindings',
                'slots': slots,
                'roles': roles,
                'cubemaps': cubemap_refs,
                'flags': {
                    'native_fgo_arcade': True, 'suffix_recovery': True,
                    'rgb_mask_channel': 'LUMINANCE', 'cubemap_aware': True,
                },
            })
            evidence.append(f'native FGO suffix binding: {mat_name} -> {sorted(roles)}')

    texture_roles = {}
    ambiguous = {}
    for tex_name, role_set in texture_role_sets.items():
        if len(role_set) == 1:
            texture_roles[tex_name] = next(iter(role_set))
        elif role_set:
            ambiguous[tex_name] = sorted(role_set)
    _meta = dds_metadata or {}
    _cube_known = [v for k, v in known.items() if k.startswith('eye_env') and v]
    audit = {
        'known': {k: v for k, v in known.items() if v},
        'records': len(records),
        'bound_textures': len(texture_roles),
        'ramps_bound': 0,
        'rgb_mask_channel': 'LUMINANCE',
        'cubemap_bindings': list(dict.fromkeys(_cube_known)),
        'cubemap_count': sum(1 for row in _meta.values() if row.get('cubemap', False)),
    }
    return records, texture_roles, ambiguous, evidence, audit

def _sabershader_v1029_read_cstring(data, offset):
    try:
        end = data.find(b'\0', int(offset))
        if end < 0:
            return '', int(offset)
        return data[int(offset):end].decode('utf-8', 'replace'), end + 1
    except Exception:
        return '', int(offset)

def _sabershader_v1029_find_native_files(fgo_source_scope):
    """Find the source-scoped FGO Arcade obj/tex pair without recursive searching."""
    root_text = str((fgo_source_scope or {}).get('root', '') or '')
    if not root_text:
        return None, None
    root = Path(root_text)
    char_id = root.name
    obj_candidates = [root / f'{char_id}_obj.bin']
    tex_candidates = [root / f'{char_id}_tex.bin']
    try:
        obj_candidates.extend(sorted(root.glob('*_obj.bin'))[:8])
        tex_candidates.extend(sorted(root.glob('*_tex.bin'))[:8])
    except Exception:
        pass
    obj_path = next((p for p in obj_candidates if p.exists() and p.is_file()), None)
    tex_path = next((p for p in tex_candidates if p.exists() and p.is_file()), None)
    return obj_path, tex_path

def _sabershader_v1029_texbin_names(tex_path):
    if tex_path is None:
        return [], {'valid': False, 'reason': 'tex.bin missing'}
    try:
        data = Path(tex_path).read_bytes()
        if len(data) < 2:
            return [], {'valid': False, 'reason': 'tex.bin too small'}
        count = struct.unpack_from('<H', data, 0)[0]
        pos = 2
        names = []
        for _ in range(int(count)):
            if pos >= len(data):
                raise ValueError('texture name table truncated')
            nlen = int(data[pos]); pos += 1
            if pos + nlen + 4 > len(data):
                raise ValueError('texture name entry truncated')
            name = data[pos:pos+nlen].decode('ascii', 'replace'); pos += nlen
            _offset = struct.unpack_from('<I', data, pos)[0]; pos += 4
            names.append(name)
        return names, {'valid': True, 'count': len(names), 'path': str(tex_path)}
    except Exception as exc:
        return [], {'valid': False, 'reason': str(exc), 'path': str(tex_path)}

def _sabershader_v1029_native_texture_filename(native_name, char_id, available_paths=None):
    """Translate tex.bin names such as svt_0001_s02_SVT_* into source DDS basenames."""
    raw = str(native_name or '')
    lower = raw.casefold()
    prefix = str(char_id or '').casefold() + '_'
    short = raw[len(prefix):] if prefix and lower.startswith(prefix) else raw
    desired = short if short.casefold().endswith('.dds') else short + '.dds'
    available = {Path(p).name.casefold(): Path(p).name for p in (available_paths or [])}
    if desired.casefold() in available:
        return available[desired.casefold()]

    d_stem = Path(desired).stem.casefold()
    for key, actual in available.items():
        if Path(actual).stem.casefold() == d_stem:
            return actual
    return desired

def _sabershader_v1029_parse_objbin_material_table(obj_path, tex_path, source_paths=None):
    """Parse native FGO Arcade material records and all shader texture slots.

    Format follows the public FGOA objset structure, but this parser is standalone
    and keeps the 136-byte material parameter block instead of discarding it.
    Slot semantics are deliberately conservative: only the slots already exported
    by the established parser (0/4/8/16/18) are treated as known. Other slots,
    including 1/2/5/6 ramps, stay numbered and source-authored.
    """
    audit = {
        'valid': False, 'obj_path': str(obj_path or ''), 'tex_path': str(tex_path or ''),
        'objects': 0, 'materials': 0, 'bindings': 0, 'ramp_bindings': 0,
        'slot_counts': {}, 'reason': '',
    }
    if obj_path is None or tex_path is None:
        audit['reason'] = 'native obj/tex pair missing'
        return [], audit
    try:
        data = Path(obj_path).read_bytes()
        if len(data) < 32 or struct.unpack_from('<I', data, 0)[0] != 84288768:
            raise ValueError('unexpected FGO obj.bin magic')
        tex_names, tex_audit = _sabershader_v1029_texbin_names(tex_path)
        if not tex_audit.get('valid'):
            raise ValueError('tex.bin name table unavailable: ' + str(tex_audit.get('reason', '')))
        obj_count = int(struct.unpack_from('<I', data, 4)[0])
        table_loc = int(struct.unpack_from('<q', data, 8)[0])
        if table_loc < 0 or table_loc + obj_count * 8 > len(data):
            raise ValueError('object table out of bounds')
        blocks = [int(struct.unpack_from('<q', data, table_loc + i*8)[0]) for i in range(obj_count)]
        rows_by_name = {}
        char_id = Path(obj_path).name.rsplit('_obj.bin', 1)[0]
        for block in blocks:
            if block < 0 or block + 44*8 > len(data):
                continue
            vals = struct.unpack_from('<44Q', data, block)
            mat_count = int(vals[15])
            mats_loc = int(block + vals[16])
            bind_count = int(vals[17])
            binds_loc = int(block + vals[18])
            string_count = int(vals[38])
            strings_loc = int(block + vals[39])

            strings = []
            pos = strings_loc
            for _ in range(string_count):
                if pos + 2 > len(data):
                    raise ValueError('string table truncated')
                _declared = struct.unpack_from('<H', data, pos)[0]; pos += 2
                value, pos = _sabershader_v1029_read_cstring(data, pos)
                strings.append(value)

            bindings = []
            pos = binds_loc
            for bi in range(bind_count):
                if pos + 56 > len(data):
                    raise ValueError('texture binding table truncated')
                tex_index, slot, bind_unk2 = struct.unpack_from('<iii', data, pos)
                native_name = tex_names[tex_index] if 0 <= tex_index < len(tex_names) else f'#{tex_index}'
                file_name = _sabershader_v1029_native_texture_filename(native_name, char_id, source_paths)
                bindings.append({
                    'index': bi, 'texture_index': int(tex_index), 'slot': int(slot),
                    'unk2': int(bind_unk2), 'native_name': native_name, 'file_name': file_name,
                    'is_ramp': Path(file_name).name.casefold().startswith('_ramp01'),
                })
                audit['slot_counts'][str(int(slot))] = int(audit['slot_counts'].get(str(int(slot)), 0)) + 1
                if Path(file_name).name.casefold().startswith('_ramp01'):
                    audit['ramp_bindings'] += 1
                pos += 56

            pos = mats_loc
            for mi in range(mat_count):
                if pos + 184 > len(data):
                    raise ValueError('material table truncated')
                name_idx = int(struct.unpack_from('<Q', data, pos)[0])
                bind_start = int(struct.unpack_from('<q', data, pos+8)[0])
                unk2 = int(struct.unpack_from('<q', data, pos+16)[0])
                bind_len = int(struct.unpack_from('<i', data, pos+24)[0])
                unk4 = int(struct.unpack_from('<i', data, pos+28)[0])
                raw_params = data[pos+32:pos+168]
                unk6 = int(struct.unpack_from('<q', data, pos+168)[0])
                unk7 = int(struct.unpack_from('<q', data, pos+176)[0])
                name = strings[name_idx] if 0 <= name_idx < len(strings) else f'Material_{mi}'
                raw_floats = list(struct.unpack('<34f', raw_params))
                bind_rows = list(bindings[max(0,bind_start):max(0,bind_start)+max(0,bind_len)])
                row = {
                    'material_name': name,
                    'material_index': mi,
                    'binding_start': bind_start,
                    'binding_count': bind_len,
                    'unk2': unk2, 'unk4': unk4, 'unk6': unk6, 'unk7': unk7,
                    'raw_params_hex': raw_params.hex(),
                    'raw_params_f32': raw_floats,
                    'slots': bind_rows,
                }

                old = rows_by_name.get(name.casefold())
                if old is None or len(bind_rows) > len(old.get('slots', [])):
                    rows_by_name[name.casefold()] = row
                pos += 184
        rows = list(rows_by_name.values())
        audit['valid'] = True
        audit['objects'] = obj_count
        audit['materials'] = len(rows)
        audit['bindings'] = sum(len(r.get('slots', [])) for r in rows)
        audit['reason'] = 'native material table parsed'
        return rows, audit
    except Exception as exc:
        audit['reason'] = str(exc)
        return [], audit

def _sabershader_v1029_native_binding_records(material_rows, source_paths=None):
    """Convert proven native slots into resolver bindings while retaining every raw slot."""
    records = []
    texture_role_sets = {}
    evidence = []

    known_slot_roles = {0: 'base', 4: 'specular', 8: 'normal', 16: 'opacity'}
    for row in material_rows or []:
        roles = {}
        slots = {}
        cubemaps = {}
        raw_slots = []
        for bind in row.get('slots', []) or []:
            slot = int(bind.get('slot', -1))
            tex_name = str(bind.get('file_name', '') or '')
            if not tex_name:
                continue
            raw_slots.append(dict(bind))
            role = known_slot_roles.get(slot)
            if slot == 18:
                cubemaps.setdefault('reflection', tex_name)
                continue

            if role is None and not bool(bind.get('is_ramp', False)):
                semantic = _xdzr8_v1122_semantic_role(tex_name, {'fgo_arcade_profile': {'enabled': True}})
                if slot == 12 and semantic == 'highlight':
                    role = 'highlight'
                elif slot == 14 and semantic == 'shadow_color':
                    role = 'shadow_color'
                elif slot == 7 and semantic == 'specular':
                    role = 'specular'
            if role:
                slot_label = f'NativeSlot{slot}'
                slots[slot_label] = tex_name
                roles.setdefault(role, []).append(tex_name)
                texture_role_sets.setdefault(Path(tex_name).name.casefold(), set()).add(role)
        records.append({
            'material_name': str(row.get('material_name', '')),
            'source_file': 'native_fgo_arcade_objbin',
            'slots': slots,
            'roles': roles,
            'cubemaps': cubemaps,
            'fgo_native_slots': raw_slots,
            'fgo_raw_params_f32': list(row.get('raw_params_f32', []) or []),
            'fgo_raw_params_hex': str(row.get('raw_params_hex', '')),
            'fgo_native_flags': {
                'unk2': row.get('unk2'), 'unk4': row.get('unk4'),
                'unk6': row.get('unk6'), 'unk7': row.get('unk7'),
            },
            'flags': {'native_fgo_arcade': True, 'objbin_material_table': True},
        })
        evidence.append(f"native FGO obj.bin: {row.get('material_name','')} slots={[b.get('slot') for b in raw_slots]}")
    texture_roles = {}
    ambiguous = {}
    for name, role_set in texture_role_sets.items():
        if len(role_set) == 1:
            texture_roles[name] = next(iter(role_set))
        elif role_set:
            ambiguous[name] = sorted(role_set)
    return records, texture_roles, ambiguous, evidence

def _sabershader_v1029_material_row(source_intelligence, material_name):
    lookup = (source_intelligence or {}).get('fgo_objbin_material_lookup', {}) or {}
    return lookup.get(str(material_name or '').casefold())

def _xdzr8_v1122_detect_source_intelligence(folder, objects=None, materials=None):
    roots = _xdzr8_v1122_nearby_roots(folder)
    meta_files = _xdzr8_v1122_metadata_files(folder)
    fx_overrides, fx_evidence = _xdzr8_v1122_fx_texture_defines(meta_files)
    pmx_materials_all = []
    for meta_path in meta_files:
        if meta_path.suffix.lower() == '.pmx':
            pmx_materials_all.extend(_xdzr8_v1123_parse_pmx_materials(meta_path))
    pmx_scope = _xdzr8_v11831_scope_pmx_sources(pmx_materials_all, objects, materials)
    pmx_materials = list(pmx_scope.get('selected', []) or [])

    pmx_lookup = _xdzr8_v1123_build_pmx_lookup(pmx_materials)
    binding_records, binding_texture_roles, binding_ambiguous, binding_evidence = _xdzr8_v1181_material_json_bindings(meta_files)
    binding_material_lookup = _xdzr8_v1181_build_binding_lookup(binding_records)
    image_paths = []
    if roots:

        root = roots[0]
        try:
            for path in root.rglob('*'):
                if path.is_file() and path.suffix.lower() in SABERSHADER11_IMAGE_EXTENSIONS:
                    image_paths.append(path)
        except Exception:
            pass
    fgo_source_scope = _sabershader_v1022_fgo_source_scope(folder)
    detection_paths = list(image_paths)
    if fgo_source_scope.get('resolved', False):
        detection_paths = list(fgo_source_scope.get('paths', []) or [])
    dialects, dialect_texture_roles, dialect_texture_roots, dialect_evidence, companion_meta = _xdzr8_v1181_detect_companion_dialects(detection_paths)
    uma_naming_profile = _xdzr8_v1193_detect_uma_source_naming(materials, detection_paths)
    if uma_naming_profile.get('enabled', False):
        if 'uma source naming dictionary' not in dialects:
            dialects.append('uma source naming dictionary')
        if uma_naming_profile.get('diff_only', False) and 'uma diff-only source pack' not in dialects:
            dialects.append('uma diff-only source pack')
        dialect_evidence.extend('V11.9.3.1 ' + str(e) for e in uma_naming_profile.get('evidence', []))
    companion_lookup_meta = _xdzr8_v1183_build_companion_family_lookup(
        detection_paths, companion_meta.get('families', []), companion_meta.get('cross_id_aliases', {}), None
    )
    fgo_arcade_profile = _sabershader_v1_detect_fgo_arcade_profile(detection_paths, objects, materials)
    fgo_objbin_rows = []
    fgo_objbin_audit = {'valid': False, 'reason': 'not FGO Arcade'}
    fgo_objbin_path = ''
    fgo_texbin_path = ''
    if fgo_arcade_profile.get('enabled', False):
        if fgo_source_scope.get('resolved', False):

            image_paths = list(fgo_source_scope.get('renderable_paths', []) or [])
        _objbin, _texbin = _sabershader_v1029_find_native_files(fgo_source_scope)
        fgo_objbin_path = str(_objbin or '')
        fgo_texbin_path = str(_texbin or '')
        fgo_objbin_rows, fgo_objbin_audit = _sabershader_v1029_parse_objbin_material_table(
            _objbin, _texbin, list(fgo_source_scope.get('paths', []) or image_paths)
        )
        if fgo_objbin_rows:
            native_records, native_texture_roles, native_ambiguous, native_evidence = _sabershader_v1029_native_binding_records(
                fgo_objbin_rows, list(fgo_source_scope.get('paths', []) or image_paths)
            )
            native_audit = {
                'source': 'OBJ_BIN_NATIVE_TABLE',
                'records': len(native_records),
                'bound_textures': len(native_texture_roles),
                'ramps_bound': int(fgo_objbin_audit.get('ramp_bindings', 0)),
                'slot_counts': dict(fgo_objbin_audit.get('slot_counts', {})),
                'materials': int(fgo_objbin_audit.get('materials', 0)),
                'bindings': int(fgo_objbin_audit.get('bindings', 0)),
            }
        else:

            native_records, native_texture_roles, native_ambiguous, native_evidence, native_audit = _sabershader_v1021_fgo_native_binding_records(
                materials, list(fgo_source_scope.get('paths', []) or image_paths), fgo_source_scope.get('dds_metadata', {})
            )
            native_audit = dict(native_audit or {})
            native_audit['source'] = 'SUFFIX_FALLBACK'
            native_audit['objbin_reason'] = str(fgo_objbin_audit.get('reason', ''))
        if native_records:
            binding_records = list(binding_records) + list(native_records)
            binding_material_lookup = _xdzr8_v1181_build_binding_lookup(binding_records)
            for name, role in (native_texture_roles or {}).items():
                binding_texture_roles.setdefault(name, role)
            for name, roles in (native_ambiguous or {}).items():
                if name.casefold() not in binding_texture_roles:
                    merged = set(binding_ambiguous.get(name.casefold(), []) or [])
                    merged.update(roles)
                    binding_ambiguous[name.casefold()] = sorted(merged)
            binding_evidence = list(binding_evidence) + list(native_evidence)
    mesh_provenance = _xdzr8_v1182_mesh_provenance(objects)
    if binding_records:
        dialects = ['explicit shader-slot bindings'] + [d for d in dialects if d != 'explicit shader-slot bindings']
    has_model = any(p.suffix.lower() in {'.pmx', '.pmd'} for p in meta_files)
    has_fx = any(p.suffix.lower() in {'.fx', '.fxsub', '.fxh'} for p in meta_files)
    stems = [p.stem for p in image_paths]
    mmd_short = sum(1 for stem in stems if re.search(r'_(?:c|h|s|a|al|light)$', stem, re.I))
    mmd_scene_signal = False
    try:
        for mat in materials or []:
            if not getattr(mat, 'use_nodes', False) or not getattr(mat, 'node_tree', None):
                continue
            for node in mat.node_tree.nodes:
                key = _sabershader11_key(getattr(node, 'name', '')) + _sabershader11_key(getattr(node, 'label', ''))
                if 'mmdbasetex' in key or 'mmdtoontex' in key or 'mmdtexuv' in key:
                    mmd_scene_signal = True; break
            if mmd_scene_signal:
                break
    except Exception:
        pass
    if not mmd_scene_signal:
        try:
            root_names = ' '.join(str(getattr(o, 'name', '')) for o in (objects or []))
            if re.search(r'(^|[^a-z])mmd([^a-z]|$)', root_names.lower()):
                mmd_scene_signal = True
        except Exception:
            pass
    if fgo_arcade_profile.get('enabled', False):
        family = 'General'
        confidence = str(fgo_arcade_profile.get('confidence', 'HIGH'))
        convention = 'Fate Grand Order Arcade SVT/ramp export'

        pmx_materials = []
        pmx_lookup = {}
        pmx_scope = dict(pmx_scope or {})
        pmx_scope['selected'] = []
        pmx_scope['selected_file'] = ''
        pmx_scope['selected_path'] = ''
        pmx_scope['confidence'] = 'NONE'
        pmx_scope['reason'] = 'FGO Arcade profile overrides unrelated PMX metadata'
    elif has_model or has_fx or mmd_scene_signal or (mmd_short >= 3 and fx_overrides) or uma_naming_profile.get('enabled', False):
        family = 'MMD-type'
        if uma_naming_profile.get('confidence') == 'HIGH':
            confidence = 'HIGH'
        else:
            confidence = 'HIGH' if (has_model and (has_fx or fx_overrides)) else 'MEDIUM'
        if uma_naming_profile.get('enabled', False):
            convention = 'Uma source naming dictionary' + (' + MMD/FX metadata' if (has_fx or fx_overrides or has_model or mmd_scene_signal) else '')
        else:
            convention = 'MMD/FX toon metadata' if (has_fx or fx_overrides) else 'MMD model metadata'
    else:
        family = 'General'
        signatures = _xdzr8_v1122_general_signature(stems)
        signatures.extend(d for d in dialects if d not in signatures)
        confidence = 'HIGH' if (binding_records or len(signatures) >= 2) else ('MEDIUM' if image_paths else 'LOW')
        convention = ', '.join(signatures) if signatures else 'generic texture naming'
    return {
        'family': family,
        'confidence': confidence,
        'convention': convention,
        'render_profile': ('Fate Grand Order Arcade' if fgo_arcade_profile.get('enabled') else 'Universal'),
        'fgo_arcade_profile': fgo_arcade_profile,
        'uma_naming_profile': uma_naming_profile,
        'fgo_native_binding_audit': (native_audit if fgo_arcade_profile.get('enabled', False) and 'native_audit' in locals() else {}),
        'fgo_objbin_audit': (fgo_objbin_audit if 'fgo_objbin_audit' in locals() else {}),
        'fgo_objbin_path': (fgo_objbin_path if 'fgo_objbin_path' in locals() else ''),
        'fgo_texbin_path': (fgo_texbin_path if 'fgo_texbin_path' in locals() else ''),
        'fgo_objbin_material_table': list(fgo_objbin_rows if 'fgo_objbin_rows' in locals() else []),
        'fgo_objbin_material_lookup': {str(r.get('material_name','')).casefold(): r for r in (fgo_objbin_rows if 'fgo_objbin_rows' in locals() else [])},
        'fgo_source_scope': (fgo_source_scope if 'fgo_source_scope' in locals() else {}),
        'fgo_dds_metadata': ((fgo_source_scope or {}).get('dds_metadata', {}) if 'fgo_source_scope' in locals() else {}),
        'fgo_cubemap_paths': list((fgo_source_scope or {}).get('cubemap_paths', []) if 'fgo_source_scope' in locals() else []),
        'fgo_ramp_paths': list((fgo_source_scope or {}).get('ramp_paths', []) if 'fgo_source_scope' in locals() else []),
        'fgo_rgb_mask_paths': list((fgo_source_scope or {}).get('mask_rgb_paths', []) if 'fgo_source_scope' in locals() else []),
        'fgo_renderable_image_paths': list((fgo_source_scope or {}).get('renderable_paths', []) if 'fgo_source_scope' in locals() else image_paths),
        'metadata_files': meta_files,
        'fx_overrides': fx_overrides,
        'fx_evidence': fx_evidence,
        'image_paths': image_paths,
        'pmx_materials': pmx_materials,
        'pmx_materials_all': pmx_materials_all,
        'pmx_lookup': pmx_lookup,
        'pmx_scope': pmx_scope,
        'pmx_scope_selected_file': pmx_scope.get('selected_file', ''),
        'pmx_scope_selected_path': pmx_scope.get('selected_path', ''),
        'pmx_scope_confidence': pmx_scope.get('confidence', 'NONE'),
        'pmx_scope_reason': pmx_scope.get('reason', ''),
        'binding_records': binding_records,
        'binding_material_lookup': binding_material_lookup,
        'binding_texture_roles': binding_texture_roles,
        'binding_ambiguous_textures': binding_ambiguous,
        'binding_evidence': binding_evidence,
        'dialects': dialects,
        'dialect_texture_roles': dialect_texture_roles,
        'dialect_texture_roots': dialect_texture_roots,
        'dialect_evidence': dialect_evidence,
        'companion_families': companion_lookup_meta.get('families', companion_meta.get('families', [])),
        'companion_family_lookup': companion_lookup_meta.get('lookup', {}),
        'cross_id_companion_rows': companion_meta.get('cross_id_rows', []),
        'cross_id_companion_count': int(companion_meta.get('cross_id_count', 0)),
        'cross_id_companion_aliases': companion_meta.get('cross_id_aliases', {}),
        'derived_texture_rows': companion_meta.get('derived_rows', []),
        'derived_texture_count': int(companion_meta.get('derived_count', 0)),
        'eye_highlight_companions': companion_meta.get('eye_highlights', []),
        'mesh_provenance': mesh_provenance,
        'detected_binding_roles': sorted({role for rec in binding_records for role in (rec.get('roles') or {})}),
    }

def _xdzr8_v1122_semantic_role(path_or_name, intelligence=None):
    name = Path(str(path_or_name or '')).name
    lower_name = name.lower()
    stem = Path(name).stem.lower()
    compact = _sabershader11_key(stem)
    info = intelligence or {}

    override = (info.get('binding_texture_roles') or {}).get(lower_name)
    if override:
        return override
    override = (info.get('fx_overrides') or {}).get(lower_name)
    if override:
        return override
    override = (info.get('dialect_texture_roles') or {}).get(lower_name)
    if override:
        return override
    family = info.get('family', 'General')
    fgo_arcade = bool((info.get('fgo_arcade_profile') or {}).get('enabled', False))
    if fgo_arcade:

        if stem.startswith('_ramp01'):
            return 'diffuse_ramp'
        if stem.startswith('_a_') and stem.endswith('_a'):
            return 'opacity'
        if 'envmap_eye' in compact or 'envmapdivaeye' in compact:
            return 'reflection'
        if re.search(r'_eye_(?:left|right)_h$', stem):
            return 'highlight'
        if re.search(r'_eye_(?:left|right)_n$', stem):
            return 'normal'
        if stem.endswith('_n0') or stem.endswith('_n'):
            return 'normal'
        if stem.endswith('_s'):
            return 'specular'
        if stem.endswith('_face_bs'):
            return 'shadow_color'
        if stem.endswith('_cheek'):
            return 'emotion'
        if stem.endswith('_facebase') or stem.endswith('_face'):
            return 'base'
        if stem.endswith('_skin') or stem.endswith('_hair') or stem.endswith('_clothall') or stem.endswith('_chestarm') or stem.endswith('_white') or stem.endswith('_alfa_gold'):
            return 'base'
    if family == 'MMD-type':

        if bool((info.get('uma_naming_profile') or {}).get('enabled', False)):
            if re.search(r'_eye0$', stem):
                return 'base'
            if re.search(r'_eyehi\d+$', stem):
                return 'highlight'
            if stem.endswith('_shad_c'):
                return 'shadow_color'
            if stem.endswith('_ctrl'):
                return 'control_map'
            if stem.endswith('_base'):
                return 'region_map'
            if stem.endswith('_rfl'):
                return 'reflection'
            if stem.endswith('_diff'):
                return 'base'

        long_role = _sabershader11_role_from_text(stem)
        if any(token in compact for token in ('normal','roughness','metallic','emission','opacity','alpha','facemap','lightmap')):
            return long_role
        for suffix, role in _XDZR8_V1122_MMD_SUFFIX_ROLES:
            if stem.endswith(suffix):
                return role
        return long_role
    for token, role in _XDZR8_V1122_GENERAL_PATTERNS:
        if token in compact:
            return role

    if re.search(r'(?:^|[_\-.])(orm|arm|mra)$', stem, re.I):
        return 'packed_material'
    return _sabershader11_role_from_text(stem)

def _xdzr8_v1122_contextual_existing_images(mat, existing, intelligence=None):
    result = dict(existing or {})
    info = intelligence or {}
    if bool((info.get('fgo_arcade_profile') or {}).get('enabled', False)):
        current_reflection = result.get('reflection')
        if current_reflection is not None and _sabershader_v1022_is_fgo_cubemap_name(getattr(current_reflection, 'name', ''), info):
            result.pop('reflection', None)
    if not mat or not getattr(mat, 'use_nodes', False) or not getattr(mat, 'node_tree', None):
        return result
    try:
        for node in mat.node_tree.nodes:
            if node.bl_idname != 'ShaderNodeTexImage' or not getattr(node, 'image', None):
                continue
            role = _xdzr8_v1122_semantic_role(node.image.name, intelligence)
            if role == 'reflection' and _sabershader_v1022_is_fgo_cubemap_name(node.image.name, info):
                continue

            for old_role, img in list(result.items()):
                if img == node.image and old_role != role and old_role in {'specular','opacity','base'}:
                    result.pop(old_role, None)
            result.setdefault(role, node.image)
    except Exception:
        pass
    return result

def _xdzr8_v1122_role_counts(index):
    counts = {}
    for item in index or []:
        if len(item) >= 2:
            counts[item[1]] = counts.get(item[1], 0) + 1
    return counts

def _xdzr8_v1122_texture_family_root(name, role=None, intelligence=None):
    """Strip the detected semantic suffix from a texture filename."""
    stem = Path(str(name or '')).stem
    lower = stem.lower()
    info = intelligence or {}
    explicit_root = (info.get('dialect_texture_roots') or {}).get(Path(str(name or '')).name.casefold())
    if explicit_root:
        return explicit_root
    family = info.get('family', 'General')
    if bool((info.get('fgo_arcade_profile') or {}).get('enabled', False)):
        if lower.startswith('_ramp01'):
            return 'fgoarcade_ramp'
        fgo_suffixes = (
            ('_face_bs','shadow_color'), ('_facebase','base'), ('_cheek','emotion'),
            ('_eye_left_h','highlight'), ('_eye_right_h','highlight'),
            ('_eye_left_n','normal'), ('_eye_right_n','normal'),
            ('_n0','normal'), ('_n','normal'), ('_s','specular'), ('_a','opacity'),
        )
        for suffix, srole in fgo_suffixes:
            if (role is None or srole == role) and lower.endswith(suffix):
                return _sabershader11_key(stem[:-len(suffix)])
    if family == 'MMD-type':
        if bool((info.get('uma_naming_profile') or {}).get('enabled', False)):
            uma_suffixes = (('_shad_c','shadow_color'),('_ctrl','control_map'),('_base','region_map'),('_rfl','reflection'),('_diff','base'))
            for suffix, srole in uma_suffixes:
                if (role is None or srole == role) and lower.endswith(suffix):
                    return _sabershader11_key(stem[:-len(suffix)])
            if role == 'base' and re.search(r'_eye0$', lower):
                return _sabershader11_key(re.sub(r'eye0$', 'eye', stem, flags=re.I))
            if role == 'highlight' and re.search(r'_eyehi\d+$', lower):
                return _sabershader11_key(re.sub(r'eyehi\d+$', 'eye', stem, flags=re.I))
        for suffix, srole in _XDZR8_V1122_MMD_SUFFIX_ROLES:
            if (role is None or srole == role) and lower.endswith(suffix):
                return _sabershader11_key(stem[:-len(suffix)])
    role_suffixes = SABERSHADER11_ROLE_SUFFIXES.get(role, ()) if role else ()
    for suffix in sorted(role_suffixes, key=len, reverse=True):
        if lower.endswith(suffix.lower()):
            return _sabershader11_key(stem[:-len(suffix)])

    proven_short = {
        'diffuse_ramp': ('_rd',), 'specular_ramp': ('_rs',),
        'outline_mask': ('_st',), 'stroke_map': ('_st',),
        'split_normal': ('_hn',), 'packed_material': ('_p',),
        'emission': ('_e',),
    }
    for suffix in proven_short.get(role, ()):
        if lower.endswith(suffix):
            return _sabershader11_key(stem[:-len(suffix)])

    for token, srole in _XDZR8_V1122_GENERAL_PATTERNS:
        if (role is None or srole == role) and token in _sabershader11_key(stem):
            compact = _sabershader11_key(stem)
            if compact.endswith(token):
                return compact[:-len(token)]
    return _sabershader11_key(stem)

def _xdzr8_v1122_find_family_texture(index, reference_image, role, intelligence=None):
    if not index or not reference_image:
        return None
    try:
        ref_role = _xdzr8_v1122_semantic_role(reference_image.name, intelligence)
        ref_root = _xdzr8_v1122_texture_family_root(reference_image.name, ref_role, intelligence)
    except Exception:
        return None
    if not ref_root:
        return None
    best = None
    best_score = -1
    for path, file_role, _key in index:
        if file_role != role:
            continue
        root = _xdzr8_v1122_texture_family_root(path.name, file_role, intelligence)
        if root == ref_root:
            return path
        if root and (root in ref_root or ref_root in root):
            score = min(len(root), len(ref_root)) / max(len(root), len(ref_root), 1)
            if score > best_score:
                best_score = score; best = path
    return best if best_score >= 0.72 else None

_XDZR8_V113_RESOLVER_ROLES = (
    'base', 'normal', 'roughness', 'metallic', 'specular', 'emission',
    'opacity', 'ao', 'mask', 'shadow_color', 'toon_control', 'face_map',
    'light_aux', 'packed_material', 'packed_aux', 'auxiliary',
    'diffuse_ramp', 'specular_ramp', 'outline_mask', 'sdf_lightmap', 'sdf_mask',
    'shadow_lut', 'highlight', 'emotion', 'matcap', 'line_map', 'stroke_map',
    'split_normal', 'fur_map', 'vertex_noise', 'control_map', 'region_map', 'reflection',
    'derived_eye_atlas',
)

def _xdzr8_v113_texture_catalog(index, intelligence=None):
    """Group indexed textures by semantic family root and role.

    The catalog never assumes that RGB channels have a fixed meaning.  It only
    groups filenames that V11.2.2 has already interpreted semantically.
    """
    catalog = {}
    for item in index or []:
        if len(item) < 2:
            continue
        path, role = item[0], item[1]
        try:
            root = _xdzr8_v1122_texture_family_root(path.name, role, intelligence)
        except Exception:
            root = _sabershader11_key(Path(str(path)).stem)
        root = root or _sabershader11_key(Path(str(path)).stem)
        catalog.setdefault(root, {}).setdefault(role, []).append(path)
    return catalog

def _xdzr8_v113_material_reference_roots(source_mat, source_ref, existing, intelligence=None):
    """Collect high-confidence texture-family anchors for one source material."""
    refs = {}
    reasons = {}

    def add(root, weight, reason):
        root = str(root or '')
        if not root:
            return
        if weight > refs.get(root, -1.0):
            refs[root] = float(weight)
            reasons[root] = str(reason)

    for role, image in (existing or {}).items():
        if not image:
            continue
        try:
            semantic = _xdzr8_v1122_semantic_role(image.name, intelligence)
            root = _xdzr8_v1122_texture_family_root(image.name, semantic, intelligence)
            add(root, 135.0 if semantic == 'base' else 105.0, f'existing {semantic} binding')
        except Exception:
            pass

    try:
        for rec in _xdzr8_v1123_match_pmx_records(source_mat, source_ref, intelligence):
            tex_name = Path(str(rec.get('texture') or '').replace('\\', '/')).name
            if not tex_name:
                continue
            semantic = _xdzr8_v1122_semantic_role(tex_name, intelligence)
            root = _xdzr8_v1122_texture_family_root(tex_name, semantic, intelligence)
            add(root, 165.0, f'PMX binding {tex_name}')
    except Exception:
        pass

    try:
        for rec in _xdzr8_v1181_match_binding_records(source_mat, source_ref, intelligence):
            for role, tex_names in (rec.get('roles') or {}).items():
                for tex_name in tex_names:
                    semantic = role or _xdzr8_v1122_semantic_role(tex_name, intelligence)
                    root = _xdzr8_v1122_texture_family_root(tex_name, semantic, intelligence)
                    add(root, 195.0, f'explicit source slot {role}: {tex_name}')
    except Exception:
        pass
    return refs, reasons

def _xdzr8_v113_material_name_score(source_name, root):
    candidates = _sabershader11_material_name_candidates(source_name)
    if not candidates or not root:
        return 0.0
    best = 0.0
    for cand in candidates:
        if root == cand:
            best = max(best, 92.0)
        elif cand in root or root in cand:
            short = min(len(cand), len(root)); long = max(len(cand), len(root), 1)
            best = max(best, 68.0 + 18.0 * short / long)
    return best

def _xdzr8_v113_rank_candidates(index, role, source_name, refs, intelligence=None):
    ranked = []
    for path, file_role, _key in index or []:
        if file_role != role:
            continue
        try:
            root = _xdzr8_v1122_texture_family_root(path.name, file_role, intelligence)
        except Exception:
            root = _sabershader11_key(path.stem)
        score = _xdzr8_v113_material_name_score(source_name, root)
        reasons = []
        if score:
            reasons.append('material-name affinity')
        for ref_root, ref_weight in (refs or {}).items():
            if root == ref_root:
                if ref_weight > score:
                    score = ref_weight
                reasons.append(f'exact family {ref_root}')
            elif root and ref_root and (root in ref_root or ref_root in root):
                ratio = min(len(root), len(ref_root)) / max(len(root), len(ref_root), 1)
                fuzzy = ref_weight * 0.58 * ratio
                if fuzzy > score:
                    score = fuzzy
                if ratio >= 0.82:
                    reasons.append(f'near family {ref_root}')
        ranked.append({
            'path': path,
            'role': role,
            'root': root,
            'score': float(score),
            'reason': ', '.join(dict.fromkeys(reasons)) or 'role-only candidate',
        })
    ranked.sort(key=lambda row: (-row['score'], str(row['path']).lower()))
    return ranked

def _xdzr8_v113_role_expected(role, category, catalog, refs, existing, intelligence=None):
    if role == 'base':
        return True
    if role in (existing or {}):
        return True

    for root in refs or {}:
        if role in (catalog.get(root) or {}):
            return True
    return False

def _xdzr8_v113_resolve_texture_set(source_mat, source_ref, category, texture_index, settings, intelligence, existing):
    """Resolve a semantic texture set without guessing ambiguous candidates."""
    source_name = _sabershader111_safe_material_name(source_ref or source_mat, 'Material')
    try:
        source_name = str((source_mat or source_ref).get('SaberShader_V11_SourceMaterial', source_name))
    except Exception:
        pass
    catalog = (intelligence or {}).get('texture_catalog') or _xdzr8_v113_texture_catalog(texture_index, intelligence)
    refs, ref_reasons = _xdzr8_v113_material_reference_roots(source_mat, source_ref, existing, intelligence)
    strictness = float(getattr(settings, 'universal_texture_match_strictness', 0.55))
    threshold = 48.0 + strictness * 34.0

    images = dict(existing or {})
    paths = {}
    statuses = {}
    reasons = {}
    ambiguous = {}
    extras = []
    chosen_roots = set(refs)
    fgo_enabled = bool(((intelligence or {}).get('fgo_arcade_profile') or {}).get('enabled', False))
    fgo_existing_bypassed = 0
    fgo_safe_cache_used = 0
    fgo_decode_failed = 0
    fgo_safe_cache_rows = []

    exact_path_by_name = {}
    for item in texture_index or []:
        try:
            exact_path_by_name.setdefault(Path(item[0]).name.casefold(), item[0])
        except Exception:
            pass
    for path in (intelligence or {}).get('image_paths', []) or []:
        try:
            exact_path_by_name.setdefault(Path(path).name.casefold(), path)
        except Exception:
            pass
    explicit_role_names = {}
    for rec in _xdzr8_v1181_match_binding_records(source_mat, source_ref, intelligence):
        for role, tex_names in (rec.get('roles') or {}).items():
            for tex_name in tex_names:
                explicit_role_names.setdefault(role, set()).add(Path(tex_name).name)

    def _fgo_force_existing_role(role_key, image_obj=None, declared_names=None):
        nonlocal fgo_existing_bypassed, fgo_safe_cache_used, fgo_decode_failed
        if not fgo_enabled:
            return image_obj, None, None
        declared_names = list(declared_names or [])
        candidate_path = None
        source_name = ''
        if image_obj is not None:
            source_name = str(getattr(image_obj, 'name', '') or '')
            raw_fp = str(getattr(image_obj, 'filepath', '') or '')
            if raw_fp:
                try:
                    candidate_path = str(Path(bpy.path.abspath(raw_fp)).resolve())
                except Exception:
                    candidate_path = raw_fp
        if (not candidate_path) and source_name:
            match = exact_path_by_name.get(Path(source_name).name.casefold())
            if match is not None:
                candidate_path = str(match)
        if not candidate_path:
            for nm in declared_names:
                match = exact_path_by_name.get(Path(nm).name.casefold())
                if match is not None:
                    candidate_path = str(match)
                    break
        if not candidate_path:
            return image_obj, None, 'no source path'
        safe_img, changed, safe_reason = _sabershader_v1026_force_safe_fgo_image(image_obj, role=role_key, source_path=candidate_path)
        if safe_img is not None and safe_img is not image_obj:
            fgo_existing_bypassed += 1
            fgo_safe_cache_used += 1
            fgo_safe_cache_rows.append(f'{role_key}:{Path(candidate_path).name} -> {safe_reason}')
            return safe_img, candidate_path, safe_reason
        if safe_img is image_obj and _sabershader_v1026_is_fgo_safe_cache_image(safe_img):
            fgo_safe_cache_used += 1
            fgo_safe_cache_rows.append(f'{role_key}:{Path(candidate_path).name} -> {safe_reason}')
            return safe_img, candidate_path, safe_reason
        if 'failed' in str(safe_reason).casefold() or 'exception' in str(safe_reason).casefold():
            fgo_decode_failed += 1
            fgo_safe_cache_rows.append(f'{role_key}:{Path(candidate_path).name} -> {safe_reason}')
        return safe_img, candidate_path, safe_reason

    if fgo_enabled:
        for role_key, image_obj in list(images.items()):
            safe_img, forced_path, safe_reason = _fgo_force_existing_role(role_key, image_obj, explicit_role_names.get(role_key, set()))
            if safe_img is not None:
                images[role_key] = safe_img
                if forced_path:
                    paths[role_key] = str(forced_path)
                if _sabershader_v1026_is_fgo_safe_cache_image(safe_img):
                    statuses.setdefault(role_key, 'EXISTING')
                    reasons[role_key] = safe_reason or 'FGO safe DDS cache (existing bypass)'

    for role, name_set in explicit_role_names.items():
        if images.get(role) and not fgo_enabled:
            continue
        unique_names = sorted({n for n in name_set if n})
        if len(unique_names) == 1:
            tex_name = unique_names[0]
            path = exact_path_by_name.get(tex_name.casefold())
            if path is not None:
                img = _sabershader11_load_image(path)
                if img and fgo_enabled:
                    safe_img, _dds_changed, _dds_reason = _sabershader_v1026_force_safe_fgo_image(img, role=role, source_path=path)
                    if safe_img is not None:
                        if safe_img is not img:
                            fgo_existing_bypassed += 1
                            fgo_safe_cache_used += 1
                        elif _sabershader_v1026_is_fgo_safe_cache_image(safe_img):
                            fgo_safe_cache_used += 1
                        img = safe_img or img
                        fgo_safe_cache_rows.append(f'{role}:{Path(path).name} -> {_dds_reason}')
                    elif 'failed' in str(_dds_reason).casefold() or 'exception' in str(_dds_reason).casefold():
                        fgo_decode_failed += 1
                        fgo_safe_cache_rows.append(f'{role}:{Path(path).name} -> {_dds_reason}')
                if img:
                    images[role] = img
                    paths[role] = str(path)
                    statuses[role] = 'FOUND'
                    reasons[role] = f'explicit source material slot -> {tex_name}'
                    try:
                        chosen_roots.add(_xdzr8_v1122_texture_family_root(tex_name, role, intelligence))
                    except Exception:
                        pass
        elif len(unique_names) > 1:
            ambiguous[role] = unique_names
            statuses[role] = 'AMBIGUOUS'
            reasons[role] = f'{len(unique_names)} textures declared for this explicit source role'

    alias_table = (intelligence or {}).get('cross_id_companion_aliases', {}) or {}
    for ref_root in list(refs):
        for role, alias_path in (alias_table.get(ref_root) or {}).items():
            if images.get(role) or statuses.get(role) == 'AMBIGUOUS':
                continue
            try:
                img = _sabershader11_load_image(alias_path)
            except Exception:
                img = None
            if img:
                images[role] = img
                paths[role] = str(alias_path)
                statuses[role] = 'FOUND'
                reasons[role] = f'cross-ID authored companion for anchored family {ref_root}'

    bound_ctx = _xdzr8_v1183_material_bound_companion_context(source_mat, source_ref, images, intelligence)
    locked_roots = set(bound_ctx.get('family_roots', []) or [])
    if bound_ctx.get('primary_root'):
        chosen_roots.add(bound_ctx.get('primary_root'))
    for root in locked_roots:
        chosen_roots.add(root)
    for role, family_path in (bound_ctx.get('family_images') or {}).items():
        if images.get(role) or statuses.get(role) == 'AMBIGUOUS':
            continue
        img = _sabershader11_load_image(family_path)
        if img:
            images[role] = img
            paths[role] = str(family_path)
            statuses[role] = 'FOUND'
            reasons[role] = f'material-bound companion family {bound_ctx.get("primary_root") or ""}'

    for role in _XDZR8_V113_RESOLVER_ROLES:
        if statuses.get(role) == 'AMBIGUOUS':

            continue
        if images.get(role):
            if role not in statuses:
                statuses[role] = 'EXISTING'
                reasons[role] = 'source material binding'
            try:
                semantic = role if statuses.get(role) == 'FOUND' else _xdzr8_v1122_semantic_role(images[role].name, intelligence)
                chosen_roots.add(_xdzr8_v1122_texture_family_root(images[role].name, semantic, intelligence))
            except Exception:
                pass
            continue

        ranked = _xdzr8_v113_rank_candidates(texture_index, role, source_name, refs, intelligence)
        if locked_roots and role in ({'base'} | _XDZR8_V1181_DIALECT_AUX_ROLES):
            locked_ranked = [row for row in ranked if row.get('root') in locked_roots]
            if locked_ranked:
                ranked = locked_ranked
        expected = _xdzr8_v113_role_expected(role, category, catalog, refs, images, intelligence)
        if not ranked:
            statuses[role] = 'MISSING' if expected else 'OPTIONAL'
            reasons[role] = 'no indexed candidate'
            continue

        top = ranked[0]

        if top['score'] < threshold and len(ranked) == 1 and strictness <= 0.25:
            top = dict(top); top['score'] = threshold; top['reason'] += ', unique-role low-strictness fallback'

        if top['score'] < threshold:
            statuses[role] = 'MISSING' if expected else 'OPTIONAL'
            reasons[role] = f'best candidate below threshold ({top["score"]:.1f} < {threshold:.1f})'
            continue

        contenders = [row for row in ranked if (top['score'] - row['score']) <= 5.0]
        distinct = {(row['root'], str(row['path']).lower()) for row in contenders}
        if len(distinct) > 1 and role != 'auxiliary':
            statuses[role] = 'AMBIGUOUS'
            ambiguous[role] = [str(row['path']) for row in contenders[:8]]
            reasons[role] = f'{len(contenders)} near-equal candidates; no automatic assignment'
            continue

        img = _sabershader11_load_image(top['path'])
        if img:
            images[role] = img
            paths[role] = str(top['path'])
            statuses[role] = 'FOUND'
            reasons[role] = f'{top["reason"]}; score={top["score"]:.1f}'
            if top['root']:
                chosen_roots.add(top['root'])
        else:
            statuses[role] = 'MISSING' if expected else 'OPTIONAL'
            reasons[role] = 'candidate could not be loaded'
            continue

        if role == 'auxiliary' and top['root']:
            same_family = [row for row in ranked if row['root'] == top['root'] and str(row['path']) != str(top['path'])]
            for row in same_family:
                extra_img = _sabershader11_load_image(row['path'])
                if extra_img:
                    extras.append({'role': role, 'path': str(row['path']), 'image': extra_img, 'root': row['root']})

    family = (intelligence or {}).get('family', 'General')
    visible_roles = {
        'base', 'normal', 'opacity', 'roughness', 'metallic', 'specular',
        'emission', 'ao', 'mask', 'toon_control',
    }
    if family == 'MMD-type':
        visible_roles.update({'shadow_color', 'light_aux', 'auxiliary'})
    else:
        visible_roles.update({'face_map', 'packed_material', 'packed_aux'})
    if bool(((intelligence or {}).get('fgo_arcade_profile') or {}).get('enabled', False)):
        visible_roles.update({'diffuse_ramp', 'shadow_color', 'highlight', 'emotion', 'reflection', 'specular', 'normal', 'opacity'})

    visible_roles.update(_XDZR8_V1181_DIALECT_AUX_ROLES)
    dds_rows = []
    dds_cache_count = 0
    if fgo_enabled:
        for role, img in list(images.items()):
            safe_img, changed, dds_reason = _sabershader_v101_dds_resilient_image(img, role=role)
            images[role] = safe_img
            if safe_img is not None:
                try: safe_img.colorspace_settings.name = _sabershader_v1023_role_colorspace(role)
                except Exception: pass
            if changed:
                dds_cache_count += 1
            if img is not None and (str(getattr(img, 'name', '') or '').casefold().endswith('.dds') or str(getattr(img, 'filepath', '') or '').casefold().endswith('.dds') or _sabershader_v1026_is_fgo_safe_cache_image(img)):
                dds_rows.append(f'{role}:{getattr(img, "name", "")} -> {dds_reason}')

    counts = {key: 0 for key in ('FOUND', 'EXISTING', 'MISSING', 'OPTIONAL', 'AMBIGUOUS')}
    for role, status in statuses.items():
        if role in visible_roles:
            counts[status] = counts.get(status, 0) + 1
    return {
        'images': images,
        'paths': paths,
        'statuses': statuses,
        'reasons': reasons,
        'ambiguous': ambiguous,
        'extras': extras,
        'catalog': catalog,
        'reference_roots': sorted(r for r in chosen_roots if r),
        'reference_reasons': ref_reasons,
        'counts': counts,
        'dds_resilience_count': int(dds_cache_count),
        'dds_resilience_rows': list(dds_rows),
        'fgo_native_dds_cache_count': int(sum(1 for row in dds_rows if 'native ARGB8888 cache' in row or 'forced safe cache' in row)),
        'fgo_native_dds_cache_rows': [row for row in dds_rows if 'native ARGB8888 cache' in row or 'forced safe cache' in row][:32],
        'fgo_existing_bypassed': int(fgo_existing_bypassed),
        'fgo_safe_cache_used': int(fgo_safe_cache_used),
        'fgo_decode_failed': int(fgo_decode_failed),
        'fgo_safe_cache_rows': list(fgo_safe_cache_rows[:64]),
    }

_XDZR8_V114_CHANNEL_LABELS = {
    'ao': 'Ambient Occlusion',
    'roughness': 'Roughness',
    'metallic': 'Metallic',
    'material_id': 'Material ID',
    'specular_mask': 'Specular Mask',
    'transparency': 'Transparency',
    'smoothness': 'Smoothness',
    'emission_mask': 'Emission Mask',
    'unused': 'Unused / Reserved',
    'unknown': 'Unknown Channel',
}

def _xdzr8_v114_packed_profile(image, semantic_role, category, intelligence=None):
    """Return a conservative packed-channel profile for one image.

    Specific source conventions stay internal. A profile is only decoded when
    the filename/semantic role itself is strong enough to identify the layout.
    Otherwise the map is reported as UNRESOLVED and its channels are not given
    invented meanings.
    """
    if image is None:
        return None
    name = str(getattr(image, 'name', '') or '')
    stem = Path(name).stem.lower()
    compact = _sabershader11_key(stem)
    family = (intelligence or {}).get('family', 'General')

    if 'otherdatatex2' in compact:
        return {
            'id': 'OTHER_DATA_AUX',
            'label': 'Transparency + Smoothness + Emission',
            'confidence': 'HIGH',
            'channels': {'R':'transparency','G':'smoothness','B':'emission_mask','A':'unused'},
            'derived': {'roughness': ('ONE_MINUS', 'G')},
        }
    if 'otherdatatex' in compact:
        return {
            'id': 'OTHER_DATA_MATERIAL',
            'label': 'Material ID + Metallic + Specular',
            'confidence': 'HIGH',
            'channels': {'R':'material_id','G':'metallic','B':'specular_mask','A':'unused'},
            'derived': {},
        }

    token_match = re.search(r'(?:^|[_\-.])(orm|arm|mra)$', stem, re.I)
    token = token_match.group(1).lower() if token_match else ''
    if token in {'orm', 'arm'}:
        return {
            'id': token.upper(),
            'label': 'AO + Roughness + Metallic',
            'confidence': 'HIGH',
            'channels': {'R':'ao','G':'roughness','B':'metallic','A':'unused'},
            'derived': {},
        }
    if token == 'mra':
        return {
            'id': 'MRA',
            'label': 'Metallic + Roughness + AO',
            'confidence': 'HIGH',
            'channels': {'R':'metallic','G':'roughness','B':'ao','A':'unused'},
            'derived': {},
        }

    if semantic_role in {'packed_material', 'packed_aux', 'mask'} or any(
        token in compact for token in ('materialmasks', 'materialmaskstex', 'packed')
    ):
        return {
            'id': 'UNRESOLVED',
            'label': 'Packed Map • Channel Layout Unresolved',
            'confidence': 'LOW',
            'channels': {'R':'unknown','G':'unknown','B':'unknown','A':'unknown'},
            'derived': {},
        }
    return None

def _xdzr8_v114_new_separate_color(nodes):
    try:
        node = nodes.new('ShaderNodeSeparateColor')
        try:
            node.mode = 'RGB'
        except Exception:
            pass
        return node
    except Exception:

        try:
            return nodes.new('ShaderNodeSeparateRGB')
        except Exception:
            return None

def _xdzr8_v114_output_socket(separate, channel):
    if not separate:
        return None
    aliases = {
        'R': ('Red','R'), 'G': ('Green','G'), 'B': ('Blue','B'),
    }
    for name in aliases.get(channel, (channel,)):
        sock = separate.outputs.get(name)
        if sock is not None:
            return sock
    return None

def _xdzr8_v114_build_packed_channel_nodes(nodes, links, texture_nodes, category, intelligence=None, enabled=True):
    """Expose safely decoded packed channels as readable node endpoints."""
    audit = {
        'maps': 0, 'decoded': 0, 'unresolved': 0, 'channels': 0,
        'derived': 0, 'profiles': [], 'rows': [],
    }
    if not enabled:
        return audit

    seen_images = set()
    y_cursor = -1840
    for semantic_role in ('mask', 'packed_material', 'packed_aux'):
        tex = (texture_nodes or {}).get(semantic_role)
        image = getattr(tex, 'image', None) if tex else None
        if image is None:
            continue
        try:
            ptr = image.as_pointer()
        except Exception:
            ptr = id(image)
        if ptr in seen_images:
            continue
        seen_images.add(ptr)

        profile = _xdzr8_v114_packed_profile(image, semantic_role, category, intelligence)
        if not profile:
            continue
        audit['maps'] += 1
        profile_id = profile['id']
        audit['profiles'].append(profile_id)
        if profile_id == 'UNRESOLVED':
            audit['unresolved'] += 1
        else:
            audit['decoded'] += 1

        try:
            tex.label = f"{SABERSHADER11_ROLE_LABELS.get(semantic_role, 'Packed Map')}  •  {profile['label']}"
            tex['XDZR8_PackedProfile'] = profile_id
            tex['XDZR8_PackedConfidence'] = profile['confidence']
        except Exception:
            pass

        sep = _xdzr8_v114_new_separate_color(nodes)
        if sep is None:
            audit['rows'].append(f"{image.name}: {profile_id} (splitter unavailable)")
            continue
        sep.name = f"XDZR8 V11.4 • Packed Split • {profile_id}"
        sep.label = f"Packed Channels • {profile['label']}"
        sep.location = (-500, y_cursor)
        try:
            links.new(tex.outputs['Color'], sep.inputs[0])
        except Exception:
            pass

        channel_nodes = {}
        for offset, channel in enumerate(('R','G','B','A')):
            meaning = profile['channels'].get(channel, 'unknown')
            pretty = _XDZR8_V114_CHANNEL_LABELS.get(meaning, meaning.replace('_',' ').title())
            reroute = nodes.new('NodeReroute')
            reroute.name = f"XDZR8 V11.4 • {profile_id} • {channel} • {pretty}"
            reroute.label = f"{channel} • {pretty}"
            reroute.location = (-250, y_cursor - offset * 54)
            source = tex.outputs.get('Alpha') if channel == 'A' else _xdzr8_v114_output_socket(sep, channel)
            if source is not None:
                try:
                    links.new(source, reroute.inputs[0])
                except Exception:
                    pass
            channel_nodes[channel] = reroute
            audit['channels'] += 1

        for derived_role, spec in (profile.get('derived') or {}).items():
            op, channel = spec
            source_node = channel_nodes.get(channel)
            if op == 'ONE_MINUS' and source_node is not None:
                math_node = nodes.new('ShaderNodeMath')
                math_node.operation = 'SUBTRACT'
                math_node.name = f"XDZR8 V11.4 • Derived {derived_role.title()}"
                math_node.label = f"Derived {derived_role.title()} = 1 - {channel}"
                math_node.location = (0, y_cursor - 54)
                math_node.inputs[0].default_value = 1.0
                try:
                    links.new(source_node.outputs[0], math_node.inputs[1])
                except Exception:
                    pass
                audit['derived'] += 1

        channel_text = ', '.join(
            f"{ch}={_XDZR8_V114_CHANNEL_LABELS.get(role, role)}"
            for ch, role in profile['channels'].items()
        )
        audit['rows'].append(f"{image.name}: {profile_id} [{profile['confidence']}] • {channel_text}")
        y_cursor -= 290
    return audit

def _xdzr8_v114_material_packed_audit(materials):
    totals = {'maps':0, 'decoded':0, 'unresolved':0, 'channels':0, 'derived':0}
    profiles = {}
    rows = []
    seen = set()
    for mat in materials or []:
        if mat is None:
            continue
        try:
            ptr = mat.as_pointer()
            if ptr in seen:
                continue
            seen.add(ptr)
            if not bool(mat.get('SaberShader_V11_Universal', False)):
                continue
            for key, prop in (
                ('maps','XDZR8_V114_PackedMaps'), ('decoded','XDZR8_V114_DecodedPackedMaps'),
                ('unresolved','XDZR8_V114_UnresolvedPackedMaps'), ('channels','XDZR8_V114_ExtractedChannels'),
                ('derived','XDZR8_V114_DerivedChannels'),
            ):
                totals[key] += int(mat.get(prop, 0))
            ptext = str(mat.get('XDZR8_V114_PackedProfiles', '') or '')
            for p in [x for x in ptext.split('; ') if x]:
                profiles[p] = profiles.get(p, 0) + 1
            row = str(mat.get('XDZR8_V114_PackedAudit', '') or '')
            if row:
                rows.append(f"{mat.name}: {row}")
        except Exception:
            pass
    totals['profiles'] = profiles
    totals['rows'] = rows
    return totals

def _xdzr8_v113_status_label(label, image, status=None):
    status = str(status or ('FOUND' if image else 'MISSING')).upper()
    if image and status in {'FOUND', 'EXISTING'}:
        status = 'FOUND'
    return f'{label}  •  {status}'

def _sabershader11_label_texture_tree(tree, family_hint='', source_intelligence=None):
    if not tree:
        return 0
    count = 0
    for node in tree.nodes:
        if node.bl_idname == 'ShaderNodeTexImage':
            lname = node.name.lower()
            role = None
            if node.name == 'mmd_base_tex' or node.name == 'mmd_base_tex.001':
                role = 'base'
            elif node.name == 'mmd_toon_tex':
                role = 'toon'
            elif node.name == 'Image Texture.001':
                role = 'hn' if 'hair' in family_hint.lower() else 'normal'
            elif node.name == 'Image Texture.002':
                role = 'p'
            elif node.name == 'Image Texture.003':
                role = 'st'
            elif node.name == 'Image Texture.004':
                role = 'rs'
            if role is None:
                if node.image and source_intelligence:
                    role = _xdzr8_v1122_semantic_role(node.image.name, source_intelligence)
                else:
                    role = _sabershader11_role_from_text(' '.join((node.name, node.label, node.image.name if node.image else '')))
            label = SABERSHADER11_ROLE_LABELS.get(role, 'Image Texture')
            try:
                resolver_status = node.get('XDZR8_TextureStatus', '')
            except Exception:
                resolver_status = ''
            node.label = _xdzr8_v113_status_label(label, node.image, resolver_status or None)
            count += 1
        elif node.bl_idname == 'ShaderNodeGroup' and getattr(node, 'node_tree', None):
            count += _sabershader11_label_texture_tree(node.node_tree, node.node_tree.name, source_intelligence)
    return count

def _sabershader11_label_material_textures(mat, source_intelligence=None):
    if not mat or not mat.use_nodes or not mat.node_tree:
        return 0
    return _sabershader11_label_texture_tree(mat.node_tree, mat.name, source_intelligence)

def _xdzr8_v11821_norm_file_name(value):
    raw = str(value or '').strip().replace('\\', '/')
    return raw.rsplit('/', 1)[-1].casefold() if raw else ''

def _xdzr8_v11821_image_targets():
    """Collect exact image basenames referenced by the current .blend.

    These names are evidence only. They are never fuzzy-matched during path
    recovery: a broken image is rebound only when its exact basename resolves
    to one unique file in the selected/discovered texture root.
    """
    targets = set()
    rows = []
    for img in bpy.data.images:
        try:
            if getattr(img, 'source', 'FILE') not in {'FILE', 'SEQUENCE', 'MOVIE'}:
                continue
        except Exception:
            pass
        names = []
        try: names.append(_xdzr8_v11821_norm_file_name(img.filepath))
        except Exception: pass
        try: names.append(_xdzr8_v11821_norm_file_name(img.name))
        except Exception: pass
        names = [n for n in names if n and Path(n).suffix.lower() in SABERSHADER11_IMAGE_EXTENSIONS]
        if names:
            targets.update(names)
            rows.append((getattr(img, 'name', ''), names[0]))
    return targets, rows

def _xdzr8_v11821_add_root(out, seen, path, label):
    try:
        p = Path(path).expanduser()
        if not p.exists() or not p.is_dir():
            return
        p = p.resolve()

        if p.parent == p:
            return
        key = os.path.normcase(str(p))
        if key not in seen:
            seen.add(key)
            out.append((p, str(label)))
    except Exception:
        pass

def _xdzr8_v11821_candidate_roots(configured_folder):
    roots, seen = [], set()
    configured = str(configured_folder or '').strip()
    if configured:
        try:
            _xdzr8_v11821_add_root(roots, seen, bpy.path.abspath(configured), 'configured folder')
        except Exception:
            _xdzr8_v11821_add_root(roots, seen, configured, 'configured folder')

    blend_dir = None
    try:
        if bpy.data.filepath:
            blend_dir = Path(bpy.data.filepath).resolve().parent
    except Exception:
        blend_dir = None
    typical = ('Texture2D', 'Textures', 'Texture', 'textures', 'texture', 'Tex', 'tex', 'images', 'Images')
    if blend_dir is not None:
        for name in typical:
            _xdzr8_v11821_add_root(roots, seen, blend_dir / name, f'blend sibling {name}')
        _xdzr8_v11821_add_root(roots, seen, blend_dir, 'blend directory')
        try:
            parent = blend_dir.parent
            if parent != blend_dir and parent.parent != parent:
                for name in typical:
                    _xdzr8_v11821_add_root(roots, seen, parent / name, f'blend parent {name}')
        except Exception:
            pass

    for img in bpy.data.images:
        try:
            raw = bpy.path.abspath(str(img.filepath or '')).strip()
        except Exception:
            raw = str(getattr(img, 'filepath', '') or '').strip()
        if not raw:
            continue
        try:
            p = Path(raw)
            parent = p.parent
            steps = 0
            while parent != parent.parent and steps < 5 and not parent.exists():
                parent = parent.parent
                steps += 1
            if parent.exists() and parent.is_dir() and parent.parent != parent:
                for name in typical:
                    _xdzr8_v11821_add_root(roots, seen, parent / name, f'broken-path ancestor {name}')

                if steps <= 2:
                    _xdzr8_v11821_add_root(roots, seen, parent, 'broken-path ancestor')
        except Exception:
            pass
    return roots

def _xdzr8_v11821_scan_root(root, targets=None, max_files=24000, max_depth=5):
    root = Path(root)
    targets = set(targets or [])
    images = []
    hits = set()
    scanned = 0
    stack = [(root, 0)]
    while stack and scanned < int(max_files):
        current, depth = stack.pop()
        try:
            entries = list(current.iterdir())
        except Exception:
            continue
        for path in entries:
            if scanned >= int(max_files):
                break
            try:
                if path.is_dir():
                    if depth < int(max_depth) and not path.name.startswith('.'):
                        stack.append((path, depth + 1))
                    continue
                scanned += 1
                if path.suffix.lower() in SABERSHADER11_IMAGE_EXTENSIONS:
                    images.append(path)
                    if path.name.casefold() in targets:
                        hits.add(path.name.casefold())
            except Exception:
                continue
    return images, hits, scanned

def _xdzr8_v11821_discover_texture_root(configured_folder):
    """Return a bounded, evidence-ranked texture root for path recovery."""
    targets, _rows = _xdzr8_v11821_image_targets()
    candidates = _xdzr8_v11821_candidate_roots(configured_folder)
    tested = []
    best = None
    for root, label in candidates:
        images, hits, scanned = _xdzr8_v11821_scan_root(root, targets)
        tested.append({'root': root, 'label': label, 'images': len(images), 'hits': len(hits), 'scanned': scanned})
        configured_bonus = 1 if label == 'configured folder' else 0

        score = (len(hits), configured_bonus, len(root.parts), -len(images))
        if images and (best is None or score > best['score']):
            best = {'root': root, 'label': label, 'paths': images, 'hits': hits, 'score': score, 'scanned': scanned}
        if targets and len(hits) == len(targets) and len(hits) >= 3 and label == 'configured folder':
            break
    return {
        'targets': sorted(targets),
        'candidates': tested,
        'root': best['root'] if best else None,
        'root_source': best['label'] if best else '',
        'paths': list(best['paths']) if best else [],
        'exact_hits': len(best['hits']) if best else 0,
        'scanned': int(best['scanned']) if best else 0,
    }

def _xdzr8_v11821_recover_loaded_images(image_paths):
    """Rebind broken bpy.data.images by unique exact basename only."""
    by_name = {}
    for path in image_paths or []:
        try:
            by_name.setdefault(path.name.casefold(), []).append(Path(path))
        except Exception:
            pass
    recovered = []
    ambiguous = []
    already_ok = 0
    failed = []
    for img in bpy.data.images:
        try:
            if getattr(img, 'packed_file', None) is not None:
                continue
            raw = bpy.path.abspath(str(img.filepath or '')).strip()
        except Exception:
            raw = str(getattr(img, 'filepath', '') or '').strip()
        try:
            if raw and Path(raw).exists():
                already_ok += 1
                continue
        except Exception:
            pass
        names = []
        try: names.append(_xdzr8_v11821_norm_file_name(img.filepath))
        except Exception: pass
        try: names.append(_xdzr8_v11821_norm_file_name(img.name))
        except Exception: pass
        candidates = []
        for name in names:
            if name:
                candidates.extend(by_name.get(name, []))
        unique = []
        seen = set()
        for p in candidates:
            try: key = os.path.normcase(str(p.resolve()))
            except Exception: key = os.path.normcase(str(p))
            if key not in seen:
                seen.add(key); unique.append(p)
        if len(unique) == 1:
            path = unique[0]
            try:
                img.filepath = str(path)
                try: img.filepath_raw = str(path)
                except Exception: pass
                img.reload()
                recovered.append(f'{img.name} -> {path.name}')
            except Exception as exc:
                failed.append(f'{img.name}: {exc}')
        elif len(unique) > 1:
            ambiguous.append(f'{img.name}: {len(unique)} exact-basename matches')
    return {
        'recovered': recovered,
        'recovered_count': len(recovered),
        'ambiguous': ambiguous,
        'ambiguous_count': len(ambiguous),
        'already_ok': already_ok,
        'failed': failed,
    }

def _xdzr8_v11821_texture_index_from_paths(paths, intelligence=None):
    out = []
    seen = set()
    for path in paths or []:
        try:
            p = Path(path)
            key = os.path.normcase(str(p.resolve()))
            if key in seen or not p.is_file() or p.suffix.lower() not in SABERSHADER11_IMAGE_EXTENSIONS:
                continue
            seen.add(key)
            out.append((p, _xdzr8_v1122_semantic_role(p.name, intelligence), _sabershader11_key(p.stem)))
        except Exception:
            pass
    return out

def _sabershader11_texture_folder_index(folder, intelligence=None):
    folder = bpy.path.abspath(str(folder or '')).strip()
    if not folder:
        return [], None
    root = Path(folder)
    if not root.exists() or not root.is_dir():
        return [], root
    files = []
    try:
        for path in root.rglob('*'):
            if path.is_file() and path.suffix.lower() in SABERSHADER11_IMAGE_EXTENSIONS:
                role = _xdzr8_v1122_semantic_role(path.name, intelligence)
                files.append((path, role, _sabershader11_key(path.stem)))
    except Exception as exc:
        log(f"V11 texture scan warning: {exc}")
    return files, root

def _sabershader11_material_name_candidates(mat_name):
    base = re.sub(r'\.\d{3}$', '', str(mat_name or ''))
    candidates = {_sabershader11_key(base)}
    for token in ('material', 'mat', 'mi', 'm_'):
        k = _sabershader11_key(base.replace(token, ''))
        if k:
            candidates.add(k)
    return [c for c in candidates if len(c) >= 2]

def _sabershader11_find_texture_for_material(index, mat_name, role, strictness=0.55):
    if not index:
        return None
    candidates = _sabershader11_material_name_candidates(mat_name)
    best = None
    best_score = -1.0
    role_items = [item for item in index if item[1] == role]
    if not role_items:
        return None
    for path, file_role, key in role_items:
        role_suffix_keys = [_sabershader11_key(x) for x in SABERSHADER11_ROLE_SUFFIXES.get(role, ())]
        root_key = key
        for sk in role_suffix_keys:
            if sk and root_key.endswith(sk):
                root_key = root_key[:-len(sk)]
                break
        score = 0.0
        for cand in candidates:
            if not cand:
                continue
            if root_key == cand:
                score = max(score, 1.0)
            elif cand in root_key or root_key in cand:
                short = min(len(cand), len(root_key)); long = max(len(cand), len(root_key), 1)
                score = max(score, 0.70 + 0.25 * short / long)
            else:

                common = len(set(cand) & set(root_key)) / max(1, len(set(cand) | set(root_key)))
                score = max(score, common * 0.58)
        if score > best_score:
            best_score = score
            best = path

    if best_score < float(strictness):
        if len(role_items) == 1 and float(strictness) <= 0.25:
            return role_items[0][0]
        return None
    return best

def _sabershader_v1026_is_fgo_safe_cache_image(image):
    try:
        return bool(image and str(getattr(image, 'name', '') or '').startswith('SaberShader - DDS Cache - '))
    except Exception:
        return False

def _sabershader_v1026_force_safe_fgo_image(image, role=None, source_path=None):
    """Bypass Blender-loaded FGO DDS images and force the native safe cache."""
    if image is None and not source_path:
        return image, False, 'missing image'
    try:
        src_name = str(getattr(image, 'name', '') or '') if image is not None else ''
        raw_path = str(getattr(image, 'filepath', '') or '') if image is not None else ''
        abs_path = ''
        if raw_path:
            try:
                abs_path = str(Path(bpy.path.abspath(raw_path)).resolve())
            except Exception:
                abs_path = raw_path
        candidate = str(source_path or abs_path or raw_path or '')
        if not candidate and src_name:
            candidate = src_name
        name = Path(candidate.replace('\\','/')).name if candidate else Path(src_name).name
        lname = str(name or '').casefold()
        if not lname.endswith('.dds'):
            return image, False, 'not DDS'
        if _sabershader_v1026_is_fgo_safe_cache_image(image):
            return image, False, 'safe cache already assigned'
        if not lname.startswith(('svt_', '_a_svt_', '_ramp01')):
            return image, False, 'not FGO DDS family'
        if source_path:
            resolved = str(Path(source_path).resolve())
        elif abs_path:
            resolved = abs_path
        elif raw_path:
            resolved = str(Path(raw_path).resolve()) if os.path.exists(raw_path) else raw_path
        else:
            return image, False, 'no source path for FGO DDS bypass'
        safe, changed, reason = _sabershader_v1023_fgo_dds_cache_from_path(
            resolved, colorspace=_sabershader_v1023_role_colorspace(role)
        )
        if safe is not None:
            return safe, True, f'forced safe cache: {reason}'
        return image, False, f'forced safe cache failed: {reason}'
    except Exception as exc:
        return image, False, f'forced safe cache exception: {exc}'

def _sabershader_v101_dds_resilient_image(image, role=None):
    """Return a safe Blender image for DDS sources, preferring FGO native decode."""
    if image is None:
        return image, False, 'missing image'
    try:
        src_name = str(getattr(image, 'name', '') or '')
        raw_path = str(getattr(image, 'filepath', '') or '')
        abs_path = ''
        if raw_path:
            try: abs_path = str(Path(bpy.path.abspath(raw_path)).resolve())
            except Exception: abs_path = raw_path
        source_path = abs_path or raw_path
        suffix = Path(source_path.replace('\\','/')).suffix.lower() if source_path else Path(src_name).suffix.lower()
    except Exception:
        return image, False, 'image metadata unavailable'
    if suffix != '.dds' and not src_name.casefold().endswith('.dds'):
        return image, False, 'not DDS'

    if source_path and Path(source_path).name.casefold().startswith(('svt_', '_a_svt_', '_ramp01')):
        safe, changed, reason = _sabershader_v1023_fgo_dds_cache_from_path(
            source_path, colorspace=_sabershader_v1023_role_colorspace(role)
        )
        if safe is not None:
            return safe, changed, reason
        if 'cubemap' in reason:
            return image, False, reason

    source_key = os.path.normcase(source_path or src_name)
    cache_name = 'SaberShader DDS Cache - ' + (Path(src_name).stem or Path(source_path).stem or 'Image')
    for existing in bpy.data.images:
        try:
            if bool(existing.get('SaberShader_V101_DDSCache', False)) and str(existing.get('SaberShader_V101_DDSSource', '')) == source_key:
                return existing, False, 'cached RGBA copy reused'
        except Exception:
            pass
    try:
        if not bool(getattr(image, 'has_data', False)):
            try: image.reload()
            except Exception: pass
        width, height = int(image.size[0]), int(image.size[1])
        if width <= 0 or height <= 0:
            return image, False, 'DDS has no decoded dimensions'
        from array import array
        pixels = array('f', [0.0]) * (width * height * 4)
        image.pixels.foreach_get(pixels)
        safe = bpy.data.images.new(cache_name, width=width, height=height, alpha=True, float_buffer=False)
        safe.pixels.foreach_set(pixels); safe.update()
        try: safe.colorspace_settings.name = image.colorspace_settings.name
        except Exception: pass
        try: safe.pack()
        except Exception: pass
        safe['SaberShader_V101_DDSCache'] = True
        safe['SaberShader_V101_DDSSource'] = source_key
        return safe, True, f'generic RGBA cache {width}x{height}'
    except Exception as exc:
        return image, False, f'DDS cache failed: {exc}'

def _sabershader11_load_image(path):
    if not path:
        return None
    try:
        abs_path = str(Path(path).resolve())
        p = Path(abs_path)
        if p.suffix.casefold() == '.dds' and p.name.casefold().startswith(('svt_', '_a_svt_', '_ramp01')):
            native, _changed, native_reason = _sabershader_v1023_fgo_dds_cache_from_path(abs_path)
            if native is not None:
                return native
            if 'cubemap' in native_reason:
                return None
        for img in bpy.data.images:
            try:
                if bpy.path.abspath(img.filepath) and str(Path(bpy.path.abspath(img.filepath)).resolve()) == abs_path:
                    return img
            except Exception:
                pass
        return bpy.data.images.load(abs_path, check_existing=True)
    except Exception as exc:
        log(f"V11 texture load warning: {path}: {exc}")
        return None

