        layer.inputs['Blend'].default_value = 0.11

        inv = nodes.new('ShaderNodeMath')
        inv.operation = 'SUBTRACT'
        inv.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Invert Facing'
        inv.location = (3040, -180)
        inv.inputs[0].default_value = 1.0
        links.new(layer.outputs['Facing'], inv.inputs[1])

        edge = nodes.new('ShaderNodeMapRange')
        edge.clamp = True
        try:
            edge.interpolation_type = 'SMOOTHERSTEP'
        except Exception:
            pass
        edge.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Edge Mask'
        edge.label = 'Uma Face Outline • Silhouette Edge'
        edge.location = (3230, -180)
        edge.inputs['From Min'].default_value = 0.26
        edge.inputs['From Max'].default_value = 0.60
        edge.inputs['To Min'].default_value = 0.0
        edge.inputs['To Max'].default_value = 1.0
        links.new(inv.outputs[0], edge.inputs['Value'])
        contour_mask = edge.outputs['Result']

        if uv_socket is not None:
            uv_sep = nodes.new('ShaderNodeSeparateXYZ')
