            links.new(chin_v, chin_core.inputs[1])

            chin_mul = nodes.new('ShaderNodeMath')
            chin_mul.operation = 'MULTIPLY'
            chin_mul.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Chin Edge'
            chin_mul.location = (3600, -1180)
            links.new(edge.outputs['Result'], chin_mul.inputs[0])
