            chin_gain = nodes.new('ShaderNodeMath')
            chin_gain.operation = 'MULTIPLY'
            chin_gain.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Chin Gain'
            chin_gain.location = (3780, -1180)
            chin_gain.inputs[1].default_value = 1.28
            links.new(chin_mul.outputs[0], chin_gain.inputs[0])

            chin_merge = nodes.new('ShaderNodeMath')
            chin_merge.operation = 'MAXIMUM'
            chin_merge.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Jaw+Chin'
            chin_merge.location = (3960, -700)
            links.new(contour_mask, chin_merge.inputs[0])
            links.new(chin_gain.outputs[0], chin_merge.inputs[1])
            contour_mask = chin_merge.outputs[0]
            audit['camera_chin_contour'] = True

            nose_zone = nodes.new('ShaderNodeMath')
            nose_zone.operation = 'MULTIPLY'
            nose_zone.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Nose Zone'
            nose_zone.location = (3410, -2030)
            links.new(nose_u, nose_zone.inputs[0])
            links.new(nose_v, nose_zone.inputs[1])

            mouth_zone = nodes.new('ShaderNodeMath')
            mouth_zone.operation = 'MULTIPLY'
            mouth_zone.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Mouth Zone'
            mouth_zone.location = (3410, -1610)
            links.new(mouth_u, mouth_zone.inputs[0])
            links.new(mouth_v, mouth_zone.inputs[1])

            bw = nodes.new('ShaderNodeRGBToBW')
            bw.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Detail BW'
            bw.location = (3410, -2450)
            links.new(base_socket, bw.inputs['Color'])

            dinv = nodes.new('ShaderNodeInvert')
            dinv.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Detail Invert'
            dinv.location = (3590, -2450)
            dinv.inputs['Fac'].default_value = 1.0
            links.new(bw.outputs['Val'], dinv.inputs['Color'])

            dramp = nodes.new('ShaderNodeValToRGB')
            dramp.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Detail Mask'
            dramp.location = (3790, -2450)
            dramp.color_ramp.interpolation = 'LINEAR'
            de = dramp.color_ramp.elements
            while len(de) > 2:
                dramp.color_ramp.elements.remove(de[-1])
