            mouth_detail.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Mouth Detail Gate'
            mouth_detail.location = (3600, -1610)
            links.new(mouth_zone.outputs[0], mouth_detail.inputs[0])
            links.new(dramp.outputs['Color'], mouth_detail.inputs[1])

            nose_gain = nodes.new('ShaderNodeMath')
            nose_gain.operation = 'MULTIPLY'
            nose_gain.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Nose Gate Strength'
            nose_gain.location = (3600, -2030)
            nose_gain.inputs[1].default_value = 1.10
            links.new(nose_zone.outputs[0], nose_gain.inputs[0])

            mouth_gain = nodes.new('ShaderNodeMath')
