            feature_union = nodes.new('ShaderNodeMath')
            feature_union.operation = 'MAXIMUM'
            feature_union.name = 'XDZR8 V11.9.2.13 • Uma Face Outline Feature Union'
            feature_union.location = (3970, -1810)
            links.new(nose_gain.outputs[0], feature_union.inputs[0])
            links.new(mouth_gain.outputs[0], feature_union.inputs[1])

            feature_cap = nodes.new('ShaderNodeMath')
