def _sabershader11_reference_scene_detected(materials):
    def hits(source):
        names = {_sabershader11_key(m.name) for m in source if m}
        d = sum(1 for n in DOLORIS if _sabershader11_key(n) in names or _sabershader11_key('SaberShader_V8_Doloris_'+n) in names)
        o = sum(1 for n in OBLIVIONIS if _sabershader11_key(n) in names or _sabershader11_key('SaberShader_V8_Oblivionis_'+n) in names)
        return d, o
    d_hits, o_hits = hits(materials)
    global_d, global_o = hits(bpy.data.materials)
    target_is_reference = d_hits >= 5 or o_hits >= 5
    full_reference_scene = global_d >= 5 and global_o >= 5
    return target_is_reference and full_reference_scene, d_hits, o_hits

def _xdzr8_v1177_reference_global_signature():
    """Conservative global preflight for the locked two-character reference scene.

    AUTO character isolation must remain conservative for arbitrary multi-character
    scenes. The approved Ave Mujica reference scene is the one exception because it
    has a strong, stable two-family material signature and its legacy builder already
    knows how to process Doloris and Oblivionis globally. Require BOTH families so a
    random model with generic names such as Face/Hair/Clothes cannot trigger this.
    """
    names = {_sabershader11_key(m.name) for m in bpy.data.materials if m}
    d_hits = sum(1 for n in DOLORIS if _sabershader11_key(n) in names or _sabershader11_key('SaberShader_V8_Doloris_'+n) in names)
    o_hits = sum(1 for n in OBLIVIONIS if _sabershader11_key(n) in names or _sabershader11_key('SaberShader_V8_Oblivionis_'+n) in names)
    detected = d_hits >= 5 and o_hits >= 5
    return bool(detected), int(d_hits), int(o_hits)

def _xdzr8_v1177_run_locked_reference_preflight(context, settings, operator, d_hits, o_hits):
    """Run the locked reference backend before generic character detection.

    This path is intentionally narrow: AUTO mode + global Doloris/Oblivionis
    signature + reference backend enabled. It does not infer a generic character
    cluster and therefore cannot accidentally absorb stage/prop meshes.
    """
    visible = _sabershader111_visible_meshes(context.scene)
    target_reason = 'Auto → Locked Reference Scene Signature'
    detection_note = (
        f'global reference preflight matched Doloris={int(d_hits)} and Oblivionis={int(o_hits)}; '
        f'generic isolation bypassed safely ({len(visible)} visible non-helper meshes)'
    )
    context.scene['SaberShader_V11_TargetReason'] = target_reason
    context.scene['SaberShader_V11_DetectionConfidence'] = 'HIGH'
    context.scene['SaberShader_V11_DetectionNote'] = detection_note
    context.scene['SaberShader_V11_DetectedArmature'] = ''
    context.scene['SaberShader_V11_ExcludedSceneMeshes'] = 0
    context.scene['XDZR8_V11_6_4_PhysicsHelpersExcluded'] = 0
    context.scene['SaberShader_V11_MeshCount'] = len(visible)
    context.scene['SaberShader_V11_MaterialCount'] = len([m for m in bpy.data.materials if m])
    context.scene['XDZR8_V11_2_1_DirectRigMeshes'] = 0
    context.scene['XDZR8_V11_2_1_ClusterExpandedMeshes'] = 0
    context.scene['XDZR8_SourceFamily'] = 'REFERENCE_LOCKED'
    context.scene['XDZR8_SourceIntelligenceConfidence'] = 'HIGH'
    context.scene['XDZR8_SourceConvention'] = 'Ave Mujica locked reference signature'
    context.scene['XDZR8_GeometryProfile'] = 'REFERENCE_LOCKED'
    context.scene['XDZR8_GeometryProfileConfidence'] = 'HIGH'
    context.scene['XDZR8_OutlineStrategy'] = 'REFERENCE_B3_12_LOCKED'
    context.scene['XDZR8_V11_7_7_ReferencePreflight'] = True
    context.scene['XDZR8_V11_7_7_ReferenceDolorisHits'] = int(d_hits)
    context.scene['XDZR8_V11_7_7_ReferenceOblivionisHits'] = int(o_hits)

    log('='*96)
    log('XDZR8 SABERSHADER V11.9.2.13.1 — Uma Face Outline Fail-Closed Hotfix')
    log(f'Locked reference preflight: Doloris hits={d_hits}, Oblivionis hits={o_hits}, visibleMeshes={len(visible)}')
    log('AUTO generic character isolation bypassed; using approved V10.9C2.4 reference backend.')
    try:
        settings.shot_profile = 'AVE'
    except Exception:
        pass
    _xdzr8_build_progress_update(context, 52, 'Building locked V10.9C2.4 reference backend', force_redraw=True)
    result = bpy.ops.sabershader.sabershader_build_v8()
    _xdzr8_build_progress_update(context, 92, 'Finalizing locked reference report', force_redraw=True)
    finished = ('FINISHED' in result) if result is not None else False
    report = [
        'XDZR8 Sabershader V11.9.1 — SaberShader Node Group Architecture',
        f'Character source: {target_reason}',
        'Detection confidence: HIGH',
        f'Detection note: {detection_note}',
        f'Visible non-helper meshes: {len(visible)}',
        f'Visible mesh names: {", ".join(o.name for o in visible) if visible else "none"}',
        f'Global Doloris signature hits: {d_hits}',
        f'Global Oblivionis signature hits: {o_hits}',
        'Backend: locked V10.9C2.4 reference compatibility',
        'Generic V11 character isolation: BYPASSED by exact reference-scene regression guard',
        'Generic adaptive outline: NOT USED',
        'Reference outline: B3.12 lock preserved',
        'Final Grade: C2.4 lock preserved',
        '',
        'Result: locked reference backend executed.' if finished else 'Result: locked reference backend did not finish successfully.',
    ]
    _sabershader11_write_report(report)
    if not finished:
        _xdzr8_build_progress_finish(context, False, 'Reference backend failed')
        operator.report({'ERROR'}, 'Locked reference scene was detected, but the V10.9C2.4 backend did not finish successfully. See XDZR8_Sabershader_Analysis.')
        return {'CANCELLED'}
    _xdzr8_build_progress_finish(context, True, 'Reference build complete')
    operator.report({'INFO'}, 'Add Shaders complete: locked reference scene detected automatically; V10.9C2.4 look preserved.')
    return {'FINISHED'}

def _xdzr8_v11232_source_name(mat):
    """Stable pre-V11 source name for canonical and role-variant materials."""
    if mat is None:
        return ''
    try:
        return str(mat.get('SaberShader_V11_SourceMaterial', '') or mat.name)
    except Exception:
        return _sabershader111_safe_material_name(mat, '')

def _xdzr8_v11232_usage_groups(objects):
    """Group material-slot usages by their original source material name.

    V11.8.3 quarantines authored source helper/outline materials so they stay
    untouched on the model and do not enter the semantic classifier.
    """
    groups = {}
    for obj in (objects or []):
        if not obj or getattr(obj, 'type', '') != 'MESH':
            continue
        for slot_index, slot in enumerate(getattr(obj, 'material_slots', [])):
            mat = slot.material
            if mat is None:
                continue
            is_helper, _reason = _xdzr8_v11822_is_source_helper_material(mat)
            if is_helper:
                continue
            source_name = _xdzr8_v11232_source_name(mat)
            if not source_name:
                continue
            group = groups.setdefault(source_name, {'materials': [], 'usages': [], 'objects': []})
            if mat not in group['materials']:
                group['materials'].append(mat)
            group['usages'].append((obj, slot_index, mat))
            if obj not in group['objects']:
                group['objects'].append(obj)
    return groups

def _xdzr8_v11234_rank_stats(score_rows):
    top = float(score_rows[0][1]) if score_rows else 0.0
    second = float(score_rows[1][1]) if len(score_rows) > 1 else 0.0
    return top, second, top - second

def _xdzr8_v11234_object_role_evidence(obj, role, character_context=None):
    """Return object-local semantic or geometric evidence for a usage role.

    V11.6 extends the textual guardrail with conservative head-region geometry
    hints so generic MMD head-family materials can still specialize to hair,
    face or eyes when the object itself carries no readable English name.
    """
    if not obj or role not in XDZR8_V112_ROLE_TOKENS:
        return False, 'no object-local evidence'
    joined = _xdzr8_v116_object_text(obj, include_vgroups=True)
    hits = [tok for tok in XDZR8_V112_ROLE_TOKENS.get(role, ()) if _xdzr8_v112_text_has_token(joined, tok)]
    if hits:
        return True, 'object-local ' + '/'.join(hits[:4])
    if role in {'hair', 'face', 'eyes', 'eyes5', 'mouth'}:
        hint = _xdzr8_v116_object_role_hints(obj, character_context)
        score = float((hint.get('scores') or {}).get(role, 0.0))
        threshold = {'hair': 2.8, 'face': 2.6, 'eyes': 2.8, 'eyes5': 2.4, 'mouth': 2.3}.get(role, 2.8)
        if score >= threshold:
            return True, f'V11.6 geometry {role}={score:.1f}'
    return False, 'no object/mesh/vertex-group or V11.6 geometry evidence for ' + str(role)

def _xdzr8_v11234_explicit_transparency_evidence(source_ref, obj=None):
    """Transparent Cloth is never inferred merely because it won a score race."""
    reasons = []
    try:
        images = _sabershader11_existing_role_images(source_ref) if source_ref else {}
    except Exception:
        images = {}
    if images.get('opacity'):
        reasons.append('explicit opacity texture')

    alpha = 1.0
    try:
        principled = _sabershader11_principled(source_ref)
        if principled:
            alpha = min(alpha, float(_sabershader11_socket_default(principled, 'Alpha', 1.0)))
    except Exception:
        pass
    try:
        alpha = min(alpha, float(source_ref.diffuse_color[3]))
    except Exception:
        pass
    if alpha < 0.985:
        reasons.append(f'explicit alpha={alpha:.3f}')

    names = []
    try:
        names.append(source_ref.name)
        names.append(str(source_ref.get('SaberShader_V11_SourceMaterial', '') or ''))
    except Exception:
        pass
    if obj:
        names.extend([getattr(obj, 'name', ''), getattr(getattr(obj, 'data', None), 'name', '')])
    joined = ' '.join(n for n in names if n)
    hits = [tok for tok in XDZR8_V112_ROLE_TOKENS.get('transparent_cloth', ()) if _xdzr8_v112_text_has_token(joined, tok)]
    if hits:
        reasons.append('transparent naming ' + '/'.join(hits[:3]))
    return bool(reasons), '; '.join(reasons) if reasons else 'no explicit alpha/opacity/transparent evidence'

def _xdzr8_v11234_role_guardrail(overall_role, role, confidence, score_rows, source_ref, obj, character_context=None):
    """Conservative gate for a *per-object* role change.

    A specialization is not a second global classifier. It is allowed only when
    the target object itself supplies strong evidence that it should differ from
    the canonical source role.
    """
    if not role or role == overall_role:
        return False, 'same as canonical role'
    if confidence != 'HIGH':
        return False, f'confidence {confidence}; specialization requires HIGH'

    top, second, margin = _xdzr8_v11234_rank_stats(score_rows)
    if top < 6.0 or margin < 2.0:
        return False, f'weak HIGH candidate top={top:.1f} margin={margin:.1f}'

    local_ok, local_reason = _xdzr8_v11234_object_role_evidence(obj, role, character_context)

    if role == 'transparent_cloth':
        transparency_ok, transparency_reason = _xdzr8_v11234_explicit_transparency_evidence(source_ref, obj)
        if not transparency_ok:
            return False, 'Transparent Cloth guard: ' + transparency_reason

        return True, transparency_reason + (f'; {local_reason}' if local_ok else '')

    if not local_ok:
        return False, local_reason
    return True, local_reason

def _xdzr8_v11234_mass_limit_for_role(role):

    if role in {'transparent_cloth', 'stockings', 'mask', 'accessory'}:
        return 0.35

    return 0.60

def _xdzr8_v11232_accept_usage_role(overall_role, role, confidence, score_rows):
    """Legacy compatibility wrapper.

    V11.2.3.4 performs the real safety decision in _xdzr8_v11234_role_guardrail,
    where object-local and alpha evidence are available. Keep this helper for
    callers/add-on compatibility, but never allow MEDIUM specialization anymore.
    """
    if not role or role == overall_role or confidence != 'HIGH' or not score_rows:
        return False
    top, second, margin = _xdzr8_v11234_rank_stats(score_rows)
    return top >= 6.0 and margin >= 2.0

def _xdzr8_v11232_plan_usage_specialization(objects, texture_index, settings, source_intelligence, canonical_by_source, report):
    """Create guarded per-object role variants for genuinely mixed source use.

    V11.2.3.4 treats specialization as an exception, not a fallback classifier:
    only HIGH-confidence, object-local semantic differences are eligible. Large
    majority flips and unsupported transparency are rejected and audited.
    """
    groups = _xdzr8_v11232_usage_groups(objects)
    specialized_by_obj_source = {}
    variant_cache = {}
    specialized_sources = 0
    specialized_objects = 0
    created_variants = 0
    unresolved_single_object = 0
    detail_lines = []
    rejected_lines = []
    rejected_specializations = 0
    rejected_role_counts = {}
    mass_guard_blocks = 0
    raw_candidates = 0

    for source_name, group in groups.items():
        mats = group['materials']
        users = group['objects']
        if not mats or not users:
            continue
        representative = mats[0]
        source_ref = bpy.data.materials.get(source_name) or _sabershader111_resolve_original_source_material(representative) or representative

        if _xdzr8_v112_manual_override(representative, source_ref):
            continue

        overall_role, overall_reason, overall_conf, overall_scores = _sabershader11_classify_material(source_ref, users, source_intelligence)
        per_object = {}
        raw_accepted = {}
        for obj in users:
            role, why, conf, scores = _sabershader11_classify_material(source_ref, [obj], source_intelligence)
            per_object[obj.name] = (role, why, conf, scores)
            if _xdzr8_v11232_accept_usage_role(overall_role, role, conf, scores):
                raw_candidates += 1
                ok, guard_reason = _xdzr8_v11234_role_guardrail(
                    overall_role, role, conf, scores, source_ref, obj, (source_intelligence or {}).get('character_geometry')
                )
                if ok:
                    raw_accepted[obj.name] = (role, why, conf, scores, guard_reason)
                else:
                    rejected_specializations += 1
                    rejected_role_counts[role] = rejected_role_counts.get(role, 0) + 1
                    rejected_lines.append(f'- REJECT {source_name} @ {obj.name}: {overall_role} -> {role} [{conf}] • {guard_reason}')

        if not raw_accepted:
            continue

        if len(users) <= 1:
            unresolved_single_object += 1
            for obj_name, data in raw_accepted.items():
                role = data[0]
                rejected_specializations += 1
                rejected_role_counts[role] = rejected_role_counts.get(role, 0) + 1
                rejected_lines.append(f'- REJECT {source_name} @ {obj_name}: single-object mixed geometry; kept canonical {overall_role}')
            detail_lines.append(f'- {source_name}: mixed-role evidence inside one object; kept canonical {overall_role}')
            continue

        by_role = {}
        for obj_name, data in raw_accepted.items():
            by_role.setdefault(data[0], []).append(obj_name)
        blocked_objects = set()
        for role, obj_names in by_role.items():
            ratio = len(obj_names) / max(1, len(users))
            limit = _xdzr8_v11234_mass_limit_for_role(role)
            if len(users) >= 4 and ratio > limit:
                mass_guard_blocks += 1
                blocked_objects.update(obj_names)
                rejected_specializations += len(obj_names)
                rejected_role_counts[role] = rejected_role_counts.get(role, 0) + len(obj_names)
                rejected_lines.append(
                    f'- MASS GUARD {source_name}: rejected {len(obj_names)}/{len(users)} usages '
                    f'({ratio:.0%}) for {overall_role} -> {role}; limit={limit:.0%}. '
                    'Treat as canonical-classifier evidence, not object specialization.'
                )
        accepted = {name: data for name, data in raw_accepted.items() if name not in blocked_objects}
        if not accepted:
            continue

        role_set = {overall_role} | {data[0] for data in accepted.values()}
        if len(role_set) <= 1:
            continue

        source_had_specialization = False
        for obj in users:
            data = accepted.get(obj.name)
            if not data:
                continue
            role, why, conf, scores, guard_reason = data
            cache_key = (source_name, role)
            variant = variant_cache.get(cache_key)
            if variant is None:
                try:
                    variant, _images, _paths = _sabershader11_build_generic_material(
                        source_ref, role, texture_index, settings, source_intelligence, variant_key=role
                    )
                    variant['XDZR8_UsageRole'] = role
                    variant['XDZR8_UsageSource'] = source_name
                    variant['XDZR8_UsageReason'] = why
                    variant['XDZR8_UsageConfidence'] = conf
                    variant['XDZR8_UsageGuardrailEvidence'] = guard_reason
                    variant['XDZR8_ClassifierVersion'] = 'V11.7.1'
                    variant_cache[cache_key] = variant
                    created_variants += 1
                except Exception as exc:
                    rejected_specializations += 1
                    rejected_role_counts[role] = rejected_role_counts.get(role, 0) + 1
                    rejected_lines.append(f'- REJECT {source_name} / {obj.name}: variant build failed: {exc}')
                    continue
            specialized_by_obj_source[(obj.name, source_name)] = variant
            specialized_objects += 1
            source_had_specialization = True
            score_text = ', '.join(f'{r}={v:.1f}' for r, v in scores[:2])
            detail_lines.append(
                f'- ACCEPT {source_name} @ {obj.name}: {overall_role} -> {role} [{conf}] '
                f'({score_text}) • {guard_reason}'
            )
        if source_had_specialization:
            specialized_sources += 1

    report += ['', 'MIXED-ROLE MATERIAL USAGE SPECIALIZATION — GUARDED']
    report += detail_lines if detail_lines else ['- No safe object-level role splits were required.']
    report += ['', 'SPECIALIZATION SAFETY — REJECTED CANDIDATES']
    report += rejected_lines if rejected_lines else ['- No specialization candidates were rejected.']
    return {
        'assignments': specialized_by_obj_source,
        'variants': variant_cache,
        'specialized_sources': specialized_sources,
        'specialized_objects': specialized_objects,
        'created_variants': created_variants,
        'unresolved_single_object': unresolved_single_object,
        'raw_candidates': raw_candidates,
        'rejected_specializations': rejected_specializations,
        'rejected_role_counts': dict(sorted(rejected_role_counts.items())),
        'mass_guard_blocks': mass_guard_blocks,
    }

def _xdzr8_v11232_assign_generated(objects, replacements, canonical_by_source, specialized_by_obj_source):
    """Assign canonical or per-object role-specialized generated materials."""
    touched = 0
    for obj in (objects or []):
        changed = False
        for slot in getattr(obj, 'material_slots', []):
            current = slot.material
            if current is None:
                continue
            source_name = _xdzr8_v11232_source_name(current)
            target = specialized_by_obj_source.get((obj.name, source_name))
            if target is None:
                target = replacements.get(current) or canonical_by_source.get(source_name)
            if target is not None and slot.material != target:
                slot.material = target
                changed = True
        if changed:
            touched += 1
    return touched

def _xdzr8_v1171_component_stats(obj, poly_indices, character_context=None):
    data = getattr(obj, 'data', None)
    if data is None or not poly_indices:
        return None
    verts = getattr(data, 'vertices', None)
    polys = getattr(data, 'polygons', None)
    if verts is None or polys is None:
        return None
    vids = set()
    for pi in poly_indices:
        try:
            vids.update(int(v) for v in polys[int(pi)].vertices)
        except Exception:
            pass
    if not vids:
        return None
    points = []
    mw = obj.matrix_world
    for vid in vids:
        try:
            points.append(mw @ verts[vid].co)
        except Exception:
            pass
    if not points:
        return None
    lo = Vector((min(p.x for p in points), min(p.y for p in points), min(p.z for p in points)))
    hi = Vector((max(p.x for p in points), max(p.y for p in points), max(p.z for p in points)))
    center = (lo + hi) * 0.5
    span = hi - lo
    ctx = character_context or {}
    axis = int(ctx.get('axis', 2))
    cmin = ctx.get('min', lo); cmax = ctx.get('max', hi); ccenter = ctx.get('center', center)
    height = max(float(ctx.get('height', float(cmax[axis] - cmin[axis]))), 1e-6)
    lateral = [i for i in range(3) if i != axis] or [0, 1]
    ext = {i: max(abs(float(cmax[i] - cmin[i])), 1e-6) for i in lateral}
    width_axis = max(lateral, key=lambda i: ext[i])
    depth_axis = min(lateral, key=lambda i: ext[i])
    center_n = (float(center[axis]) - float(cmin[axis])) / height
    min_n = (float(lo[axis]) - float(cmin[axis])) / height
    max_n = (float(hi[axis]) - float(cmin[axis])) / height
    span_n = abs(float(span[axis])) / height
    width_center_n = abs(float(center[width_axis] - ccenter[width_axis])) / ext[width_axis]
    width_span_n = abs(float(span[width_axis])) / ext[width_axis]
    depth_center_n = abs(float(center[depth_axis] - ccenter[depth_axis])) / ext[depth_axis]
    depth_span_n = abs(float(span[depth_axis])) / ext[depth_axis]
    return {
        'polygons': len(poly_indices), 'vertices': len(vids), 'vertex_indices': vids,
        'center_n': float(center_n), 'min_n': float(min_n), 'max_n': float(max_n), 'span_n': float(span_n),
        'width_center_n': float(width_center_n), 'width_span_n': float(width_span_n),
        'depth_center_n': float(depth_center_n), 'depth_span_n': float(depth_span_n),
        'vertical_axis': axis, 'width_axis': width_axis, 'depth_axis': depth_axis,
    }

def _xdzr8_v1171_source_components(obj, source_name, character_context=None):
    """Connected polygon islands for one canonical source material.

    Connectivity uses shared mesh edges. Material slots generated by previous
    component-specialization runs still carry SaberShader_V11_SourceMaterial, so all of
    them collapse back into the same source identity on repeat runs.
    """
    data = getattr(obj, 'data', None)
    if data is None or getattr(obj, 'type', '') != 'MESH':
        return [], []
    source_slots = []
    for idx, slot in enumerate(getattr(obj, 'material_slots', [])):
        mat = getattr(slot, 'material', None)
        if mat is not None and _xdzr8_v11232_source_name(mat) == source_name:
            source_slots.append(int(idx))
    if not source_slots:
        return [], []
    source_set = set(source_slots)
    selected = [int(p.index) for p in data.polygons if int(p.material_index) in source_set]
    if not selected:
        return [], source_slots
    selected_set = set(selected)
    edge_to_polys = {}
    for pi in selected:
        poly = data.polygons[pi]
        vs = [int(v) for v in poly.vertices]
        for i, a in enumerate(vs):
            b = vs[(i + 1) % len(vs)]
            edge = (a, b) if a <= b else (b, a)
            edge_to_polys.setdefault(edge, []).append(pi)
    adjacency = {pi: set() for pi in selected}
    for linked in edge_to_polys.values():
        if len(linked) < 2:
            continue
        for pi in linked:
            adjacency[pi].update(pj for pj in linked if pj != pi and pj in selected_set)
    pending = set(selected)
    rows = []
    while pending:
        seed = pending.pop()
        stack = [seed]
        comp = [seed]
        while stack:
            pi = stack.pop()
            for other in adjacency.get(pi, ()):
                if other in pending:
                    pending.remove(other)
                    stack.append(other)
                    comp.append(other)
        stats = _xdzr8_v1171_component_stats(obj, comp, character_context)
        if stats:
            stats['polygon_indices'] = sorted(comp)
            rows.append(stats)
    rows.sort(key=lambda r: int(r.get('polygons', 0)), reverse=True)
    return rows, source_slots

def _xdzr8_v1171_choose_mixed_head_roles(components):
    """Classify only high-confidence Face/Hair islands in a mixed head atlas."""
    decisions = {}
    face_rows = []
    for idx, row in enumerate(components or []):
        p = int(row.get('polygons', 0))
        c = float(row.get('center_n', 0.0)); sp = float(row.get('span_n', 0.0))
        wc = float(row.get('width_center_n', 9.0)); ws = float(row.get('width_span_n', 0.0))
        ds = float(row.get('depth_span_n', 0.0))
        eligible = (
            p >= 60 and 0.72 <= c <= 0.98 and 0.035 <= sp <= 0.30 and
            wc <= 0.10 and 0.04 <= ws <= 0.45 and ds <= 0.60
        )
        if not eligible:
            continue
        score = 0.0
        score += min(6.5, float(p) / 150.0)
        score += max(0.0, 2.8 - abs(c - 0.89) * 12.0)
        score += max(0.0, 2.4 - wc * 22.0)
        score += max(0.0, 1.7 - abs(sp - 0.12) * 8.0)
        score += min(1.6, ws * 8.0)
        face_rows.append((score, p, idx))
    face_idx = max(face_rows, default=(0.0, 0, -1))[2]
    if face_idx >= 0:
        decisions[face_idx] = ('face', 'largest compact central upper-head surface')

    for idx, row in enumerate(components or []):
        if idx == face_idx:
            continue
        p = int(row.get('polygons', 0))
        c = float(row.get('center_n', 0.0)); mx = float(row.get('max_n', 0.0)); sp = float(row.get('span_n', 0.0))
        wc = float(row.get('width_center_n', 0.0)); ws = float(row.get('width_span_n', 0.0))
        ds = float(row.get('depth_span_n', 0.0))
        long_tail = p >= 70 and mx >= 0.88 and sp >= 0.30
        crown_mass = p >= 40 and c >= 0.84 and mx >= 0.88 and (sp >= 0.04 or wc >= 0.06 or ds >= 0.07)
        side_head = p >= 70 and c >= 0.78 and mx >= 0.86 and wc >= 0.05 and (ws >= 0.04 or ds >= 0.08)
        if long_tail:
            decisions[idx] = ('hair', 'long crown-reaching connected island')
        elif crown_mass or side_head:
            decisions[idx] = ('hair', 'substantial non-face upper-head island')
    return decisions

def _xdzr8_v1171_find_or_make_role_slot(obj, source_name, canonical_slot, variant, role, reserved_slots=None):
    reserved = set(int(i) for i in (reserved_slots or set()))

    for idx, slot in enumerate(getattr(obj, 'material_slots', [])):
        if int(idx) in reserved:
            continue
        mat = getattr(slot, 'material', None)
        if mat is None:
            continue
        try:
            is_component = bool(mat.get('XDZR8_V11_7_1_ComponentSpecialized', False))
            mat_role = str(mat.get('XDZR8_UsageRole', '') or mat.get('SaberShader_V11_Category', ''))
        except Exception:
            is_component = False; mat_role = ''
        if _xdzr8_v11232_source_name(mat) == source_name and is_component and mat_role == role:
            if slot.material != variant:
                slot.material = variant
            return int(idx)

    for idx, slot in enumerate(getattr(obj, 'material_slots', [])):
        if int(idx) == int(canonical_slot) or int(idx) in reserved:
            continue
        mat = getattr(slot, 'material', None)
        if mat is not None and _xdzr8_v11232_source_name(mat) == source_name:
            slot.material = variant
            return int(idx)
    try:
        obj.data.materials.append(variant)
        return len(obj.material_slots) - 1
    except Exception:
        return -1

def _xdzr8_v1176_isolate_face_component_shading(mat):
    """Flatten generic V11 toon banding on semantic face-component variants.

    V11 universal materials do NOT use the legacy ``SaberShader Anime Toon Mix`` node
    names. Their actual final chain is:

        Base Color / Diffuse -> SaberShader V11 • Base × Toon -> SaberShader V11 • NPR Emission

    V11.7.5 looked for the legacy names and therefore never touched Miku's
    universal face component (telemetry: componentFaceShadingIsolationFailed=1).

    This pass keeps the exact canonical clone, alpha routing, textures and UVs,
    but reconnects the V11 NPR Emission color DIRECTLY to the original base
    texture/fallback color for semantic Face components. Hair/body/cloth and the
    canonical mixed-atlas material remain untouched.
    """
    if mat is None or not bool(mat.get('XDZR8_V11_7_1_ComponentSpecialized', False)):
        return False, 'not a component variant'
    try:
        semantic_role = str(mat.get('XDZR8_UsageRole', '') or mat.get('XDZR8_V11_7_3_SemanticRole', '')).strip().lower()
    except Exception:
        semantic_role = ''
    if semantic_role != 'face':
        return False, 'semantic role is not face'
    nt = getattr(mat, 'node_tree', None)
    if nt is None:
        return False, 'material has no node tree'
    nodes = nt.nodes
    links = nt.links

    emit = nodes.get('SaberShader V11 • NPR Emission')
    base_tex = nodes.get('SaberShader V11 • Base Color / Diffuse')
    base_fallback = nodes.get('SaberShader V11 • Base Color Fallback')
    toon_mix = nodes.get('SaberShader V11 • Base × Toon')
    toon_ramp = nodes.get('SaberShader V11 • Toon Bands')
    if emit is None:
        return False, 'V11 NPR Emission node not found'

    source_socket = None
    source_desc = ''
    if base_tex is not None and getattr(base_tex, 'image', None) is not None and base_tex.outputs.get('Color'):
        source_socket = base_tex.outputs.get('Color')
        source_desc = f'Base Color / Diffuse ({base_tex.image.name})'
    elif base_fallback is not None and base_fallback.outputs:
        source_socket = base_fallback.outputs[0]
        source_desc = 'Base Color Fallback'
    if source_socket is None:
        return False, 'no V11 base color source found'

    color_input = emit.inputs.get('Color')
    if color_input is None:
        return False, 'V11 NPR Emission has no Color input'
    for link in list(color_input.links):
        links.remove(link)
    links.new(source_socket, color_input)

    if toon_mix is not None:
        toon_mix.label = 'BYPASSED on semantic Face • V11.7.6'
        try:
            toon_mix.mute = True
        except Exception:
            pass
    if toon_ramp is not None:
        toon_ramp.label = 'Face banding isolated • V11.7.6'

    mat['XDZR8_V11_7_6_FaceShadingIsolated'] = True
    mat['XDZR8_V11_7_6_FaceShadingIsolationSource'] = source_desc
    mat['XDZR8_V11_7_6_FaceShadingIsolationReason'] = 'V11 NPR emission receives base color directly; Base × Toon is bypassed'
    return True, f'V11 NPR emission <- {source_desc}; generic toon banding bypassed'

def _xdzr8_v1173_exact_canonical_component_clone(canonical, source_name, role, objects=None):
    """Create a component semantic variant as an exact copy of the canonical material.

    Unlike V11.7.2 this never calls the generic material builder. The canonical
    material has already passed texture resolution, alpha preservation and every
    visual configuration stage, so copying that datablock is the only reliable
    way to guarantee visual identity. Stale component variants are rebound to the
    canonical material before deletion so repeat runs do not leave invalid slots.
    """
    if canonical is None:
        raise RuntimeError('missing canonical material')
    role = str(role or 'cloth').strip().lower()
    internal_key = f"SaberShader_V11_{safe_name(str(source_name))}__ROLE_COMPONENT_{safe_name(role.upper())}"
    public_name = _sabershader_v1_public_material_name(role, semantic_role=role)
    old = _sabershader_v1_find_component_variant(internal_key, source_name, role)
    if old is canonical:
        old = None
    if old is not None:

        for obj in (objects or bpy.context.scene.objects):
            if getattr(obj, 'type', None) != 'MESH':
                continue
            for slot in getattr(obj, 'material_slots', []):
                try:
                    if slot.material == old:
                        slot.material = canonical
                except (ReferenceError, RuntimeError):
                    pass
        try:
            bpy.data.materials.remove(old, do_unlink=True)
        except (ReferenceError, RuntimeError):
            pass

    variant = canonical.copy()
    variant.name = public_name
    variant['SaberShader_V1_InternalMaterialKey'] = str(internal_key)
    variant['SaberShader_V1_PublicMaterialName'] = str(public_name)

    canonical_category = str(canonical.get('SaberShader_V11_Category', '') or 'cloth')
    variant['XDZR8_V11_7_3_CanonicalCategory'] = canonical_category
    variant['XDZR8_V11_7_3_SemanticRole'] = role
    variant['XDZR8_V11_7_3_ExactCanonicalClone'] = True
    variant['XDZR8_V11_7_3_VisualShaderPreserved'] = True
    variant['XDZR8_UsageRole'] = role
    variant['XDZR8_UsageSpecialized'] = True
    variant['XDZR8_UsageSource'] = str(source_name)
    variant['XDZR8_UsageReason'] = 'V11.7.3 exact canonical clone; semantic component role only'
    variant['XDZR8_UsageConfidence'] = 'HIGH'
    variant['XDZR8_ClassifierVersion'] = 'V11.9'

    variant['XDZR8_V11_7_1_ComponentSpecialized'] = True
    variant['XDZR8_V11_7_1_ComponentRole'] = role
    variant['XDZR8_V11_7_2_ComponentSemanticSpecialized'] = True
    variant['XDZR8_V11_7_3_ComponentSemanticSpecialized'] = True
    if role == 'face':
        ok, why = _xdzr8_v1176_isolate_face_component_shading(variant)
        variant['XDZR8_V11_7_6_FaceShadingIsolationApplied'] = bool(ok)
        variant['XDZR8_V11_7_6_FaceShadingIsolationWhy'] = str(why)
    return variant

def _xdzr8_v1171_component_local_specialization(objects, texture_index, settings, source_intelligence, canonical_by_source, report):
    """Safely split only high-confidence connected components of mixed atlases."""
    result = {
        'sources': 0, 'objects': 0, 'components': 0, 'polygons': 0,
        'face_components': 0, 'hair_components': 0, 'created_variants': 0,
        'semantic_variants': 0, 'visual_shader_preserved': 0, 'role_shader_rebuilds': 0,
        'exact_canonical_clones': 0, 'canonical_category_preserved': 0,
        'face_shading_isolated': 0, 'face_shading_isolation_failed': 0,
        'variants': {}, 'rows': [], 'skipped': [],
    }
    info = source_intelligence if isinstance(source_intelligence, dict) else {}
    local_audit = info.get('_v117_material_local_audit', {}) or {}
    if not local_audit:
        report += ['', 'V11.7.1 COMPONENT-LOCAL SPECIALIZATION', '- No V11.7 material-local audit was available.']
        return result
    try:
        character_context = info.get('character_geometry') or _xdzr8_v116_character_geometry(objects)
    except Exception:
        character_context = info.get('character_geometry') or {}

    touched_sources = set(); touched_objects = set(); variant_cache = {}
    for source_name, canonical in (canonical_by_source or {}).items():
        row = local_audit.get(source_name) or {}
        mixed = set(row.get('mixed_roles', []) or [])
        if not bool(row.get('primary_mode', False)) or not {'face', 'hair'}.issubset(mixed):
            continue
        source_ref = bpy.data.materials.get(source_name) or _sabershader111_resolve_original_source_material(canonical) or canonical
        try:
            canonical_role = str(canonical.get('SaberShader_V11_Category', '') or 'cloth')
        except Exception:
            canonical_role = 'cloth'
        for obj in (objects or []):
            components, source_slots = _xdzr8_v1171_source_components(obj, source_name, character_context)
            if len(components) < 2 or not source_slots:
                continue
            decisions = _xdzr8_v1171_choose_mixed_head_roles(components)
            if not decisions or 'face' not in {d[0] for d in decisions.values()}:
                result['skipped'].append(f'{source_name}@{obj.name}: no safe face/hair component split')
                continue

            canonical_slot = int(source_slots[0])
            for idx in source_slots:
                try:
                    if obj.material_slots[int(idx)].material == canonical:
                        canonical_slot = int(idx); break
                except Exception:
                    pass
            try:
                obj.material_slots[canonical_slot].material = canonical
            except Exception:
                pass
            source_slot_set = set(int(i) for i in source_slots)
            for poly in obj.data.polygons:
                if int(poly.material_index) in source_slot_set:
                    poly.material_index = canonical_slot

            role_slots = {canonical_role: canonical_slot}
            for role in sorted({d[0] for d in decisions.values()}):
                if role == canonical_role:
                    continue
                cache_key = (source_name, role)
                variant = variant_cache.get(cache_key)
                if variant is None:
                    try:

                        variant = _xdzr8_v1173_exact_canonical_component_clone(
                            canonical, source_name, role, objects=objects
                        )
                        variant_cache[cache_key] = variant
                        result['created_variants'] += 1
                        result['semantic_variants'] += 1
                        result['visual_shader_preserved'] += 1
                        result['exact_canonical_clones'] += 1
                        if str(variant.get('SaberShader_V11_Category', '')) == str(canonical.get('SaberShader_V11_Category', '')):
                            result['canonical_category_preserved'] += 1
                        if role == 'face':
                            if bool(variant.get('XDZR8_V11_7_6_FaceShadingIsolationApplied', False)):
                                result['face_shading_isolated'] += 1
                            else:
                                result['face_shading_isolation_failed'] += 1
                    except Exception as exc:
                        result['skipped'].append(f'{source_name}@{obj.name}: {role} exact-clone semantic variant failed: {exc}')
                        continue
                slot_idx = _xdzr8_v1171_find_or_make_role_slot(
                    obj, source_name, canonical_slot, variant, role, reserved_slots=set(role_slots.values())
                )
                if slot_idx >= 0:
                    role_slots[role] = slot_idx

            object_components = 0; object_polys = 0
            for comp_idx, (role, reason) in decisions.items():
                slot_idx = role_slots.get(role)
                if slot_idx is None:
                    continue
                comp = components[int(comp_idx)]
                changed = 0
                for pi in comp.get('polygon_indices', []):
                    try:
                        obj.data.polygons[int(pi)].material_index = int(slot_idx)
                        changed += 1
                    except Exception:
                        pass
                if changed <= 0:
                    continue
                object_components += 1; object_polys += changed
                result['components'] += 1; result['polygons'] += changed
                if role == 'face': result['face_components'] += 1
                if role == 'hair': result['hair_components'] += 1
                result['rows'].append(
                    f'{source_name} @ {obj.name}: component#{comp_idx} -> {role} polys={changed} '
                    f'z={comp.get("center_n",0.0):.3f} span={comp.get("span_n",0.0):.3f} '
                    f'wOff={comp.get("width_center_n",0.0):.3f} wSpan={comp.get("width_span_n",0.0):.3f} '
                    f'dSpan={comp.get("depth_span_n",0.0):.3f} visual={canonical_role} semantic={role} • {reason}'
                )
            if object_components:
                touched_sources.add(source_name); touched_objects.add(obj.name)
                try:
                    obj.data.update()
                except Exception:
                    pass
    result['sources'] = len(touched_sources)
    result['objects'] = len(touched_objects)
    result['variants'] = variant_cache
    try:
        info['_v1171_component_specialization'] = {
            'sources': result['sources'], 'objects': result['objects'], 'components': result['components'],
            'polygons': result['polygons'], 'face_components': result['face_components'],
            'hair_components': result['hair_components'], 'created_variants': result['created_variants'],
            'semantic_variants': result['semantic_variants'],
            'visual_shader_preserved': result['visual_shader_preserved'],
            'role_shader_rebuilds': result['role_shader_rebuilds'],
            'exact_canonical_clones': result['exact_canonical_clones'],
            'canonical_category_preserved': result['canonical_category_preserved'],
            'face_shading_isolated': result['face_shading_isolated'],
            'face_shading_isolation_failed': result['face_shading_isolation_failed'],
            'rows': list(result['rows']), 'skipped': list(result['skipped']),
        }
    except Exception:
        pass
    report += ['', 'V11.7.6 FACE FLAT SHADING + TOPOLOGY-LOCKED JAWLINE']
    report.append(f'- Mixed sources specialized: {result["sources"]}')
    report.append(f'- Objects specialized: {result["objects"]}')
    report.append(f'- Components specialized: {result["components"]} (face={result["face_components"]}, hair={result["hair_components"]})')
    report.append(f'- Polygons reassigned by connected component: {result["polygons"]}')
    report.append(f'- Component semantic variants created/rebuilt: {result["created_variants"]}')
    report.append(f'- Exact canonical clones: {result["exact_canonical_clones"]}; canonical category preserved: {result["canonical_category_preserved"]}')
    report.append(f'- Face-component shading isolation: isolated={result["face_shading_isolated"]}, failed={result["face_shading_isolation_failed"]}')
    report.append(f'- Visual shader preserved variants: {result["visual_shader_preserved"]}; target-role shader rebuilds: {result["role_shader_rebuilds"]}')
    report += [f'- {line}' for line in result['rows'][:80]] if result['rows'] else ['- No high-confidence mixed-atlas components required specialization.']
    if len(result['rows']) > 80:
        report.append('- ... additional component specialization rows omitted')
    if result['skipped']:
        report += ['', 'COMPONENT SPECIALIZATION — CONSERVATIVE SKIPS']
        report += [f'- {line}' for line in result['skipped'][:40]]
    return result

def _xdzr8_v11233_effective_role_audit(objects, canonical_by_source, specialization):
    """Audit final assigned roles without changing any material, object or shader.

    source_roles counts canonical generated materials by source-material role.
    effective_roles counts unique generated materials that are actually assigned
    after specialization. objects_by_effective_role counts unique character
    objects using each effective role; an object can legitimately appear under
    more than one role when it has multiple material slots.
    """
    source_roles = {}
    for source_name, mat in (canonical_by_source or {}).items():
        try:
            role = str(mat.get('SaberShader_V11_Category', '') or 'unknown')
        except Exception:
            role = 'unknown'
        source_roles[role] = source_roles.get(role, 0) + 1

    assigned_material_roles = {}
    role_objects = {}
    for obj in (objects or []):
        for slot in getattr(obj, 'material_slots', []):
            mat = getattr(slot, 'material', None)
            if mat is None:
                continue
            try:
                if not bool(mat.get('SaberShader_V11_Universal', False)):
                    continue
                role = str(mat.get('SaberShader_V11_Category', '') or 'unknown')
            except Exception:
                continue
            assigned_material_roles[mat.name] = role
            role_objects.setdefault(role, set()).add(obj.name)

    effective_roles = {}
    for role in assigned_material_roles.values():
        effective_roles[role] = effective_roles.get(role, 0) + 1

    specialized_roles = {}
    for (_source_name, role), mat in (specialization.get('variants', {}) or {}).items():
        try:
            resolved = str(mat.get('XDZR8_UsageRole', '') or mat.get('SaberShader_V11_Category', '') or role or 'unknown')
        except Exception:
            resolved = str(role or 'unknown')
        specialized_roles[resolved] = specialized_roles.get(resolved, 0) + 1

    transition_objects = {}
    for (obj_name, source_name), mat in (specialization.get('assignments', {}) or {}).items():
        try:
            role = str(mat.get('XDZR8_UsageRole', '') or mat.get('SaberShader_V11_Category', '') or 'unknown')
        except Exception:
            role = 'unknown'
        transition_objects.setdefault((source_name, role), set()).add(obj_name)

    transitions = []
    for (source_name, role), obj_names in sorted(transition_objects.items(), key=lambda item: (item[0][0].lower(), item[0][1])):
        canonical = canonical_by_source.get(source_name)
        try:
            canonical_role = str(canonical.get('SaberShader_V11_Category', '') or 'unknown') if canonical else 'unknown'
        except Exception:
            canonical_role = 'unknown'
        transitions.append({
            'source': source_name,
            'canonical_role': canonical_role,
            'specialized_role': role,
            'objects': len(obj_names),
            'object_names': sorted(obj_names),
        })

    return {
        'source_roles': dict(sorted(source_roles.items())),
        'effective_roles': dict(sorted(effective_roles.items())),
        'specialized_roles': dict(sorted(specialized_roles.items())),
        'objects_by_effective_role': {role: len(names) for role, names in sorted(role_objects.items())},
        'transitions': transitions,
        'processed_objects': len(objects or []),
    }

def _sabershader11_assign_generated(objects, replacements):
    touched = 0
    for obj in objects:
        changed = False
        for slot in obj.material_slots:
            src = slot.material
            if src in replacements:
                slot.material = replacements[src]
                changed = True
        if changed:
            touched += 1
    return touched

def _sabershader11_write_report(lines):
    text = bpy.data.texts.get(SABERSHADER11_REPORT_TEXT) or bpy.data.texts.new(SABERSHADER11_REPORT_TEXT)
    text.clear()
    text.write('\n'.join(lines) + '\n')
    return text.name

def _xdzr8_find_node(tree, names=(), labels=(), prefixes=(), bl_idname=None):
    for name in names:
        node = tree.nodes.get(name)
        if node is not None and (bl_idname is None or node.bl_idname == bl_idname):
            return node
    for node in tree.nodes:
        if bl_idname is not None and node.bl_idname != bl_idname:
            continue
        if labels and node.label in labels:
            return node
        if prefixes and any(node.name.startswith(p) for p in prefixes):
            return node
    return None

def _xdzr8_socket(node, names, is_output=False):
    if node is None:
        return None
    sockets = node.outputs if is_output else node.inputs
    for name in names:
        sock = sockets.get(name)
        if sock is not None:
            return sock
    return sockets[0] if len(sockets) else None

def _xdzr8_force_link(tree, from_node, out_names, to_node, in_names, label, problems):
    out_socket = _xdzr8_socket(from_node, out_names, is_output=True)
    in_socket = _xdzr8_socket(to_node, in_names, is_output=False)
    if from_node is None or to_node is None or out_socket is None or in_socket is None:
        problems.append(label)
        return False
    for link in list(in_socket.links):
        tree.links.remove(link)
    try:
        tree.links.new(out_socket, in_socket)
    except Exception:
        problems.append(label)
        return False
    ok = bool(in_socket.is_linked and any(l.from_socket == out_socket for l in in_socket.links))
    if not ok:
        problems.append(label)
    return ok

def _xdzr8_repair_universal_compositor_wiring(settings):
    scene = bpy.context.scene
    tree = _sabershader10_tree(scene)
    nodes = tree.nodes
    problems = []
    wired = 0

    render_layers = _xdzr8_find_node(tree, names=('Render Layers',), bl_idname='CompositorNodeRLayers')
    exposure = _xdzr8_find_node(tree, names=(SABERSHADER10_PREFIX + 'Exposure',), labels=('V10 • Exposure (UNIVERSAL)',))
    base_contrast = _xdzr8_find_node(tree, names=(SABERSHADER10_PREFIX + 'Contrast',), labels=('V10 • Graphic contrast',))
    saturation = _xdzr8_find_node(tree, names=(SABERSHADER10_PREFIX + 'Saturation',), labels=('V10 • Saturation',))
    final_glow = _xdzr8_find_node(tree, names=(SABERSHADER10_PREFIX + 'Final Glow',), labels=('V10 • Selective Glow',))
    v10_mask = _xdzr8_find_node(tree, names=(SABERSHADER10_PREFIX + 'Vignette Mask',), labels=('V10 • Soft vignette mask',))
    v10_blur = _xdzr8_find_node(tree, names=(SABERSHADER10_PREFIX + 'Vignette Blur',), labels=('V10 • Vignette feather',))
    v10_mix = _xdzr8_find_node(tree, names=(SABERSHADER10_PREFIX + 'Vignette Mix',), labels=('V10 • Final vignette',))

    black = _xdzr8_find_node(tree, names=(SABERSHADER109C2_PREFIX + 'Black Roll-Off',), labels=('V10.9C2.1 • Black roll-off / midtone easing',))
    diff_blur = _xdzr8_find_node(tree, labels=('V10.9C2.4 • Short highlight diffusion',), prefixes=(SABERSHADER109C2_PREFIX + 'Highlight Diffusion B',))
    diff_mix = _xdzr8_find_node(tree, labels=('V10.9C2.4 • Line-preserving diffusion',), prefixes=(SABERSHADER109C2_PREFIX + 'Highlight Diffusion M',))
    series_contrast = _xdzr8_find_node(tree, names=(SABERSHADER109C2_PREFIX + 'Series Contrast',), labels=('V10.9C2.4 • Series contrast micro-tune',))
    chroma = _xdzr8_find_node(tree, names=(SABERSHADER109C2_PREFIX + 'Chroma Cohesion',), labels=('V10.9C2 • Chroma cohesion',))
    halation = _xdzr8_find_node(tree, names=(SABERSHADER109C2_PREFIX + 'Halation',), labels=('V10.9C2.4 • Fog Glow halation',))
    halation_mix = _xdzr8_find_node(tree, names=(SABERSHADER109C2_PREFIX + 'Halation Mix',), labels=('V10.9C2.4 • Restrained halation blend',))
    c2_mask = _xdzr8_find_node(tree, names=(SABERSHADER109C2_PREFIX + 'Vignette Mask',), labels=('V10.9C2 • Vignette mask',))
    c2_blur = _xdzr8_find_node(tree, names=(SABERSHADER109C2_PREFIX + 'Vignette Blur',), labels=('V10.9C2 • Vignette feather',))
    c2_mix = _xdzr8_find_node(tree, names=(SABERSHADER109C2_PREFIX + 'Vignette Mix',), labels=('V10.9C2 • Final series vignette',))
    sink = _xdzr8_find_node(tree, names=(SABERSHADER109C22_PREFIX + 'MASTER FINAL SINK',), labels=('XDZR8 Sabershader • MASTER FINAL SINK', 'V10.9C2.2 • MASTER FINAL SINK'))
    viewer = _xdzr8_find_node(tree, names=(SABERSHADER109C22_PREFIX + 'FINAL VIEWER', 'Viewer'), bl_idname='CompositorNodeViewer')

    group_out = _sabershader109c22_active_group_output(tree)
    for node in list(nodes):
        if node == group_out or node.bl_idname != 'NodeGroupOutput':
            continue
        if node.name.startswith(SABERSHADER109C2_PREFIX):
            nodes.remove(node)

    chain = [
        (render_layers, ('Image',), exposure, ('Image',), 'Render Layers -> Exposure'),
        (exposure, ('Image',), base_contrast, ('Image',), 'Exposure -> Contrast'),
        (base_contrast, ('Image',), saturation, ('Image',), 'Contrast -> Saturation'),
        (saturation, ('Image',), final_glow, ('Image',), 'Saturation -> Final Glow'),
        (v10_mask, ('Mask',), v10_blur, ('Image',), 'V10 Vignette Mask -> Blur'),
        (final_glow, ('Image',), v10_mix, ('Color1',), 'Final Glow -> V10 Vignette'),
        (v10_blur, ('Image',), v10_mix, ('Fac',), 'V10 Vignette Blur -> Fac'),
        (v10_mix, ('Color',), black, ('Image',), 'V10 Vignette -> Black Roll-Off'),
        (black, ('Image',), diff_blur, ('Image',), 'Black Roll-Off -> Diffusion Blur'),
        (black, ('Image',), diff_mix, ('Color1',), 'Black Roll-Off -> Diffusion Base'),
        (diff_blur, ('Image',), diff_mix, ('Color2',), 'Diffusion Blur -> Diffusion Mix'),
        (diff_mix, ('Color',), series_contrast, ('Image',), 'Diffusion Mix -> Series Contrast'),
        (series_contrast, ('Image',), chroma, ('Image',), 'Series Contrast -> Chroma'),
        (chroma, ('Image',), halation, ('Image',), 'Chroma -> Halation'),
        (chroma, ('Image',), halation_mix, ('Color1',), 'Chroma -> Halation Base'),
        (halation, ('Image',), halation_mix, ('Color2',), 'Halation -> Halation Mix'),
        (c2_mask, ('Mask',), c2_blur, ('Image',), 'C2 Vignette Mask -> Blur'),
        (halation_mix, ('Color',), c2_mix, ('Color1',), 'Halation Mix -> C2 Vignette'),
        (c2_blur, ('Image',), c2_mix, ('Fac',), 'C2 Vignette Blur -> Fac'),
        (c2_mix, ('Color',), sink, ('Input',), 'C2 Vignette -> MASTER FINAL SINK'),
        (sink, ('Output',), group_out, ('Image',), 'MASTER FINAL SINK -> Render Output'),
        (sink, ('Output',), viewer, ('Image',), 'MASTER FINAL SINK -> Viewer'),
    ]
    for spec in chain:
        wired += int(_xdzr8_force_link(tree, *spec, problems))

    expected = len(chain)
    ok = wired == expected and not problems
    scene['XDZR8_UniversalCompositorWiringOK'] = bool(ok)
    scene['XDZR8_UniversalCompositorWiredLinks'] = int(wired)
    scene['XDZR8_UniversalCompositorExpectedLinks'] = int(expected)
    scene['XDZR8_UniversalCompositorWiringProblems'] = ' | '.join(problems)
    scene['XDZR8_UniversalCompositorWorkflow'] = 'Render Layers -> V10 Shot Composer -> C2 Final Grade -> MASTER FINAL SINK -> Render Output + Viewer'
    scene.render.use_compositing = True
    return {'ok': bool(ok), 'wired': int(wired), 'expected': int(expected), 'problems': list(problems)}

def _xdzr8_build_universal_compositor(settings):
    scene = bpy.context.scene
    if not bool(getattr(settings, 'universal_build_compositor', True)):
        scene['XDZR8_UniversalCompositor'] = False
        return {'built': 0, 'base': 0, 'grade': 0, 'routing': 0, 'source': 'disabled', 'wiring_ok': False, 'wired': 0, 'expected': 0, 'problems': []}

    try:
        settings.shot_profile = 'UNIVERSAL'
    except Exception:
        pass
    try:
        settings.final_exposure = 0.0
        settings.final_contrast = 0.040
        settings.final_saturation = 0.980
        settings.final_bloom_strength = 0.080
        settings.final_bloom_threshold = 1.25
        settings.final_vignette = 0.060
        settings.final_depth_grade = False
        settings.auto_tune_final_anime_composite_v109c2 = True
        settings.build_final_anime_composite_v109c2 = True
        settings.build_series_grade_micro_tune_v109c24 = True
        settings.series_grade_micro_tune_strength_v109c24 = 1.0
        settings.build_final_output_routing_v109c22 = True
        settings.mirror_final_to_viewer_v109c22 = True
        settings.quarantine_legacy_viewer_link_v109c22 = True
    except Exception:
        pass

    base = build_v10_shot_composer(settings)
    grade = build_v109c2_final_anime_composite(settings)
    routing = build_v109c22_final_output_routing(settings)
    wiring = _xdzr8_repair_universal_compositor_wiring(settings)

    tree = _sabershader10_tree(scene)
    try:
        tree.name = f'XDZR8 Sabershader • Compositor • {scene.name}'
    except Exception:
        pass
    sink = tree.nodes.get(SABERSHADER109C22_PREFIX + 'MASTER FINAL SINK')
    if sink:
        sink.label = 'XDZR8 Sabershader • MASTER FINAL SINK'
    group_out = (tree.nodes.get('SaberShader V9.1 • Shoot • Group Output')
                 or tree.nodes.get(SABERSHADER10_PREFIX + 'Group Output')
                 or tree.nodes.get('Group Output'))
    if group_out is None:
        group_out = next((n for n in tree.nodes if n.bl_idname == 'NodeGroupOutput'), None)
    if group_out:
        group_out.label = 'XDZR8 Sabershader • MASTER RENDER OUTPUT'
    viewer = tree.nodes.get(SABERSHADER109C22_PREFIX + 'FINAL VIEWER') or tree.nodes.get('Viewer')
    if viewer:
        viewer.label = 'XDZR8 Sabershader • FINAL VIEWER'

    scene.render.use_compositing = True
    scene['XDZR8_UniversalCompositor'] = bool(base and grade and routing.get('built') and wiring.get('ok'))
    scene['XDZR8_UniversalCompositorProfile'] = 'UNIVERSAL'
    scene['XDZR8_UniversalCompositorTree'] = tree.name
    scene['XDZR8_UniversalCompositorBase'] = int(base)
    scene['XDZR8_UniversalCompositorGrade'] = int(grade)
    scene['XDZR8_UniversalCompositorRouting'] = int(routing.get('built', 0))
    scene['XDZR8_UniversalCompositorSource'] = str(routing.get('source', 'none'))
    scene['XDZR8_UniversalCompositorWiringOK'] = bool(wiring.get('ok'))
    scene['XDZR8_UniversalCompositorWiredLinks'] = int(wiring.get('wired', 0))
    scene['XDZR8_UniversalCompositorExpectedLinks'] = int(wiring.get('expected', 0))
    return {
        'built': int(bool(base and grade and routing.get('built') and wiring.get('ok'))),
        'base': int(base),
        'grade': int(grade),
        'routing': int(routing.get('built', 0)),
        'source': str(routing.get('source', 'none')),
        'wiring_ok': bool(wiring.get('ok')),
        'wired': int(wiring.get('wired', 0)),
        'expected': int(wiring.get('expected', 0)),
        'problems': list(wiring.get('problems', [])),
    }

