def _xdzr8_v116_cleanup():
    removed = 0
    for obj in list(bpy.data.objects):
        try:
            generated = bool(obj.get('XDZR8_V11_6_AdaptiveOutline', False)) or obj.name.startswith(XDZR8_V116_OUTLINE_OBJECT_PREFIX)
        except Exception:
            generated = False
        if generated:
            try:
                bpy.data.objects.remove(obj, do_unlink=True)
                removed += 1
            except Exception:
                pass
    col = bpy.data.collections.get(XDZR8_V116_OUTLINE_COLLECTION)
    if col is not None:
        try:
            bpy.data.collections.remove(col)
        except Exception:
            pass
    return removed

def _xdzr8_v116_collection():
    col = bpy.data.collections.get(XDZR8_V116_OUTLINE_COLLECTION)
    if col is None:
        col = bpy.data.collections.new(XDZR8_V116_OUTLINE_COLLECTION)
        bpy.context.scene.collection.children.link(col)
    col['XDZR8_V11_6_AdaptiveOutline'] = True
    return col

def _xdzr8_v116_character_bounds(objects):
    points = []
    for obj in objects or []:
        if not obj or getattr(obj, 'type', None) != 'MESH':
            continue
        try:
            points.extend(obj.matrix_world @ Vector(corner) for corner in obj.bound_box)
        except Exception:
            pass
    if not points:
        return None
    mn = Vector((min(p.x for p in points), min(p.y for p in points), min(p.z for p in points)))
    mx = Vector((max(p.x for p in points), max(p.y for p in points), max(p.z for p in points)))
    size = mx - mn
    height = max(abs(size.z), abs(size.y), abs(size.x), 1e-6)

    zheight = abs(size.z)
    if zheight >= height * 0.42:
        height = zheight
    pad = max(height * 0.035, 1e-6)
    return {'min': mn - Vector((pad, pad, pad)), 'max': mx + Vector((pad, pad, pad)), 'height': float(height), 'size': size}

def _xdzr8_v116_camera_factor(objects, height, settings):
    if not bool(getattr(settings, 'universal_outline_camera_adapt', True)):
        return 1.0
    cam = getattr(bpy.context.scene, 'camera', None)
    if cam is None or height <= 1e-9:
        return 1.0
    try:
        if getattr(cam.data, 'type', '') == 'ORTHO':
            return 1.0
    except Exception:
        pass
    centers = []
    for obj in objects or []:
        try:
            centers.append(obj.matrix_world.translation.copy())
        except Exception:
            pass
    if not centers:
        return 1.0
    center = sum(centers, Vector((0.0, 0.0, 0.0))) / len(centers)
    try:
        dist = (cam.matrix_world.translation - center).length
    except Exception:
        return 1.0
    ratio = dist / max(height, 1e-6)
    return max(0.88, min(1.18, 0.86 + ratio * 0.055))

def _xdzr8_v116_object_text(obj, include_vgroups=True):

    chunks = []
    if obj is not None and include_vgroups:
        try:
            chunks.extend(vg.name for vg in list(getattr(obj, 'vertex_groups', []))[:256])
        except Exception:
            pass
    return ' '.join(str(c) for c in chunks if c)

def _xdzr8_v116_token_hits(text, tokens):
    return [tok for tok in (tokens or ()) if _xdzr8_v112_text_has_token(text, tok)]

def _xdzr8_v116_character_geometry(objects):
    bounds = _xdzr8_v116_character_bounds(objects)
    if not bounds:
        return None
    size = bounds.get('size') or Vector((1.0, 1.0, 1.0))
    extents = [abs(float(size.x)), abs(float(size.y)), abs(float(size.z))]
    axis = max(range(3), key=lambda i: extents[i])
    if extents[2] >= max(extents) * 0.42:
        axis = 2
    mn = bounds['min']
    mx = bounds['max']
    height = max(float(mx[axis] - mn[axis]), 1e-6)
    lateral_axes = [i for i in range(3) if i != axis]
    lateral_extent = max(max(abs(float(size[i])) for i in lateral_axes), 1e-6) if lateral_axes else 1e-6
    return {
        'bounds': bounds,
        'axis': axis,
        'min': mn,
        'max': mx,
        'height': height,
        'center': (mn + mx) * 0.5,
        'lateral_extent': lateral_extent,
        'head_start_n': 0.58,
        'eye_band_min_n': 0.68,
        'eye_band_max_n': 0.95,
        'face_band_min_n': 0.54,
        'face_band_max_n': 0.90,
    }

def _xdzr8_v116_object_role_hints(obj, character_context=None):
    result = {
        'scores': {'hair': 0.0, 'face': 0.0, 'eyes': 0.0, 'eyes5': 0.0, 'mouth': 0.0},
        'evidence': {'hair': [], 'face': [], 'eyes': [], 'eyes5': [], 'mouth': []},
        'head_zone': False, 'eye_zone': False, 'front_fringe': False,
        'center_n': 0.0, 'span_n': 0.0, 'lateral_n': 1.0,
    }
    if obj is None:
        return result

    text = _xdzr8_v116_object_text(obj, include_vgroups=True)
    hair_hits = _xdzr8_v116_token_hits(text, XDZR8_V112_ROLE_TOKENS.get('hair', ()))
    face_hits = _xdzr8_v116_token_hits(text, XDZR8_V112_ROLE_TOKENS.get('face', ()))
    eye_hits = _xdzr8_v116_token_hits(text, XDZR8_V112_ROLE_TOKENS.get('eyes', ()))
    eye5_hits = _xdzr8_v116_token_hits(text, XDZR8_V112_ROLE_TOKENS.get('eyes5', ()))
    mouth_hits = _xdzr8_v116_token_hits(text, XDZR8_V112_ROLE_TOKENS.get('mouth', ()))
    cloth_hits = _xdzr8_v116_token_hits(text, XDZR8_V112_ROLE_TOKENS.get('cloth', ()))
    body_hits = _xdzr8_v116_token_hits(text, XDZR8_V112_ROLE_TOKENS.get('body', ()))

    if hair_hits:
        value = 4.8 + min(1.2, max(0, len(hair_hits) - 1) * 0.35)
        result['scores']['hair'] += value
        result['evidence']['hair'].append('tokens ' + '/'.join(hair_hits[:4]))
    if face_hits:
        value = 4.6 + min(0.8, max(0, len(face_hits) - 1) * 0.30)
        result['scores']['face'] += value
        result['evidence']['face'].append('tokens ' + '/'.join(face_hits[:4]))
    if eye_hits:
        value = 5.2 + min(0.8, max(0, len(eye_hits) - 1) * 0.30)
        result['scores']['eyes'] += value
        result['evidence']['eyes'].append('tokens ' + '/'.join(eye_hits[:4]))
    if eye5_hits:
        value = 4.8 + min(0.8, max(0, len(eye5_hits) - 1) * 0.30)
        result['scores']['eyes5'] += value
        result['evidence']['eyes5'].append('tokens ' + '/'.join(eye5_hits[:4]))
    if mouth_hits:
        value = 4.2 + min(0.6, max(0, len(mouth_hits) - 1) * 0.30)
        result['scores']['mouth'] += value
        result['evidence']['mouth'].append('tokens ' + '/'.join(mouth_hits[:4]))

    if character_context:
        try:
            axis = int(character_context['axis'])
            mn = character_context['min']
            mx = character_context['max']
            center, _diag = _sabershader111_world_bounds(obj)
            pts = [obj.matrix_world @ Vector(corner) for corner in obj.bound_box]
            lo = [min(p[i] for p in pts) for i in range(3)]
            hi = [max(p[i] for p in pts) for i in range(3)]
            height = max(float(character_context['height']), 1e-6)
            center_n = max(0.0, min(1.0, (float(center[axis]) - float(mn[axis])) / height))
            span_n = max(0.0, min(1.0, (float(hi[axis]) - float(lo[axis])) / height))
            lateral_axes = [i for i in range(3) if i != axis]
            lat_dist = math.sqrt(sum((float(center[i]) - float(character_context['center'][i])) ** 2 for i in lateral_axes))
            lateral_n = lat_dist / max(float(character_context.get('lateral_extent', 1.0)), 1e-6)
            result['center_n'] = center_n
            result['span_n'] = span_n
            result['lateral_n'] = lateral_n
            head_zone = max(float(hi[axis]), float(center[axis])) >= (float(mn[axis]) + height * float(character_context.get('head_start_n', 0.58)))
            eye_zone = (
                float(character_context.get('eye_band_min_n', 0.68)) <= center_n <= float(character_context.get('eye_band_max_n', 0.95))
                and span_n <= 0.22 and lateral_n <= 0.34
            )
            result['head_zone'] = bool(head_zone)
            result['eye_zone'] = bool(eye_zone)

            if head_zone:
                result['scores']['face'] += 0.9
                result['evidence']['face'].append('head zone')
                if not cloth_hits and not body_hits and center_n >= 0.66 and span_n <= 0.62:
                    result['scores']['hair'] += 1.8
                    result['evidence']['hair'].append('upper head geometry')
                if 0.56 <= center_n <= 0.90 and span_n <= 0.42 and lateral_n <= 0.34:
                    result['scores']['face'] += 1.2
                    result['evidence']['face'].append('central head surface')
                if 0.58 <= center_n <= 0.84 and span_n <= 0.16 and lateral_n <= 0.18:
                    result['scores']['mouth'] += 1.2
                    result['evidence']['mouth'].append('small central head detail')
            if eye_zone:
                result['scores']['eyes'] += 1.9
                result['scores']['eyes5'] += 1.1
                result['evidence']['eyes'].append('eye band geometry')
                result['evidence']['eyes5'].append('eye band geometry')
            front_fringe = bool(head_zone and center_n >= 0.70 and center_n <= 0.97 and span_n >= 0.08 and span_n <= 0.46 and lateral_n <= 0.26 and result['scores']['hair'] >= 2.5)
            result['front_fringe'] = front_fringe
            if front_fringe:
                result['scores']['hair'] += 0.8
                result['evidence']['hair'].append('front fringe guard band')
        except Exception:
            pass
    return result

def _xdzr8_v116_apply_head_intelligence(scores, evidence, objects, source_intelligence=None):
    info = source_intelligence or {}
    if not bool(info.get('enable_face_hair_intelligence', True)):
        return {}
    character_context = info.get('character_geometry') or _xdzr8_v116_character_geometry(objects)
    best = {}
    counts = {}
    for obj in (objects or []):
        hint = _xdzr8_v116_object_role_hints(obj, character_context)
        for role, value in (hint.get('scores') or {}).items():
            value = float(value or 0.0)
            if value <= 0.0:
                continue
            counts[role] = counts.get(role, 0) + 1
            current = best.get(role)
            if current is None or value > current['value']:
                reason = '; '.join((hint.get('evidence') or {}).get(role, [])[:2]) or 'geometry intelligence'
                best[role] = {'value': value, 'object': getattr(obj, 'name', 'Object'), 'reason': reason}
    for role, row in best.items():
        bonus = min(1.0, max(0, counts.get(role, 1) - 1) * 0.20)
        total = float(row['value']) + bonus
        scores[role] = scores.get(role, 0.0) + total
        evidence.setdefault(role, []).append(f'V11.6 {row["object"]}: {row["reason"]} +{total:.1f}')
    return {'best': best, 'counts': counts, 'character_context': character_context}

def _xdzr8_v116_effective_role(mat):
    if mat is None:
        return 'cloth'
    try:
        role = str(mat.get('XDZR8_UsageRole', '') or mat.get('SaberShader_V11_Category', '') or '').strip().lower()
    except Exception:
        role = ''
    return role if role in XDZR8_V116_ROLE_MULTIPLIER else 'cloth'

def _xdzr8_v116_refined_outline_role(obj, mat, character_context=None, settings=None):
    role = _xdzr8_v116_effective_role(mat)
    if role in {'hair', 'face', 'eyes', 'eyes5', 'mouth'}:
        return role
    if settings is not None and not bool(getattr(settings, 'universal_face_hair_intelligence', True)):
        return role
    hint = _xdzr8_v116_object_role_hints(obj, character_context)
    for target, threshold in (('eyes', 4.8), ('eyes5', 4.3), ('hair', 4.0), ('face', 3.8), ('mouth', 3.7)):
        if float((hint.get('scores') or {}).get(target, 0.0)) >= threshold:
            if role == 'transparent_cloth' and target in {'eyes', 'eyes5', 'mouth'}:
                continue
            return target
    return role

def _xdzr8_v116_outline_role_trim(obj, role, character_context=None, settings=None):
    if settings is not None and not bool(getattr(settings, 'universal_head_outline_guard', True)):
        return 1.0, 'guard disabled'
    hint = _xdzr8_v116_object_role_hints(obj, character_context)
    if role == 'hair' and hint.get('front_fringe'):
        return 0.46, 'front fringe guard'
    if role == 'hair' and hint.get('head_zone'):
        return 0.62, 'head hair trim'
    if role == 'face' and hint.get('head_zone'):
        return 0.78, 'face trim'
    if role == 'eyes5' and hint.get('eye_zone'):
        return 0.56, 'eye detail trim'
    if role == 'mouth' and hint.get('head_zone'):
        return 0.64, 'mouth detail trim'
    return 1.0, 'no trim'

def _xdzr8_v1161_object_bounds(obj):
    if obj is None:
        return None
    try:
        pts = [obj.matrix_world @ Vector(corner) for corner in obj.bound_box]
        if not pts:
            return None
        lo = Vector((min(p.x for p in pts), min(p.y for p in pts), min(p.z for p in pts)))
        hi = Vector((max(p.x for p in pts), max(p.y for p in pts), max(p.z for p in pts)))
        center = (lo + hi) * 0.5
        diag = max((hi - lo).length, 1e-6)
        return {'min': lo, 'max': hi, 'center': center, 'diag': diag}
    except Exception:
        center, diag = _sabershader111_world_bounds(obj)
        half = max(float(diag) * 0.25, 1e-5)
        vec = Vector((half, half, half))
        return {'min': center - vec, 'max': center + vec, 'center': center, 'diag': max(float(diag), 1e-6)}

def _xdzr8_v1161_bounds_intersect(a, b, margin=0.0):
    if not a or not b:
        return False
    try:
        alo, ahi = a['min'], a['max']
        blo, bhi = b['min'], b['max']
        m = float(margin or 0.0)
        return not (
            ahi.x < blo.x - m or alo.x > bhi.x + m or
            ahi.y < blo.y - m or alo.y > bhi.y + m or
            ahi.z < blo.z - m or alo.z > bhi.z + m
        )
    except Exception:
        return False

def _xdzr8_v1161_build_face_window(objects, character_context=None, settings=None):
    if settings is not None and not bool(getattr(settings, 'universal_head_outline_guard', True)):
        return None
    boxes = []
    counts = {'face': 0, 'eyes': 0, 'mouth': 0}
    for obj in (objects or []):
        if not obj or getattr(obj, 'type', None) != 'MESH':
            continue
        hint = _xdzr8_v116_object_role_hints(obj, character_context)
        scores = hint.get('scores') or {}
        face_like = float(scores.get('face', 0.0)) >= 3.8
        eye_like = max(float(scores.get('eyes', 0.0)), float(scores.get('eyes5', 0.0))) >= 4.2
        mouth_like = float(scores.get('mouth', 0.0)) >= 3.4
        if not (face_like or eye_like or mouth_like):
            continue
        bounds = _xdzr8_v1161_object_bounds(obj)
        if not bounds:
            continue
        boxes.append(bounds)
        if face_like:
            counts['face'] += 1
        if eye_like:
            counts['eyes'] += 1
        if mouth_like:
            counts['mouth'] += 1
    if not boxes:
        return None
    lo = Vector((min(b['min'].x for b in boxes), min(b['min'].y for b in boxes), min(b['min'].z for b in boxes)))
    hi = Vector((max(b['max'].x for b in boxes), max(b['max'].y for b in boxes), max(b['max'].z for b in boxes)))
    ref_diag = max((hi - lo).length, 1e-6)
    ref_height = max(float((character_context or {}).get('height', 0.0)), ref_diag, 1e-6)
    pad = max(ref_height * 0.010, ref_diag * 0.060)
    vec = Vector((pad, pad, pad))
    lo -= vec
    hi += vec
    return {'min': lo, 'max': hi, 'center': (lo + hi) * 0.5, 'diag': max((hi - lo).length, 1e-6), 'counts': counts, 'sources': len(boxes)}

def _xdzr8_v1161_should_suppress_hair_shell(obj, role, character_context=None, face_window=None, settings=None):
    if role != 'hair':
        return False, 'non-hair role'
    if settings is not None and not bool(getattr(settings, 'universal_head_outline_guard', True)):
        return False, 'guard disabled'
    if not face_window:
        return False, 'face window unavailable'
    hint = _xdzr8_v116_object_role_hints(obj, character_context)
    if not bool(hint.get('front_fringe')):
        return False, 'not front fringe'
    obj_bounds = _xdzr8_v1161_object_bounds(obj)
    if not obj_bounds:
        return False, 'object bounds unavailable'
    ref_height = max(float((character_context or {}).get('height', 0.0)), 1e-6)
    margin = max(ref_height * 0.008, float(face_window.get('diag', 1.0)) * 0.015)
    if _xdzr8_v1161_bounds_intersect(obj_bounds, face_window, margin=margin):
        return True, 'front fringe face-window suppression'
    if bool(hint.get('eye_zone')) and float(hint.get('lateral_n', 1.0)) <= 0.22:
        return True, 'front fringe eye-zone suppression'
    return False, 'front fringe clear of face window'

def _xdzr8_v1163_bounds_inside_inner(inner, outer, margin=0.0):
    if not inner or not outer:
        return False
    try:
        m = float(margin or 0.0)
        return (
            inner['min'].x >= outer['min'].x + m and inner['max'].x <= outer['max'].x - m and
            inner['min'].y >= outer['min'].y + m and inner['max'].y <= outer['max'].y - m and
            inner['min'].z >= outer['min'].z + m and inner['max'].z <= outer['max'].z - m
        )
    except Exception:
        return False

def _xdzr8_v1163_build_head_hair_window(objects, character_context=None, settings=None):
    if settings is not None and not bool(getattr(settings, 'universal_head_outline_guard', True)):
        return None
    boxes = []
    counts = {'hair': 0, 'face': 0, 'eyes': 0, 'mouth': 0}
    for obj in (objects or []):
        if not obj or getattr(obj, 'type', None) != 'MESH':
            continue
        hint = _xdzr8_v116_object_role_hints(obj, character_context)
        scores = hint.get('scores') or {}
        if not bool(hint.get('head_zone')):
            continue
        center_n = float(hint.get('center_n', 0.0))
        span_n = float(hint.get('span_n', 1.0))
        lateral_n = float(hint.get('lateral_n', 1.0))
        face_like = float(scores.get('face', 0.0)) >= 3.6
        eye_like = max(float(scores.get('eyes', 0.0)), float(scores.get('eyes5', 0.0))) >= 4.0
        mouth_like = float(scores.get('mouth', 0.0)) >= 3.2
        hair_like = float(scores.get('hair', 0.0)) >= 3.0
        include = False
        if face_like or eye_like or mouth_like:
            if center_n >= 0.56 and center_n <= 0.96 and span_n <= 0.46 and lateral_n <= 0.34:
                include = True
        elif hair_like:
            if center_n >= 0.64 and center_n <= 0.97 and span_n <= 0.40 and lateral_n <= 0.42:
                include = True
        if not include:
            continue
        bounds = _xdzr8_v1161_object_bounds(obj)
        if not bounds:
            continue
        boxes.append(bounds)
        if hair_like:
            counts['hair'] += 1
        if face_like:
            counts['face'] += 1
        if eye_like:
            counts['eyes'] += 1
        if mouth_like:
            counts['mouth'] += 1
    if not boxes:
        return None
    lo = Vector((min(b['min'].x for b in boxes), min(b['min'].y for b in boxes), min(b['min'].z for b in boxes)))
    hi = Vector((max(b['max'].x for b in boxes), max(b['max'].y for b in boxes), max(b['max'].z for b in boxes)))
    ref_diag = max((hi - lo).length, 1e-6)
    ref_height = max(float((character_context or {}).get('height', 0.0)), ref_diag, 1e-6)
    pad = max(ref_height * 0.008, ref_diag * 0.030)
    vec = Vector((pad, pad, pad))
    lo -= vec
    hi += vec
    return {'min': lo, 'max': hi, 'center': (lo + hi) * 0.5, 'diag': max((hi - lo).length, 1e-6), 'counts': counts, 'sources': len(boxes)}

def _xdzr8_v1163_should_suppress_hair_shell(obj, role, character_context=None, face_window=None, head_hair_window=None, settings=None):
    suppressed, reason = _xdzr8_v1161_should_suppress_hair_shell(obj, role, character_context, face_window, settings)
    if suppressed:
        return True, reason
    if role != 'hair':
        return False, 'non-hair role'
    if settings is not None and not bool(getattr(settings, 'universal_head_outline_guard', True)):
        return False, 'guard disabled'
    if not head_hair_window:
        return False, 'head hair window unavailable'
    hint = _xdzr8_v116_object_role_hints(obj, character_context)
    if not bool(hint.get('head_zone')):
        return False, 'not head-zone hair'
    obj_bounds = _xdzr8_v1161_object_bounds(obj)
    if not obj_bounds:
        return False, 'object bounds unavailable'
    ref_height = max(float((character_context or {}).get('height', 0.0)), 1e-6)
    diag = max(float(head_hair_window.get('diag', 1.0)), 1e-6)
    inner_margin = max(ref_height * 0.010, diag * 0.050)
    face_margin = max(ref_height * 0.006, diag * 0.020)
    contained = _xdzr8_v1163_bounds_inside_inner(obj_bounds, head_hair_window, margin=inner_margin)
    face_overlap = bool(face_window and _xdzr8_v1161_bounds_intersect(obj_bounds, face_window, margin=face_margin))
    center_n = float(hint.get('center_n', 0.0))
    span_n = float(hint.get('span_n', 1.0))
    lateral_n = float(hint.get('lateral_n', 1.0))
    central = center_n >= 0.64 and center_n <= 0.98 and lateral_n <= 0.42
    compact = span_n <= 0.46
    if contained and (central or compact or face_overlap):
        return True, 'head hair interior guard'
    if face_overlap and central and span_n <= 0.54:
        return True, 'head hair face overlap guard'
    return False, 'head hair silhouette preserved'

def _xdzr8_v116_groups(obj, character_context=None, settings=None):
    data = getattr(obj, 'data', None)
    if data is None or not getattr(data, 'polygons', None):
        return []
    used = {}
    for poly in data.polygons:
        used[int(poly.material_index)] = used.get(int(poly.material_index), 0) + 1
    groups = {}
    for index, slot in enumerate(getattr(obj, 'material_slots', [])):
        if index not in used or getattr(slot, 'material', None) is None:
            continue
        role = _xdzr8_v116_refined_outline_role(obj, slot.material, character_context, settings)
        group = groups.setdefault(role, {'role': role, 'indices': [], 'polygons': 0, 'materials': []})
        group['indices'].append(index)
        group['polygons'] += int(used.get(index, 0))
        group['materials'].append(slot.material.name)
    return list(groups.values())

def _xdzr8_v1166_recalculate_shell_normals(mesh):
    """Legacy compatibility helper retained for old material graphs.

    Recalculate face normals on the OUTLINE COPY only.

    Low-poly MMD meshes often contain disconnected/open islands whose imported
    split normals are excellent for shading but unsafe for inverted-hull
    extrusion. This function never touches the source mesh datablock.
    """
    info = {'recalculated': False, 'faces': 0, 'error': ''}
    if mesh is None:
        info['error'] = 'no mesh'
        return info
    bm = bmesh.new()
    try:
        bm.from_mesh(mesh)
        faces = list(bm.faces)
        info['faces'] = len(faces)
        if not faces:
            info['error'] = 'no faces'
            return info
        bmesh.ops.recalc_face_normals(bm, faces=faces)
        bm.normal_update()
        bm.to_mesh(mesh)
        try:
            mesh.update(calc_edges=True, calc_edges_loose=True)
        except TypeError:
            mesh.update()
        info['recalculated'] = True
    except Exception as exc:
        info['error'] = str(exc)
    finally:
        bm.free()
    return info

def _xdzr8_v1166_build_frontface_leak_guard(nt, out, role, color):
    """Legacy compatibility helper retained for old material graphs.

    Build a view-angle guard for the LOW_POLY whole-mesh silhouette.

    The outline remains visible at grazing angles (the actual silhouette), but
    broad shell faces looking toward the camera become transparent. Using the
    absolute Normal·Incoming term makes this robust to disconnected islands
    whose winding may be reversed.
    """
    emit = nt.nodes.new('ShaderNodeEmission')
    emit.name = 'XDZR8 V11.6.8.1 • Silhouette Ink'
    emit.label = 'Low-Poly Silhouette Ink'
    emit.location = (-20, 80)
    emit.inputs['Color'].default_value = color
    emit.inputs['Strength'].default_value = 1.0

    transparent = nt.nodes.new('ShaderNodeBsdfTransparent')
    transparent.name = 'XDZR8 V11.6.8.1 • Leak Guard Transparent'
    transparent.label = 'Frontface Leak Guard'
    transparent.location = (-20, -90)

    geo = nt.nodes.new('ShaderNodeNewGeometry')
    geo.name = 'XDZR8 V11.6.8.1 • Geometry Facing'
    geo.label = 'Shell Facing'
    geo.location = (-650, -10)

    dot = nt.nodes.new('ShaderNodeVectorMath')
    dot.name = 'XDZR8 V11.6.8.1 • Normal Dot Incoming'
    dot.label = '|Normal · View|'
    dot.operation = 'DOT_PRODUCT'
    dot.location = (-440, -10)
    normal_socket = geo.outputs.get('True Normal') or geo.outputs.get('Normal')
    incoming_socket = geo.outputs.get('Incoming')
    if normal_socket is not None:
        nt.links.new(normal_socket, dot.inputs[0])
    if incoming_socket is not None:
        nt.links.new(incoming_socket, dot.inputs[1])

    absolute = nt.nodes.new('ShaderNodeMath')
    absolute.name = 'XDZR8 V11.6.8.1 • Absolute Facing'
    absolute.label = 'Absolute Facing'
    absolute.operation = 'ABSOLUTE'
    absolute.location = (-250, -10)
    nt.links.new(dot.outputs.get('Value'), absolute.inputs[0])

    grazing = nt.nodes.new('ShaderNodeMath')
    grazing.name = 'XDZR8 V11.6.8.1 • Grazing Gate'
    grazing.label = 'Silhouette Only • < 0.42'
    grazing.operation = 'LESS_THAN'
    grazing.location = (-70, -10)
    grazing.inputs[1].default_value = 0.42
    nt.links.new(absolute.outputs[0], grazing.inputs[0])

    mix = nt.nodes.new('ShaderNodeMixShader')
    mix.name = 'XDZR8 V11.6.8.1 • Frontface Leak Guard'
    mix.label = 'Frontface Leak Guard'
    mix.location = (190, 20)
    nt.links.new(grazing.outputs[0], mix.inputs[0])
    nt.links.new(transparent.outputs['BSDF'], mix.inputs[1])
    nt.links.new(emit.outputs['Emission'], mix.inputs[2])
    nt.links.new(mix.outputs[0], out.inputs['Surface'])
    return {
        'enabled': True,
        'threshold': 0.42,
        'node': mix.name,
    }

def _xdzr8_v1167_local_scale(obj):
    """Approximate local->world scale for converting outline width to mesh space."""
    if obj is None:
        return 1.0
    try:
        mw = obj.matrix_world.to_3x3()
        scales = [mw.col[i].length for i in range(3)]
        valid = [float(v) for v in scales if float(v) > 1e-8]
        if valid:
            return max(sum(valid) / len(valid), 1e-8)
    except Exception:
        pass
    return 1.0

def _xdzr8_v1167_connected_face_components(bm):
    """Return edge-connected face islands for low-poly orientation sanitation."""
    faces = list(bm.faces)
    if not faces:
        return []
    pending = set(faces)
    components = []
    while pending:
        seed = pending.pop()
        stack = [seed]
        comp = [seed]
        while stack:
            face = stack.pop()
            for edge in face.edges:
                for other in edge.link_faces:
                    if other in pending:
                        pending.remove(other)
                        stack.append(other)
                        comp.append(other)
        components.append(comp)
    return components

def _xdzr8_v1167_direct_backface_hull(mesh, src_obj, bounds, world_thickness):
    """Build a classic inverted hull directly on the outline copy.

    LOW_POLY meshes can contain many disconnected/open islands inside one object.
    Solidify duplicates those surfaces and can expose entire front-facing plates.
    This path instead sanitizes each connected island, orients it away from the
    character center, expands vertices along the sanitized vertex normals, then
    reverses all faces once. With material backface culling, broad front faces
    disappear and only the expanded silhouette remains. Source geometry is never
    modified.
    """
    info = {
        'built': False,
        'components': 0,
        'components_flipped': 0,
        'faces': 0,
        'vertices_expanded': 0,
        'local_thickness': 0.0,
        'orientation_guard': False,
        'error': '',
    }
    if mesh is None or src_obj is None:
        info['error'] = 'missing mesh/object'
        return info

    try:
        world_center = (Vector(bounds['min']) + Vector(bounds['max'])) * 0.5
        ref_center = src_obj.matrix_world.inverted_safe() @ world_center
    except Exception:
        ref_center = Vector((0.0, 0.0, 0.0))

    local_scale = _xdzr8_v1167_local_scale(src_obj)
    local_thickness = max(float(world_thickness) / max(local_scale, 1e-8), 1e-7)
    info['local_thickness'] = float(local_thickness)

    bm = bmesh.new()
    try:
        bm.from_mesh(mesh)
        bm.faces.ensure_lookup_table()
        bm.verts.ensure_lookup_table()
        faces = list(bm.faces)
        info['faces'] = len(faces)
        if not faces:
            info['error'] = 'no faces'
            return info

        components = _xdzr8_v1167_connected_face_components(bm)
        info['components'] = len(components)
        flipped = 0

        for comp in components:
            if not comp:
                continue

            try:
                bmesh.ops.recalc_face_normals(bm, faces=comp)
            except Exception:
                pass
            bm.normal_update()

            vote = 0.0
            weight = 0.0
            for face in comp:
                try:
                    center = face.calc_center_median()
                    radial = center - ref_center
                    if radial.length_squared <= 1e-16:
                        continue
                    area = max(float(face.calc_area()), 1e-10)
                    vote += float(face.normal.dot(radial.normalized())) * area
                    weight += area
                except Exception:
                    continue
            if weight > 0.0 and vote < 0.0:
                try:
                    bmesh.ops.reverse_faces(bm, faces=comp)
                    flipped += 1
                except Exception:
                    pass

        bm.normal_update()

        for vert in bm.verts:
            try:
                n = vert.normal.copy()
                if n.length_squared > 1e-16:
                    vert.co += n.normalized() * local_thickness
            except Exception:
                pass
        info['vertices_expanded'] = len(bm.verts)

        try:
            bmesh.ops.reverse_faces(bm, faces=list(bm.faces))
        except Exception:
            for face in bm.faces:
                try:
                    face.normal_flip()
                except Exception:
                    pass
        bm.normal_update()
        bm.to_mesh(mesh)
        try:
            mesh.update(calc_edges=True, calc_edges_loose=True)
        except TypeError:
            mesh.update()

        info['components_flipped'] = int(flipped)
        info['orientation_guard'] = True
        info['built'] = True
    except Exception as exc:
        info['error'] = str(exc)
    finally:
        bm.free()
    return info

def _xdzr8_v11682_boundary_edge_components(edges):
    """Return edge-connected boundary loops/chains without touching source data."""
    pending = set(edges or [])
    components = []
    while pending:
        seed = pending.pop()
        stack = [seed]
        comp = [seed]
        while stack:
            edge = stack.pop()
            verts = set(edge.verts)
            linked = []
            for other in list(pending):
                try:
                    if any(v in verts for v in other.verts):
                        linked.append(other)
                except Exception:
                    continue
            for other in linked:
                pending.remove(other)
                stack.append(other)
                comp.append(other)
        components.append(comp)
    return components

def _xdzr8_v11682_face_support_ribbon(mesh, src_obj, world_width):
    """Build a narrow, double-sided outer-boundary ribbon for LOW_POLY faces.

    A material-pruned anime face can be an open front surface. A classic inverted
    hull may therefore have no rear-facing polygons to reveal after backface
    culling, even when its vertices are expanded. V11.6.8.5 avoids reopening the
    whole Low-Poly backend: only the auxiliary face-support copy is reduced to a
    thin ribbon around its largest boundary loop. Smaller loops/holes are ignored,
    so eyes, mouth and other interior facial details are not outlined.
    """
    info = {
        'built': False,
        'faces': 0,
        'boundary_loops': 0,
        'outer_boundary_vertices': 0,
        'ribbon_faces': 0,
        'tangent_vertices_expanded': 0,
        'outer_boundary_perimeter': 0.0,
        'local_width': 0.0,
        'error': '',
    }
    if mesh is None or src_obj is None:
        info['error'] = 'missing mesh/object'
        return info

    local_scale = _xdzr8_v1167_local_scale(src_obj)
    local_width = max(float(world_width) / max(local_scale, 1e-8), 1e-7)
    info['local_width'] = float(local_width)

    bm = bmesh.new()
    try:
        bm.from_mesh(mesh)
        bm.faces.ensure_lookup_table()
        bm.verts.ensure_lookup_table()
        original_faces = list(bm.faces)
        info['faces'] = len(original_faces)
        if not original_faces:
            info['error'] = 'no faces'
            return info

        try:
            bmesh.ops.recalc_face_normals(bm, faces=original_faces)
        except Exception:
            pass
        bm.normal_update()

        boundary_edges = [edge for edge in bm.edges if len(edge.link_faces) == 1]
        components = _xdzr8_v11682_boundary_edge_components(boundary_edges)
        info['boundary_loops'] = len(components)
        if not components:
            info['error'] = 'face support has no open boundary'
            return info

        def perimeter(component):
            total = 0.0
            for edge in component:
                try:
                    total += float(edge.calc_length())
                except Exception:
                    pass
            return total

        outer = max(components, key=perimeter)
        info['outer_boundary_perimeter'] = float(perimeter(outer))
        outer_verts = set()
        touching_faces = set()
        for edge in outer:
            outer_verts.update(edge.verts)
            touching_faces.update(edge.link_faces)
        info['outer_boundary_vertices'] = len(outer_verts)
        if len(outer_verts) < 3:
            info['error'] = 'outer boundary too small'
            return info

        center = Vector((0.0, 0.0, 0.0))
        for vert in outer_verts:
            center += vert.co
        center /= float(len(outer_verts))

        avg_normal = Vector((0.0, 0.0, 0.0))
        for face in touching_faces:
            try:
                avg_normal += face.normal * max(float(face.calc_area()), 1e-10)
            except Exception:
                pass
        if avg_normal.length_squared <= 1e-16:

            for vert in outer_verts:
                try:
                    avg_normal += vert.normal
                except Exception:
                    pass
        plane_normal = avg_normal.normalized() if avg_normal.length_squared > 1e-16 else None

        expanded = {}
        tangent_count = 0
        deform_layer = None
        try:
            deform_layer = bm.verts.layers.deform.active
        except Exception:
            deform_layer = None
        for vert in outer_verts:
            radial = vert.co - center
            tangent = radial.copy()
            if plane_normal is not None:
                tangent -= plane_normal * float(tangent.dot(plane_normal))
            if tangent.length_squared <= 1e-16:
                tangent = radial
            if tangent.length_squared <= 1e-16:
                continue
            new_vert = bm.verts.new(vert.co + tangent.normalized() * local_width)

            if deform_layer is not None:
                try:
                    src_weights = vert[deform_layer]
                    dst_weights = new_vert[deform_layer]
                    for group_index, weight in src_weights.items():
                        dst_weights[group_index] = weight
                except Exception:
                    pass
            expanded[vert] = new_vert
            tangent_count += 1
        bm.verts.index_update()
        bm.verts.ensure_lookup_table()

        ribbon_faces = []
        for edge in outer:
            try:
                v1, v2 = edge.verts
                n1 = expanded.get(v1)
                n2 = expanded.get(v2)
                if n1 is None or n2 is None:
                    continue
                try:
                    face = bm.faces.new((v1, v2, n2, n1))
                except ValueError:
                    face = bm.faces.new((v2, v1, n1, n2))
                ribbon_faces.append(face)
            except Exception:
                continue
        if not ribbon_faces:
            info['error'] = 'could not build boundary ribbon'
            return info

        try:
            bmesh.ops.delete(bm, geom=original_faces, context='FACES')
        except Exception:
            for face in original_faces:
                try:
                    bm.faces.remove(face)
                except Exception:
                    pass
        loose = [vert for vert in bm.verts if not vert.link_faces]
        if loose:
            try:
                bmesh.ops.delete(bm, geom=loose, context='VERTS')
            except Exception:
                pass

        bm.normal_update()
        bm.to_mesh(mesh)
        try:
            mesh.update(calc_edges=True, calc_edges_loose=True)
        except TypeError:
            mesh.update()

        info['ribbon_faces'] = len(ribbon_faces)
        info['tangent_vertices_expanded'] = int(tangent_count)
        info['built'] = True
    except Exception as exc:
        info['error'] = str(exc)
    finally:
        bm.free()
    return info

def _xdzr8_v1192161_uma_view_silhouette_jaw_ribbon(mesh, src_obj, world_width, character_context=None):
    """Build a narrow lower-face ribbon from the *current camera silhouette*.

    This is deliberately separate from V11.7.6 Miku topology-jaw logic.  The
    input mesh has already been pruned to semantically proven Uma Face slots.
    Candidate edges are selected from real geometry using the current render
    camera: manifold edges qualify when adjacent face orientation crosses the
    view direction, while open boundaries qualify only near the bottom/outer jaw
    so mouth/eye holes cannot become ink.  The generated strip is centered on
    the selected edge chain in the camera plane and contains no original face
    polygons, so it cannot blacken the facial surface.

    Camera dependence is sampled when Add Shaders runs. Rebuild after changing
    the render camera/viewpoint.
    """
    info = {
        'built': False, 'faces': 0, 'candidate_edges': 0, 'silhouette_edges': 0,
        'manifold_silhouette_edges': 0, 'boundary_silhouette_edges': 0,
        'components': 0, 'kept_components': 0, 'ribbon_faces': 0,
        'tangent_vertices_expanded': 0, 'jaw_arc_edges': 0, 'jaw_arc_vertices': 0,
        'jaw_arc_ratio': 0.56, 'camera_aware': True, 'camera_name': '',
        'topology_locked': False, 'centered_ribbon': True,
        'surface_inset': False, 'surface_exterior': False,
        'half_width_world': 0.0, 'front_bias_world': 0.0,
        'vertical_axis': -1, 'width_axis': -1, 'depth_axis': -1,
        'error': '',
    }
    if mesh is None or src_obj is None:
        info['error'] = 'missing mesh/object'
        return info
    cam = getattr(getattr(bpy.context, 'scene', None), 'camera', None)
    if cam is None:
        info['error'] = 'no active render camera for Uma silhouette sampling'
        return info
    info['camera_name'] = str(getattr(cam, 'name', '') or '')

    world_width = max(float(world_width), 1e-7)
    half_width = world_width * 0.5
    info['half_width_world'] = float(half_width)

    ctx = character_context or {}
    axis = int(ctx.get('axis', 2))
    cmin = ctx.get('min'); cmax = ctx.get('max'); ccenter = ctx.get('center')
    if cmin is None or cmax is None or ccenter is None:
        try:
            pts = [src_obj.matrix_world @ Vector(corner) for corner in src_obj.bound_box]
            cmin = Vector((min(p.x for p in pts), min(p.y for p in pts), min(p.z for p in pts)))
            cmax = Vector((max(p.x for p in pts), max(p.y for p in pts), max(p.z for p in pts)))
            ccenter = (cmin + cmax) * 0.5
            ext = [abs(float(cmax[i] - cmin[i])) for i in range(3)]
            axis = max(range(3), key=lambda i: ext[i])
            if ext[2] >= max(ext) * 0.42:
                axis = 2
        except Exception:
            cmin = Vector((-0.5, -0.5, -0.5)); cmax = Vector((0.5, 0.5, 0.5))
            ccenter = Vector((0.0, 0.0, 0.0)); axis = 2
    extents = [max(abs(float(cmax[i] - cmin[i])), 1e-8) for i in range(3)]
    lateral = [i for i in range(3) if i != axis]
    width_axis = max(lateral, key=lambda i: extents[i]) if lateral else 0
    depth_axis = min(lateral, key=lambda i: extents[i]) if lateral else (1 if axis != 1 else 0)
    info['vertical_axis'] = int(axis); info['width_axis'] = int(width_axis); info['depth_axis'] = int(depth_axis)

    try:
        cam_pos = cam.matrix_world.translation.copy()
        ortho = str(getattr(cam.data, 'type', '')) == 'ORTHO'

        ortho_to_camera = cam.matrix_world.to_quaternion() @ Vector((0.0, 0.0, 1.0))
        if ortho_to_camera.length_squared > 1e-16:
            ortho_to_camera.normalize()
    except Exception as exc:
        info['error'] = f'camera transform unavailable: {exc}'
        return info

    bm = bmesh.new()
    try:
        bm.from_mesh(mesh)
        bm.faces.ensure_lookup_table(); bm.verts.ensure_lookup_table(); bm.edges.ensure_lookup_table()
        original_faces = list(bm.faces)
        info['faces'] = len(original_faces)
        if not original_faces:
            info['error'] = 'no face polygons after semantic Face-slot pruning'
            return info
        try:
            bmesh.ops.recalc_face_normals(bm, faces=original_faces)
        except Exception:
            pass
        bm.normal_update()

        mw = src_obj.matrix_world.copy()
        normal_matrix = mw.to_3x3().inverted_safe().transposed()
        world_pos = {v: mw @ v.co for v in bm.verts}
        face_world_normals = {}
        for f in original_faces:
            try:
                n = normal_matrix @ f.normal
                if n.length_squared > 1e-16:
                    n.normalize()
                face_world_normals[f] = n
            except Exception:
                face_world_normals[f] = Vector((0.0, 0.0, 1.0))

        vals_v = [float(p[axis]) for p in world_pos.values()]
        vals_w = [float(p[width_axis]) for p in world_pos.values()]
        if not vals_v or not vals_w:
            info['error'] = 'face bounds unavailable'
            return info
        vmin, vmax = min(vals_v), max(vals_v)
        wmin, wmax = min(vals_w), max(vals_w)
        vspan = max(vmax - vmin, 1e-8)
        wcenter = (wmin + wmax) * 0.5
        whalf = max((wmax - wmin) * 0.5, 1e-8)

        def view_to_camera(point):
            if ortho:
                return ortho_to_camera.copy()
            vec = cam_pos - point
            if vec.length_squared <= 1e-16:
                return ortho_to_camera.copy()
            vec.normalize()
            return vec

        def edge_world_length(edge):
            a = world_pos[edge.verts[0]]; b = world_pos[edge.verts[1]]
            return float((a-b).length)

        selected = []
        manifold_count = 0
        boundary_count = 0
        for edge in bm.edges:
            linked = list(edge.link_faces)
            if not linked or len(linked) > 2:
                continue
            p1 = world_pos[edge.verts[0]]; p2 = world_pos[edge.verts[1]]
            mid = (p1 + p2) * 0.5
            vn = (float(mid[axis]) - vmin) / vspan

            if vn > 0.56:
                continue
            lateral_n = abs(float(mid[width_axis]) - wcenter) / whalf
            view = view_to_camera(mid)
            info['candidate_edges'] += 1
            if len(linked) == 2:
                d0 = float(face_world_normals[linked[0]].dot(view))
                d1 = float(face_world_normals[linked[1]].dot(view))

                if d0 * d1 > 0.0 and min(abs(d0), abs(d1)) > 0.10:
                    continue
                selected.append(edge); manifold_count += 1
            else:

                if not (vn <= 0.22 or lateral_n >= 0.40):
                    continue
                selected.append(edge); boundary_count += 1

        info['manifold_silhouette_edges'] = int(manifold_count)
        info['boundary_silhouette_edges'] = int(boundary_count)
        info['silhouette_edges'] = len(selected)
        if len(selected) < 2:
            info['error'] = 'no safe lower-face camera silhouette edges'
            return info

        components = _xdzr8_v11682_boundary_edge_components(selected)
        info['components'] = len(components)
        components = [c for c in components if len(c) >= 2]
        if not components:
            info['error'] = 'camera silhouette has no usable connected edge chain'
            return info
        comp_rows = sorted(((sum(edge_world_length(e) for e in c), c) for c in components), key=lambda x: x[0], reverse=True)
        max_perim = max(comp_rows[0][0], 1e-8)
        kept_components = [c for perim, c in comp_rows[:4] if perim >= max_perim * 0.18]
        if not kept_components:
            info['error'] = 'camera silhouette components rejected as micro detail'
            return info
        info['kept_components'] = len(kept_components)
        kept_edges = []
        seen_edges = set()
        for comp in kept_components:
            for e in comp:
                if e not in seen_edges:
                    seen_edges.add(e); kept_edges.append(e)
        kept_verts = set()
        neighbors = {}
        for e in kept_edges:
            v1, v2 = e.verts
            kept_verts.update((v1, v2))
            neighbors.setdefault(v1, []).append(v2)
            neighbors.setdefault(v2, []).append(v1)
        info['jaw_arc_edges'] = len(kept_edges)
        info['jaw_arc_vertices'] = len(kept_verts)
        if len(kept_edges) < 2 or len(kept_verts) < 3:
            info['error'] = 'safe jaw silhouette chain too small'
            return info

        inv_world = mw.inverted_safe()
        deform_layer = None
        try:
            deform_layer = bm.verts.layers.deform.active
        except Exception:
            deform_layer = None
        def copy_weights(src, dst):
            if deform_layer is None:
                return
            try:
                for gi, weight in src[deform_layer].items():
                    dst[deform_layer][gi] = weight
            except Exception:
                pass

        front_bias = min(world_width * 0.10, max(vspan, whalf * 2.0) * 0.00008)
        info['front_bias_world'] = float(front_bias)
        ring_a = {}; ring_b = {}
        for vert in kept_verts:
            p = world_pos[vert]
            nbs = neighbors.get(vert, [])
            tangent = Vector((0.0, 0.0, 0.0))
            if len(nbs) >= 2:

                best = None; best_d = -1.0
                for i, a in enumerate(nbs):
                    for b in nbs[i+1:]:
                        pa = world_pos[a]; pb = world_pos[b]
                        d = (pa-pb).length_squared
                        if d > best_d:
                            best_d = d; best = (pa, pb)
                if best:
                    tangent = best[1] - best[0]
            elif len(nbs) == 1:
                tangent = world_pos[nbs[0]] - p
            if tangent.length_squared <= 1e-16:
                tangent[width_axis] = 1.0
            tangent.normalize()
            view = view_to_camera(p)
            screen_normal = view.cross(tangent)
            if screen_normal.length_squared <= 1e-16:
                screen_normal = Vector((0.0, 0.0, 0.0))
                screen_normal[width_axis] = -float(tangent[axis])
                screen_normal[axis] = float(tangent[width_axis])
            if screen_normal.length_squared <= 1e-16:
                screen_normal[axis] = 1.0
            screen_normal.normalize()
            bias = view * front_bias
            pa = p - screen_normal * half_width + bias
            pb = p + screen_normal * half_width + bias
            va = bm.verts.new(inv_world @ pa); vb = bm.verts.new(inv_world @ pb)
            copy_weights(vert, va); copy_weights(vert, vb)
            ring_a[vert] = va; ring_b[vert] = vb

        bm.verts.index_update(); bm.verts.ensure_lookup_table()
        ribbon_faces = []
        for edge in kept_edges:
            v1, v2 = edge.verts
            a1, a2 = ring_a.get(v1), ring_a.get(v2)
            b1, b2 = ring_b.get(v1), ring_b.get(v2)
            if any(v is None for v in (a1, a2, b1, b2)):
                continue
            try:
                face = bm.faces.new((a1, a2, b2, b1))
            except ValueError:
                try:
                    face = bm.faces.new((a2, a1, b1, b2))
                except Exception:
                    continue
            ribbon_faces.append(face)
        if not ribbon_faces:
            info['error'] = 'could not build camera-silhouette ribbon faces'
            return info

        try:
            bmesh.ops.delete(bm, geom=original_faces, context='FACES')
        except Exception:
            for face in original_faces:
                try: bm.faces.remove(face)
                except Exception: pass
        loose = [v for v in bm.verts if not v.link_faces]
        if loose:
            try: bmesh.ops.delete(bm, geom=loose, context='VERTS')
            except Exception: pass

        bm.normal_update(); bm.to_mesh(mesh)
        try: mesh.update(calc_edges=True, calc_edges_loose=True)
        except TypeError: mesh.update()
        info['ribbon_faces'] = len(ribbon_faces)
        info['tangent_vertices_expanded'] = int(len(kept_verts) * 2)
        info['built'] = True
    except Exception as exc:
        info['error'] = str(exc)
    finally:
        bm.free()
    return info

def _xdzr8_v1174_face_support_jawline_exterior_ribbon(mesh, src_obj, world_width, character_context=None):
    """Build a front-biased EXTERIOR ribbon on the recovered lower jaw boundary.

    V11.7.3 ruled out component-material shading as the source of the persistent
    cheek/chin crescent: an exact clone of the canonical material produced the
    same artifact. The culprit is geometric. The V11.6.8.5 strip was placed from
    the jaw boundary *toward the face centre*, so the outline itself occupied
    visible facial pixels.

    V11.7.6 keeps every proven selection step (real recovered facial component,
    largest outer boundary, lower jaw arc, armature-weight transfer, tiny front
    bias) but flips only the ribbon direction. The second ring is moved AWAY from
    the face centre in the character width/height plane. Depth movement remains
    forbidden, so the strip cannot dive into the neck. The original jaw boundary
    is therefore the inner edge of the ink, while all generated area lies outside
    the facial surface.
    """
    info = {
        'built': False,
        'faces': 0,
        'boundary_loops': 0,
        'outer_boundary_vertices': 0,
        'outer_boundary_perimeter': 0.0,
        'jaw_arc_edges': 0,
        'jaw_arc_vertices': 0,
        'jaw_arc_ratio': float(XDZR8_V11685_JAW_ARC_RATIO),
        'jaw_cut_world': 0.0,
        'ribbon_faces': 0,
        'tangent_vertices_expanded': 0,
        'surface_inset': False,
        'surface_exterior': True,
        'front_bias_world': 0.0,
        'front_sign': 0.0,
        'vertical_axis': -1,
        'width_axis': -1,
        'depth_axis': -1,
        'local_width': 0.0,
        'error': '',
    }
    if mesh is None or src_obj is None:
        info['error'] = 'missing mesh/object'
        return info

    world_width = max(float(world_width), 1e-7)
    local_scale = _xdzr8_v1167_local_scale(src_obj)
    info['local_width'] = float(world_width / max(local_scale, 1e-8))

    ctx = character_context or {}
    axis = int(ctx.get('axis', 2))
    cmin = ctx.get('min')
    cmax = ctx.get('max')
    ccenter = ctx.get('center')
    if cmin is None or cmax is None or ccenter is None:
        try:
            pts = [src_obj.matrix_world @ Vector(corner) for corner in src_obj.bound_box]
            cmin = Vector((min(p.x for p in pts), min(p.y for p in pts), min(p.z for p in pts)))
            cmax = Vector((max(p.x for p in pts), max(p.y for p in pts), max(p.z for p in pts)))
            ccenter = (cmin + cmax) * 0.5
            ext = [abs(float(cmax[i] - cmin[i])) for i in range(3)]
            axis = max(range(3), key=lambda i: ext[i])
            if ext[2] >= max(ext) * 0.42:
                axis = 2
        except Exception:
            cmin = Vector((-0.5, -0.5, -0.5))
            cmax = Vector((0.5, 0.5, 0.5))
            ccenter = Vector((0.0, 0.0, 0.0))
            axis = 2
    extents = [max(abs(float(cmax[i] - cmin[i])), 1e-8) for i in range(3)]
    lateral = [i for i in range(3) if i != axis]
    width_axis = max(lateral, key=lambda i: extents[i]) if lateral else 0
    depth_axis = min(lateral, key=lambda i: extents[i]) if lateral else (1 if axis != 1 else 0)
    info['vertical_axis'] = int(axis)
    info['width_axis'] = int(width_axis)
    info['depth_axis'] = int(depth_axis)

    bm = bmesh.new()
    try:
        bm.from_mesh(mesh)
        bm.faces.ensure_lookup_table()
        bm.verts.ensure_lookup_table()
        original_faces = list(bm.faces)
        info['faces'] = len(original_faces)
        if not original_faces:
            info['error'] = 'no faces'
            return info

        try:
            bmesh.ops.recalc_face_normals(bm, faces=original_faces)
        except Exception:
            pass
        bm.normal_update()

        boundary_edges = [edge for edge in bm.edges if len(edge.link_faces) == 1]
        components = _xdzr8_v11682_boundary_edge_components(boundary_edges)
        info['boundary_loops'] = len(components)
        if not components:
            info['error'] = 'face support has no open boundary'
            return info

        def world_edge_length(edge):
            try:
                a = src_obj.matrix_world @ edge.verts[0].co
                b = src_obj.matrix_world @ edge.verts[1].co
                return float((a - b).length)
            except Exception:
                return float(edge.calc_length()) * local_scale

        def world_perimeter(component):
            return sum(world_edge_length(edge) for edge in component)

        outer = max(components, key=world_perimeter)
        info['outer_boundary_perimeter'] = float(world_perimeter(outer))
        outer_verts = set()
        for edge in outer:
            outer_verts.update(edge.verts)
        info['outer_boundary_vertices'] = len(outer_verts)
        if len(outer_verts) < 3:
            info['error'] = 'outer boundary too small'
            return info

        world_pos = {vert: src_obj.matrix_world @ vert.co for vert in outer_verts}
        face_center_world = Vector((0.0, 0.0, 0.0))
        for p in world_pos.values():
            face_center_world += p
        face_center_world /= float(len(world_pos))

        vmin = min(float(p[axis]) for p in world_pos.values())
        vmax = max(float(p[axis]) for p in world_pos.values())
        vspan = max(vmax - vmin, 1e-8)
        jaw_cut = vmin + vspan * float(XDZR8_V11685_JAW_ARC_RATIO)
        info['jaw_cut_world'] = float(jaw_cut)

        jaw_candidates = []
        for edge in outer:
            p1 = world_pos.get(edge.verts[0])
            p2 = world_pos.get(edge.verts[1])
            if p1 is None or p2 is None:
                continue
            if (float(p1[axis]) + float(p2[axis])) * 0.5 <= jaw_cut:
                jaw_candidates.append(edge)
        jaw_components = _xdzr8_v11682_boundary_edge_components(jaw_candidates)
        if not jaw_components:
            info['error'] = 'no lower jaw boundary arc'
            return info
        jaw_edges = max(jaw_components, key=world_perimeter)
        jaw_verts = set()
        for edge in jaw_edges:
            jaw_verts.update(edge.verts)
        info['jaw_arc_edges'] = len(jaw_edges)
        info['jaw_arc_vertices'] = len(jaw_verts)
        if len(jaw_edges) < 3 or len(jaw_verts) < 4:
            info['error'] = 'lower jaw arc too small'
            return info

        delta_depth = float(face_center_world[depth_axis] - ccenter[depth_axis])
        if abs(delta_depth) <= 1e-8:
            front_sign = -1.0
        else:
            front_sign = 1.0 if delta_depth > 0.0 else -1.0
        info['front_sign'] = float(front_sign)
        front_bias = world_width * float(XDZR8_V11685_SURFACE_FRONT_BIAS_RATIO)
        info['front_bias_world'] = float(front_bias)

        inv_world = src_obj.matrix_world.inverted_safe()
        deform_layer = None
        try:
            deform_layer = bm.verts.layers.deform.active
        except Exception:
            deform_layer = None

        def copy_weights(src, dst):
            if deform_layer is None:
                return
            try:
                src_weights = src[deform_layer]
                dst_weights = dst[deform_layer]
                for group_index, weight in src_weights.items():
                    dst_weights[group_index] = weight
            except Exception:
                pass

        boundary_ring = {}
        exterior_ring = {}
        bias_vec = Vector((0.0, 0.0, 0.0))
        bias_vec[depth_axis] = front_sign * front_bias

        for vert in jaw_verts:
            p = world_pos[vert]
            outward = p - face_center_world

            outward[depth_axis] = 0.0
            if outward.length_squared <= 1e-16:
                outward = Vector((0.0, 0.0, 0.0))
                outward[axis] = -1.0
            outward.normalize()
            p_boundary = p + bias_vec
            p_exterior = p + outward * world_width + bias_vec
            vb = bm.verts.new(inv_world @ p_boundary)
            vo = bm.verts.new(inv_world @ p_exterior)
            copy_weights(vert, vb)
            copy_weights(vert, vo)
            boundary_ring[vert] = vb
            exterior_ring[vert] = vo

        bm.verts.index_update()
        bm.verts.ensure_lookup_table()

        ribbon_faces = []
        for edge in jaw_edges:
            try:
                v1, v2 = edge.verts
                b1, b2 = boundary_ring.get(v1), boundary_ring.get(v2)
                o1, o2 = exterior_ring.get(v1), exterior_ring.get(v2)
                if any(v is None for v in (b1, b2, o1, o2)):
                    continue
                try:
                    face = bm.faces.new((b1, b2, o2, o1))
                except ValueError:
                    face = bm.faces.new((b2, b1, o1, o2))
                ribbon_faces.append(face)
            except Exception:
                continue
        if not ribbon_faces:
            info['error'] = 'could not build jawline exterior ribbon'
            return info

        try:
            bmesh.ops.delete(bm, geom=original_faces, context='FACES')
        except Exception:
            for face in original_faces:
                try:
                    bm.faces.remove(face)
                except Exception:
                    pass
        loose = [vert for vert in bm.verts if not vert.link_faces]
        if loose:
            try:
                bmesh.ops.delete(bm, geom=loose, context='VERTS')
            except Exception:
                pass

        bm.normal_update()
        bm.to_mesh(mesh)
        try:
            mesh.update(calc_edges=True, calc_edges_loose=True)
        except TypeError:
            mesh.update()

        info['ribbon_faces'] = len(ribbon_faces)
        info['tangent_vertices_expanded'] = int(len(jaw_verts) * 2)
        info['built'] = True
    except Exception as exc:
        info['error'] = str(exc)
    finally:
        bm.free()
    return info

def _xdzr8_v1176_face_support_topology_jawline_ribbon(mesh, src_obj, world_width, character_context=None):
    """Build a thin ribbon CENTERED on the model's real lower-jaw edge chain.

    The previous exterior ribbon deliberately displaced ink away from the face.
    The user's topology reference shows that the desired contour is the actual
    polygon edge chain itself. V11.7.6 therefore keeps the exact recovered
    796-poly facial component and the proven lower-42% jaw arc selection, but
    uses that arc as the *centerline* of the ink.

    A narrow strip is generated half a width on each side of the edge chain in
    the character width/height plane, with only a tiny camera/front bias in the
    depth axis to avoid z-fighting. The centerline never moves, so the outline
    follows the original topology instead of floating below or outside it.
    """
    info = {
        'built': False,
        'faces': 0,
        'boundary_loops': 0,
        'outer_boundary_vertices': 0,
        'outer_boundary_perimeter': 0.0,
        'jaw_arc_edges': 0,
        'jaw_arc_vertices': 0,
        'jaw_arc_ratio': float(XDZR8_V11685_JAW_ARC_RATIO),
        'jaw_cut_world': 0.0,
        'ribbon_faces': 0,
        'tangent_vertices_expanded': 0,
        'surface_inset': False,
        'surface_exterior': False,
        'topology_locked': True,
        'centered_ribbon': True,
        'half_width_world': 0.0,
        'front_bias_world': 0.0,
        'front_sign': 0.0,
        'vertical_axis': -1,
        'width_axis': -1,
        'depth_axis': -1,
        'local_width': 0.0,
        'error': '',
    }
    if mesh is None or src_obj is None:
        info['error'] = 'missing mesh/object'
        return info

    world_width = max(float(world_width), 1e-7)
    half_width = world_width * 0.5
    info['half_width_world'] = float(half_width)
    local_scale = _xdzr8_v1167_local_scale(src_obj)
    info['local_width'] = float(world_width / max(local_scale, 1e-8))

    ctx = character_context or {}
    axis = int(ctx.get('axis', 2))
    cmin = ctx.get('min'); cmax = ctx.get('max'); ccenter = ctx.get('center')
    if cmin is None or cmax is None or ccenter is None:
        try:
            pts = [src_obj.matrix_world @ Vector(corner) for corner in src_obj.bound_box]
            cmin = Vector((min(p.x for p in pts), min(p.y for p in pts), min(p.z for p in pts)))
            cmax = Vector((max(p.x for p in pts), max(p.y for p in pts), max(p.z for p in pts)))
            ccenter = (cmin + cmax) * 0.5
            ext = [abs(float(cmax[i] - cmin[i])) for i in range(3)]
            axis = max(range(3), key=lambda i: ext[i])
            if ext[2] >= max(ext) * 0.42:
                axis = 2
        except Exception:
            cmin = Vector((-0.5, -0.5, -0.5)); cmax = Vector((0.5, 0.5, 0.5)); ccenter = Vector((0,0,0)); axis = 2

    extents = [max(abs(float(cmax[i] - cmin[i])), 1e-8) for i in range(3)]
    lateral = [i for i in range(3) if i != axis]
    width_axis = max(lateral, key=lambda i: extents[i]) if lateral else 0
    depth_axis = min(lateral, key=lambda i: extents[i]) if lateral else (1 if axis != 1 else 0)
    info['vertical_axis'] = int(axis); info['width_axis'] = int(width_axis); info['depth_axis'] = int(depth_axis)

    bm = bmesh.new()
    try:
        bm.from_mesh(mesh)
        bm.faces.ensure_lookup_table(); bm.verts.ensure_lookup_table(); bm.edges.ensure_lookup_table()
        original_faces = list(bm.faces)
        info['faces'] = len(original_faces)
        if not original_faces:
            info['error'] = 'no faces'; return info
        try:
            bmesh.ops.recalc_face_normals(bm, faces=original_faces)
        except Exception:
            pass
        bm.normal_update()

        boundary_edges = [edge for edge in bm.edges if len(edge.link_faces) == 1]
        components = _xdzr8_v11682_boundary_edge_components(boundary_edges)
        info['boundary_loops'] = len(components)
        if not components:
            info['error'] = 'face support has no open boundary'; return info

        def world_edge_length(edge):
            try:
                a = src_obj.matrix_world @ edge.verts[0].co
                b = src_obj.matrix_world @ edge.verts[1].co
                return float((a-b).length)
            except Exception:
                return float(edge.calc_length()) * local_scale
        def world_perimeter(component):
            return sum(world_edge_length(edge) for edge in component)

        outer = max(components, key=world_perimeter)
        info['outer_boundary_perimeter'] = float(world_perimeter(outer))
        outer_verts = set()
        for edge in outer: outer_verts.update(edge.verts)
        info['outer_boundary_vertices'] = len(outer_verts)
        if len(outer_verts) < 3:
            info['error'] = 'outer boundary too small'; return info

        world_pos = {vert: src_obj.matrix_world @ vert.co for vert in outer_verts}
        face_center_world = sum((p for p in world_pos.values()), Vector((0,0,0))) / float(len(world_pos))
        vmin = min(float(p[axis]) for p in world_pos.values())
        vmax = max(float(p[axis]) for p in world_pos.values())
        vspan = max(vmax-vmin, 1e-8)
        jaw_cut = vmin + vspan * float(XDZR8_V11685_JAW_ARC_RATIO)
        info['jaw_cut_world'] = float(jaw_cut)

        jaw_candidates = []
        for edge in outer:
            p1 = world_pos.get(edge.verts[0]); p2 = world_pos.get(edge.verts[1])
            if p1 is None or p2 is None: continue
            if (float(p1[axis]) + float(p2[axis])) * 0.5 <= jaw_cut:
                jaw_candidates.append(edge)
        jaw_components = _xdzr8_v11682_boundary_edge_components(jaw_candidates)
        if not jaw_components:
            info['error'] = 'no lower jaw boundary arc'; return info
        jaw_edges = max(jaw_components, key=world_perimeter)
        jaw_verts = set()
        neighbors = {}
        for edge in jaw_edges:
            v1, v2 = edge.verts
            jaw_verts.update((v1, v2))
            neighbors.setdefault(v1, []).append(v2)
            neighbors.setdefault(v2, []).append(v1)
        info['jaw_arc_edges'] = len(jaw_edges); info['jaw_arc_vertices'] = len(jaw_verts)
        if len(jaw_edges) < 3 or len(jaw_verts) < 4:
            info['error'] = 'lower jaw arc too small'; return info

        delta_depth = float(face_center_world[depth_axis] - ccenter[depth_axis])
        front_sign = -1.0 if abs(delta_depth) <= 1e-8 else (1.0 if delta_depth > 0.0 else -1.0)
        info['front_sign'] = float(front_sign)
        front_bias = world_width * float(XDZR8_V11685_SURFACE_FRONT_BIAS_RATIO)
        info['front_bias_world'] = float(front_bias)
        bias_vec = Vector((0,0,0)); bias_vec[depth_axis] = front_sign * front_bias

        inv_world = src_obj.matrix_world.inverted_safe()
        deform_layer = None
        try: deform_layer = bm.verts.layers.deform.active
        except Exception: deform_layer = None
        def copy_weights(src, dst):
            if deform_layer is None: return
            try:
                for gi, weight in src[deform_layer].items():
                    dst[deform_layer][gi] = weight
            except Exception:
                pass

        ring_a = {}; ring_b = {}
        for vert in jaw_verts:
            p = world_pos[vert]
            nbs = neighbors.get(vert, [])
            tangent = Vector((0,0,0))
            if len(nbs) >= 2:
                p0 = world_pos.get(nbs[0], src_obj.matrix_world @ nbs[0].co)
                p1 = world_pos.get(nbs[1], src_obj.matrix_world @ nbs[1].co)
                tangent = p1 - p0
            elif len(nbs) == 1:
                pn = world_pos.get(nbs[0], src_obj.matrix_world @ nbs[0].co)
                tangent = pn - p
            tangent[depth_axis] = 0.0
            if tangent.length_squared <= 1e-16:
                tangent[width_axis] = 1.0
            tangent.normalize()

            normal2 = Vector((0,0,0))
            normal2[width_axis] = -float(tangent[axis])
            normal2[axis] = float(tangent[width_axis])
            if normal2.length_squared <= 1e-16:
                normal2[axis] = 1.0
            normal2.normalize()

            pa = p - normal2 * half_width + bias_vec
            pb = p + normal2 * half_width + bias_vec
            va = bm.verts.new(inv_world @ pa); vb = bm.verts.new(inv_world @ pb)
            copy_weights(vert, va); copy_weights(vert, vb)
            ring_a[vert] = va; ring_b[vert] = vb

        bm.verts.index_update(); bm.verts.ensure_lookup_table()
        ribbon_faces = []
        for edge in jaw_edges:
            v1, v2 = edge.verts
            a1, a2 = ring_a.get(v1), ring_a.get(v2)
            b1, b2 = ring_b.get(v1), ring_b.get(v2)
            if any(v is None for v in (a1,a2,b1,b2)): continue
            try: face = bm.faces.new((a1, a2, b2, b1))
            except ValueError:
                try: face = bm.faces.new((a2, a1, b1, b2))
                except Exception: continue
            ribbon_faces.append(face)
        if not ribbon_faces:
            info['error'] = 'could not build topology-locked jaw ribbon'; return info

        try: bmesh.ops.delete(bm, geom=original_faces, context='FACES')
        except Exception:
            for face in original_faces:
                try: bm.faces.remove(face)
                except Exception: pass
        loose = [v for v in bm.verts if not v.link_faces]
        if loose:
            try: bmesh.ops.delete(bm, geom=loose, context='VERTS')
            except Exception: pass

        bm.normal_update(); bm.to_mesh(mesh)
        try: mesh.update(calc_edges=True, calc_edges_loose=True)
        except TypeError: mesh.update()
        info['ribbon_faces'] = len(ribbon_faces)
        info['tangent_vertices_expanded'] = int(len(jaw_verts)*2)
        info['built'] = True
    except Exception as exc:
        info['error'] = str(exc)
    finally:
        bm.free()
    return info

def _xdzr8_v1192186_clamp01(v):
    try:
        return max(0.0, min(1.0, float(v)))
    except Exception:
        return 0.0

def _xdzr8_v1192186_rgba(rgb, alpha=1.0):
    vals = list(rgb[:3]) if isinstance(rgb, (list, tuple)) else [0.0, 0.0, 0.0]
    while len(vals) < 3:
        vals.append(0.0)
    return (_xdzr8_v1192186_clamp01(vals[0]), _xdzr8_v1192186_clamp01(vals[1]), _xdzr8_v1192186_clamp01(vals[2]), _xdzr8_v1192186_clamp01(alpha))

def _xdzr8_v1192186_material_base_color(mat):
    if mat is None:
        return None
    try:
        if bool(getattr(mat, 'use_nodes', False)) and getattr(mat, 'node_tree', None) is not None:
            nodes = list(getattr(mat.node_tree, 'nodes', []) or [])
            for node in nodes:
                try:
                    if str(getattr(node, 'type', '')) == 'BSDF_PRINCIPLED':
                        sock = node.inputs.get('Base Color')
                        if sock is not None:
                            dv = getattr(sock, 'default_value', None)
                            if dv is not None and len(dv) >= 3:
                                return _xdzr8_v1192186_rgba((dv[0], dv[1], dv[2]), 1.0)
                except Exception:
                    pass
            for node in nodes:
                try:
                    if str(getattr(node, 'type', '')) == 'RGB':
                        dv = getattr(node.outputs[0], 'default_value', None)
                        if dv is not None and len(dv) >= 3:
                            return _xdzr8_v1192186_rgba((dv[0], dv[1], dv[2]), 1.0)
                except Exception:
                    pass
    except Exception:
        pass
    try:
        dv = getattr(mat, 'diffuse_color', None)
        if dv is not None and len(dv) >= 3:
            return _xdzr8_v1192186_rgba((dv[0], dv[1], dv[2]), 1.0)
    except Exception:
        pass
    return None

def _xdzr8_v1192186_materials_from_indices(src_obj, indices):
    mats = []
    seen = set()
    slots = list(getattr(src_obj, 'material_slots', []) or []) if src_obj is not None else []
    for raw in list(indices or []):
        try:
            idx = int(raw)
        except Exception:
            continue
        if idx < 0 or idx >= len(slots) or idx in seen:
            continue
        seen.add(idx)
        mat = getattr(slots[idx], 'material', None)
        if mat is not None:
            mats.append(mat)
    return mats

def _xdzr8_v1192186_scene_outline_context(scene=None):
    scene = scene or getattr(bpy.context, 'scene', None)
    ctx = {'enabled': True, 'weight': 0.10, 'color': (0.0, 0.0, 0.0, 1.0), 'source': 'world'}
    if scene is None:
        return ctx
    try:
        if 'XDZR8_V11_9_2_18_6_OutlineSceneAware' in scene:
            ctx['enabled'] = bool(scene.get('XDZR8_V11_9_2_18_6_OutlineSceneAware', True))
    except Exception:
        pass
    try:
        if 'XDZR8_V11_9_2_18_6_OutlineSceneWeight' in scene:
            ctx['weight'] = max(0.0, min(1.0, float(scene.get('XDZR8_V11_9_2_18_6_OutlineSceneWeight', 0.10))))
    except Exception:
        pass
    col = None
    try:
        world = getattr(scene, 'world', None)
        if world is not None and bool(getattr(world, 'use_nodes', False)) and getattr(world, 'node_tree', None) is not None:
            for node in getattr(world.node_tree, 'nodes', []) or []:
                if str(getattr(node, 'type', '')) == 'BACKGROUND':
                    sock = node.inputs.get('Color')
                    if sock is not None:
                        dv = getattr(sock, 'default_value', None)
                        if dv is not None and len(dv) >= 3:
                            col = (dv[0], dv[1], dv[2], 1.0)
                            break
        if col is None and world is not None:
            dv = getattr(world, 'color', None)
            if dv is not None and len(dv) >= 3:
                col = (dv[0], dv[1], dv[2], 1.0)
    except Exception:
        col = None
    if col is None:
        col = (0.0, 0.0, 0.0, 1.0)
        ctx['source'] = 'fallback'
    else:
        ctx['source'] = 'world'
    ctx['color'] = _xdzr8_v1192186_rgba(col, 1.0)
    return ctx

def _xdzr8_v1192186_outline_color(role, source_materials=None, scene=None):
    import colorsys
    role_default = XDZR8_V116_ROLE_INK.get(role, (0.010, 0.007, 0.014, 1.0))
    source_materials = [m for m in (source_materials or []) if m is not None]
    samples = []
    names = []
    for mat in source_materials:
        base = _xdzr8_v1192186_material_base_color(mat)
        if base is not None:
            samples.append(base)
            names.append(str(getattr(mat, 'name', '')))
    if samples:
        r = sum(c[0] for c in samples) / len(samples)
        g = sum(c[1] for c in samples) / len(samples)
        b = sum(c[2] for c in samples) / len(samples)
        base_rgb = (_xdzr8_v1192186_clamp01(r), _xdzr8_v1192186_clamp01(g), _xdzr8_v1192186_clamp01(b))
    else:
        base_rgb = role_default[:3]
    h, s, v = colorsys.rgb_to_hsv(*base_rgb)

    role_value = {
        'face': 0.17, 'body': 0.16, 'hair': 0.18, 'cloth': 0.14,
        'transparent_cloth': 0.16, 'stockings': 0.15, 'glove': 0.13,
        'boots': 0.12, 'mask': 0.12, 'accessory': 0.13, 'silhouette': 0.12,
        'eyes5': 0.10, 'mouth': 0.12,
    }.get(role, 0.13)
    value = max(0.06, min(0.28, role_value + (v * 0.06)))
    sat = min(1.0, max(0.10, s * 0.68 + 0.18))
    tinted = colorsys.hsv_to_rgb(h, sat, value)
    fallback_mix = 0.28 if samples else 0.0
    mixed = tuple(
        _xdzr8_v1192186_clamp01((tinted[i] * (1.0 - fallback_mix)) + (role_default[i] * fallback_mix))
        for i in range(3)
    )
    scene_ctx = _xdzr8_v1192186_scene_outline_context(scene)
    scene_weight = float(scene_ctx.get('weight', 0.0)) if bool(scene_ctx.get('enabled', True)) else 0.0
    scene_rgb = scene_ctx.get('color', (0.0, 0.0, 0.0, 1.0))[:3]
    scene_tinted = tuple(_xdzr8_v1192186_clamp01((c * 0.18) + (mixed[i] * 0.52)) for i, c in enumerate(scene_rgb))
    final = tuple(_xdzr8_v1192186_clamp01((mixed[i] * (1.0 - scene_weight)) + (scene_tinted[i] * scene_weight)) for i in range(3))
    meta = {
        'base_rgb': tuple(base_rgb), 'source_names': list(names), 'sample_count': int(len(samples)),
        'scene_weight': float(scene_weight), 'scene_rgb': tuple(scene_rgb), 'scene_source': str(scene_ctx.get('source', 'fallback')),
    }
    return _xdzr8_v1192186_rgba(final, 1.0), meta

def _xdzr8_v1192186_color_hash(role, source_materials=None, scene=None, face_support=False):
    import zlib
    color, meta = _xdzr8_v1192186_outline_color(role, source_materials=source_materials, scene=scene)
    parts = [role, 'fs' if face_support else 'std']
    parts.extend(meta.get('source_names', [])[:8])
    parts.append(','.join(f'{v:.4f}' for v in color[:3]))
    parts.append(f'sw={meta.get("scene_weight", 0.0):.4f}')
    key = '|'.join(parts).encode('utf-8', errors='ignore')
    return color, meta, format(zlib.adler32(key) & 0xffffffff, '08x')

def _xdzr8_v1192186_assign_outline_materials(mesh, src_obj, group, role, settings, character_context=None, face_support=False):
    info = {'assigned': False, 'primary_material': None, 'audit': [], 'material_count': 0}
    if mesh is None:
        return info
    try:
        poly_indices = sorted({int(poly.material_index) for poly in mesh.polygons})
    except Exception:
        poly_indices = sorted(set(int(i) for i in (group.get('indices', []) or []) if int(i) >= 0))
    if not poly_indices:
        mat = _xdzr8_v116_material(role, invisible=False, face_support=face_support)
        try:
            mesh.materials.clear()
        except Exception:
            while len(mesh.materials):
                mesh.materials.pop(index=len(mesh.materials)-1)
        mesh.materials.append(mat)
        for poly in mesh.polygons:
            poly.material_index = 0
        info.update({'assigned': True, 'primary_material': mat, 'audit': [f'fallback:{role}'], 'material_count': 1})
        return info

    max_index = max(poly_indices)
    mapped = []
    for idx in range(max_index + 1):
        src_mat = None
        try:
            if idx < len(src_obj.material_slots):
                src_mat = getattr(src_obj.material_slots[idx], 'material', None)
        except Exception:
            src_mat = None
        if idx in poly_indices:
            slot_role = role
            if role == 'silhouette' and src_mat is not None:
                try:
                    slot_role, _slot_source = _xdzr8_v11684_face_support_slot_role(src_obj, src_mat, character_context, settings)
                except Exception:
                    slot_role = role
                if slot_role not in XDZR8_V116_ROLE_INK:
                    slot_role = role
            mat = _xdzr8_v116_material(slot_role, invisible=False, face_support=face_support, source_materials=[src_mat] if src_mat is not None else [])
            mapped.append(mat)
            c = tuple(float(v) for v in getattr(mat, 'diffuse_color', (0.0, 0.0, 0.0, 1.0))[:3])
            info['audit'].append(f'{idx}:{slot_role}:{getattr(src_mat, "name", "")}:({c[0]:.3f},{c[1]:.3f},{c[2]:.3f})')
            if info['primary_material'] is None:
                info['primary_material'] = mat
        else:
            mapped.append(_xdzr8_v116_material(role, invisible=True))
    try:
        mesh.materials.clear()
    except Exception:
        while len(mesh.materials):
            mesh.materials.pop(index=len(mesh.materials)-1)
    for mat in mapped:
        mesh.materials.append(mat)
    info['assigned'] = True
    info['material_count'] = int(len(mapped))
    return info

def _xdzr8_v116_material(role, invisible=False, face_support=False, source_materials=None):
    role = str(role or 'silhouette').strip().lower()
    scene = getattr(bpy.context, 'scene', None)
    backface_only = bool(getattr(scene, 'get', lambda *_: False)('SaberShader_V102_OutlineBackfaceOnly', False)) if scene is not None else False
    if invisible:
        public_name = 'SaberShader - Outline Helper'
        mat = None
        for candidate in list(bpy.data.materials):
            try:
                if bool(candidate.get('SaberShader_V1_OutlineHelper', False)):
                    mat = candidate
                    break
            except Exception:
                pass
        mat = mat or bpy.data.materials.new(name=public_name)
        try:
            mat.name = public_name
        except Exception:
            pass
        color = None; meta = {}; sig = 'invisible'
    else:
        color, meta, sig = _xdzr8_v1192186_color_hash(role, source_materials=source_materials, scene=scene, face_support=face_support)
        public_name = _sabershader_v1_public_material_name(role, semantic_role=('face' if face_support else role), outline=True)
        mat = None
        for candidate in list(bpy.data.materials):
            try:
                if not bool(candidate.get('XDZR8_V11_6_AdaptiveOutline', False)):
                    continue
                if bool(candidate.get('SaberShader_V1_OutlineHelper', False)):
                    continue
                if str(candidate.get('SaberShader_V1_OutlineSignature', '')) != str(sig):
                    continue
                if str(candidate.get('XDZR8_V11_6_Role', '')) != role:
                    continue
                if bool(candidate.get('XDZR8_V11_6_8_5_FaceSupportRibbon', False)) != bool(face_support):
                    continue
                if bool(candidate.get('SaberShader_V102_OutlineBackfaceOnly', False)) != bool(backface_only):
                    continue
                mat = candidate
                break
            except Exception:
                continue
        mat = mat or bpy.data.materials.new(name=public_name)
        try:
            if not str(mat.name).startswith(public_name):
                mat.name = public_name
        except Exception:
            pass

    mat.use_nodes = True
    nt = mat.node_tree
    nt.nodes.clear()
    out = nt.nodes.new('ShaderNodeOutputMaterial')
    out.location = (520, 0)
    if invisible:
        shader = nt.nodes.new('ShaderNodeBsdfTransparent')
        shader.name = 'SaberShader - Outline Helper'
        nt.links.new(shader.outputs['BSDF'], out.inputs['Surface'])
        try:
            mat.diffuse_color = (0.0, 0.0, 0.0, 0.0)
        except Exception:
            pass
        if hasattr(mat, 'use_backface_culling'):
            mat.use_backface_culling = False
        mat['XDZR8_V11_6_8_5_DirectBackfaceHull'] = False
        mat['XDZR8_V11_6_8_5_FrontfaceLeakGuard'] = False
        mat['SaberShader_V1_OutlineHelper'] = True
    else:
        if backface_only:
            geo = nt.nodes.new('ShaderNodeNewGeometry')
            geo.name = 'SaberShader - Outline Facing Guard'
            geo.label = 'Outline Facing Guard'
            geo.location = (-240, 0)
            emission = nt.nodes.new('ShaderNodeEmission')
            emission.name = _sabershader_v1_public_material_name(role, semantic_role=('face' if face_support else role), outline=True)
            emission.label = emission.name
            emission.location = (80, 120)
            emission.inputs['Color'].default_value = color
            emission.inputs['Strength'].default_value = 1.0
            transparent = nt.nodes.new('ShaderNodeBsdfTransparent')
            transparent.location = (80, -120)
            mix = nt.nodes.new('ShaderNodeMixShader')
            mix.location = (300, 0)
            nt.links.new(geo.outputs['Backfacing'], mix.inputs['Fac'])
            nt.links.new(transparent.outputs['BSDF'], mix.inputs[1])
            nt.links.new(emission.outputs['Emission'], mix.inputs[2])
            nt.links.new(mix.outputs['Shader'], out.inputs['Surface'])
            shader = emission
        else:
            shader = nt.nodes.new('ShaderNodeEmission')
            shader.name = _sabershader_v1_public_material_name(role, semantic_role=('face' if face_support else role), outline=True)
            shader.label = shader.name
            shader.inputs['Color'].default_value = color
            shader.inputs['Strength'].default_value = 1.0
            nt.links.new(shader.outputs['Emission'], out.inputs['Surface'])
        try:
            mat.diffuse_color = color
        except Exception:
            pass
        if hasattr(mat, 'use_backface_culling'):

            mat.use_backface_culling = False if (face_support or backface_only) else True
        mat['XDZR8_V11_6_8_5_DirectBackfaceHull'] = bool(role == 'silhouette' and not face_support)
        mat['XDZR8_V11_6_8_5_FaceSupportRibbon'] = bool(face_support)
        mat['XDZR8_V11_6_8_5_FrontfaceLeakGuard'] = bool(backface_only)
        mat['XDZR8_V11_9_2_18_6_MaterialDerivedColor'] = True
        mat['XDZR8_V11_9_2_18_6_SourceMaterials'] = ', '.join(meta.get('source_names', [])[:8])
        mat['XDZR8_V11_9_2_18_6_SourceMaterialCount'] = int(meta.get('sample_count', 0))
        mat['XDZR8_V11_9_2_18_6_SceneWeight'] = float(meta.get('scene_weight', 0.0))
        mat['XDZR8_V11_9_2_18_6_SceneSource'] = str(meta.get('scene_source', 'fallback'))
        mat['XDZR8_V11_9_2_18_6_BaseColorRGB'] = ','.join(f'{v:.5f}' for v in meta.get('base_rgb', (0.0,0.0,0.0)))
        mat['XDZR8_V11_9_2_18_6_SceneColorRGB'] = ','.join(f'{v:.5f}' for v in meta.get('scene_rgb', (0.0,0.0,0.0)))
        mat['SaberShader_V1_OutlineSignature'] = str(sig)
        mat['SaberShader_V1_PublicMaterialName'] = str(public_name)
        mat['SaberShader_V102_OutlineBackfaceOnly'] = bool(backface_only)
    mat['XDZR8_V11_6_AdaptiveOutline'] = True
    mat['XDZR8_V11_6_Role'] = role if not invisible else 'invisible'
    return mat

def _xdzr8_v116_has_armature_deform(obj):
    try:
        return any(mod.type == 'ARMATURE' and getattr(mod, 'show_render', True) for mod in obj.modifiers)
    except Exception:
        return False

def _xdzr8_v116_outside_world(co, bounds):
    if not bounds:
        return False
    mn, mx = bounds['min'], bounds['max']
    return co.x < mn.x or co.x > mx.x or co.y < mn.y or co.y > mx.y or co.z < mn.z or co.z > mx.z

def _xdzr8_v116_bake_static_solidify_and_clamp(dup, bounds, enabled=True):
    info = {'baked': False, 'faces_removed': 0, 'outside_verts': 0}
    if not enabled or dup is None or _xdzr8_v116_has_armature_deform(dup):
        return info
    old_mesh = getattr(dup, 'data', None)
    try:
        depsgraph = bpy.context.evaluated_depsgraph_get()
        depsgraph.update()
        evaluated = dup.evaluated_get(depsgraph)
        baked = bpy.data.meshes.new_from_object(evaluated, preserve_all_data_layers=True, depsgraph=depsgraph)
        baked.name = f'XDZR8_V116_Clamped__{old_mesh.name if old_mesh else dup.name}'
        dup.data = baked
        for mod in list(dup.modifiers):
            dup.modifiers.remove(mod)
        bm = bmesh.new()
        try:
            bm.from_mesh(baked)
            mw = dup.matrix_world.copy()
            bad = set()
            outside = set()
            for face in list(bm.faces):
                if any(_xdzr8_v116_outside_world(mw @ vert.co, bounds) for vert in face.verts):
                    bad.add(face)
                    outside.update(face.verts)
            info['outside_verts'] = len(outside)
            if bad:
                info['faces_removed'] = len(bad)
                bmesh.ops.delete(bm, geom=list(bad), context='FACES')
            loose_edges = [edge for edge in bm.edges if not edge.link_faces]
            if loose_edges:
                bmesh.ops.delete(bm, geom=loose_edges, context='EDGES')
            loose_verts = [vert for vert in bm.verts if not vert.link_faces and not vert.link_edges]
            if loose_verts:
                bmesh.ops.delete(bm, geom=loose_verts, context='VERTS')
            bm.to_mesh(baked)
        finally:
            bm.free()
        baked.update()
        info['baked'] = True
        if old_mesh is not None and getattr(old_mesh, 'users', 1) == 0:
            try: bpy.data.meshes.remove(old_mesh)
            except Exception: pass
    except Exception as exc:
        log(f'V11.6 static outline clamp warning: {getattr(dup, "name", "outline")}: {exc}')
    return info

def _xdzr8_v119218_find_authored_outline_uv(mesh):
    """Return the proven Uma facial-outline permission UV layer, if present."""
    if mesh is None:
        return ''
    try:
        for layer in list(getattr(mesh, 'uv_layers', []) or []):
            name = str(getattr(layer, 'name', '') or '')
            if name.casefold() == '_uv3':
                return name
    except Exception:
        pass
    return ''

def _xdzr8_v1192181_dedicated_transparent_material(tag):
    """Create one dedicated transparent routing material for V11.9.2.18.1.

    Solidify material offsets are slot-index based.  Reusing one Material datablock
    in multiple routing slots made the V11.9.2.18 full-topology helper ambiguous in
    Blender runtime.  Each routing state now owns a unique datablock.
    """
    safe = re.sub(r'[^A-Za-z0-9_\-]+', '_', str(tag or 'Transparent'))
    name = f'SaberShader - Face Outline Helper - {safe}'
    mat = bpy.data.materials.get(name) or bpy.data.materials.new(name=name)
    mat.use_nodes = True
    nt = mat.node_tree
    nt.nodes.clear()
    out = nt.nodes.new('ShaderNodeOutputMaterial')
    out.location = (260, 0)
    trans = nt.nodes.new('ShaderNodeBsdfTransparent')
    trans.name = f'XDZR8 V11.9.2.18.1 • {safe} Transparent'
    trans.location = (0, 0)
    nt.links.new(trans.outputs['BSDF'], out.inputs['Surface'])
    try:
        mat.diffuse_color = (0.0, 0.0, 0.0, 0.0)
    except Exception:
        pass
    try:
        mat.surface_render_method = 'DITHERED'
    except Exception:
        try:
            mat.blend_method = 'HASHED'
        except Exception:
            try:
                mat.blend_method = 'BLEND'
            except Exception:
                pass
    try:
        mat.shadow_method = 'NONE'
    except Exception:
        pass
    if hasattr(mat, 'use_backface_culling'):
        mat.use_backface_culling = False
    mat['XDZR8_V11_9_2_18_1_UmaRoutingTransparent'] = True
    mat['XDZR8_V11_9_2_18_1_UmaRoutingTag'] = str(tag or '')
    return mat

def _xdzr8_v1192182_filter_face_indices(group):
    """Narrow Uma face-support ownership to the principal facial surfaces only."""
    raw_indices = [int(i) for i in (group.get('indices', []) or [])]
    raw_mats = [str(m) for m in (group.get('materials', []) or [])]
    if not raw_indices:
        return [], []
    filtered = []
    kept_names = []
    for idx, name in zip(raw_indices, raw_mats or [''] * len(raw_indices)):
        low = str(name).casefold()
        if any(tag in low for tag in ('mayu', 'brow', 'lash', 'eyebrow')):
            continue
        if ('face' in low) or not raw_mats:
            filtered.append(int(idx))
            kept_names.append(str(name))
    if filtered:
        return filtered, kept_names
    return raw_indices, raw_mats

def _xdzr8_v1192182_plain_face_ink_material(source_materials=None):
    """Final isolated Uma outline material: pure XDZR8 ink, no transparent helper branch."""
    name = 'SaberShader - Face Outline'
    mat = bpy.data.materials.get(name) or bpy.data.materials.new(name=name)
    mat.use_nodes = True
    nt = mat.node_tree
    nt.nodes.clear()
    out = nt.nodes.new('ShaderNodeOutputMaterial'); out.location = (240, 0)
    emit = nt.nodes.new('ShaderNodeEmission'); emit.location = (0, 0)
    emit.name = 'XDZR8 V11.9.2.18.7 • Full Profile Face Ink'
    ink_color, _ink_meta, _ink_sig = _xdzr8_v1192186_color_hash('face', source_materials=source_materials, scene=getattr(bpy.context, 'scene', None), face_support=True)
    emit.inputs['Color'].default_value = ink_color
    emit.inputs['Strength'].default_value = 1.0
    nt.links.new(emit.outputs['Emission'], out.inputs['Surface'])
    try:
        mat.diffuse_color = ink_color
    except Exception:
        pass
    if hasattr(mat, 'use_backface_culling'):
        mat.use_backface_culling = True
    try:
        mat.shadow_method = 'NONE'
    except Exception:
        pass
    mat['XDZR8_V11_9_2_18_2_UmaIsolatedFaceInk'] = True
    mat['XDZR8_V11_9_2_18_3_UmaBackfaceSilhouetteOnly'] = True
    return mat

def _xdzr8_v1192182_bake_isolate_face_shell(dup, outline_mat, uv_name, keep_material_index=3, character_bounds=None):
    """Bake Solidify, isolate jawline shell, and suppress inner facial residues.

    V11.9.2.18.7 keeps the safe post-Solidify isolation and chin-connected jaw
    gate, then adds the missing upper profile silhouette observed in game
    turnarounds: nose bridge -> forehead. The extension is not a hard-coded line.
    It retains only front-depth-extreme face-shell geometry that can chain back to
    the accepted jaw/profile base, so normal backface culling decides when that
    geometry becomes visible in profile. _UV3 interior-feature evidence remains a
    hard veto, keeping mouth/eye residues out of the dedicated facial shell.
    """
    info = {
        'built': False, 'evaluated_polygons': 0, 'face_shell_polygons': 0,
        'authored_mask_polygons': 0, 'final_outline_polygons': 0, 'deleted_polygons': 0,
        'spatial_candidate_polygons': 0, 'filtered_components': 0,
        'accepted_jaw_components': 0, 'rejected_eye_like': 0,
        'rejected_nose_like': 0, 'rejected_mouth_like': 0,
        'rejected_micro_like': 0, 'accepted_jaw_polygons': 0,
        'bridged_jaw_components': 0, 'bridged_jaw_polygons': 0,
        'continuity_gap': 0.0, 'continuity_bridge_applied': False,
        'full_profile_continuity': False, 'profile_candidate_polygons': 0,
        'accepted_profile_components': 0, 'accepted_profile_polygons': 0,
        'profile_chain_applied': False, 'profile_front_sign': 0,
        'profile_depth_band': 0.24, 'profile_gap_limit': 0.0,
        'profile_component_audit': [],
        'vertical_axis': -1, 'width_axis': -1, 'depth_axis': -1, 'jaw_band_max': 0.30,
        'jaw_touch_max': 0.10, 'jaw_center_max': 0.24,
        'bridge_center_max': 0.48, 'bridge_min_max': 0.38,
        'component_audit': [], 'error': '',
    }
    if dup is None or getattr(dup, 'type', '') != 'MESH':
        info['error'] = 'missing helper object'
        return info
    old_mesh = getattr(dup, 'data', None)
    try:
        depsgraph = bpy.context.evaluated_depsgraph_get()
        depsgraph.update()
        evaluated = dup.evaluated_get(depsgraph)
        baked = bpy.data.meshes.new_from_object(evaluated, preserve_all_data_layers=True, depsgraph=depsgraph)
        baked.name = f'XDZR8_V1192187_FullProfile__{old_mesh.name if old_mesh else dup.name}'
        info['evaluated_polygons'] = int(len(getattr(baked, 'polygons', []) or []))

        bm = bmesh.new()
        try:
            bm.from_mesh(baked)
            bm.faces.ensure_lookup_table(); bm.verts.ensure_lookup_table(); bm.edges.ensure_lookup_table()
            uv_layer = None
            try:
                uv_layer = bm.loops.layers.uv.get(str(uv_name))
            except Exception:
                uv_layer = None

            shell_faces = [f for f in bm.faces if int(getattr(f, 'material_index', -1)) == int(keep_material_index)]
            info['face_shell_polygons'] = int(len(shell_faces))
            if not shell_faces:
                info['error'] = 'post-solidify Face shell is empty'
                return info

            mw = dup.matrix_world.copy()
            shell_points = []
            for face in shell_faces:
                for vert in face.verts:
                    try:
                        shell_points.append(mw @ vert.co)
                    except Exception:
                        pass
            if not shell_points:
                info['error'] = 'Face shell bounds unavailable'
                return info
            fmin = Vector((min(p.x for p in shell_points), min(p.y for p in shell_points), min(p.z for p in shell_points)))
            fmax = Vector((max(p.x for p in shell_points), max(p.y for p in shell_points), max(p.z for p in shell_points)))
            fsize = fmax - fmin

            axis = 2
            try:
                csize = Vector((character_bounds or {}).get('size', fsize))
                ext = [abs(float(csize[i])) for i in range(3)]
                largest = max(ext)
                axis = 2 if ext[2] >= largest * 0.42 else max(range(3), key=lambda i: ext[i])
            except Exception:
                axis = 2
            lateral = [i for i in range(3) if i != axis]
            width_axis = max(lateral, key=lambda i: abs(float(fsize[i]))) if lateral else 0
            depth_candidates = [i for i in range(3) if i not in {axis, width_axis}]
            depth_axis = depth_candidates[0] if depth_candidates else (lateral[0] if lateral else 1)
            info['vertical_axis'] = int(axis); info['width_axis'] = int(width_axis); info['depth_axis'] = int(depth_axis)
            vspan = max(abs(float(fsize[axis])), 1e-8)
            wspan = max(abs(float(fsize[width_axis])), 1e-8)
            dspan = max(abs(float(fsize[depth_axis])), 1e-8)
            wcenter = (float(fmin[width_axis]) + float(fmax[width_axis])) * 0.5
            dcenter = (float(fmin[depth_axis]) + float(fmax[depth_axis])) * 0.5
            bridge_gap_limit = max(vspan, wspan) * 0.082
            profile_gap_limit = max(vspan, dspan) * 0.105
            info['continuity_gap'] = float(bridge_gap_limit)
            info['profile_gap_limit'] = float(profile_gap_limit)

            def face_center_world(face):
                try:
                    return mw @ face.calc_center_median()
                except Exception:
                    pts = [mw @ v.co for v in face.verts]
                    return sum(pts, Vector((0, 0, 0))) / max(len(pts), 1)

            def authored_feature(face):
                if uv_layer is None:
                    return False
                for loop in face.loops:
                    try:
                        uv = loop[uv_layer].uv
                        x_gate = 1.0 if float(uv.x) > 0.90 else 0.0
                        y_gate = 1.0 if float(uv.y) > 0.90 else 0.0
                        if max(y_gate - x_gate, 0.0) > 0.5:
                            return True
                    except Exception:
                        continue
                return False

            feature_faces = set()
            spatial_faces = set()
            profile_source_faces = set()
            for face in shell_faces:
                p = face_center_world(face)
                vn = (float(p[axis]) - float(fmin[axis])) / vspan
                is_feature = authored_feature(face)
                if is_feature:
                    feature_faces.add(face)
                    continue
                if vn <= 0.40:
                    spatial_faces.add(face)
                if 0.18 <= vn <= 0.98:
                    profile_source_faces.add(face)
            info['authored_mask_polygons'] = int(len(feature_faces))
            info['spatial_candidate_polygons'] = int(len(spatial_faces))

            def components(face_set):
                pending = set(face_set)
                out = []
                while pending:
                    seed = pending.pop()
                    stack = [seed]; comp = [seed]
                    while stack:
                        face = stack.pop()
                        for edge in face.edges:
                            for other in edge.link_faces:
                                if other in pending:
                                    pending.remove(other); stack.append(other); comp.append(other)
                    out.append(comp)
                return out

            def classify_band(center_n):
                if center_n >= 0.52:
                    return 'eye'
                if center_n >= 0.30:
                    return 'nose'
                return 'mouth'

            def bbox_gap(a, b):
                gap_sq = 0.0
                for i in range(3):
                    a0, a1 = a['bbox_min'][i], a['bbox_max'][i]
                    b0, b1 = b['bbox_min'][i], b['bbox_max'][i]
                    d = 0.0
                    if a1 < b0:
                        d = float(b0 - a1)
                    elif b1 < a0:
                        d = float(a0 - b1)
                    gap_sq += d * d
                return gap_sq ** 0.5

            def stats_for_component(comp, idx):
                pts = [mw @ v.co for f in comp for v in f.verts]
                if not pts:
                    return None
                vvals = [float(p[axis]) for p in pts]
                wvals = [float(p[width_axis]) for p in pts]
                dvals = [float(p[depth_axis]) for p in pts]
                min_n = (min(vvals) - float(fmin[axis])) / vspan
                max_n = (max(vvals) - float(fmin[axis])) / vspan
                center_n = (((min(vvals) + max(vvals)) * 0.5) - float(fmin[axis])) / vspan
                width_span_n = (max(wvals) - min(wvals)) / wspan
                lateral_n = abs((((min(wvals) + max(wvals)) * 0.5) - wcenter) / max((wspan * 0.5), 1e-8))
                depth_min_n = (min(dvals) - float(fmin[depth_axis])) / dspan
                depth_max_n = (max(dvals) - float(fmin[depth_axis])) / dspan
                depth_center_n = (((min(dvals) + max(dvals)) * 0.5) - float(fmin[depth_axis])) / dspan
                bbox_min = Vector((min(p.x for p in pts), min(p.y for p in pts), min(p.z for p in pts)))
                bbox_max = Vector((max(p.x for p in pts), max(p.y for p in pts), max(p.z for p in pts)))
                feature_like = classify_band(center_n)
                touches_chin = min_n <= float(info['jaw_touch_max'])
                low_center = center_n <= float(info['jaw_center_max'])
                meaningful_span = width_span_n >= 0.10 or len(comp) >= 8
                micro_like = width_span_n < 0.06 and len(comp) < 6
                return {
                    'index': int(idx), 'faces': list(comp), 'count': int(len(comp)), 'pts': pts,
                    'bbox_min': bbox_min, 'bbox_max': bbox_max,
                    'min_n': float(min_n), 'max_n': float(max_n), 'center_n': float(center_n),
                    'width_span_n': float(width_span_n), 'lateral_n': float(lateral_n),
                    'depth_min_n': float(depth_min_n), 'depth_max_n': float(depth_max_n), 'depth_center_n': float(depth_center_n),
                    'touches_chin': bool(touches_chin), 'low_center': bool(low_center),
                    'meaningful_span': bool(meaningful_span), 'micro_like': bool(micro_like),
                    'feature_like': feature_like,
                }

            for comp in components(feature_faces):
                pts = [mw @ v.co for f in comp for v in f.verts]
                if not pts:
                    continue
                cmin = min(float(p[axis]) for p in pts); cmax = max(float(p[axis]) for p in pts)
                center_n = (((cmin + cmax) * 0.5) - float(fmin[axis])) / vspan
                band = classify_band(center_n)
                if band == 'eye':
                    info['rejected_eye_like'] += 1
                elif band == 'nose':
                    info['rejected_nose_like'] += 1
                else:
                    info['rejected_mouth_like'] += 1

            spatial_stats = []
            for ci, comp in enumerate(components(spatial_faces)):
                st = stats_for_component(comp, ci)
                if st is not None:
                    spatial_stats.append(st)
            info['filtered_components'] = int(len(spatial_stats))

            accepted_stats = []
            rejected_stats = []
            audit_rows = []
            for st in spatial_stats:
                accept_primary = bool(st['touches_chin'] and st['low_center'] and st['meaningful_span'] and not (st['feature_like'] == 'mouth' and st['lateral_n'] < 0.40 and st['width_span_n'] < 0.40 and st['count'] < 90))
                if accept_primary:
                    accepted_stats.append(st)
                    info['accepted_jaw_components'] += 1
                    info['accepted_jaw_polygons'] += int(st['count'])
                    reason = 'accepted_jaw'
                else:
                    rejected_stats.append(st)
                    if st['micro_like']:
                        info['rejected_micro_like'] += 1
                        reason = 'micro'
                    else:
                        band = st['feature_like']
                        if band == 'eye':
                            info['rejected_eye_like'] += 1
                            reason = 'eye'
                        elif band == 'nose':
                            info['rejected_nose_like'] += 1
                            reason = 'nose'
                        else:
                            info['rejected_mouth_like'] += 1
                            reason = 'mouth'
                audit_rows.append(
                    f"{st['index']}:{reason}:faces={st['count']},min={st['min_n']:.3f},center={st['center_n']:.3f},max={st['max_n']:.3f},wspan={st['width_span_n']:.3f},lat={st['lateral_n']:.3f},d={st['depth_center_n']:.3f}"
                )

            if not accepted_stats:
                info['component_audit'] = audit_rows[:24]
                info['error'] = 'spatial jaw gate found no safe chin-connected outline component'
                return info

            bridge_rows = []
            for st in rejected_stats:
                if st['micro_like']:
                    continue
                gap = min((bbox_gap(st, acc) for acc in accepted_stats), default=1e9)
                side_profile = st['lateral_n'] >= 0.44
                low_enough = st['center_n'] <= float(info['bridge_center_max']) and st['min_n'] <= float(info['bridge_min_max'])
                not_eye = st['feature_like'] != 'eye' and st['center_n'] < 0.49
                not_central_mouth = not (st['feature_like'] == 'mouth' and st['lateral_n'] < 0.64)
                nose_bridge_ok = (st['feature_like'] != 'nose') or (st['count'] <= 6 and st['width_span_n'] <= 0.24 and st['lateral_n'] >= 0.48)
                bridgeable = bool(side_profile and low_enough and not_eye and not_central_mouth and nose_bridge_ok and gap <= bridge_gap_limit and st['count'] >= 2)
                if bridgeable:
                    accepted_stats.append(st)
                    info['bridged_jaw_components'] += 1
                    info['bridged_jaw_polygons'] += int(st['count'])
                    info['continuity_bridge_applied'] = True
                    bridge_rows.append(
                        f"{st['index']}:bridge:faces={st['count']},gap={gap:.5f},min={st['min_n']:.3f},center={st['center_n']:.3f},max={st['max_n']:.3f},lat={st['lateral_n']:.3f}"
                    )
            if bridge_rows:
                audit_rows.extend(bridge_rows)

            accepted_seed_faces = set()
            accepted_seed_points = []
            for st in accepted_stats:
                accepted_seed_faces.update(st['faces'])
                accepted_seed_points.extend(st.get('pts', []) or [])
            if accepted_seed_points:
                mean_depth = sum(float(p[depth_axis]) for p in accepted_seed_points) / max(len(accepted_seed_points), 1)
                front_sign = 1 if mean_depth >= dcenter else -1
            else:
                front_sign = 0
            info['profile_front_sign'] = int(front_sign)

            profile_faces = set()
            depth_band = float(info.get('profile_depth_band', 0.24))
            for face in profile_source_faces:
                if face in accepted_seed_faces:
                    continue
                p = face_center_world(face)
                vn = (float(p[axis]) - float(fmin[axis])) / vspan
                wn = abs((float(p[width_axis]) - wcenter) / max((wspan * 0.5), 1e-8))
                dn = (float(p[depth_axis]) - float(fmin[depth_axis])) / dspan
                if not (0.22 <= vn <= 0.97):
                    continue
                if wn > 0.62:
                    continue
                front_ok = (dn >= (1.0 - depth_band)) if front_sign > 0 else ((dn <= depth_band) if front_sign < 0 else False)
                if front_ok:
                    profile_faces.add(face)
            info['profile_candidate_polygons'] = int(len(profile_faces))

            profile_stats = []
            for pi, comp in enumerate(components(profile_faces)):
                st = stats_for_component(comp, 1000 + pi)
                if st is not None:
                    profile_stats.append(st)

            profile_targets = list(accepted_stats)
            pending_profile = sorted(profile_stats, key=lambda s: (s['min_n'], s['center_n'], -s['count']))
            profile_rows = []
            changed = True
            while changed and pending_profile:
                changed = False
                remaining = []
                for st in pending_profile:
                    if st['micro_like'] and st['count'] < 3:
                        remaining.append(st)
                        continue
                    front_component = (st['depth_center_n'] >= 0.66 or st['depth_max_n'] >= 0.82) if front_sign > 0 else (st['depth_center_n'] <= 0.34 or st['depth_min_n'] <= 0.18)
                    central_width = st['lateral_n'] <= 0.66 and st['width_span_n'] <= 0.72
                    vertical_ok = st['max_n'] >= 0.30 and st['min_n'] <= 0.97
                    gap = min((bbox_gap(st, target) for target in profile_targets), default=1e9)
                    chain_ok = gap <= profile_gap_limit
                    if front_component and central_width and vertical_ok and chain_ok:
                        profile_targets.append(st)
                        accepted_stats.append(st)
                        info['accepted_profile_components'] += 1
                        info['accepted_profile_polygons'] += int(st['count'])
                        info['profile_chain_applied'] = True
                        changed = True
                        profile_rows.append(
                            f"{st['index']}:profile:faces={st['count']},gap={gap:.5f},min={st['min_n']:.3f},center={st['center_n']:.3f},max={st['max_n']:.3f},lat={st['lateral_n']:.3f},d={st['depth_center_n']:.3f}"
                        )
                    else:
                        remaining.append(st)
                pending_profile = remaining
            info['full_profile_continuity'] = bool(info['accepted_profile_components'] > 0)
            info['profile_component_audit'] = profile_rows[:24]
            if profile_rows:
                audit_rows.extend(profile_rows)

            accepted_faces = set()
            for st in accepted_stats:
                accepted_faces.update(st['faces'])

            keep_faces = accepted_faces
            to_delete = [f for f in list(bm.faces) if f not in keep_faces]
            info['deleted_polygons'] = int(len(to_delete))
            if to_delete:
                try:
                    bmesh.ops.delete(bm, geom=to_delete, context='FACES')
                except Exception:
                    for f in to_delete:
                        try:
                            bm.faces.remove(f)
                        except Exception:
                            pass
            loose_edges = [e for e in bm.edges if not e.link_faces]
            if loose_edges:
                try:
                    bmesh.ops.delete(bm, geom=loose_edges, context='EDGES')
                except Exception:
                    pass
            loose_verts = [v for v in bm.verts if not v.link_faces and not v.link_edges]
            if loose_verts:
                try:
                    bmesh.ops.delete(bm, geom=loose_verts, context='VERTS')
                except Exception:
                    pass

            final_polys = len(bm.faces)
            info['final_outline_polygons'] = int(final_polys)
            info['component_audit'] = audit_rows[:24]
            if final_polys <= 0:
                info['error'] = 'post-solidify isolation produced no outline faces'
                return info
            bm.to_mesh(baked)
        finally:
            bm.free()
        try:
            baked.update(calc_edges=True, calc_edges_loose=True)
        except TypeError:
            baked.update()

        dup.data = baked
        for mod in list(getattr(dup, 'modifiers', []) or []):
            try:
                dup.modifiers.remove(mod)
            except Exception:
                pass
        try:
            baked.materials.clear()
        except Exception:
            while len(baked.materials):
                baked.materials.pop(index=len(baked.materials)-1)
        baked.materials.append(outline_mat)
        for poly in baked.polygons:
            poly.material_index = 0
        if old_mesh is not None and getattr(old_mesh, 'users', 1) == 0:
            try:
                bpy.data.meshes.remove(old_mesh)
            except Exception:
                pass

        try:
            log(
                'V11.9.2.18.5 Uma spatial jaw gate: '
                f'faceShell={info["face_shell_polygons"]} authoredFeaturePolys={info["authored_mask_polygons"]} '
                f'spatialCandidates={info["spatial_candidate_polygons"]} components={info["filtered_components"]} '
                f'acceptedJawComponents={info["accepted_jaw_components"]} acceptedJawPolys={info["accepted_jaw_polygons"]} '
                f'bridgedJawComponents={info["bridged_jaw_components"]} bridgedJawPolys={info["bridged_jaw_polygons"]} '
                f'rejectedEye={info["rejected_eye_like"]} rejectedNose={info["rejected_nose_like"]} '
                f'rejectedMouth={info["rejected_mouth_like"]} rejectedMicro={info["rejected_micro_like"]} '
                f'continuityGap={info["continuity_gap"]:.5f} continuityBridgeApplied={info["continuity_bridge_applied"]} '
                f'profileCandidates={info["profile_candidate_polygons"]} acceptedProfileComponents={info["accepted_profile_components"]} '
                f'acceptedProfilePolys={info["accepted_profile_polygons"]} profileFrontSign={info["profile_front_sign"]} '
                f'profileGap={info["profile_gap_limit"]:.5f} profileChainApplied={info["profile_chain_applied"]} '
                f'final={info["final_outline_polygons"]}'
            )
            if info['component_audit']:
                log('V11.9.2.18.7 Uma jaw/profile component audit: ' + ' | '.join(info['component_audit'][:12]))
            if info.get('profile_component_audit'):
                log('V11.9.2.18.7 Uma full-profile audit: ' + ' | '.join(info['profile_component_audit'][:12]))
        except Exception:
            pass

        info['built'] = True
        return info
    except Exception as exc:
        info['error'] = str(exc)
        return info

def _xdzr8_v119218_uma_authored_mask_material(uv_name, source_materials=None):
    """Build XDZR8's own transparent/ink material from the proven Uma _UV3 meaning."""
    name = 'SaberShader - Face Outline Authored Mask'
    mat = bpy.data.materials.get(name) or bpy.data.materials.new(name=name)
    mat.use_nodes = True
    nt = mat.node_tree
    nt.nodes.clear()

    out = nt.nodes.new('ShaderNodeOutputMaterial')
    out.location = (720, 0)

    uv = nt.nodes.new('ShaderNodeUVMap')
    uv.name = 'XDZR8 V11.9.2.18 • Authored Outline UV'
    uv.label = 'Uma authored outline permission'
    uv.uv_map = str(uv_name)
    uv.location = (-820, 120)

    sep = nt.nodes.new('ShaderNodeSeparateXYZ')
    sep.name = 'XDZR8 V11.9.2.18 • _UV3 Channels'
    sep.location = (-620, 120)
    nt.links.new(uv.outputs['UV'], sep.inputs['Vector'])

    xgt = nt.nodes.new('ShaderNodeMath')
    xgt.operation = 'GREATER_THAN'
    xgt.name = 'XDZR8 V11.9.2.18 • _UV3 X Gate'
    xgt.location = (-420, 220)
    xgt.inputs[1].default_value = 0.90
    nt.links.new(sep.outputs['X'], xgt.inputs[0])

    ygt = nt.nodes.new('ShaderNodeMath')
    ygt.operation = 'GREATER_THAN'
    ygt.name = 'XDZR8 V11.9.2.18 • _UV3 Y Gate'
    ygt.location = (-420, 60)
    ygt.inputs[1].default_value = 0.90
    nt.links.new(sep.outputs['Y'], ygt.inputs[0])

    diff = nt.nodes.new('ShaderNodeMath')
    diff.operation = 'SUBTRACT'
    diff.name = 'XDZR8 V11.9.2.18 • Authored Permission Differential'
    diff.location = (-220, 120)
    nt.links.new(ygt.outputs[0], diff.inputs[0])
    nt.links.new(xgt.outputs[0], diff.inputs[1])

    clamp = nt.nodes.new('ShaderNodeClamp')
    clamp.name = 'XDZR8 V11.9.2.18 • Permission Clamp'
    clamp.location = (-20, 120)
    clamp.inputs['Min'].default_value = 0.0
    clamp.inputs['Max'].default_value = 1.0
    nt.links.new(diff.outputs[0], clamp.inputs['Value'])

    transparent = nt.nodes.new('ShaderNodeBsdfTransparent')
    transparent.name = 'XDZR8 V11.9.2.18 • Masked Transparent'
    transparent.location = (160, -80)

    ink = nt.nodes.new('ShaderNodeEmission')
    ink.name = 'XDZR8 V11.9.2.18 • Authored Face Ink'
    ink.location = (160, 100)
    ink_color, _ink_meta, _ink_sig = _xdzr8_v1192186_color_hash('face', source_materials=source_materials, scene=getattr(bpy.context, 'scene', None), face_support=True)
    ink.inputs['Color'].default_value = ink_color
    ink.inputs['Strength'].default_value = 1.0

    mix = nt.nodes.new('ShaderNodeMixShader')
    mix.name = 'XDZR8 V11.9.2.18 • Authored Permission Mix'
    mix.location = (440, 40)
    nt.links.new(clamp.outputs['Result'], mix.inputs[0])
    nt.links.new(transparent.outputs['BSDF'], mix.inputs[1])
    nt.links.new(ink.outputs['Emission'], mix.inputs[2])
    nt.links.new(mix.outputs['Shader'], out.inputs['Surface'])

    try:
        mat.diffuse_color = ink_color
    except Exception:
        pass
    if hasattr(mat, 'use_backface_culling'):
        mat.use_backface_culling = True

    try:
        mat.surface_render_method = 'DITHERED'
    except Exception:
        try:
            mat.blend_method = 'HASHED'
        except Exception:
            try:
                mat.blend_method = 'BLEND'
            except Exception:
                pass
    try:
        mat.shadow_method = 'NONE'
    except Exception:
        pass
    mat['XDZR8_V11_9_2_18_UmaAuthoredMask'] = True
    mat['XDZR8_V11_9_2_18_UmaAuthoredMaskUV'] = str(uv_name)
    mat['XDZR8_V11_9_2_18_UmaAuthoredMaskRule'] = '(Y>0.9)-(X>0.9)'
    return mat

def _xdzr8_v119218_build_source_topology_mask_outline(src_obj, group, collection, bounds, base_thickness, settings):
    """Build raw-Uma face support without pruning/recalculating source topology."""
    info = {
        'built': False, 'role': 'face', 'reason': '', 'face_support': True,
        'face_support_ribbon': False, 'face_support_ribbon_fallback': False,
        'direct_backface_hull': False, 'solidify_free': False,
        'source_topology_preserved': False, 'split_normals_preserved': False,
        'authored_mask': False, 'authored_mask_uv': '', 'authored_mask_rule': '',
        'face_source_polygons': 0, 'nonface_source_polygons': 0,
        'face_support_thickness': 0.0, 'face_support_multiplier': 0.0,
        'face_support_trim': 1.0, 'face_support_tangent_boost': 0.0,
        'face_support_boundary_loops': 0, 'face_support_outer_boundary_vertices': 0,
        'face_support_tangent_vertices': 0,
        'face_support_materials': list(group.get('materials', []) or []),
        'face_support_indices': list(group.get('indices', []) or []),
        'face_support_filtered_materials': [],
        'face_support_filtered_indices': [],
        'source_polygons': 0, 'evaluated_polygons': 0, 'face_shell_polygons': 0,
        'authored_mask_polygons': 0, 'final_outline_polygons': 0,
        'face_support_role_sources': list(group.get('face_role_sources', []) or []),
        'face_support_slot_role_audit': list(group.get('slot_role_audit', []) or []),
        'face_support_recovery_candidate_audit': list(group.get('recovery_candidate_audit', []) or []),
        'error': '',
    }
    if src_obj is None or getattr(src_obj, 'type', '') != 'MESH' or getattr(src_obj, 'data', None) is None:
        info['error'] = 'missing mesh/object'
        info['reason'] = 'Uma source-topology outline missing source mesh'
        return None, info

    src_mesh = src_obj.data
    uv_name = _xdzr8_v119218_find_authored_outline_uv(src_mesh)
    if not uv_name:
        info['error'] = 'proven _UV3 authored outline permission layer not found'
        info['reason'] = 'Uma authored-mask outline fail-closed: _UV3 unavailable'
        return None, info

    filtered_face_indices, filtered_face_materials = _xdzr8_v1192182_filter_face_indices(group)
    face_indices = {int(i) for i in filtered_face_indices}
    if not face_indices:
        info['error'] = 'no semantically proven Face material indices'
        info['reason'] = 'Uma authored-mask outline fail-closed: no Face indices'
        return None, info

    dup = src_obj.copy()
    try:
        mesh = src_mesh.copy()
    except Exception as exc:
        info['error'] = f'source mesh copy failed: {exc}'
        info['reason'] = 'Uma authored-mask outline source copy failed'
        return None, info
    dup.data = mesh
    try:
        dup.animation_data_clear()
    except Exception:
        pass
    safe_name = re.sub(r'[^A-Za-z0-9_\-]+', '_', src_obj.name)[:52]
    dup.name = f'{XDZR8_V116_OUTLINE_OBJECT_PREFIX}{safe_name}__face'
    dup.matrix_world = src_obj.matrix_world.copy()
    dup.parent = src_obj.parent
    dup.parent_type = src_obj.parent_type
    dup.parent_bone = src_obj.parent_bone
    collection.objects.link(dup)

    for mod in list(getattr(dup, 'modifiers', []) or []):
        if str(getattr(mod, 'type', '')) != 'ARMATURE':
            try:
                dup.modifiers.remove(mod)
            except Exception:
                pass

    original_material_indices = [int(poly.material_index) for poly in mesh.polygons]

    face_source_materials = _xdzr8_v1192186_materials_from_indices(src_obj, filtered_face_indices)
    nonface_base = _xdzr8_v1192181_dedicated_transparent_material('NonFaceBase')
    nonface_shell = _xdzr8_v1192181_dedicated_transparent_material('NonFaceShell')
