    dup.hide_select = True
    dup.show_name = False
    dup.show_in_front = False
    try:
        dup.visible_shadow = False
    except Exception:
        pass

    split_preserved = False
    info['face_support_filtered_materials'] = list(filtered_face_materials)
    info['face_support_filtered_indices'] = [int(i) for i in filtered_face_indices]
    info['source_polygons'] = int(len(getattr(src_mesh, 'polygons', []) or []))
