    dup['XDZR8_V11_9_2_18_2_UmaFinalOutlinePolygons'] = int(baked.get('final_outline_polygons', 0))
    dup['XDZR8_V11_9_2_18_3_UmaSpatialJawGate'] = True
    dup['XDZR8_V11_9_2_18_3_UmaFilteredComponents'] = int(baked.get('filtered_components', 0))
