def _xdzr8_v116_build_shell(src_obj, group, collection, bounds, base_thickness, camera_factor, settings, character_context=None, face_window=None, head_hair_window=None):
    role = str(group.get('role', 'cloth'))
    role_mul = float(XDZR8_V116_ROLE_MULTIPLIER.get(role, 1.0))
    if role_mul <= 0.0:
        return None, {'reason': 'role skipped', 'role': role}
    height = max(float(bounds.get('height', 1.0)), 1e-6)
    try:
        largest_dim = max(abs(float(v)) for v in src_obj.dimensions)
    except Exception:
        largest_dim = height
    if role in {'accessory', 'eyes5', 'mouth'} and largest_dim < height * 0.0045 and int(group.get('polygons', 0)) < 500:
        return None, {'reason': 'micro detail skipped', 'role': role}

    suppressed, suppress_reason = _xdzr8_v1163_should_suppress_hair_shell(src_obj, role, character_context, face_window, head_hair_window, settings)
    if suppressed:
        return None, {'reason': 'face window protected', 'role': role, 'suppressed': True, 'suppression_reason': suppress_reason}

    if bool(group.get('uma_authored_mask_outline', False)) and role == 'face':
        return _xdzr8_v119218_build_source_topology_mask_outline(
            src_obj, group, collection, bounds, base_thickness, settings
        )

    dup = src_obj.copy()
    mesh, sanitation = _sabershader109b310_make_sanitized_shell_mesh(src_obj, settings)
    if mesh is None:
        return None, {'reason': 'sanitation failed', 'role': role}
    dup.data = mesh
    dup.animation_data_clear()
    safe_name = re.sub(r'[^A-Za-z0-9_\-]+', '_', src_obj.name)[:52]
    dup.name = f'{XDZR8_V116_OUTLINE_OBJECT_PREFIX}{safe_name}__{role}'
    dup.matrix_world = src_obj.matrix_world.copy()
    dup.parent = src_obj.parent
    dup.parent_type = src_obj.parent_type
    dup.parent_bone = src_obj.parent_bone
    collection.objects.link(dup)
    _sabershader109b310_sanitize_shell_modifiers(dup, sanitation, settings)
    face_support = bool(group.get('face_support', False))
    face_component_recovery = {
        'built': False, 'candidate_components': 0, 'eligible_components': 0,
        'material_index': -1, 'material_name': '', 'polygons': 0, 'vertices': 0,
        'score': 0.0, 'center_n': 0.0, 'span_n': 0.0,
        'width_center_n': 0.0, 'width_span_n': 0.0,
        'depth_center_n': 0.0, 'depth_span_n': 0.0, 'error': '',
    }
    if face_support and bool(group.get('face_component_recovery', False)):
        face_component_recovery = _xdzr8_v11684_recover_face_surface_component(
            mesh, src_obj, group, character_context
        )
        if not face_component_recovery.get('built', False):
            log(
                f"V11.6.8.5 face component recovery fallback: {src_obj.name}: "
                f"{face_component_recovery.get('error', 'unknown error')}"
            )
            if not _sabershader107a_prune_mesh_to_material_indices(mesh, group.get('indices', []), settings):
                bpy.data.objects.remove(dup, do_unlink=True)
                return None, {'reason': 'empty role geometry after component recovery fallback', 'role': role}
    else:
        if not _sabershader107a_prune_mesh_to_material_indices(mesh, group.get('indices', []), settings):
            bpy.data.objects.remove(dup, do_unlink=True)
            return None, {'reason': 'empty role geometry', 'role': role}

    thickness = max(height * 0.00004, min(height * 0.0040, float(base_thickness) * role_mul * float(camera_factor)))
    trim_mul, trim_reason = _xdzr8_v116_outline_role_trim(src_obj, role, character_context, settings)
    face_support_boost = 1.0
    face_support_multiplier = float(role_mul)
    face_support_tangent_boost = 0.0

    if face_support and role == 'face':
        if bool(group.get('uma_reference_outline', False)):

            face_support_multiplier = 0.46
            trim_mul = 1.00
            trim_reason = 'Uma reference outline architecture jawline'
            face_support_tangent_boost = 0.48
        else:
            face_support_multiplier = float(XDZR8_V11685_FACE_SUPPORT_MULTIPLIER)
            trim_mul = float(XDZR8_V11685_FACE_SUPPORT_TRIM)
            trim_reason = 'face support topology-locked jawline'
            face_support_tangent_boost = float(XDZR8_V11685_FACE_SUPPORT_TANGENT_BOOST)
        thickness = max(
            height * 0.000028,
            min(height * 0.0030, float(base_thickness) * face_support_multiplier * float(camera_factor)),
        )
    else:
        thickness = max(height * 0.000035, thickness * float(trim_mul) * float(face_support_boost))
    dynamic = _xdzr8_v116_has_armature_deform(dup)

    use_direct_hull = (role == 'silhouette') or bool(group.get('use_direct_backface_hull', False))
    if use_direct_hull:
        face_support_ribbon = bool(face_support and role == 'face')
        face_support_ribbon_fallback = False
        ribbon_width = 0.0
        if face_support_ribbon:
            ribbon_width = float(thickness) * max(float(face_support_tangent_boost), 0.0)
            if bool(group.get('uma_reference_outline', False)):
                hull = _xdzr8_v1192161_uma_view_silhouette_jaw_ribbon(
                    mesh, src_obj, ribbon_width, character_context
                )
                if not hull.get('built', False):

                    log(
                        f"V11.9.2.16.1 Uma camera-silhouette fail-closed: {src_obj.name}: "
                        f"{hull.get('error', 'unknown error')}"
                    )
                    try:
                        bpy.data.objects.remove(dup, do_unlink=True)
                    except Exception:
                        pass
                    return None, {
                        'reason': 'Uma camera-silhouette jawline not safely provable',
                        'role': role, 'uma_fail_closed': True,
                        'uma_camera_silhouette_error': str(hull.get('error', 'unknown error')),
                    }
                failure_reason = 'Uma camera-silhouette face support failed'
                warning_label = 'Uma camera-silhouette face-support backend'
            else:
                hull = _xdzr8_v1176_face_support_topology_jawline_ribbon(mesh, src_obj, ribbon_width, character_context)
                if not hull.get('built', False):

                    log(f"V11.7.6 topology-jawline fallback: {src_obj.name}: {hull.get('error', 'unknown error')}")
                    hull = _xdzr8_v11682_face_support_ribbon(mesh, src_obj, ribbon_width)
                    face_support_ribbon_fallback = bool(hull.get('built', False))
                    if not hull.get('built', False):
                        hull = _xdzr8_v1167_direct_backface_hull(mesh, src_obj, bounds, thickness)
                        face_support_ribbon = False
                failure_reason = 'face support backend failed'
                warning_label = 'face-support backend'
        else:
            hull = _xdzr8_v1167_direct_backface_hull(mesh, src_obj, bounds, thickness)
            failure_reason = 'direct hull failed'
            warning_label = 'direct backface hull'
        if not hull.get('built', False):
            log(f"V11.6.8.5 {warning_label} warning: {src_obj.name}: {hull.get('error', 'unknown error')}")
            try:
                bpy.data.objects.remove(dup, do_unlink=True)
            except Exception:
                pass
            return None, {'reason': failure_reason, 'role': role}

        material_assignment = _xdzr8_v1192186_assign_outline_materials(mesh, src_obj, group, role, settings, character_context=character_context, face_support=face_support_ribbon)
        outline_mat = material_assignment.get('primary_material', None) or _xdzr8_v116_material(role, invisible=False, face_support=face_support_ribbon)
        try:
            outline_mat['XDZR8_V11_6_8_5_DirectBackfaceHull'] = bool(not face_support_ribbon)
            outline_mat['XDZR8_V11_6_8_5_FaceSupportRibbon'] = bool(face_support_ribbon)
        except Exception:
            pass

        dup.hide_select = True
        dup.show_name = False
        dup.show_in_front = False
        try:
            dup.visible_shadow = False
        except Exception:
            pass
        dup['XDZR8_V11_6_AdaptiveOutline'] = True
        dup['XDZR8_V11_6_SourceObject'] = src_obj.name
        dup['XDZR8_V11_6_Role'] = role
        dup['XDZR8_V11_6_8_5_FaceSupport'] = bool(face_support)
        dup['XDZR8_V11_6_8_5_FaceSupportBoost'] = float(face_support_boost)
        dup['XDZR8_V11_6_8_5_FaceSupportMultiplier'] = float(face_support_multiplier) if face_support else float(role_mul)
        dup['XDZR8_V11_6_8_5_FaceSupportTrim'] = float(trim_mul) if face_support else 1.0
        dup['XDZR8_V11_6_8_5_FaceSupportTangentBoost'] = float(face_support_tangent_boost) if face_support else 0.0
        dup['XDZR8_V11_6_8_5_FaceSupportBoundaryLoops'] = int(hull.get('boundary_loops', 0)) if face_support else 0
        dup['XDZR8_V11_6_8_5_FaceSupportOuterBoundaryVerts'] = int(hull.get('outer_boundary_vertices', 0)) if face_support else 0
        dup['XDZR8_V11_6_8_5_FaceSupportTangentVerts'] = int(hull.get('tangent_vertices_expanded', 0)) if face_support else 0
        dup['XDZR8_V11_6_Thickness'] = float(thickness)
        dup['XDZR8_V11_6_TrimReason'] = str(trim_reason)
        dup['XDZR8_V11_6_CharacterHeight'] = float(height)
        dup['XDZR8_V11_6_Dynamic'] = bool(dynamic)
        dup['XDZR8_V11_6_StaticClamp'] = False
        dup['XDZR8_V11_6_ClampFacesRemoved'] = 0
        dup['XDZR8_V11_6_8_5_DirectBackfaceHull'] = bool(not face_support_ribbon)
        dup['XDZR8_V11_6_8_5_FaceSupportRibbon'] = bool(face_support_ribbon)
        dup['XDZR8_V11_6_8_5_FaceSupportRibbonFallback'] = bool(face_support_ribbon_fallback)
        dup['XDZR8_V11_6_8_5_FaceSupportRibbonFaces'] = int(hull.get('ribbon_faces', 0)) if face_support_ribbon else 0
        dup['XDZR8_V11_6_8_5_FaceSupportRibbonWidth'] = float(ribbon_width) if face_support_ribbon else 0.0
        dup['XDZR8_V11_6_8_5_JawArcEdges'] = int(hull.get('jaw_arc_edges', 0)) if face_support else 0
        dup['XDZR8_V11_6_8_5_JawArcVertices'] = int(hull.get('jaw_arc_vertices', 0)) if face_support else 0
        dup['XDZR8_V11_6_8_5_JawArcRatio'] = float(hull.get('jaw_arc_ratio', 0.0)) if face_support else 0.0
        dup['XDZR8_V11_6_8_5_JawSurfaceInset'] = bool(hull.get('surface_inset', False)) if face_support else False
