                    new_mat['XDZR8_RoleReason'] = why
                    new_mat['XDZR8_RoleScores'] = ' | '.join(f'{role}:{score:.1f}' for role, score in score_rows)
                    new_mat['XDZR8_ClassifierVersion'] = 'V11.9'
                    new_mat['XDZR8_V11_7_MaterialLocalGeometry'] = bool(local_audit.get('used', False))
                    new_mat['XDZR8_V11_7_MaterialLocalPrimary'] = bool(local_audit.get('primary_mode', False))
                    new_mat['XDZR8_V11_7_MaterialLocalMixed'] = '/'.join(local_audit.get('mixed_roles', []) or [])
