                    new_mat['XDZR8_V11_7_1_PMXBindingRecords'] = '; '.join(binding_row.get('records', []) or [])
                    new_mat['XDZR8_V11_7_1_PMXAliasRejected'] = str(binding_row.get('alias_rejected', '') or '')
                    if fgo_param_row is not None:
                        new_mat['SaberShader_V1028_FGOSourceDiffuseRGBA'] = str(fgo_param_row.get('diffuse_rgba'))
                        new_mat['SaberShader_V1028_FGOSourceBaseColor'] = str(fgo_param_row.get('base_color'))
                        new_mat['SaberShader_V1028_FGOSourceRoughness'] = str(fgo_param_row.get('roughness'))
                        new_mat['SaberShader_V1028_FGOSourceMetallic'] = str(fgo_param_row.get('metallic'))
                        new_mat['SaberShader_V1028_FGOSourceSpecular'] = str(fgo_param_row.get('specular'))
                        new_mat['SaberShader_V1028_FGOSourceAlpha'] = str(fgo_param_row.get('alpha'))
                        new_mat['SaberShader_V1028_FGORampProvenance'] = str(fgo_param_row.get('ramp_provenance', 'NONE'))
                        new_mat['SaberShader_V1028_FGORampRefs'] = '; '.join(fgo_param_row.get('ramp_refs', []))
                        new_mat['SaberShader_V1028_FGOSourceImages'] = '; '.join(f"{x.get('role')}={Path(x.get('image','')).name}" for x in fgo_param_row.get('image_nodes', [])[:16])
                        new_mat['SaberShader_V1028_FGOConstants'] = ' | '.join(fgo_param_row.get('constant_nodes', [])[:16])
                    if bool((source_intelligence.get('fgo_arcade_profile') or {}).get('enabled', False)):
                        _native_row = _sabershader_v1029_material_row(source_intelligence, source_name)
