                found = ', '.join(f'{r}:{Path(p).name}' for r,p in found_paths.items()) if found_paths else 'none'
                score_text = ', '.join(f'{role}={score:.1f}' for role, score in score_rows[:3])
                usage_note = f'; usages={len(users)} objects' if len(users) > 1 else ''
                alpha_note = f'; alpha: {alpha_source or "preserved"} ({alpha_reason})' if alpha_preserved else ''
                resolver_summary = ', '.join(f'{r}:{s}' for r,s in resolver_statuses.items() if s in {'FOUND','MISSING','AMBIGUOUS'}) or 'existing/optional only'
                resolver_rows.append(f'{mat_name}: {resolver_summary}')
                report.append(f'- {mat_name} -> {category} [{role_confidence}] ({why}); scores: {score_text}; folder matches: {found}; resolver: {resolver_summary}{usage_note}{alpha_note}')
