            log(f"SaberShader V1.0.3.6 FGO legacy material parameter audit: materials={fgo_parameter_audit.get('materials',0)} principled={fgo_parameter_audit.get('principled',0)} rampPool={_ramp_pool} directRefs={fgo_parameter_audit.get('direct_ramp',0)} bindingRefs={fgo_parameter_audit.get('binding_ramp',0)} propertyRefs={fgo_parameter_audit.get('property_ramp',0)} resolvedMaterials={fgo_parameter_audit.get('resolved_ramp_materials',0)} unresolvedMaterials={fgo_parameter_audit.get('unresolved_ramp_materials',0)} provenRefs={_resolved_refs!r}")
            for _row in fgo_parameter_audit.get('rows', [])[:32]:
                log(f'SaberShader V1.0.3.2 FGO legacy material source: {_row}')
