            report.append(f'- Source ramp pool: {_ramp_pool}; direct node refs={fgo_parameter_audit.get("direct_ramp",0)}; explicit binding refs={fgo_parameter_audit.get("binding_ramp",0)}; custom-property refs={fgo_parameter_audit.get("property_ramp",0)}')
            report.append(f'- Ramp provenance resolved for {fgo_parameter_audit.get("resolved_ramp_materials",0)} material(s); unresolved/no-guess={fgo_parameter_audit.get("unresolved_ramp_materials",0)}; unique proven refs={len(_resolved_refs)}')
            report += [f'- {row}' for row in fgo_parameter_audit.get('rows', [])[:32]]
