                log(f'SaberShader V1.0.3.6 FGO native cheek source-mask restoration: materials={_cheek_ground_truth} strength={_cheek_strength_value:.3f} sourceMaskRestored={_cheek_source_mask_restored} maskModes={sorted(set(_cheek_mask_modes))!r} colorSource=slot0 maskSource=slot16_rgb_luminance')
