SABERSHADER105A1_SAFE_NO_LINEART = True

def _sabershader105a1_is_generated_lineart_receiver(obj):
    if not obj or obj.type != 'GREASEPENCIL':
        return False
    try:
        if bool(obj.get('SaberShader_V9_LineArtObject', False)):
            return True
    except Exception:
        pass
    return obj.name.startswith('SaberShader V9 • LineArt • ')

def _sabershader105a1_quarantine_lineart(reason='safe cloth test'):
    """Remove only SaberShader-generated LINEART modifiers and hide their GP receivers.

    The crash we are avoiding happens in Blender's C/C++ Line Art evaluator,
    so catching Python exceptions cannot protect Blender. The safest A/B cloth
    test is to keep Line Art out of the depsgraph until the material work is
    validated.
    """
    removed = 0
    receivers = 0
    for obj in list(bpy.data.objects):
        if not _sabershader105a1_is_generated_lineart_receiver(obj):
            continue
        receivers += 1
        for mod in list(obj.modifiers):
            mtype = str(getattr(mod, 'type', ''))
            generated_name = mod.name.startswith('SaberShader V9')
            if mtype in {'LINEART', 'GREASEPENCIL_LINEART'} or generated_name:
                try:
                    obj.modifiers.remove(mod)
                    removed += 1
                except Exception as exc:
                    log(f"V10.5A.1 quarantine: no se pudo quitar {obj.name}/{mod.name}: {exc}")
        try:
            obj.hide_viewport = True
            obj.hide_render = True
            obj['SaberShader_V10_5A1_LineArtQuarantined'] = True
            obj['SaberShader_V10_5A1_LineArtReason'] = str(reason)
        except Exception:
            pass

    scene = getattr(bpy.context, 'scene', None)
    if scene:
        try:
            scene['SaberShader_V10_5A1_SAFE_NO_LINEART'] = True
            scene['SaberShader_V10_5A1_LineArtReceivers'] = int(receivers)
            scene['SaberShader_V10_5A1_LineArtModifiersRemoved'] = int(removed)
        except Exception:
            pass
    log(f"V10.5B SAFE: Line Art quarantined receivers={receivers} modifiers_removed={removed} ({reason})")
    return removed

def _sabershader105a1_lineart_is_quarantined():
    scene = getattr(bpy.context, 'scene', None)
    if not SABERSHADER105A1_SAFE_NO_LINEART:
        return False
    if scene is None:
        return True
    try:
        return bool(scene.get('SaberShader_V10_5A1_SAFE_NO_LINEART', True))
    except Exception:
        return True

