SABERSHADER9_ENABLE_CREASES = True

def _sabershader9_outline_color(char_name):
    """Tinta casi negra cromática, evitando negro RGB absoluto."""
    name = str(char_name).lower()
    if name.startswith("doloris"):
        return (0.008, 0.0055, 0.014, 1.0)
    if name.startswith("oblivionis"):
        return (0.009, 0.0065, 0.016, 1.0)
    return (0.008, 0.006, 0.012, 1.0)

def _sabershader9_get_gp_material(char_name):
    """Create a Grease Pencil stroke material using only non-texture data."""
    name = f"{SABERSHADER9_LINE_MATERIAL_PREFIX}{char_name}"
    mat = bpy.data.materials.get(name)
    if not mat:
        mat = bpy.data.materials.new(name)

    gp_style = getattr(mat, "grease_pencil", None)
    if gp_style is None:
        create_gp = getattr(bpy.data.materials, "create_gpencil_data", None)
        if create_gp is not None:
            try:
                create_gp(mat)
            except Exception as exc:
                log(f"V9 GP material: create_gpencil_data() falló para '{mat.name}': {exc}")
        gp_style = getattr(mat, "grease_pencil", None)

    if gp_style is None:
        raise RuntimeError(
            "No se pudo inicializar el estilo de material Grease Pencil en Blender 5.1; "
            "Material.grease_pencil sigue sin estar disponible después de create_gpencil_data()."
        )

    color = _sabershader9_outline_color(char_name)
    gp_style.color = color
    gp_style.fill_color = (0.0, 0.0, 0.0, 0.0)
    gp_style.mode = 'LINE'
    gp_style.stroke_style = 'SOLID'
    gp_style.show_fill = False
    gp_style.show_stroke = True

    gp_style.stroke_image = None
    gp_style.fill_image = None

    mat.diffuse_color = color
    mat["SaberShader_V9_LineMaterial"] = True
    mat["SaberShader_V9_NoImages"] = True
    return mat

def _sabershader9_get_or_make_source_collection(char_name):
    """Create/reuse a collection that contains the already-existing character meshes."""
    name = f"{SABERSHADER9_LINE_COLLECTION_PREFIX}{char_name}"
    col = bpy.data.collections.get(name)
    if not col:
        col = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(col)

    prefix = f"SaberShader_V8_{char_name}_"
    eye_only = {"eyes", "eyes3", "eyes5", "mouth", "expression", "expression2"}

    for obj in bpy.context.scene.objects:
        if obj.type != 'MESH':
            continue
        if not any(
            slot.material and slot.material.name.startswith(prefix)
            for slot in obj.material_slots
        ):
            continue

        cats = {
            slot.material.get("SaberShader_V8_Category", "")
            for slot in obj.material_slots
            if slot.material and slot.material.name.startswith(prefix)
        }
        cats.discard("")

        if cats and cats.issubset(eye_only):
            continue

        if obj.name not in col.objects:
            try:
                col.objects.link(obj)
            except RuntimeError:

                pass

        lineart = getattr(obj, "lineart", None)
        if lineart is not None:
            try:
                lineart.usage = 'INCLUDE'
            except Exception:
                pass

    col["SaberShader_V9_LineArtSource"] = True
    col["SaberShader_V9_Character"] = char_name
    return col

def _sabershader9_new_gp_object(char_name):
    """Create/reuse the Grease Pencil receiver object for one character."""
    name = f"{SABERSHADER9_LINE_OBJECT_PREFIX}{char_name}"
    existing = bpy.data.objects.get(name)
    if existing and existing.type == 'GREASEPENCIL':
        return existing
    if existing:
        log(f"V9: {name} exists but is not Grease Pencil; creating a safe alternate.")

    old_active = bpy.context.view_layer.objects.active
    old_selected = list(bpy.context.selected_objects)
    try:
        bpy.ops.object.select_all(action='DESELECT')
        bpy.ops.object.grease_pencil_add(
            type='EMPTY',
            use_in_front=False,
            stroke_depth_offset=SABERSHADER9_STROKE_DEPTH_OFFSET,
            use_lights=False,
            stroke_depth_order='3D',
            location=(0.0, 0.0, 0.0),
        )
        obj = bpy.context.view_layer.objects.active
        if not obj:
            raise RuntimeError("bpy.ops.object.grease_pencil_add() no creó un objeto activo.")
        obj.name = name
    finally:
        bpy.ops.object.select_all(action='DESELECT')
        for sel in old_selected:
            if sel and sel.name in bpy.data.objects:
                sel.select_set(True)
        if old_active and old_active.name in bpy.data.objects:
            bpy.context.view_layer.objects.active = old_active

    obj["SaberShader_V9_LineArtObject"] = True
    obj["SaberShader_V9_Character"] = char_name
    return obj

def _sabershader9_setup_gp_data(gp_obj, char_name):
    """Prepare layers/material slot without touching any mesh textures."""
    data = gp_obj.data
    mat = _sabershader9_get_gp_material(char_name)
    if mat.name not in {m.name for m in data.materials if m}:
        data.materials.append(mat)

    try:
        layers = data.layers
        if len(layers) == 0:
            layers.new("V9_Silhouette", set_active=True)
        elif layers.get("V9_Silhouette") is None:
            layers.new("V9_Silhouette", set_active=False)
        if layers.get("V9_Internal") is None:
            layers.new("V9_Internal", set_active=False)
    except Exception as exc:
        log(f"V9 layers: usando las capas existentes ({exc})")

    return mat

def _sabershader9_remove_old_outline_modifiers():
    """Remove legacy V8 inverted-hull outline modifiers from mesh objects only.

    V8 stored its legacy outline marker properties on the OBJECT, not on the
    Modifier. Blender 5.1 Modifier objects do not support IDProperties in this
    context, so calling ``mod.get(...)`` raises TypeError.

    The cleanup therefore:
      1) always removes modifiers with the exact legacy V8 outline names;
      2) also uses the legacy object-level markers to recognize old outline
         modifiers whose exact name may have been altered;
      3) never inspects custom properties on a Modifier and never removes
         unrelated modifiers.
    """
    old_names = {
        "SaberShader V8.18 • Sanzigen Outline",
        "SaberShader V8.19 • Sanzigen Outline",
        "SaberShader V8.20 • Sanzigen Outline",
        "SaberShader V8.21 • Sanzigen Outline",
    }
    old_prefix = "SaberShader V8."
    marker_names = (
        "SaberShader_V8_19_Outline",
        "SaberShader_V8_21_OutlineWidth",
    )

    removed = 0
    for obj in bpy.context.scene.objects:
        if obj.type != 'MESH':
            continue

        has_legacy_marker = (
            obj.get("SaberShader_V8_19_Outline") is not None
            or obj.get("SaberShader_V8_21_OutlineWidth") is not None
        )

        for mod in list(obj.modifiers):
            is_exact_legacy_name = mod.name in old_names

            is_marked_legacy_outline = (
                has_legacy_marker
                and mod.name.startswith(old_prefix)
                and "Outline" in mod.name
            )

            if is_exact_legacy_name or is_marked_legacy_outline:
                log(f"V9 cleanup: removing old outline modifier '{mod.name}' from '{obj.name}'")
                obj.modifiers.remove(mod)
                removed += 1

    return removed

def _sabershader9_new_lineart_modifier(gp_obj, name, source_collection, material, radius,
                               *, silhouette=False, creases=False, materials=False,
                               intersections=False, light_contour=False, shadow=False,
                               light_object=None, shadow_profile="AVE", use_cache=False,
                               layer_name="", opacity=1.0):
    """Create/configure a Blender 5.1 Line Art modifier."""
    mod = next((m for m in gp_obj.modifiers if m.name == name), None)
    if mod is None:
        try:
            mod = gp_obj.modifiers.new(name=name, type='LINEART')
        except TypeError:

            mod = gp_obj.modifiers.new(name=name, type='GREASEPENCIL_LINEART')

    mod.show_viewport = True
    mod.show_render = True

    mod.source_type = 'COLLECTION'
    mod.source_collection = source_collection
    mod.use_custom_camera = bool(bpy.context.scene.camera)
    if bpy.context.scene.camera:
        mod.source_camera = bpy.context.scene.camera

    mod.target_material = material
    if layer_name:
        mod.target_layer = layer_name

    mod.radius = float(radius)
    mod.opacity = float(max(0.0, min(1.0, opacity)))
    mod.overscan = 0.1
    mod.stroke_depth_offset = SABERSHADER9_STROKE_DEPTH_OFFSET
    mod.use_back_face_culling = True
    mod.smooth_tolerance = SABERSHADER9_SMOOTH_TOLERANCE
    mod.chaining_image_threshold = SABERSHADER9_CHAIN_THRESHOLD
    mod.split_angle = SABERSHADER9_SPLIT_ANGLE
    mod.use_cache = bool(use_cache)

    mod.use_contour = bool(silhouette)
    mod.use_crease = bool(creases)
    mod.use_material = bool(materials)
    mod.use_intersection = bool(intersections)
    mod.use_light_contour = bool(light_contour)
    mod.use_shadow = bool(shadow)
    if light_contour or shadow:
        mod.light_contour_object = light_object
        _sabershader98_prepare_shadow_camera(mod, source_collection, shadow_profile)

    if creases or light_contour or shadow or materials or intersections:
        _sabershader99_configure_secondary_modifier(mod, shadow_profile)
    mod.use_edge_mark = False
    mod.use_loose = False

    if silhouette:

        try:
            mod.silhouette_filtering = 'GROUP'
        except Exception:
            pass

    if creases:
        mod.crease_threshold = float(SABERSHADER9_CREASE_THRESHOLD_DEG) * 3.141592653589793 / 180.0
        mod.use_crease_on_smooth = False
        mod.use_crease_on_sharp = True

    if hasattr(mod, "fill_strokes"):
        mod.fill_strokes = False

    gp_obj["SaberShader_V9_LineArt"] = True
    gp_obj["SaberShader_V9_Radius"] = float(radius)
    return mod

def apply_camera_lineart(char_name, enabled=True):
    """Build the V9 camera-dependent Grease Pencil Line Art system."""
    if not enabled:
        return 0

    scene = bpy.context.scene
    if not scene.camera:
        log(f"V9 Line Art {char_name}: NO active camera; object will be created but strokes need a camera.")

    removed = _sabershader9_remove_old_outline_modifiers()
    if removed:
        log(f"V9: removed {removed} old V8 outline modifiers")

    source_col = _sabershader9_get_or_make_source_collection(char_name)
    settings = getattr(scene, "sabershader_settings", None)
    profile = getattr(settings, "shot_profile", "AVE") if settings else "AVE"
    suppression_enabled = bool(getattr(settings, "build_artist_line_suppression", True)) if settings else True
    suppression = float(getattr(settings, "line_suppression_strength", 0.70)) if settings else 0.70
    detail_col = _sabershader99_get_or_make_detail_collection(char_name, profile, suppression) if suppression_enabled else source_col
    gp_obj = _sabershader9_new_gp_object(char_name)
    material = _sabershader9_setup_gp_data(gp_obj, char_name)

    for mod in list(gp_obj.modifiers):
        if mod.name.startswith(SABERSHADER9_LINE_MOD_PREFIX):
            gp_obj.modifiers.remove(mod)

    if not scene.camera:

        gp_obj.hide_render = True
        log(f"V9 Line Art {char_name}: GP receiver created but render disabled because scene.camera is missing.")
        return 0

    gp_obj.hide_render = False

    _sabershader9_new_lineart_modifier(
        gp_obj,
        f"{SABERSHADER9_LINE_MOD_PREFIX}Silhouette",
        source_col,
        material,
        SABERSHADER9_SILHOUETTE_RADIUS,
        silhouette=True,
        creases=False,
        materials=False,
        intersections=False,
        use_cache=False,
        layer_name="V9_Silhouette",
    )

    count = 1

    if SABERSHADER9_ENABLE_CREASES:
        _sabershader9_new_lineart_modifier(
            gp_obj,
            f"{SABERSHADER9_LINE_MOD_PREFIX}Creases",
            detail_col,
            material,
            SABERSHADER9_INTERNAL_RADIUS,
            silhouette=False,
            creases=True,
            materials=False,
            intersections=False,
            use_cache=True,
            layer_name="V9_Internal",
        )
        count += 1

    if SABERSHADER9_ENABLE_MATERIAL_BORDERS:
        _sabershader9_new_lineart_modifier(
            gp_obj,
            f"{SABERSHADER9_LINE_MOD_PREFIX}MaterialBorders",
            detail_col,
            material,
            SABERSHADER9_MATERIAL_RADIUS,
            silhouette=False,
            creases=False,
            materials=True,
            intersections=False,
            use_cache=True,
            layer_name="V9_Internal",
        )
        count += 1

    if SABERSHADER9_ENABLE_INTERSECTIONS:
        _sabershader9_new_lineart_modifier(
            gp_obj,
            f"{SABERSHADER9_LINE_MOD_PREFIX}Intersections",
            detail_col,
            material,
            SABERSHADER9_INTERNAL_RADIUS,
            silhouette=False,
            creases=False,
            materials=False,
            intersections=True,
            use_cache=True,
            layer_name="V9_Internal",
        )
        count += 1

    settings = getattr(scene, "sabershader_settings", None)
    profile = getattr(settings, "shot_profile", "AVE") if settings else "AVE"
    style = SABERSHADER98_STYLE.get(profile, SABERSHADER98_STYLE["AVE"])
    reference_light = _sabershader98_find_reference_light()
    light_enabled = bool(getattr(settings, "build_light_contour_lines", True)) if settings else True
    shadow_enabled = bool(getattr(settings, "build_shadow_line_art", True)) if settings else True

    if reference_light and light_enabled:
        _sabershader9_new_lineart_modifier(gp_obj, f"{SABERSHADER98_LINE_PREFIX}Light Contour", detail_col, material, style["light"],
                                   light_contour=True, light_object=reference_light, shadow_profile=profile,
                                   use_cache=True, layer_name="V9_Internal", opacity=style["light_opacity"])
        count += 1
    if reference_light and shadow_enabled:
        _sabershader9_new_lineart_modifier(gp_obj, f"{SABERSHADER98_LINE_PREFIX}Cast Shadow", detail_col, material, style["shadow"],
                                   shadow=True, light_object=reference_light, shadow_profile=profile,
                                   use_cache=True, layer_name="V9_Internal", opacity=style["shadow_opacity"])
        count += 1

    gp_obj["SaberShader_V9_8_Profile"] = profile
    gp_obj["SaberShader_V9_8_LightObject"] = reference_light.name if reference_light else ""
    gp_obj["SaberShader_V9_8_LightContourEnabled"] = bool(reference_light and light_enabled)
    gp_obj["SaberShader_V9_8_ShadowLinesEnabled"] = bool(reference_light and shadow_enabled)
    gp_obj["SaberShader_V9_9_DetailSource"] = detail_col.name if detail_col else source_col.name
    gp_obj["SaberShader_V9_9_LineSuppressionEnabled"] = bool(suppression_enabled)
    gp_obj["SaberShader_V9_9_LineSuppressionStrength"] = float(suppression)
    gp_obj["SaberShader_V9_9_SuppressionMode"] = "secondary passes only; silhouette untouched"
    gp_obj["SaberShader_V9_LineArtMethod"] = "Grease Pencil Line Art"
    gp_obj["SaberShader_V9_SourceCollection"] = source_col.name
    gp_obj["SaberShader_V9_ActiveCamera"] = scene.camera.name if scene.camera else ""
    gp_obj["SaberShader_V9_SilhouetteRadius"] = SABERSHADER9_SILHOUETTE_RADIUS
    gp_obj["SaberShader_V9_InternalRadius"] = SABERSHADER9_INTERNAL_RADIUS
    gp_obj["SaberShader_V9_CreaseThresholdDegrees"] = SABERSHADER9_CREASE_THRESHOLD_DEG
    gp_obj["SaberShader_V9_NoImageTexturesChanged"] = True

    log(
        f"V9 Line Art {char_name}: object={gp_obj.name} source={source_col.name} "
        f"passes={count} silhouette_radius={SABERSHADER9_SILHOUETTE_RADIUS:.6f} "
        f"internal_radius={SABERSHADER9_INTERNAL_RADIUS:.6f}"
    )
    return count

SABERSHADER91_TERTIARY_PREFIX = "SaberShader V9.1 • Tertiary • "
SABERSHADER91_LIGHT_COLOR = (1.0, 0.82, 0.68, 1.0)
SABERSHADER91_SHADOW_COLOR = (0.34, 0.38, 0.52, 1.0)
SABERSHADER91_COMP_PREFIX = "SaberShader V9.1 • Shoot • "

def _sabershader91_character_meshes(char_name):
    prefix = f"SaberShader_V8_{char_name}_"
    return [o for o in bpy.context.scene.objects if o.type == 'MESH' and any(s.material and s.material.name.startswith(prefix) for s in o.material_slots)]

def _sabershader91_gp_mat(name, color):
    mat = bpy.data.materials.get(name) or bpy.data.materials.new(name)
    gp = getattr(mat, 'grease_pencil', None)
    if gp is None and hasattr(bpy.data.materials, 'create_gpencil_data'):
        try: bpy.data.materials.create_gpencil_data(mat)
        except Exception as exc: log(f"V9.1 GP material: {exc}")
    gp = getattr(mat, 'grease_pencil', None)
    if gp is None: raise RuntimeError(f"No se pudo crear material GP: {name}")
    gp.color=color; gp.fill_color=(0,0,0,0); gp.mode='LINE'; gp.stroke_style='SOLID'; gp.show_fill=False; gp.show_stroke=True
    gp.stroke_image=None; gp.fill_image=None; mat.diffuse_color=color; mat["SaberShader_V9_1_Tertiary"]=True
    return mat

def _sabershader91_receiver(char_name, kind, color):
    name=f"{SABERSHADER91_TERTIARY_PREFIX}{char_name} • {kind}"
    obj=bpy.data.objects.get(name)
    if obj and obj.type=='GREASEPENCIL': return obj
    old_active=bpy.context.view_layer.objects.active; old_selected=list(bpy.context.selected_objects)
    try:
        bpy.ops.object.select_all(action='DESELECT')
        bpy.ops.object.grease_pencil_add(type='EMPTY', use_in_front=False, stroke_depth_offset=0.004, use_lights=False, stroke_depth_order='3D', location=(0,0,0))
        obj=bpy.context.view_layer.objects.active
        if not obj: raise RuntimeError(f"No se pudo crear {name}")
        obj.name=name
    finally:
        bpy.ops.object.select_all(action='DESELECT')
        for o in old_selected:
            if o and o.name in bpy.data.objects: o.select_set(True)
        if old_active and old_active.name in bpy.data.objects: bpy.context.view_layer.objects.active=old_active
    mat=_sabershader91_gp_mat(f"SaberShader V9.1 • {kind} Ink",color)
    if mat.name not in {m.name for m in obj.data.materials if m}: obj.data.materials.append(mat)
    try:
        if obj.data.layers.get(f"V9_1_{kind}") is None: obj.data.layers.new(f"V9_1_{kind}", set_active=True)
    except Exception as exc: log(f"V9.1 layer {name}: {exc}")
    obj["SaberShader_V9_1_Tertiary"]=True; obj["SaberShader_V9_1_Character"]=char_name; obj["SaberShader_V9_1_TertiaryKind"]=kind; obj["SaberShader_V9_1_UsePerShot"]=True
    obj["SaberShader_V9_1_ActiveCamera"]=bpy.context.scene.camera.name if bpy.context.scene.camera else ""
    obj["SaberShader_V9_1_Instruction"]="Manual drawing layer: hair rim, cheek/forehead light, facial shadow, dramatic highlights"
    return obj

def build_v91_tertiary(char_name):
    _sabershader91_receiver(char_name,'Light',SABERSHADER91_LIGHT_COLOR); _sabershader91_receiver(char_name,'Shadow',SABERSHADER91_SHADOW_COLOR)
    return 2

def _sabershader91_face_objects(char_name):
    prefix=f"SaberShader_V8_{char_name}_"; cats={"face","mouth","expression","expression2"}; out=[]
    for o in _sabershader91_character_meshes(char_name):
        if any(s.material and s.material.name.startswith(prefix) and s.material.get("SaberShader_V8_Category","") in cats for s in o.material_slots): out.append(o)
    return out

def _sabershader91_shape_key(obj,name,compress):
    if obj.data.shape_keys and obj.data.shape_keys.key_blocks.get(name): return False
    if not obj.data.shape_keys: obj.shape_key_add(name='Basis')
    key=obj.shape_key_add(name=name); verts=obj.data.vertices
    if not verts: return False
    cx=sum(v.co.x for v in verts)/len(verts)
    for i,v in enumerate(verts):
        key.data[i].co.x=cx+(v.co.x-cx)*(1.0-compress); key.data[i].co.y=v.co.y; key.data[i].co.z=v.co.z
    key.value=0.0; key.slider_min=0.0; key.slider_max=1.0

    obj["SaberShader_V9_1_Corrective_" + name] = True
    return True

def build_v91_face_corrections(char_name):
    n=0
    for o in _sabershader91_face_objects(char_name):
        n+=int(_sabershader91_shape_key(o,'V9_1_Face_3Q',0.055)); n+=int(_sabershader91_shape_key(o,'V9_1_Face_Profile',0.125)); o["SaberShader_V9_1_FaceCorrection"]=True
    return n

def build_v91_shoot_composite(profile='AVE'):
    """V9.1 compositor compatible con Blender 5.x.

    Blender 5.0+ separa el compositor del Scene y lo expone como
    scene.compositing_node_group. El antiguo CompositorNodeComposite
    fue sustituido por Group Output.
    """
    scene = bpy.context.scene

    tree = getattr(scene, 'compositing_node_group', None)
    if tree is None:
        tree = bpy.data.node_groups.new(
            name=f"SaberShader V9.1 • Compositor • {scene.name}",
            type='CompositorNodeTree'
        )
        scene.compositing_node_group = tree

    nodes = tree.nodes
    links = tree.links

    image_socket = None
    for item in tree.interface.items_tree:
        if getattr(item, 'item_type', None) == 'SOCKET' and getattr(item, 'in_out', None) == 'OUTPUT' and item.name == 'Image':
            image_socket = item
            break
    if image_socket is None:
        image_socket = tree.interface.new_socket(
            name='Image', in_out='OUTPUT', socket_type='NodeSocketColor'
        )

    for node in list(nodes):
        if node.name.startswith(SABERSHADER91_COMP_PREFIX):
            nodes.remove(node)

    rl = nodes.get('Render Layers')
    if rl is None or rl.bl_idname != 'CompositorNodeRLayers':
        rl = nodes.new(type='CompositorNodeRLayers')
    rl.name = f"{SABERSHADER91_COMP_PREFIX}Render Layers"
    rl.label = 'V9.1 Shoot • Render Layers'
    rl.scene = scene
    rl.location = (-300, 0)

    grade = nodes.new(type='CompositorNodeColorBalance')
    grade.name = f"{SABERSHADER91_COMP_PREFIX}Color Grade"
    grade.label = f"V9.1 Shoot • {profile}"
    grade.location = (0, 0)

    glare = nodes.new(type='CompositorNodeGlare')
    glare.name = f"{SABERSHADER91_COMP_PREFIX}Selective Bloom"
    glare.label = 'V9.1 Shoot • Selective Bloom'

    def _set_input(node, name, value):
        sock = node.inputs.get(name)
        if sock is not None:
            try:
                sock.default_value = value
            except (TypeError, ValueError):
                pass
    _set_input(glare, 'Type', 'Fog Glow')
    _set_input(glare, 'Quality', 'High')
    _set_input(glare, 'Threshold', 1.2)

    _set_input(glare, 'Size', 0.7)
    _set_input(glare, 'Strength', 0.08 if profile == 'MYGO' else 0.12)
    glare.location = (300, 0)

    group_out = nodes.get('Group Output')
    if group_out is None or group_out.bl_idname != 'NodeGroupOutput':
        group_out = nodes.new(type='NodeGroupOutput')
    group_out.name = f"{SABERSHADER91_COMP_PREFIX}Group Output"
    group_out.label = 'V9.1 Shoot • Output'
    group_out.location = (600, 0)

    targets = {grade, glare, group_out}
    for link in list(links):
        if link.to_node in targets:
            links.remove(link)

    if rl.outputs.get('Image') and grade.inputs.get('Image'):
        links.new(rl.outputs['Image'], grade.inputs['Image'])
    if grade.outputs.get('Image') and glare.inputs.get('Image'):
        links.new(grade.outputs['Image'], glare.inputs['Image'])

    out_socket = group_out.inputs.get('Image')
    if out_socket and glare.outputs.get('Image'):
        links.new(glare.outputs['Image'], out_socket)

    scene['SaberShader_V9_1_ShotProfile'] = profile
    scene['SaberShader_V9_1_TertiaryMix'] = 1.0
    scene['SaberShader_V9_1_ShotContrast'] = 1.0 if profile == 'MYGO' else 1.06
    scene['SaberShader_V9_1_BloomStrength'] = 0.015 if profile == 'MYGO' else 0.035
    scene.render.use_compositing = True

    return 1

SABERSHADER92_PREFIX = "SaberShader V9.2 • "
SABERSHADER92_ART_PREFIX = SABERSHADER92_PREFIX + "ArtLight • "
SABERSHADER92_LINE_PREFIX = SABERSHADER92_PREFIX + "Line • "

SABERSHADER92_KEY_DIR = {
    "MYGO": (-0.28, -0.86, 0.42),
    "AVE":  (-0.42, -0.78, 0.46),
}
SABERSHADER92_STYLE = {
    "MYGO": {
        "shadow": (0.80, 0.84, 0.92, 1.0),
        "mid":    (0.94, 0.95, 0.98, 1.0),
        "light":  (1.00, 0.99, 0.96, 1.0),
        "highlight": (1.00, 0.88, 0.78, 1.0),
        "art_fac": 0.30,
        "edge_fac": 0.10,
    },
    "AVE": {
        "shadow": (0.70, 0.73, 0.86, 1.0),
        "mid":    (0.92, 0.93, 0.98, 1.0),
        "light":  (1.00, 0.97, 0.91, 1.0),
        "highlight": (1.00, 0.70, 0.78, 1.0),
        "art_fac": 0.38,
        "edge_fac": 0.13,
    },
}

def _sabershader92_remove_old_art_nodes(group):
    if not group:
        return
    nodes, links = group.nodes, group.links
    mix = nodes.get(SABERSHADER92_ART_PREFIX + "Mix")
    if mix:
        for n in nodes:
            if n.bl_idname not in {'ShaderNodeEmission', 'ShaderNodeBsdfPrincipled'}:
                continue
            inp = n.inputs.get('Base Color') or n.inputs.get('Color')
            if not inp or not inp.is_linked or inp.links[0].from_node != mix:
                continue
            source = mix.inputs.get('Color1')
            if source and source.is_linked:
                for lk in list(inp.links):
                    links.remove(lk)
                links.new(source.links[0].from_socket, inp)
    for n in list(nodes):
        if n.name.startswith(SABERSHADER92_ART_PREFIX):
            nodes.remove(n)

def _sabershader92_ramp(ramp, profile, category):
    s = SABERSHADER92_STYLE[profile]
    shadow = s['shadow']
    mid = s['mid']
    light = s['light']
    if category == 'hair':
        shadow = (0.58, 0.63, 0.78, 1.0) if profile == 'MYGO' else (0.52, 0.50, 0.70, 1.0)
        mid = (0.88, 0.91, 0.98, 1.0)
    elif category in {'face','mouth','expression','expression2'}:
        shadow = (0.84, 0.86, 0.92, 1.0) if profile == 'MYGO' else (0.78, 0.80, 0.90, 1.0)
    elif category in {'cloth','skirt','stockings','boots','glove','bow','tie'}:
        shadow = (0.76, 0.79, 0.88, 1.0) if profile == 'MYGO' else (0.68, 0.70, 0.83, 1.0)
    rr = ramp.color_ramp
    while len(rr.elements) > 3:
        rr.elements.remove(rr.elements[-1])
    if len(rr.elements) < 2:
        rr.elements.new(0.5)
    if len(rr.elements) < 3:
        rr.elements.new(0.76)
    rr.elements[0].position = 0.24; rr.elements[0].color = shadow
    rr.elements[1].position = 0.50; rr.elements[1].color = mid
    rr.elements[2].position = 0.76; rr.elements[2].color = light
    rr.interpolation = 'EASE'

def _sabershader92_apply_art_light(group, category, profile):
    if not group:
        return False, 'grupo inexistente'

    if bool(group.get("SaberShader_V10_5A_DesignedCloth", False)) or bool(group.get("SaberShader_V10_5B_RefinedCloth", False)):
        return False, 'V10.6C.1 Cloth Final Polish: V9.2 omitido para evitar doble sombreado'
    if category in {'eyes','eyes3','eyes5'}:
        return False, 'ojos preservados'
    if _sabershader15_is_transparent_material(group):
        return False, 'alpha/transparencia preservados'
    before = _sabershader15_image_link_signature(group)
    _sabershader92_remove_old_art_nodes(group)
    nodes, links = group.nodes, group.links
    output = nodes.get('Group Output')
    if not output:
        return False, 'sin Group Output'
    shader_out = next((s for s in output.inputs if s.type == 'SHADER'), None)
    if not shader_out or not shader_out.is_linked:
        return False, 'sin shader final conectado'
    final = shader_out.links[0].from_node
    color_input = None
    if final.bl_idname == 'ShaderNodeBsdfPrincipled':
        color_input = final.inputs.get('Base Color')
    elif final.bl_idname == 'ShaderNodeEmission':
        color_input = final.inputs.get('Color')
    else:
        final = nodes.get('SaberShader Face Principled') or nodes.get('SaberShader Face Principled Toon') or nodes.get('SaberShader Anime Toon Emission') or nodes.get('Emission') or nodes.get('Principled BSDF')
        if final:
            color_input = final.inputs.get('Base Color') or final.inputs.get('Color')
    if not final or not color_input:
        return False, 'shader/color path no encontrado'
    if color_input.is_linked and color_input.links[0].from_node.bl_idname == 'ShaderNodeTexImage':
        return False, 'protección Image Texture activa'
    source_socket = color_input.links[0].from_socket if color_input.is_linked else None
    source_value = None
    if source_socket is None:
        try: source_value = tuple(color_input.default_value)
        except Exception: source_value = (1.0, 1.0, 1.0, 1.0)

    s = SABERSHADER92_STYLE[profile]
    base = final.location
    mx = nodes.new('ShaderNodeMixRGB')
    mx.name = SABERSHADER92_ART_PREFIX+'Mix'; mx.label='V9.2 • Artistic Light'; mx.blend_type='MULTIPLY'; mx.inputs['Fac'].default_value=s['art_fac']; mx.location=(base.x-260, base.y+220)
    if source_socket is not None: links.new(source_socket, mx.inputs['Color1'])
    else: mx.inputs['Color1'].default_value=source_value

    is_face_npr = category in {'face','mouth','expression','expression2'}
    ramp = nodes.new('ShaderNodeValToRGB'); ramp.name=SABERSHADER92_ART_PREFIX+'Band Ramp'; ramp.label='V9.2 • 3-band artistic light'; ramp.location=(mx.location.x-100,mx.location.y-30); _sabershader92_ramp(ramp,profile,category)

    if is_face_npr:

        tc = nodes.new('ShaderNodeTexCoord'); tc.name=SABERSHADER92_ART_PREFIX+'Face Coord'; tc.location=(mx.location.x-760,mx.location.y-20)
        sep = nodes.new('ShaderNodeSeparateXYZ'); sep.name=SABERSHADER92_ART_PREFIX+'Face XYZ'; sep.location=(mx.location.x-560,mx.location.y-20)
        rem = nodes.new('ShaderNodeMapRange'); rem.name=SABERSHADER92_ART_PREFIX+'Face Side'; rem.location=(mx.location.x-360,mx.location.y-20); rem.clamp=True
        rem.inputs['From Min'].default_value=0.34; rem.inputs['From Max'].default_value=0.66; rem.inputs['To Min'].default_value=1.0; rem.inputs['To Max'].default_value=0.0
        links.new(tc.outputs['Generated'], sep.inputs['Vector']); links.new(sep.outputs['X'], rem.inputs['Value']); links.new(rem.outputs['Result'],ramp.inputs['Fac'])
    else:
        geo = nodes.new('ShaderNodeNewGeometry'); geo.name=SABERSHADER92_ART_PREFIX+'Normal'; geo.location=(mx.location.x-760,mx.location.y-20)
        dot = nodes.new('ShaderNodeVectorMath'); dot.name=SABERSHADER92_ART_PREFIX+'Key Dot'; dot.operation='DOT_PRODUCT'; dot.location=(mx.location.x-560,mx.location.y-20)
        kd=SABERSHADER92_KEY_DIR[profile]; mag=(kd[0]*kd[0]+kd[1]*kd[1]+kd[2]*kd[2])**0.5; dot.inputs[1].default_value=(kd[0]/mag,kd[1]/mag,kd[2]/mag)
        rem = nodes.new('ShaderNodeMapRange'); rem.name=SABERSHADER92_ART_PREFIX+'Key Remap'; rem.location=(mx.location.x-360,mx.location.y-20); rem.clamp=True
        rem.inputs['From Min'].default_value=-0.15; rem.inputs['From Max'].default_value=0.95; rem.inputs['To Min'].default_value=0.0; rem.inputs['To Max'].default_value=1.0
        links.new(geo.outputs['Normal'],dot.inputs[0]); links.new(dot.outputs['Value'],rem.inputs['Value']); links.new(rem.outputs['Result'],ramp.inputs['Fac'])

    links.new(ramp.outputs['Color'], mx.inputs['Color2'])

    hm=nodes.new('ShaderNodeMixRGB'); hm.name=SABERSHADER92_ART_PREFIX+'Highlight'; hm.label='V9.2 • Controlled highlight'; hm.blend_type='ADD'; hm.inputs[2].default_value=s['highlight']; hm.location=(mx.location.x+160,mx.location.y+100)
    links.new(mx.outputs['Color'],hm.inputs['Color1'])
    if is_face_npr:

        hm.inputs['Fac'].default_value=0.0
    else:
        lw=nodes.new('ShaderNodeLayerWeight'); lw.name=SABERSHADER92_ART_PREFIX+'Facing'; lw.location=(mx.location.x-80,mx.location.y-260)
        hr=nodes.new('ShaderNodeValToRGB'); hr.name=SABERSHADER92_ART_PREFIX+'Highlight Ramp'; hr.location=(mx.location.x+120,mx.location.y-260)
        hrr=hr.color_ramp; hrr.elements[0].position=0.80; hrr.elements[0].color=(0,0,0,1); hrr.elements[1].position=0.95; hrr.elements[1].color=(1,1,1,1)
        links.new(lw.outputs.get('Facing'),hr.inputs['Fac']); links.new(hr.outputs['Color'],hm.inputs['Fac'])

    for lk in list(color_input.links): links.remove(lk)
    links.new(hm.outputs['Color'],color_input)
    after=_sabershader15_image_link_signature(group)
    if before!=after:
        raise RuntimeError(f'V9.2 safety check FAILED: Image Texture links changed on {group.name}')
    group['SaberShader_V9_2_ArtLight']=True; group['SaberShader_V9_2_Profile']=profile
    return True, ('3-band Face SDF side-light; no local normals' if is_face_npr else '3-band key + controlled facing highlight')

def build_v92_artistic_lighting(char_name, profile='AVE'):
    count=0; prefix=f'SaberShader_V8_{char_name}_'
    for obj in bpy.context.scene.objects:
        if obj.type!='MESH': continue
        for slot in obj.material_slots:
            mat=slot.material
            if not mat or not mat.name.startswith(prefix): continue
            group_node=mat.node_tree.nodes.get('XDZR8_V8') if getattr(mat,'use_nodes',False) else None
            group=group_node.node_tree if group_node else None
            if group is not None:
                ok,_=_sabershader92_apply_art_light(group,mat.get('SaberShader_V8_Category','cloth'),profile)
                if ok: count+=1
            break
    return count

def _sabershader92_line_material(name,color):
    mat=bpy.data.materials.get(name) or bpy.data.materials.new(name)
    gp=getattr(mat,'grease_pencil',None)
    if gp is None and hasattr(bpy.data.materials,'create_gpencil_data'):
        try: bpy.data.materials.create_gpencil_data(mat)
        except Exception: pass
    gp=getattr(mat,'grease_pencil',None)
    if gp is None: raise RuntimeError(f'No se pudo crear material GP: {name}')
    gp.color=color; gp.fill_color=(0,0,0,0); gp.mode='LINE'; gp.stroke_style='SOLID'; gp.show_fill=False; gp.show_stroke=True
    mat.diffuse_color=color
    return mat

def build_v92_line_hierarchy(char_name):
    gp=bpy.data.objects.get(f'SaberShader V9 • LineArt • {char_name}')
    if not gp or gp.type!='GREASEPENCIL': return 0
    sil=_sabershader92_line_material(f'{SABERSHADER92_LINE_PREFIX}{char_name} • Silhouette Ink',(0.006,0.004,0.012,1))
    inner=_sabershader92_line_material(f'{SABERSHADER92_LINE_PREFIX}{char_name} • Internal Ink',(0.028,0.024,0.040,1))
    for mat in (sil,inner):
        if mat.name not in {m.name for m in gp.data.materials if m}: gp.data.materials.append(mat)
    n=0
    for mod in gp.modifiers:
        if not mod.name.startswith(SABERSHADER9_LINE_MOD_PREFIX): continue
        try:
            if 'Silhouette' in mod.name:
                mod.target_material=sil; mod.radius=0.00155; mod.opacity=1.0; n+=1
            elif 'Creases' in mod.name:
                mod.target_material=inner; mod.radius=0.00062; mod.opacity=0.72; mod.crease_threshold=50.0*3.141592653589793/180.0; n+=1
        except Exception as exc:
            log(f'V9.2 Line hierarchy {char_name}: {exc}')
    gp['SaberShader_V9_2_LineHierarchy']=True; gp['SaberShader_V9_2_SilhouetteRadius']=0.00155; gp['SaberShader_V9_2_InternalRadius']=0.00062
    return n

def _sabershader92_smoothstep(a,b,x):
    if b<=a: return 0.0
    q=max(0.0,min(1.0,(x-a)/(b-a))); return q*q*(3.0-2.0*q)

def _sabershader92_camera_angle_deg(obj,camera):
    try:
        c=sum((Vector(v) for v in obj.bound_box),Vector())/8.0
        center=obj.matrix_world@c; direction=(camera.location-center).normalized(); local=obj.matrix_world.to_3x3().inverted()@direction
        return math.degrees(math.atan2(abs(local.x),max(1e-8,abs(local.y))))
    except Exception:
        return 0.0

def build_v92_face_angle(char_name,settings):
    if not settings.build_face_corrections or not settings.auto_face_angle or not bpy.context.scene.camera: return 0
    n=0; angles=[]
    for obj in _sabershader91_face_objects(char_name):
        angle=max(0.0,min(90.0,_sabershader92_camera_angle_deg(obj,bpy.context.scene.camera)+settings.face_angle_offset)); angles.append(angle)
        blocks=obj.data.shape_keys.key_blocks if obj.data.shape_keys else None
        if not blocks: continue
        k3=blocks.get('V9_1_Face_3Q'); kp=blocks.get('V9_1_Face_Profile')
        if k3: k3.value=_sabershader92_smoothstep(18.0,58.0,angle)
        if kp: kp.value=_sabershader92_smoothstep(52.0,88.0,angle)
        obj['SaberShader_V9_2_FaceAngleDeg']=angle; obj['SaberShader_V9_2_Face3Q']=float(k3.value) if k3 else 0.0; obj['SaberShader_V9_2_FaceProfile']=float(kp.value) if kp else 0.0; n+=1
    if angles: bpy.context.scene['SaberShader_V9_2_AvgFaceAngleDeg']=sum(angles)/len(angles)
    return n

def build_v92_parent_tertiary(char_name):
    parents=[o for o in bpy.context.scene.objects if o.type=='ARMATURE' and char_name.lower() in o.name.lower()]
    if not parents: return 0
    parent=parents[0]; n=0
    for kind in ('Light','Shadow'):
        obj=bpy.data.objects.get(f'{SABERSHADER91_TERTIARY_PREFIX}{char_name} • {kind}')
        if not obj: continue
        if obj.parent!=parent:
            mw=obj.matrix_world.copy(); obj.parent=parent; obj.matrix_world=mw
        obj['SaberShader_V9_2_TertiaryParent']=parent.name; n+=1
    return n

SABERSHADER93_PREFIX = "SaberShader V9.3 • "
SABERSHADER93_TERT_PREFIX = SABERSHADER93_PREFIX + "Tertiary • "
SABERSHADER93_HAIR_PREFIX = SABERSHADER93_PREFIX + "Hair Ribbon • "
SABERSHADER93_COL_PREFIX = SABERSHADER93_PREFIX + "Collection • "

SABERSHADER93_TERT_COLORS = {
    'Light':  (1.00, 0.76, 0.56, 1.0),
    'Shadow': (0.28, 0.32, 0.52, 1.0),
    'Accent': (1.00, 0.92, 0.68, 1.0),
}

def _sabershader93_collection(char_name):
    name = SABERSHADER93_COL_PREFIX + char_name
    col = bpy.data.collections.get(name)
    if col is None:
        col = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(col)
    col['SaberShader_V9_3_TertiaryCollection'] = True
    col['SaberShader_V9_3_Character'] = char_name
    return col

def _sabershader93_link_collection(obj, col):
    try:
        if col.objects.get(obj.name) is None:
            col.objects.link(obj)
    except Exception:
        pass

def _sabershader93_armature(char_name):
    hits=[o for o in bpy.context.scene.objects if o.type=='ARMATURE' and char_name.lower() in o.name.lower()]
    return hits[0] if hits else None

def _sabershader93_parent_keep_world(obj, parent):
    if not obj or not parent:
        return False
    try:
        mw=obj.matrix_world.copy()
        obj.parent=parent
        obj.matrix_world=mw
        return True
    except Exception:
        return False

def _sabershader93_gp_material(name, color):
    mat=bpy.data.materials.get(name) or bpy.data.materials.new(name)
    gp=getattr(mat,'grease_pencil',None)
    if gp is None and hasattr(bpy.data.materials,'create_gpencil_data'):
        try: bpy.data.materials.create_gpencil_data(mat)
        except Exception: pass
    gp=getattr(mat,'grease_pencil',None)
    if gp is None:
        raise RuntimeError(f'No se pudo preparar material GP V9.3: {name}')
    try:
        gp.color=color; gp.fill_color=(0,0,0,0); gp.mode='LINE'; gp.stroke_style='SOLID'; gp.show_fill=False; gp.show_stroke=True
    except Exception:
        pass
    mat.diffuse_color=color
    mat['SaberShader_V9_3_TertiaryMaterial']=True
    return mat

def _sabershader93_get_or_create_gp(char_name, kind, color):

    if kind in {'Light','Shadow'}:
        obj=bpy.data.objects.get(f'{SABERSHADER91_TERTIARY_PREFIX}{char_name} • {kind}')
        if obj and obj.type=='GREASEPENCIL':
            return obj
    name=f'{SABERSHADER93_TERT_PREFIX}{char_name} • {kind}'
    obj=bpy.data.objects.get(name)
    if obj and obj.type=='GREASEPENCIL':
        return obj
    old_active=bpy.context.view_layer.objects.active
    old_sel=list(bpy.context.selected_objects)
    try:
        bpy.ops.object.select_all(action='DESELECT')
        bpy.ops.object.grease_pencil_add(type='EMPTY', use_in_front=False, stroke_depth_offset=0.004, use_lights=False, stroke_depth_order='3D', location=(0,0,0))
        obj=bpy.context.view_layer.objects.active
        if obj:
            obj.name=name
    except Exception as exc:
        raise RuntimeError(f'V9.3 no pudo crear capa GP {name}: {exc}')
    finally:
        try:
            bpy.ops.object.select_all(action='DESELECT')
            for o in old_sel: o.select_set(True)
            bpy.context.view_layer.objects.active=old_active
        except Exception:
            pass
    return obj

def build_v93_tertiary_artist(char_name, settings):
    col=_sabershader93_collection(char_name)
    parent=_sabershader93_armature(char_name)
    scene=bpy.context.scene
    cam=scene.camera
    count=0
    for kind in ('Light','Shadow','Accent'):
        try:
            obj=_sabershader93_get_or_create_gp(char_name,kind,SABERSHADER93_TERT_COLORS[kind])
            if obj is None: continue
            _sabershader93_link_collection(obj,col)
            if parent:
                _sabershader93_parent_keep_world(obj,parent)
                obj['SaberShader_V9_3_TertiaryParent']=parent.name
            try:
                obj.show_in_front=True
            except Exception:
                pass
            obj['SaberShader_V9_3_Tertiary']=True
            obj['SaberShader_V9_3_Character']=char_name
            obj['SaberShader_V9_3_TertiaryKind']=kind
            obj['SaberShader_V9_3_EditableByShot']=True
            obj['SaberShader_V9_3_ActiveCamera']=cam.name if cam else ''
            obj['SaberShader_V9_3_Frame']=int(scene.frame_current)
            obj['SaberShader_V9_3_Profile']=settings.shot_profile
            obj['SaberShader_V9_3_DepthOffset']=float(settings.tertiary_depth_offset)
            obj['SaberShader_V9_3_Instruction']=(
                'DRAW HIGHLIGHT / SHADOW / ACCENT per shot. Keep sparse; favor face, hair, clothing folds and silhouette corrections.'
            )
            mat_name=f'{SABERSHADER93_TERT_PREFIX}{char_name} • {kind} Ink'
            mat=_sabershader93_gp_material(mat_name,SABERSHADER93_TERT_COLORS[kind])
            if mat.name not in {m.name for m in obj.data.materials if m}:
                obj.data.materials.append(mat)
            count+=1
        except Exception as exc:
            log(f'V9.3 Tertiary Artist {char_name} {kind}: {exc}')
    scene[f'SaberShader_V9_3_{char_name}_TertiaryReady']=True
    scene[f'SaberShader_V9_3_{char_name}_TertiaryCamera']=cam.name if cam else ''
    scene[f'SaberShader_V9_3_{char_name}_TertiaryFrame']=int(scene.frame_current)
    return count

def _sabershader93_image_sig(group):
    try:
        return _sabershader15_image_link_signature(group)
    except Exception:
        return None

def _sabershader93_apply_hair_ribbon(group, profile):
    if not group:
        return False
    nodes,links=group.nodes,group.links
    for n in list(nodes):
        if n.name.startswith(SABERSHADER93_HAIR_PREFIX):
            nodes.remove(n)
    output=nodes.get('Group Output')
    if not output: return False
    shader_out=next((s for s in output.inputs if s.type=='SHADER'),None)
    if not shader_out or not shader_out.is_linked: return False
    final=shader_out.links[0].from_node
    color_input=None
    if final.bl_idname=='ShaderNodeBsdfPrincipled': color_input=final.inputs.get('Base Color')
    elif final.bl_idname=='ShaderNodeEmission': color_input=final.inputs.get('Color')
    else:
        final=nodes.get('SaberShader Face Principled') or nodes.get('SaberShader Face Principled Toon') or nodes.get('SaberShader Anime Toon Emission') or nodes.get('Emission') or nodes.get('Principled BSDF')
        if final: color_input=final.inputs.get('Base Color') or final.inputs.get('Color')
    if not color_input: return False
    before=_sabershader93_image_sig(group)
    src=color_input.links[0].from_socket if color_input.is_linked else None
    val=tuple(color_input.default_value) if src is None else None

    lw=nodes.new('ShaderNodeLayerWeight'); lw.name=SABERSHADER93_HAIR_PREFIX+'Facing'; lw.location=(final.location.x-640,final.location.y-260)
    ramp=nodes.new('ShaderNodeValToRGB'); ramp.name=SABERSHADER93_HAIR_PREFIX+'Band'; ramp.label='V9.3 • Hair ribbon'; ramp.location=(final.location.x-420,final.location.y-260)
    cr=ramp.color_ramp
    cr.elements[0].position=0.72
    cr.elements[0].color=(0,0,0,1)
    cr.elements[1].position=0.90
    cr.elements[1].color=(1,1,1,1)

    add=nodes.new('ShaderNodeMixRGB'); add.name=SABERSHADER93_HAIR_PREFIX+'Add'; add.label='V9.3 • Hair ribbon highlight'; add.blend_type='ADD'; add.location=(final.location.x-180,final.location.y-100)
    add.inputs['Fac'].default_value=0.12 if profile=='MYGO' else 0.16
    add.inputs['Color2'].default_value=(1.0,0.78,0.82,1.0) if profile=='AVE' else (1.0,0.88,0.82,1.0)
    if src is not None: links.new(src,add.inputs['Color1'])
    else: add.inputs['Color1'].default_value=val
    links.new(lw.outputs.get('Facing'),ramp.inputs['Fac'])
    links.new(ramp.outputs['Color'],add.inputs['Fac'])
    for lk in list(color_input.links): links.remove(lk)
    links.new(add.outputs['Color'],color_input)
    after=_sabershader93_image_sig(group)
    if before!=after:

        for lk in list(color_input.links): links.remove(lk)
        if src is not None: links.new(src,color_input)
        elif val is not None: color_input.default_value=val
        return False
    group['SaberShader_V9_3_HairRibbon']=True
    group['SaberShader_V9_3_HairProfile']=profile
    return True

def build_v93_hair_ribbon(char_name, profile):
    count=0; prefix=f'SaberShader_V8_{char_name}_'
    for obj in bpy.context.scene.objects:
        if obj.type!='MESH': continue
        for slot in obj.material_slots:
            mat=slot.material
            if not mat or not mat.name.startswith(prefix): continue
            group_node=mat.node_tree.nodes.get('XDZR8_V8') if getattr(mat,'use_nodes',False) else None
            group=group_node.node_tree if group_node else None
            if group is not None and mat.get('SaberShader_V8_Category')=='hair':
                try:
                    if _sabershader93_apply_hair_ribbon(group,profile): count+=1
                except Exception as exc:
                    log(f'V9.3 Hair Ribbon {char_name}: {exc}')
            break
    return count

def build_v93_system(settings):
    profile=settings.shot_profile
    tert=(build_v93_tertiary_artist('Doloris',settings)+build_v93_tertiary_artist('Oblivionis',settings)) if settings.build_tertiary_artist else 0
    hair=(build_v93_hair_ribbon('Doloris',profile)+build_v93_hair_ribbon('Oblivionis',profile)) if settings.build_hair_ribbon else 0
    scene=bpy.context.scene
    scene['SaberShader_V9_3_ShotProfile']=profile
    scene['SaberShader_V9_3_Camera']=scene.camera.name if scene.camera else ''
    scene['SaberShader_V9_3_Frame']=int(scene.frame_current)
    scene['SaberShader_V9_3_TertiaryWorkflow']='Light / Shadow / Accent — hand-authored per shot'
    scene['SaberShader_V9_3_HairRibbonCount']=hair
    return {'tertiary':tert,'hair':hair}

SABERSHADER94_PREFIX = "SaberShader V9.5 • "
SABERSHADER94_FACE_PREFIX = SABERSHADER94_PREFIX + "Face • "
SABERSHADER94_EXPR_PREFIX = SABERSHADER94_PREFIX + "Expression • "
SABERSHADER94_LATTICE_PREFIX = SABERSHADER94_PREFIX + "Shot Deform • "
SABERSHADER94_GUIDE_PREFIX = SABERSHADER94_PREFIX + "Tertiary Guide • "
SABERSHADER94_LINE_PREFIX = SABERSHADER94_PREFIX + "Line • "

def _sabershader94_face_meshes(char_name):
    """Face-related meshes, conservatively excluding pure body/hair/eyes."""
    out = []
    for obj in _sabershader91_face_objects(char_name):
        if obj.type != 'MESH' or not obj.data or len(obj.data.vertices) == 0:
            continue
        out.append(obj)
    return out

def _sabershader94_vertex_mask_info(obj):
    verts = list(obj.data.vertices)
    if not verts:
        return None
    xs = [v.co.x for v in verts]
    zs = [v.co.z for v in verts]
    return min(xs), max(xs), min(zs), max(zs)

def _sabershader94_make_face_key(obj, name, transform_fn):
    """Create a localized corrective shape key; never changes UVs/materials."""
    if obj.data.shape_keys and obj.data.shape_keys.key_blocks.get(name):
        return False
    if not obj.data.shape_keys:
        obj.shape_key_add(name='Basis')
    key = obj.shape_key_add(name=name)
    info = _sabershader94_vertex_mask_info(obj)
    if info is None:
        return False
    min_x, max_x, min_z, max_z = info
    dx = max(max_x - min_x, 1e-8)
    dz = max(max_z - min_z, 1e-8)
    center_x = (min_x + max_x) * 0.5

    for i, vert in enumerate(obj.data.vertices):
        co = vert.co.copy()
        nx = (co.x - min_x) / dx
        nz = (co.z - min_z) / dz
        new_co = transform_fn(co.copy(), nx, nz, center_x, dx, dz)
        key.data[i].co = new_co

    key.value = 0.0
    key.slider_min = 0.0
    key.slider_max = 1.0
    obj[f'SaberShader_V9_4_Corrective_{name}'] = True
    return True

def _sabershader94_face_performance_key_defs(obj):
    """Small, localized deformations for a 2D/anime face read."""
    def eye_far(co, nx, nz, cx, dx, dz):
        if nz >= 0.54 and 0.12 <= nx <= 0.88:

            factor = 0.055 * min(1.0, abs(nx - 0.5) * 2.4)
            co.x = cx + (co.x - cx) * (1.0 - factor)
        return co

    def mouth_soft(co, nx, nz, cx, dx, dz):
        if 0.20 <= nz <= 0.47:
            factor = 0.050 * min(1.0, 1.0 - abs(nx - 0.5) * 1.2)
            co.x = cx + (co.x - cx) * (1.0 - factor)
            co.z += 0.006 * dz * (1.0 - abs(nx - 0.5) * 1.4)
        return co

    def jaw_soft(co, nx, nz, cx, dx, dz):
        if nz <= 0.30:
            factor = 0.045 * min(1.0, 1.0 - abs(nx - 0.5) * 1.3)
            co.x = cx + (co.x - cx) * (1.0 - factor)
        return co

    def profile_soft(co, nx, nz, cx, dx, dz):
        if nz <= 0.78:
            factor = 0.065 * min(1.0, 1.0 - abs(nx - 0.5) * 1.7)
            co.x = cx + (co.x - cx) * (1.0 - factor)
        return co

    return {
        'EyeFar_3Q': eye_far,
        'Mouth_Soften': mouth_soft,
        'Jaw_Soften': jaw_soft,
        'Profile_Soften': profile_soft,
    }

def build_v94_face_performance(char_name, settings):
    if not settings.build_character_performance:
        return 0
    count = 0

    for obj in _sabershader94_face_meshes(char_name):
        defs = _sabershader94_face_performance_key_defs(obj)
        for key_name, fn in defs.items():
            if _sabershader94_make_face_key(obj, f'{SABERSHADER94_FACE_PREFIX}{key_name}', fn):
                count += 1

        blocks = obj.data.shape_keys.key_blocks if obj.data.shape_keys else None
        if not blocks:
            continue
        k3 = blocks.get('V9_1_Face_3Q')
        kp = blocks.get('V9_1_Face_Profile')
        q3 = float(k3.value) if k3 else 0.0
        prof = float(kp.value) if kp else 0.0
        s = float(settings.face_performance_strength)

        for name, value in {
            f'{SABERSHADER94_FACE_PREFIX}EyeFar_3Q': 0.16 * q3 * s,
            f'{SABERSHADER94_FACE_PREFIX}Mouth_Soften': 0.12 * q3 * s,
            f'{SABERSHADER94_FACE_PREFIX}Jaw_Soften': min(0.22, (0.08 * q3 + 0.18 * prof) * s),
            f'{SABERSHADER94_FACE_PREFIX}Profile_Soften': 0.12 * prof * s,
        }.items():
            key = blocks.get(name)
            if key:
                key.value = max(0.0, min(1.0, value))

        obj['SaberShader_V9_4_FacePerformance'] = True
        obj['SaberShader_V9_4_FacePerformanceStrength'] = s
    return count

def _sabershader94_make_expression_key(obj, name, mode):
    def transform(co, nx, nz, cx, dx, dz):
        if mode == 'smile':

            if 0.18 <= nz <= 0.48:
                center_weight = max(0.0, 1.0 - abs(nx - 0.5) * 2.0)
                co.z += 0.012 * dz * center_weight
                if abs(nx - 0.5) > 0.20:
                    co.x += (co.x - cx) * 0.010
        elif mode == 'open':

            if 0.16 <= nz <= 0.44:
                co.z -= 0.014 * dz
        elif mode == 'tension':

            if 0.14 <= nz <= 0.42:
                co.x = cx + (co.x - cx) * 0.975
        return co

    return _sabershader94_make_face_key(obj, name, transform)

def build_v94_expression_corrections(char_name, settings):
    if not settings.build_expression_corrections:
        return 0
    count = 0
    for obj in _sabershader94_face_meshes(char_name):
        count += int(_sabershader94_make_expression_key(obj, f'{SABERSHADER94_EXPR_PREFIX}Smile', 'smile'))
        count += int(_sabershader94_make_expression_key(obj, f'{SABERSHADER94_EXPR_PREFIX}OpenMouth', 'open'))
        count += int(_sabershader94_make_expression_key(obj, f'{SABERSHADER94_EXPR_PREFIX}Tension', 'tension'))
        obj['SaberShader_V9_4_ExpressionCorrectionReady'] = True
        obj['SaberShader_V9_4_ExpressionSlots'] = 'Smile / OpenMouth / Tension'
    return count

def _sabershader94_character_world_bounds(char_name):
    meshes = _sabershader91_character_meshes(char_name)
    if not meshes:
        return None
    corners = []
    for obj in meshes:
        try:
            corners.extend(obj.matrix_world @ Vector(c) for c in obj.bound_box)
        except Exception:
            continue
    if not corners:
        return None
    min_v = Vector((min(v.x for v in corners), min(v.y for v in corners), min(v.z for v in corners)))
    max_v = Vector((max(v.x for v in corners), max(v.y for v in corners), max(v.z for v in corners)))
    return min_v, max_v

def _sabershader94_find_armature(char_name):
    return _sabershader93_armature(char_name)

def _sabershader94_parent_keep_world(obj, parent):
    if not obj or not parent:
        return False
    try:
        mw = obj.matrix_world.copy()
        obj.parent = parent
        obj.matrix_world = mw
        return True
    except Exception:
        return False

def build_v94_shot_deformation(char_name, settings):
    if not settings.build_shot_deformation:
        return 0
    bounds = _sabershader94_character_world_bounds(char_name)
    if bounds is None:
        return 0
    min_v, max_v = bounds
    size = max_v - min_v
    margin = Vector((max(size.x, 0.1) * 0.08, max(size.y, 0.1) * 0.08, max(size.z, 0.1) * 0.06))
    center = (min_v + max_v) * 0.5
    dims = Vector((max(size.x + margin.x * 2.0, 0.15), max(size.y + margin.y * 2.0, 0.15), max(size.z + margin.z * 2.0, 0.15)))
    name = f'{SABERSHADER94_LATTICE_PREFIX}{char_name}'
    lat = bpy.data.objects.get(name)

    if lat is None or lat.type != 'LATTICE':
        if lat is not None:
            try:
                bpy.data.objects.remove(lat, do_unlink=True)
            except Exception:
                lat = None
        old_active = bpy.context.view_layer.objects.active
        old_sel = list(bpy.context.selected_objects)
        try:
            bpy.ops.object.select_all(action='DESELECT')
            bpy.ops.object.add(type='LATTICE', location=center)
            lat = bpy.context.view_layer.objects.active
            if not lat:
                return 0
            lat.name = name
            lat.data.name = name + ' Data'
            lat.data.points_u = 3
            lat.data.points_v = 3
            lat.data.points_w = 3
            lat.dimensions = tuple(dims)
        except Exception as exc:
            log(f'V9.5 Shot Deformation {char_name}: {exc}')
            return 0
        finally:
            try:
                bpy.ops.object.select_all(action='DESELECT')
                for o in old_sel:
                    o.select_set(True)
                if old_active and old_active.name in bpy.data.objects:
                    bpy.context.view_layer.objects.active = old_active
            except Exception:
                pass

    arm = _sabershader94_find_armature(char_name)
    if arm and lat.parent != arm:
        _sabershader94_parent_keep_world(lat, arm)

    try:
        mw = lat.matrix_world.copy()
        mw.translation = center
        lat.matrix_world = mw
        lat.dimensions = tuple(dims)
        lat.display_type = 'WIRE'
        lat.show_in_front = True
    except Exception:
        pass

    lat['SaberShader_V9_4_ShotDeformation'] = True
    lat['SaberShader_V9_4_Character'] = char_name
    lat['SaberShader_V9_4_DefaultIdentity'] = True
    lat['SaberShader_V9_4_Instruction'] = 'Edit lattice points for subtle per-shot silhouette/pose corrections; do not remodel the source mesh.'
    lat['SaberShader_V9_4_Strength'] = float(settings.shot_deform_strength)

    applied = 0
    for obj in _sabershader91_character_meshes(char_name):
        mod = next((m for m in obj.modifiers if m.type == 'LATTICE' and m.name.startswith(SABERSHADER94_LATTICE_PREFIX)), None)
        if mod is None:
            mod = obj.modifiers.new(name=f'{SABERSHADER94_LATTICE_PREFIX}{char_name}', type='LATTICE')
        mod.object = lat
        try:
            mod.strength = float(settings.shot_deform_strength)
        except Exception:
            pass
        obj['SaberShader_V9_4_ShotDeformation'] = True
        applied += 1
    bpy.context.scene[f'SaberShader_V9_4_{char_name}_Lattice'] = lat.name
    return applied

def _sabershader94_ensure_tertiary_layers(obj, names):
    if not obj or obj.type != 'GREASEPENCIL':
        return 0
    count = 0
    try:
        for lname in names:
            if obj.data.layers.get(lname) is None:
                obj.data.layers.new(lname, set_active=False)
                count += 1
    except Exception as exc:
        log(f'V9.5 Tertiary layers {obj.name}: {exc}')
    return count

def _sabershader94_make_guide(char_name):
    name = f'{SABERSHADER94_GUIDE_PREFIX}{char_name}'
    guide = bpy.data.objects.get(name)
    if guide is None or guide.type != 'EMPTY':
        if guide is not None:
            try:
                bpy.data.objects.remove(guide, do_unlink=True)
            except Exception:
                pass
        try:
            bpy.ops.object.empty_add(type='PLAIN_AXES', location=(0, 0, 0))
            guide = bpy.context.view_layer.objects.active
            if guide:
                guide.name = name
        except Exception as exc:
            log(f'V9.5 Tertiary Guide {char_name}: {exc}')
            return None
    try:
        guide.empty_display_size = 0.35
        guide.show_in_front = True
    except Exception:
        pass
    scene = bpy.context.scene
    cam = scene.camera
    bounds = _sabershader94_character_world_bounds(char_name)
    if bounds is not None:
        center = (bounds[0] + bounds[1]) * 0.5
        try:
            mw = guide.matrix_world.copy()
            mw.translation = center
            guide.matrix_world = mw
        except Exception:
            guide.location = center
    if cam and guide.parent != cam:

        _sabershader94_parent_keep_world(guide, cam)
    elif cam:

        try:
            mw = guide.matrix_world.copy()
            mw.translation = center if bounds is not None else mw.translation
            guide.matrix_world = mw
        except Exception:
            pass
    guide['SaberShader_V9_4_TertiaryGuide'] = True
    guide['SaberShader_V9_4_Character'] = char_name
    guide['SaberShader_V9_4_Instruction'] = 'Shot-local guide for tertiary accents. Keep drawings sparse; prioritize face, hair, clothing folds and silhouette.'
    guide['SaberShader_V9_4_Camera'] = cam.name if cam else ''
    guide['SaberShader_V9_4_Frame'] = int(scene.frame_current)
    return guide

def build_v94_tertiary_artist(char_name, settings):
    if not settings.build_tertiary_artist:
        return 0
    count = 0

    for kind in ('Light', 'Shadow', 'Accent'):
        obj = bpy.data.objects.get(f'{SABERSHADER93_TERT_PREFIX}{char_name} • {kind}')
        if obj and obj.type == 'GREASEPENCIL':
            count += _sabershader94_ensure_tertiary_layers(
                obj,
                (
                    f'V9_4_{kind}_Face',
                    f'V9_4_{kind}_Hair',
                    f'V9_4_{kind}_Clothing',
                    f'V9_4_{kind}_Silhouette',
                ),
            )
            obj['SaberShader_V9_4_TertiaryArtist2'] = True
            obj['SaberShader_V9_4_TertiaryZones'] = 'Face / Hair / Clothing / Silhouette'
            obj['SaberShader_V9_4_Camera'] = bpy.context.scene.camera.name if bpy.context.scene.camera else ''
            obj['SaberShader_V9_4_Frame'] = int(bpy.context.scene.frame_current)
    guide = _sabershader94_make_guide(char_name)
    if guide:
        count += 1
    return count

def build_v94_smart_line_art(char_name, settings):
    if not settings.build_smart_line_art:
        return 0
    gp = bpy.data.objects.get(f'SaberShader V9 • LineArt • {char_name}')
    if not gp or gp.type != 'GREASEPENCIL':
        return 0
    profile = settings.shot_profile
    detail = float(settings.smart_line_detail)
    if profile == 'MYGO':
        sil_radius = 0.00140
        inner_radius = 0.00054 * detail
        inner_opacity = 0.60
    else:
        sil_radius = 0.00162
        inner_radius = 0.00060 * detail
        inner_opacity = 0.74
    n = 0
    for mod in gp.modifiers:
        if not mod.name.startswith(SABERSHADER9_LINE_MOD_PREFIX):
            continue
        try:
            if 'Silhouette' in mod.name:
                mod.radius = sil_radius
                mod.opacity = 1.0
                n += 1
            elif 'Creases' in mod.name:
                mod.radius = inner_radius
                mod.opacity = inner_opacity
                n += 1
            elif 'MaterialBorders' in mod.name or 'Intersections' in mod.name:

                mod.opacity = 0.32 if profile == 'MYGO' else 0.42
                n += 1
        except Exception as exc:
            log(f'V9.5 Smart Line Art {char_name}: {exc}')
    gp['SaberShader_V9_4_SmartLineArt'] = True
    gp['SaberShader_V9_4_Profile'] = profile
    gp['SaberShader_V9_4_SilhouetteRadius'] = sil_radius
    gp['SaberShader_V9_4_InternalRadius'] = inner_radius
    gp['SaberShader_V9_4_InternalOpacity'] = inner_opacity
    gp['SaberShader_V9_4_Detail'] = detail
    return n

def build_v94_system(settings):
    performance = build_v94_face_performance('Doloris', settings) + build_v94_face_performance('Oblivionis', settings)
    expressions = build_v94_expression_corrections('Doloris', settings) + build_v94_expression_corrections('Oblivionis', settings)
    deformation = build_v94_shot_deformation('Doloris', settings) + build_v94_shot_deformation('Oblivionis', settings)
    tertiary = build_v94_tertiary_artist('Doloris', settings) + build_v94_tertiary_artist('Oblivionis', settings)
    lines = 0 if _sabershader105a1_lineart_is_quarantined() else (build_v94_smart_line_art('Doloris', settings) + build_v94_smart_line_art('Oblivionis', settings))
    scene = bpy.context.scene
    scene['SaberShader_V9_4_ShotProfile'] = settings.shot_profile
    scene['SaberShader_V9_4_Camera'] = scene.camera.name if scene.camera else ''
    scene['SaberShader_V9_4_Frame'] = int(scene.frame_current)
    scene['SaberShader_V9_4_FacePerformanceStrength'] = float(settings.face_performance_strength)
    scene['SaberShader_V9_4_ShotDeformStrength'] = float(settings.shot_deform_strength)
    scene['SaberShader_V9_4_SmartLineDetail'] = float(settings.smart_line_detail)
    return {
        'performance': performance,
        'expressions': expressions,
        'deformation': deformation,
        'tertiary': tertiary,
        'lines': lines,
    }

def build_v92_system(settings):
    profile=settings.shot_profile
    art=(build_v92_artistic_lighting('Doloris',profile)+build_v92_artistic_lighting('Oblivionis',profile)) if settings.build_artistic_lighting else 0

    lines=0 if _sabershader105a1_lineart_is_quarantined() else ((build_v92_line_hierarchy('Doloris')+build_v92_line_hierarchy('Oblivionis')) if settings.build_line_hierarchy else 0)
    face=build_v92_face_angle('Doloris',settings)+build_v92_face_angle('Oblivionis',settings)
    parent=(build_v92_parent_tertiary('Doloris')+build_v92_parent_tertiary('Oblivionis')) if settings.build_tertiary else 0
    return {'art':art,'lines':lines,'face':face,'tertiary_parent':parent}

def build_v91_system(settings):
    t=f=c=0
    if settings.build_tertiary: t=build_v91_tertiary('Doloris')+build_v91_tertiary('Oblivionis')
    if settings.build_face_corrections: f=build_v91_face_corrections('Doloris')+build_v91_face_corrections('Oblivionis')
    if settings.build_shoot_composite: c=build_v91_shoot_composite(settings.shot_profile)
    v92=build_v92_system(settings)
    v93=build_v93_system(settings)
    v94=build_v94_system(settings)
    return {'tertiary':t,'face':f,'composite':c,'v92':v92,'v93':v93,'v94':v94}

SABERSHADER109C11_PREFIX = "SaberShader V10.9C1.1 • "

def _sabershader109c11_material_vertex_indices(obj, categories):
    """Vertices referenced by polygons whose assigned material category matches."""
    if not obj or obj.type != 'MESH' or not obj.data:
        return []
    cats = {str(c) for c in categories}
    slot_matches = set()
    for idx, slot in enumerate(obj.material_slots):
        mat = slot.material
        if mat and str(mat.get('SaberShader_V8_Category', '')) in cats:
            slot_matches.add(idx)
    if not slot_matches:
        return []
    out = set()
    try:
        for poly in obj.data.polygons:
            if poly.material_index in slot_matches:
                out.update(int(i) for i in poly.vertices)
    except Exception:
        return []
    return sorted(out)

def _sabershader109c11_bounds(obj, indices):
    if not indices:
        return None
    coords = [obj.data.vertices[i].co for i in indices if 0 <= i < len(obj.data.vertices)]
    if not coords:
        return None
    min_x = min(v.x for v in coords); max_x = max(v.x for v in coords)
    min_y = min(v.y for v in coords); max_y = max(v.y for v in coords)
    min_z = min(v.z for v in coords); max_z = max(v.z for v in coords)
    return (min_x, max_x, min_y, max_y, min_z, max_z)

def _sabershader109c11_key(obj, name, indices, coord_fn, value):
    """Create/update a deterministic relative Shape Key from Basis."""
    if not obj or obj.type != 'MESH' or not obj.data or not indices:
        return False
    try:
        keys = obj.data.shape_keys
        if keys is None:
            obj.shape_key_add(name='Basis', from_mix=False)
            keys = obj.data.shape_keys
        basis = keys.reference_key if keys and keys.reference_key else keys.key_blocks[0]
        key = keys.key_blocks.get(name) if keys else None
        created = False
        if key is None:
            key = obj.shape_key_add(name=name, from_mix=False)
            created = True
        try:
            key.relative_key = basis
        except Exception:
            pass

        for i in range(len(obj.data.vertices)):
            key.data[i].co = basis.data[i].co.copy()
        for i in indices:
            if 0 <= i < len(obj.data.vertices):
                base = basis.data[i].co.copy()
                key.data[i].co = coord_fn(i, base)
        key.slider_min = 0.0
        key.slider_max = 1.0
        key.value = max(0.0, min(1.0, float(value)))
        obj['SaberShader_V10_9C1_1_ProportionMatch'] = True
        obj['SaberShader_V10_9C1_1_LastKey'] = name
        return True
    except Exception as exc:
        log(f'V10.9C1.1 ShapeKey {obj.name} / {name}: {exc}')
        return False

def _sabershader109c11_eye_key(obj, char_name, strength):
    indices = _sabershader109c11_material_vertex_indices(obj, {'eyes', 'eyes3', 'eyes5'})
    b = _sabershader109c11_bounds(obj, indices)
    if not b:
        return False
    min_x, max_x, _min_y, _max_y, min_z, max_z = b
    cx = (min_x + max_x) * 0.5
    dz = max(max_z - min_z, 1e-8)

    left = [i for i in indices if obj.data.vertices[i].co.x <= cx]
    right = [i for i in indices if obj.data.vertices[i].co.x > cx]
    def center(group):
        if not group:
            return cx, (min_z + max_z) * 0.5
        pts = [obj.data.vertices[i].co for i in group]
        return sum(p.x for p in pts) / len(pts), sum(p.z for p in pts) / len(pts)
    lcx, lcz = center(left); rcx, rcz = center(right)
    s = max(0.0, min(1.0, float(strength)))
    x_scale = 1.0 - 0.030 * s
    z_scale = 1.0 - 0.105 * s
    z_lift = 0.0045 * dz * s
    def fn(i, co):
        ex, ez = (lcx, lcz) if co.x <= cx else (rcx, rcz)
        co.x = ex + (co.x - ex) * x_scale
        co.z = ez + (co.z - ez) * z_scale + z_lift
        return co
    return _sabershader109c11_key(obj, f'{SABERSHADER109C11_PREFIX}{char_name} • Eye Compact', indices, fn, s)

def _sabershader109c11_face_key(obj, char_name, strength):
    indices = _sabershader109c11_material_vertex_indices(obj, {'face', 'mouth', 'expression', 'expression2'})
    b = _sabershader109c11_bounds(obj, indices)
    if not b:
        return False
    min_x, max_x, _min_y, _max_y, min_z, max_z = b
    cx = (min_x + max_x) * 0.5
    dz = max(max_z - min_z, 1e-8)
    s = max(0.0, min(1.0, float(strength)))
    def fn(_i, co):
        nz = max(0.0, min(1.0, (co.z - min_z) / dz))

        lower = max(0.0, min(1.0, (0.62 - nz) / 0.62))
        lower = lower * lower * (3.0 - 2.0 * lower)
        x_scale = 1.0 - 0.070 * s * lower
        co.x = cx + (co.x - cx) * x_scale
        co.z += dz * 0.018 * s * lower * lower
        return co
    return _sabershader109c11_key(obj, f'{SABERSHADER109C11_PREFIX}{char_name} • Lower Face Taper', indices, fn, s)

def _sabershader109c11_mask_key(obj, char_name, strength):
    indices = _sabershader109c11_material_vertex_indices(obj, {'mask'})
    b = _sabershader109c11_bounds(obj, indices)
    if not b:
        return False
    min_x, max_x, _min_y, _max_y, min_z, max_z = b
    cx = (min_x + max_x) * 0.5
    cz = (min_z + max_z) * 0.5
    s = max(0.0, min(1.0, float(strength)))
    x_scale = 1.0 - 0.050 * s
    z_scale = 1.0 - 0.060 * s
    def fn(_i, co):
        co.x = cx + (co.x - cx) * x_scale
        co.z = cz + (co.z - cz) * z_scale
        return co
    return _sabershader109c11_key(obj, f'{SABERSHADER109C11_PREFIX}{char_name} • Mask Compact', indices, fn, s)

def _sabershader109c11_fringe_key(obj, char_name, strength):
    indices = _sabershader109c11_material_vertex_indices(obj, {'hair'})
    b = _sabershader109c11_bounds(obj, indices)
    if not b:
        return False
    min_x, max_x, _min_y, _max_y, min_z, max_z = b
    dx = max(max_x - min_x, 1e-8)
    dz = max(max_z - min_z, 1e-8)
    cx = (min_x + max_x) * 0.5
    s = max(0.0, min(1.0, float(strength)))
    def fn(_i, co):
        nx = (co.x - min_x) / dx
        nz = (co.z - min_z) / dz

        central = max(0.0, 1.0 - abs(nx - 0.5) / 0.30)

        vertical = max(0.0, min(1.0, (nz - 0.38) / 0.38))
        if nz > 0.92:
            vertical *= max(0.25, 1.0 - (nz - 0.92) / 0.08 * 0.55)
        w = central * vertical
        if w <= 0.0:
            return co
        co.x = cx + (co.x - cx) * (1.0 - 0.042 * s * w)
        if nz > 0.66:
            co.z -= dz * 0.014 * s * w * ((nz - 0.66) / 0.34)
        return co
    return _sabershader109c11_key(obj, f'{SABERSHADER109C11_PREFIX}{char_name} • Fringe Compact', indices, fn, s)

def _sabershader109c11_zero_keys():
    changed = 0
    for obj in bpy.context.scene.objects:
        if obj.type != 'MESH' or not obj.data or not obj.data.shape_keys:
            continue
        for key in obj.data.shape_keys.key_blocks:
            if key.name.startswith(SABERSHADER109C11_PREFIX):
                if abs(float(key.value)) > 1e-8:
                    key.value = 0.0
                    changed += 1
    return changed

def build_v109c11_facial_proportion_eye_match(settings):
    if not getattr(settings, 'build_facial_proportion_eye_match_v109c11', True):
        zeroed = _sabershader109c11_zero_keys()
        bpy.context.scene['SaberShader_V10_9C1_1_Enabled'] = False
