    scene['SaberShader_V10_9C1_2_ObjectCount'] = len(touched)
    scene['SaberShader_V10_9C1_2_KeyCount'] = key_count
    scene['SaberShader_V10_9C1_2_DolorisEye'] = params['Doloris']['eye']
    scene['SaberShader_V10_9C1_2_DolorisFace'] = params['Doloris']['face']
