def _sabershader109c1_face_character_target(profile, character, settings):
    if not getattr(settings, 'build_face_hair_series_match_final_v109c1', True):
        return None, 0.0
    if profile != 'AVE':
        return None, 0.0
    target = SABERSHADER109C1_FACE_CHARACTER_TARGETS.get(profile, {}).get(character)
    if not target:
        return None, 0.0
    if character == 'Doloris':
        strength = float(getattr(settings, 'doloris_face_match_final_v109c1', 0.42))
    elif character == 'Oblivionis':
        strength = float(getattr(settings, 'oblivionis_face_match_final_v109c1', 0.28))
    else:
        strength = 0.0
    return dict(target), strength

