def _sabershader108c1_final_micro_polish_cloth_style(style, profile, family, source_name, settings):
    out = dict(style)
    if not settings or not getattr(settings, 'build_final_micro_polish_v108c1', True):
        return out
    if profile != 'AVE':
        return out

    sep_t = max(0.0, min(1.0, float(getattr(settings, 'doloris_cloth_separation_v108c1', 0.18))))
    trans_t = max(0.0, min(1.0, float(getattr(settings, 'transparency_red_hold_v108c1', 0.22))))
    skirt_t = max(0.0, min(1.0, float(getattr(settings, 'oblivionis_skirt_contain_v108c1', 0.24))))
    corset_t = max(0.0, min(1.0, float(getattr(settings, 'oblivionis_corset_compact_v108c1', 0.16))))
    src_name = (source_name or '').strip().lower()

    if src_name == 'clothes':
        t = sep_t * 0.55
        out['mid_mul'] = _sabershader108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 1.010, t)
        out['light_mul'] = _sabershader108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 1.012, t)
        out['value'] = _sabershader108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 1.006, t)
        out['recover_strength'] = _sabershader108a_mix_scalar(out.get('recover_strength', 0.0), float(out.get('recover_strength', 0.0)) * 1.10, t)
    elif src_name == 'clothes3':
        out['shadow_mul'] = _sabershader108a_mix_scalar(out.get('shadow_mul', 1.0), float(out.get('shadow_mul', 1.0)) * 0.975, sep_t)
        out['mid_mul'] = _sabershader108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.978, sep_t)
        out['light_mul'] = _sabershader108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.988, sep_t)
        out['value'] = _sabershader108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.984, sep_t)
        out['emission_strength'] = _sabershader108a_mix_scalar(out.get('emission_strength', 1.0), float(out.get('emission_strength', 1.0)) * 0.992, sep_t)

    if family == 'transparent' or src_name in {'clothes4', '裙透'}:
        t = trans_t if src_name == 'clothes4' else trans_t * 0.70
        out['opacity_scale'] = _sabershader108a_mix_scalar(out.get('opacity_scale', 1.0), float(out.get('opacity_scale', 1.0)) * 0.965, t)
        out['alpha_luma_bright'] = _sabershader108a_mix_scalar(out.get('alpha_luma_bright', 0.46), max(0.20, float(out.get('alpha_luma_bright', 0.46)) - 0.030), t)
        out['recover_strength'] = _sabershader108a_mix_scalar(out.get('recover_strength', 0.0), float(out.get('recover_strength', 0.0)) * 1.18, t)
        out['saturation'] = _sabershader108a_mix_scalar(out.get('saturation', 1.0), float(out.get('saturation', 1.0)) * 1.03, t)
        out['white_compress_strength'] = _sabershader108a_mix_scalar(out.get('white_compress_strength', 0.48), float(out.get('white_compress_strength', 0.48)) * 0.96, t * 0.65)
        out['emission_strength'] = _sabershader108a_mix_scalar(out.get('emission_strength', 1.0), float(out.get('emission_strength', 1.0)) * 0.985, t * 0.60)

    if src_name == '裙':
        out['shadow_mul'] = _sabershader108a_mix_scalar(out.get('shadow_mul', 1.0), float(out.get('shadow_mul', 1.0)) * 0.975, skirt_t * 0.70)
        out['mid_mul'] = _sabershader108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.988, skirt_t * 0.65)
        out['light_mul'] = _sabershader108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.958, skirt_t)
        out['value'] = _sabershader108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.960, skirt_t)
        out['bright_protect'] = _sabershader108a_mix_scalar(out.get('bright_protect', 0.3), float(out.get('bright_protect', 0.3)) * 0.92, skirt_t * 0.85)
        out['emission_strength'] = _sabershader108a_mix_scalar(out.get('emission_strength', 1.0), float(out.get('emission_strength', 1.0)) * 0.985, skirt_t * 0.75)
    elif src_name == '服':
        t = skirt_t * 0.45
        out['shadow_mul'] = _sabershader108a_mix_scalar(out.get('shadow_mul', 1.0), float(out.get('shadow_mul', 1.0)) * 0.985, t)
        out['mid_mul'] = _sabershader108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.992, t)
        out['value'] = _sabershader108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.992, t)

    if family == 'corset' or src_name == 'clothes2':
        t = corset_t if src_name == 'clothes2' else corset_t * 0.70
        out['mid_mul'] = _sabershader108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.985, t)
        out['light_mul'] = _sabershader108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.972, t)
        out['value'] = _sabershader108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.978, t)
        out['saturation'] = _sabershader108a_mix_scalar(out.get('saturation', 1.0), float(out.get('saturation', 1.0)) * 0.988, t)
        out['bright_protect'] = _sabershader108a_mix_scalar(out.get('bright_protect', 0.3), float(out.get('bright_protect', 0.3)) * 0.985, t * 0.60)

    return out

def _sabershader108c2_final_lock_cloth_style(style, profile, family, source_name, settings):
    out = dict(style)
    if not settings or not getattr(settings, 'build_final_lock_v108c2', True):
        return out
    if profile != 'AVE':
        return out

    view_t = max(0.0, min(1.0, float(getattr(settings, 'view_consistency_v108c2', 0.12))))
    black_t = max(0.0, min(1.0, float(getattr(settings, 'black_midtone_lock_v108c2', 0.12))))
    trans_t = max(0.0, min(1.0, float(getattr(settings, 'transparency_edge_hold_v108c2', 0.14))))
    trim_t = max(0.0, min(1.0, float(getattr(settings, 'gold_trim_balance_v108c2', 0.10))))

    if view_t > 0.0:
        rmin = float(out.get('remap_min', -0.20))
        rmax = float(out.get('remap_max', 0.82))
        out['remap_min'] = _sabershader108a_mix_scalar(rmin, rmin - 0.035, view_t)
        out['remap_max'] = _sabershader108a_mix_scalar(rmax, rmax + 0.025, view_t)
        out['mid_pos'] = _sabershader108a_mix_scalar(out.get('mid_pos', 0.43), float(out.get('mid_pos', 0.43)) + 0.004, view_t)
        out['light_pos'] = _sabershader108a_mix_scalar(out.get('light_pos', 0.70), float(out.get('light_pos', 0.70)) + 0.006, view_t)
        out['inner_strength'] = _sabershader108a_mix_scalar(out.get('inner_strength', 0.10), float(out.get('inner_strength', 0.10)) * 0.985, view_t)

    if family in {'main', 'corset', 'hard'}:
        out['shadow_mul'] = _sabershader108a_mix_scalar(out.get('shadow_mul', 1.0), float(out.get('shadow_mul', 1.0)) * 0.985, black_t)
        out['mid_mul'] = _sabershader108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.982, black_t)
        out['light_mul'] = _sabershader108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.992, black_t)
        out['value'] = _sabershader108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.992, black_t)
        out['bright_protect'] = _sabershader108a_mix_scalar(out.get('bright_protect', 0.3), float(out.get('bright_protect', 0.3)) * 0.985, black_t)
        out['recover_strength'] = _sabershader108a_mix_scalar(out.get('recover_strength', 0.05), float(out.get('recover_strength', 0.05)) * 1.015, black_t * 0.50)

    elif family == 'transparent':
        out['opacity_scale'] = _sabershader108a_mix_scalar(out.get('opacity_scale', 1.0), float(out.get('opacity_scale', 1.0)) * 0.982, trans_t)
        out['alpha_luma_bright'] = _sabershader108a_mix_scalar(out.get('alpha_luma_bright', 0.46), max(0.18, float(out.get('alpha_luma_bright', 0.46)) - 0.022), trans_t)
        out['white_compress_strength'] = _sabershader108a_mix_scalar(out.get('white_compress_strength', 0.48), float(out.get('white_compress_strength', 0.48)) * 0.975, trans_t)
        out['white_compress_color'] = _sabershader108a_mix_rgba(out.get('white_compress_color', (0.68, 0.71, 0.79, 1.0)), (0.55, 0.57, 0.64, 1.0), trans_t * 0.55)
        out['recover_strength'] = _sabershader108a_mix_scalar(out.get('recover_strength', 0.03), float(out.get('recover_strength', 0.03)) * 1.08, trans_t)
        out['saturation'] = _sabershader108a_mix_scalar(out.get('saturation', 1.0), float(out.get('saturation', 1.0)) * 1.012, trans_t)
        out['emission_strength'] = _sabershader108a_mix_scalar(out.get('emission_strength', 1.0), float(out.get('emission_strength', 1.0)) * 0.992, trans_t)

    elif family in {'accent', 'ornament'}:

        out['gold_strength'] = _sabershader108a_mix_scalar(out.get('gold_strength', 0.20), float(out.get('gold_strength', 0.20)) * 0.965, trim_t)
        out['light_mul'] = _sabershader108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.993, trim_t)
        out['bright_protect'] = _sabershader108a_mix_scalar(out.get('bright_protect', 0.5), float(out.get('bright_protect', 0.5)) * 0.985, trim_t)
        out['saturation'] = _sabershader108a_mix_scalar(out.get('saturation', 1.0), float(out.get('saturation', 1.0)) * 0.995, trim_t)

    return out

SABERSHADER96_FACE_SHADOW_PREFIX = "SaberShader V9.6 • Face Shadow • "

SABERSHADER96_FACE_SHADOW_STYLE = {
    "MYGO": {

        "shadow": (0.88, 0.90, 0.96, 1.0),
        "chin":   (0.94, 0.90, 0.92, 1.0),
        "key_dir": (-0.18, -0.82, 0.55),
        "normal_from": -0.05,
        "normal_to": 0.50,
        "chin_from": 0.18,
        "chin_to": 0.52,
        "chin_scale": 0.28,
    },
    "AVE": {

        "shadow": (0.74, 0.76, 0.84, 1.0),
        "chin":   (0.82, 0.78, 0.82, 1.0),
        "key_dir": (-0.30, -0.76, 0.58),
        "normal_from": 0.08,
        "normal_to": 0.42,
        "chin_from": 0.06,
        "chin_to": 0.62,
        "chin_scale": 0.24,
    },
}

def _sabershader96_remove_nodes_and_restore(group):
    """Remove only V9.6 nodes and restore the previous Base Color source."""
    if not group:
        return False
    nodes, links = group.nodes, group.links
    final = nodes.get("SaberShader Face Principled") or nodes.get("SaberShader Face Principled Toon")
    if not final:
        return False
    base = final.inputs.get("Base Color")
    shadow2 = nodes.get(SABERSHADER96_FACE_SHADOW_PREFIX + "Chin Mix")
    shadow1 = nodes.get(SABERSHADER96_FACE_SHADOW_PREFIX + "Main Mix")
    source_socket = None
    source_value = None
    if shadow2:
        c1 = shadow2.inputs.get("Color1")
        if c1 and c1.is_linked:
            source_socket = c1.links[0].from_socket
        elif c1:
            try: source_value = tuple(c1.default_value)
            except Exception: source_value = None
    elif shadow1:
        c1 = shadow1.inputs.get("Color1")
        if c1 and c1.is_linked:
            source_socket = c1.links[0].from_socket
        elif c1:
            try: source_value = tuple(c1.default_value)
            except Exception: source_value = None
    elif base and base.is_linked:
        lk = base.links[0]
        if lk.from_node.name.startswith(SABERSHADER96_FACE_SHADOW_PREFIX):
            return False
    if base:
        for lk in list(base.links):
            if lk.from_node.name.startswith(SABERSHADER96_FACE_SHADOW_PREFIX):
                links.remove(lk)
    removed=False
    for n in list(nodes):
        if n.name.startswith(SABERSHADER96_FACE_SHADOW_PREFIX):
            nodes.remove(n); removed=True
    if removed and base:
        if source_socket is not None:
            links.new(source_socket, base)
        elif source_value is not None:
            base.default_value = source_value
    return removed

def _sabershader96_apply_face_shadow(group, profile="AVE", strength=0.55, style_override=None):
    """V10.4 designed face shadow using 2D Generated coords, not mesh normals."""
    if not group:
        return False, "grupo inexistente"
    before = _sabershader15_image_link_signature(group)
    final = group.nodes.get("SaberShader Face Principled") or group.nodes.get("SaberShader Face Principled Toon")
    if not final or final.bl_idname != 'ShaderNodeBsdfPrincipled':
        return False, "sin Principled facial V8.17/V9"
    base = final.inputs.get('Base Color')
    if not base:
        return False, "sin Base Color"
    _sabershader96_remove_nodes_and_restore(group)
    final = group.nodes.get("SaberShader Face Principled") or group.nodes.get("SaberShader Face Principled Toon")
    if not final:
        return False, "Principled facial desapareció"
    base = final.inputs.get('Base Color')
    source_socket = base.links[0].from_socket if base.is_linked else None
    source_value = None if source_socket is not None else tuple(base.default_value)
    nodes, links = group.nodes, group.links
    s = dict(SABERSHADER96_FACE_SHADOW_STYLE.get(profile, SABERSHADER96_FACE_SHADOW_STYLE['AVE']))
    if style_override:
        s = dict(style_override)
    strength = max(0.0, min(1.0, float(strength)))

    tc=nodes.new('ShaderNodeTexCoord'); tc.name=SABERSHADER96_FACE_SHADOW_PREFIX+'Generated'; tc.label='V10.4 • Face SDF coords'; tc.location=(final.location.x-980, final.location.y-160)
    sep=nodes.new('ShaderNodeSeparateXYZ'); sep.name=SABERSHADER96_FACE_SHADOW_PREFIX+'XYZ'; sep.location=(final.location.x-780, final.location.y-160)
    links.new(tc.outputs['Generated'], sep.inputs['Vector'])

    nr = nodes.new('ShaderNodeMapRange'); nr.name=SABERSHADER96_FACE_SHADOW_PREFIX+'Side Mask'; nr.label='V10.4 • Broad side shadow'; nr.location=(final.location.x-580, final.location.y-40); nr.clamp=True
    nr.inputs['From Min'].default_value=float(s.get('side_from', 0.38)); nr.inputs['From Max'].default_value=float(s.get('side_to', 0.62))
    if float(s.get('key_dir', (-0.3, -0.7, 0.5))[0]) < 0.0:
        nr.inputs['To Min'].default_value=0.0; nr.inputs['To Max'].default_value=1.0
    else:
        nr.inputs['To Min'].default_value=1.0; nr.inputs['To Max'].default_value=0.0
    links.new(sep.outputs['X'], nr.inputs['Value'])

    cr=nodes.new('ShaderNodeMapRange'); cr.name=SABERSHADER96_FACE_SHADOW_PREFIX+'Chin Mask'; cr.label='V9.6 • Chin bias'; cr.location=(final.location.x-580, final.location.y-260); cr.clamp=True
    cr.inputs['From Min'].default_value=s['chin_from']; cr.inputs['From Max'].default_value=s['chin_to']; cr.inputs['To Min'].default_value=1.0; cr.inputs['To Max'].default_value=0.0
    links.new(sep.outputs['Z'], cr.inputs['Value'])

    sm=nodes.new('ShaderNodeMath'); sm.name=SABERSHADER96_FACE_SHADOW_PREFIX+'Shadow Strength'; sm.label='V10.4 • Shadow strength'; sm.operation='MULTIPLY'; sm.location=(final.location.x-430, final.location.y-20)
    sm.inputs[1].default_value=strength
    links.new(nr.outputs['Result'], sm.inputs[0])

    mm=nodes.new('ShaderNodeMixRGB'); mm.name=SABERSHADER96_FACE_SHADOW_PREFIX+'Main Mix'; mm.label='V10.4 • Designed Face SDF Shadow'; mm.blend_type='MULTIPLY'; mm.location=(final.location.x-300, final.location.y+60)
    mm.inputs['Color2'].default_value=s['shadow']
    links.new(sm.outputs['Value'], mm.inputs['Fac'])
    if source_socket is not None: links.new(source_socket, mm.inputs['Color1'])
    else: mm.inputs['Color1'].default_value=source_value

    csm=nodes.new('ShaderNodeMath'); csm.name=SABERSHADER96_FACE_SHADOW_PREFIX+'Chin Strength'; csm.label='V9.6 • Chin strength'; csm.operation='MULTIPLY'; csm.location=(final.location.x-250, final.location.y-180)
    csm.inputs[1].default_value=max(0.0, min(1.0, strength*s.get('chin_scale', 0.28)))
    links.new(cr.outputs['Result'], csm.inputs[0])

    cm=nodes.new('ShaderNodeMixRGB'); cm.name=SABERSHADER96_FACE_SHADOW_PREFIX+'Chin Mix'; cm.label='V9.6 • Chin soft tint'; cm.blend_type='MULTIPLY'; cm.location=(final.location.x-60, final.location.y+60); cm.inputs['Color2'].default_value=s['chin']
    links.new(csm.outputs['Value'], cm.inputs['Fac']); links.new(mm.outputs['Color'], cm.inputs['Color1'])

    for lk in list(base.links): links.remove(lk)
    links.new(cm.outputs['Color'], base)

    after=_sabershader15_image_link_signature(group)
    if before!=after:
        _sabershader96_remove_nodes_and_restore(group)
        raise RuntimeError(f"V10.4 Face SDF safety check FAILED: Image Texture links changed on {group.name}")
    group['SaberShader_V9_6_FaceShadow']=True
    group['SaberShader_V9_6_Profile']=profile
    group['SaberShader_V9_6_Strength']=strength
    group['SaberShader_V10_4_FaceSDF']=True
    return True, f"2D face SDF side shadow + chin bias (strength={strength:.2f})"

def build_v96_face_shadow_system(settings):
    if not getattr(settings, 'build_face_shadow_design', True):
        return 0
    profile=getattr(settings,'shot_profile','AVE')

    strength = (0.38 if profile == 'AVE' else getattr(settings,'face_shadow_strength',0.55))
    base_style = SABERSHADER96_FACE_SHADOW_STYLE.get(profile, SABERSHADER96_FACE_SHADOW_STYLE['AVE'])
    style_override = None
    if getattr(settings, 'build_series_match_v108a', True):
        face_t = getattr(settings, 'face_series_match_strength', 0.62)
        target = SABERSHADER108A_FACE_TARGET.get(profile)
        if target:
            strength = _sabershader108a_mix_scalar(strength, target.get('effective_strength', strength), face_t)
            style_override = _sabershader108a_blend_style(base_style, target, face_t)
    count=0; prefix='SaberShader_V8_'
    for obj in bpy.context.scene.objects:
        if obj.type!='MESH': continue
        for slot in obj.material_slots:
            mat=slot.material
            if not mat or not mat.name.startswith(prefix): continue
            if mat.get('SaberShader_V8_Category')!='face': break
            gn=mat.node_tree.nodes.get('XDZR8_V8') if getattr(mat,'use_nodes',False) else None
            group=gn.node_tree if gn else None
            if group:
                try:
                    local_strength = strength
                    local_style = dict(style_override) if style_override else dict(base_style)
                    character = _sabershader108a_character_from_material(mat.name)
                    char_target, char_t = _sabershader108a1_face_character_target(profile, character, settings)
                    if char_target and char_t > 0.0:
                        local_strength = _sabershader108a_mix_scalar(local_strength, char_target.get('effective_strength', local_strength), char_t)
                        local_style = _sabershader108a_blend_style(local_style, char_target, char_t)
                    g_target, g_t = _sabershader108b_face_target(profile, settings)
                    if g_target and g_t > 0.0:
                        local_strength = _sabershader108a_mix_scalar(local_strength, g_target.get('effective_strength', local_strength), g_t)
                        local_style = _sabershader108a_blend_style(local_style, g_target, g_t)
                    b1_target, b1_t = _sabershader108b1_face_character_target(profile, character, settings)
                    if b1_target and b1_t > 0.0:
                        local_strength = _sabershader108a_mix_scalar(local_strength, b1_target.get('effective_strength', local_strength), b1_t)
                        local_style = _sabershader108a_blend_style(local_style, b1_target, b1_t)
                    c1_target, c1_t = _sabershader109c1_face_character_target(profile, character, settings)
                    if c1_target and c1_t > 0.0:
                        local_strength = _sabershader108a_mix_scalar(local_strength, c1_target.get('effective_strength', local_strength), c1_t)
                        local_style = _sabershader108a_blend_style(local_style, c1_target, c1_t)
                    ok,_=_sabershader96_apply_face_shadow(group, profile, local_strength, local_style)
                    if ok: count+=1
                except Exception as exc:
                    log(f'V9.6 Face Shadow {obj.name}: {exc}')
            break
    scene=bpy.context.scene
    scene['SaberShader_V9_6_FaceShadowCount']=count
    scene['SaberShader_V9_6_FaceShadowStrength']=float(strength)
    scene['SaberShader_V9_6_ShotProfile']=profile
    scene['SaberShader_V10_8A_FaceMatchStrength']=float(getattr(settings, 'face_series_match_strength', 0.62) if getattr(settings, 'build_series_match_v108a', True) else 0.0)
    scene['SaberShader_V10_8A1_DolorisFaceSoften']=float(getattr(settings, 'doloris_face_soften_v108a1', 0.58) if getattr(settings, 'build_character_micro_tune_v108a1', True) else 0.0)
    scene['SaberShader_V10_8B_FaceGraphicSeparation']=float(getattr(settings, 'face_graphic_separation_strength_v108b', 0.52) if getattr(settings, 'build_graphic_separation_v108b', True) else 0.0)
    scene['SaberShader_V10_8B1_DolorisFaceBalance']=float(getattr(settings, 'doloris_face_balance_v108b1', 0.50) if getattr(settings, 'build_graphic_separation_refinement_v108b1', True) else 0.0)
    scene['SaberShader_V10_9C1_DolorisFaceFinal']=float(getattr(settings, 'doloris_face_match_final_v109c1', 0.42) if getattr(settings, 'build_face_hair_series_match_final_v109c1', True) else 0.0)
    scene['SaberShader_V10_9C1_OblivionisFaceFinal']=float(getattr(settings, 'oblivionis_face_match_final_v109c1', 0.28) if getattr(settings, 'build_face_hair_series_match_final_v109c1', True) else 0.0)
    return count

SABERSHADER97_HAIR_PREFIX = "SaberShader V9.7 • Hair Toon • "

SABERSHADER97_HAIR_STYLE = {
    "MYGO": {
        "shadow": (0.76, 0.79, 0.88, 1.0),
        "mid":    (0.94, 0.95, 1.00, 1.0),
        "highlight": (1.00, 0.93, 0.92, 1.0),
        "facing0": 0.70,
        "facing1": 0.94,
        "shadow_fac": 0.24,
        "highlight_fac": 0.10,
    },
    "AVE": {
        "shadow": (0.66, 0.70, 0.84, 1.0),
        "mid":    (0.90, 0.91, 0.98, 1.0),
        "highlight": (1.00, 0.78, 0.84, 1.0),
        "facing0": 0.64,
        "facing1": 0.92,
        "shadow_fac": 0.28,
        "highlight_fac": 0.13,
    },
}

def _sabershader97_image_sig(group):
    try:
        return _sabershader15_image_link_signature(group)
    except Exception:
        return None

def _sabershader97_remove_old_chain(group):
    """Remove V9.7 and the old V9.3 ribbon, restoring the pre-ribbon Base Color source."""
    if not group:
        return False
    nodes, links = group.nodes, group.links
    final = nodes.get("Principled BSDF") or nodes.get("SaberShader Anime Toon Principled") or nodes.get("SaberShader Hair Principled")
    if not final:
        return False
    base = final.inputs.get("Base Color")
    if not base:
        return False

    source_socket = None
    source_value = None

    ribbon_add = nodes.get(SABERSHADER93_HAIR_PREFIX + 'Add')
    if ribbon_add:
        c1 = ribbon_add.inputs.get('Color1')
        if c1 and c1.is_linked:
            source_socket = c1.links[0].from_socket
        elif c1:
            try: source_value = tuple(c1.default_value)
            except Exception: source_value = None

    if source_socket is None and source_value is None and base.is_linked:
        src = base.links[0].from_socket
        if not src.node.name.startswith((SABERSHADER97_HAIR_PREFIX, SABERSHADER93_HAIR_PREFIX)):
            source_socket = src

    if source_socket is None and source_value is None and not base.is_linked:
        try: source_value = tuple(base.default_value)
        except Exception: source_value = None

    changed=False
    for n in list(nodes):
        if n.name.startswith(SABERSHADER97_HAIR_PREFIX) or n.name.startswith(SABERSHADER93_HAIR_PREFIX):
            nodes.remove(n); changed=True

    for lk in list(base.links):
        if lk.from_node.name.startswith((SABERSHADER97_HAIR_PREFIX, SABERSHADER93_HAIR_PREFIX)):
            links.remove(lk)
            changed=True

    if source_socket is not None:
        for lk in list(base.links):
            links.remove(lk)
        links.new(source_socket, base)
        changed=True
    elif source_value is not None:
        for lk in list(base.links):
            links.remove(lk)
        base.default_value=source_value
        changed=True

    return changed

def _sabershader97_apply_hair_toon(group, profile="AVE", toon_strength=0.72, highlight_strength=0.16, style_override=None):
    if not group:
        return False, "grupo inexistente"
    before = _sabershader97_image_sig(group)
    final = group.nodes.get("Principled BSDF") or group.nodes.get("SaberShader Anime Toon Principled") or group.nodes.get("SaberShader Hair Principled")
    if not final or final.bl_idname != 'ShaderNodeBsdfPrincipled':
        return False, "sin Principled de Hair"
    base = final.inputs.get('Base Color')
    if not base:
        return False, "sin Base Color"

    _sabershader97_remove_old_chain(group)
    final = group.nodes.get("Principled BSDF") or group.nodes.get("SaberShader Anime Toon Principled") or group.nodes.get("SaberShader Hair Principled")
    base = final.inputs.get('Base Color')
    source_socket = base.links[0].from_socket if base.is_linked else None
    source_value = None if source_socket is not None else tuple(base.default_value)

    nodes, links = group.nodes, group.links
    style = dict(SABERSHADER97_HAIR_STYLE.get(profile, SABERSHADER97_HAIR_STYLE['AVE']))
    if style_override:
        style = dict(style_override)
    toon_strength=max(0.0,min(1.0,float(toon_strength)))
    highlight_strength=max(0.0,min(0.5,float(highlight_strength)))

    lw=nodes.new('ShaderNodeLayerWeight'); lw.name=SABERSHADER97_HAIR_PREFIX+'Facing'; lw.label='V9.7 • Hair facing'; lw.location=(final.location.x-980,final.location.y-240)
    ramp=nodes.new('ShaderNodeValToRGB'); ramp.name=SABERSHADER97_HAIR_PREFIX+'Toon Band'; ramp.label='V9.7 • Broad hair band'; ramp.location=(final.location.x-760,final.location.y-240)
    ramp.color_ramp.interpolation='CONSTANT'
    elems=ramp.color_ramp.elements
    elems[0].position=style['facing0']; elems[0].color=style['shadow']
    elems[1].position=style['facing1']; elems[1].color=style['mid']
    links.new(lw.outputs['Facing'],ramp.inputs['Fac'])

    mult=nodes.new('ShaderNodeMixRGB'); mult.name=SABERSHADER97_HAIR_PREFIX+'Toon Mix'; mult.label='V9.7 • Hair toon mass'; mult.blend_type='MULTIPLY'; mult.location=(final.location.x-500,final.location.y-20)
    mult.inputs['Fac'].default_value=toon_strength
    if source_socket is not None: links.new(source_socket,mult.inputs['Color1'])
    else: mult.inputs['Color1'].default_value=source_value
    links.new(ramp.outputs['Color'],mult.inputs['Color2'])

    hr=nodes.new('ShaderNodeValToRGB'); hr.name=SABERSHADER97_HAIR_PREFIX+'Highlight Band'; hr.label='V9.7 • Graphic hair highlight'; hr.location=(final.location.x-760,final.location.y-430)
    hr.color_ramp.interpolation='CONSTANT'
    he=hr.color_ramp.elements
    he[0].position=style['facing1']-0.04; he[0].color=(0,0,0,1)
    he[1].position=min(0.995,style['facing1']+0.035); he[1].color=(1,1,1,1)
    links.new(lw.outputs['Facing'],hr.inputs['Fac'])
    hm=nodes.new('ShaderNodeMath'); hm.name=SABERSHADER97_HAIR_PREFIX+'Highlight Strength'; hm.label='V9.7 • Highlight strength'; hm.operation='MULTIPLY'; hm.location=(final.location.x-440, final.location.y-430)
    hm.inputs[1].default_value=highlight_strength * float(style.get('highlight_gain', (1.20 if profile=='AVE' else 1.0)))
    links.new(hr.outputs['Color'], hm.inputs[0])

    high=nodes.new('ShaderNodeMixRGB'); high.name=SABERSHADER97_HAIR_PREFIX+'Highlight Add'; high.label='V9.7 • Hair highlight'; high.blend_type='ADD'; high.location=(final.location.x-260,final.location.y-110)
    links.new(mult.outputs['Color'],high.inputs['Color1'])
    high.inputs['Color2'].default_value=style['highlight']
    links.new(hm.outputs['Value'],high.inputs['Fac'])

    for lk in list(base.links): links.remove(lk)
    links.new(high.outputs['Color'],base)

    for sock_name,val in (
        ('Roughness',float(style.get('roughness', 0.72 if profile=='MYGO' else 0.66))),
        ('Specular IOR Level',float(style.get('specular', 0.18 if profile=='MYGO' else 0.22))),
        ('Metallic',0.0),
    ):
        sock=final.inputs.get(sock_name)
        if sock and not sock.is_linked:
            sock.default_value=val
    sheen=final.inputs.get('Sheen Weight')
    if sheen and not sheen.is_linked:
        sheen.default_value=float(style.get('sheen', 0.035 if profile=='MYGO' else 0.055))
    aniso=final.inputs.get('Anisotropic')
    if aniso and not aniso.is_linked:
        aniso.default_value=0.0

    after=_sabershader97_image_sig(group)
    if before!=after:

        _sabershader97_remove_old_chain(group)
        raise RuntimeError(f"V9.7 safety check FAILED: Image Texture links changed on {group.name}")
    group['SaberShader_V9_7_HairToon']=True
    group['SaberShader_V9_7_Profile']=profile
    group['SaberShader_V9_7_ToonStrength']=toon_strength
    group['SaberShader_V9_7_HighlightStrength']=highlight_strength
    return True, f"hair toon + broad band + graphic highlight (toon={toon_strength:.2f}, hi={highlight_strength:.2f})"

def build_v97_hair_toon_system(settings):
    if not getattr(settings,'build_hair_toon_design',True):
        return 0
    profile=getattr(settings,'shot_profile','AVE')
    toon_strength=getattr(settings,'hair_toon_strength',0.72)
    highlight_strength=getattr(settings,'hair_highlight_strength',0.16)
    base_style = SABERSHADER97_HAIR_STYLE.get(profile, SABERSHADER97_HAIR_STYLE['AVE'])
    style_override = None
    if getattr(settings, 'build_series_match_v108a', True):
        hair_t = getattr(settings, 'hair_series_match_strength', 0.70)
        target = SABERSHADER108A_HAIR_TARGET.get(profile)
        if target:
            toon_strength = _sabershader108a_mix_scalar(toon_strength, target.get('toon_strength', toon_strength), hair_t)
            highlight_strength = _sabershader108a_mix_scalar(highlight_strength, target.get('highlight_strength', highlight_strength), hair_t)
            style_override = _sabershader108a_blend_style(base_style, target, hair_t)
    count=0
    prefix='SaberShader_V8_'
    for obj in bpy.context.scene.objects:
        if obj.type!='MESH':
            continue
        for slot in obj.material_slots:
            mat=slot.material
            if not mat or not mat.name.startswith(prefix):
                continue
            if mat.get('SaberShader_V8_Category')!='hair':
                break
            gn=mat.node_tree.nodes.get('XDZR8_V8') if getattr(mat,'use_nodes',False) else None
            group=gn.node_tree if gn else None
            if group:
                try:
                    local_toon = toon_strength
                    local_hi = highlight_strength
                    local_style = dict(style_override) if style_override else dict(base_style)
                    character = _sabershader108a_character_from_material(mat.name)
                    char_target, char_t = _sabershader108a1_hair_character_target(profile, character, settings)
                    if char_target and char_t > 0.0:
                        local_toon = _sabershader108a_mix_scalar(local_toon, char_target.get('toon_strength', local_toon), char_t)
                        local_hi = _sabershader108a_mix_scalar(local_hi, char_target.get('highlight_strength', local_hi), char_t)
                        local_style = _sabershader108a_blend_style(local_style, char_target, char_t)
                    g_target, g_t = _sabershader108b_hair_target(profile, settings)
                    if g_target and g_t > 0.0:
                        local_toon = _sabershader108a_mix_scalar(local_toon, g_target.get('toon_strength', local_toon), g_t)
                        local_hi = _sabershader108a_mix_scalar(local_hi, g_target.get('highlight_strength', local_hi), g_t)
                        local_style = _sabershader108a_blend_style(local_style, g_target, g_t)
                    b1_target, b1_t = _sabershader108b1_hair_character_target(profile, character, settings)
                    if b1_target and b1_t > 0.0:
                        local_toon = _sabershader108a_mix_scalar(local_toon, b1_target.get('toon_strength', local_toon), b1_t)
                        local_hi = _sabershader108a_mix_scalar(local_hi, b1_target.get('highlight_strength', local_hi), b1_t)
                        local_style = _sabershader108a_blend_style(local_style, b1_target, b1_t)
                    c1_target, c1_t = _sabershader108c1_hair_character_target(profile, character, settings)
                    if c1_target and c1_t > 0.0:
                        local_toon = _sabershader108a_mix_scalar(local_toon, c1_target.get('toon_strength', local_toon), c1_t)
                        local_hi = _sabershader108a_mix_scalar(local_hi, c1_target.get('highlight_strength', local_hi), c1_t)
                        local_style = _sabershader108a_blend_style(local_style, c1_target, c1_t)
                    final_target, final_t = _sabershader109c1_hair_character_target(profile, character, settings)
                    if final_target and final_t > 0.0:
                        local_toon = _sabershader108a_mix_scalar(local_toon, final_target.get('toon_strength', local_toon), final_t)
                        local_hi = _sabershader108a_mix_scalar(local_hi, final_target.get('highlight_strength', local_hi), final_t)
                        local_style = _sabershader108a_blend_style(local_style, final_target, final_t)
                    ok,_=_sabershader97_apply_hair_toon(group,profile,local_toon,local_hi,local_style)
                    if ok: count+=1
                except Exception as exc:
                    log(f'V9.7 Hair Toon {obj.name}: {exc}')
            break
    scene=bpy.context.scene
    scene['SaberShader_V9_7_HairToonCount']=count
    scene['SaberShader_V9_7_HairToonStrength']=float(toon_strength)
    scene['SaberShader_V9_7_HairHighlightStrength']=float(highlight_strength)
    scene['SaberShader_V9_7_ShotProfile']=profile
    scene['SaberShader_V10_8A_HairMatchStrength']=float(getattr(settings, 'hair_series_match_strength', 0.70) if getattr(settings, 'build_series_match_v108a', True) else 0.0)
    scene['SaberShader_V10_8A1_OblivionisHairRibbon']=float(getattr(settings, 'oblivionis_hair_ribbon_v108a1', 0.66) if getattr(settings, 'build_character_micro_tune_v108a1', True) else 0.0)
    scene['SaberShader_V10_8B_HairGraphicSeparation']=float(getattr(settings, 'hair_graphic_separation_strength_v108b', 0.60) if getattr(settings, 'build_graphic_separation_v108b', True) else 0.0)
    scene['SaberShader_V10_8B1_OblivionisHairBalance']=float(getattr(settings, 'oblivionis_hair_balance_v108b1', 0.58) if getattr(settings, 'build_graphic_separation_refinement_v108b1', True) else 0.0)
    scene['SaberShader_V10_8B1_ClothBlackRebalance']=float(getattr(settings, 'cloth_black_rebalance_v108b1', 0.18) if getattr(settings, 'build_graphic_separation_refinement_v108b1', True) else 0.0)
    scene['SaberShader_V10_8B1_TransparentCleanup']=float(getattr(settings, 'transparent_cleanup_v108b1', 0.22) if getattr(settings, 'build_graphic_separation_refinement_v108b1', True) else 0.0)
    scene['SaberShader_V10_8B2_TransparencyDepth']=float(getattr(settings, 'transparency_depth_v108b2', 0.20) if getattr(settings, 'build_transparency_dark_balance_v108b2', True) else 0.0)
    scene['SaberShader_V10_8B2_TransparencyChroma']=float(getattr(settings, 'transparency_chroma_preserve_v108b2', 0.18) if getattr(settings, 'build_transparency_dark_balance_v108b2', True) else 0.0)
    scene['SaberShader_V10_8B2_DarkClothDepth']=float(getattr(settings, 'dark_cloth_depth_v108b2', 0.14) if getattr(settings, 'build_transparency_dark_balance_v108b2', True) else 0.0)
    scene['SaberShader_V10_8B2_AccentProtection']=float(getattr(settings, 'accent_protection_v108b2', 0.12) if getattr(settings, 'build_transparency_dark_balance_v108b2', True) else 0.0)
    scene['SaberShader_V10_9C1_DolorisHairFinal']=float(getattr(settings, 'doloris_hair_match_final_v109c1', 0.38) if getattr(settings, 'build_face_hair_series_match_final_v109c1', True) else 0.0)
    scene['SaberShader_V10_9C1_OblivionisHairFinal']=float(getattr(settings, 'oblivionis_hair_match_final_v109c1', 0.22) if getattr(settings, 'build_face_hair_series_match_final_v109c1', True) else 0.0)
    scene['SaberShader_V10_8C_DarkMassLock']=float(getattr(settings, 'dark_mass_lock_v108c', 0.16) if getattr(settings, 'build_series_lock_v108c', True) else 0.0)
    scene['SaberShader_V10_8C_TransparencySeriesLock']=float(getattr(settings, 'transparency_series_lock_v108c', 0.18) if getattr(settings, 'build_series_lock_v108c', True) else 0.0)
    scene['SaberShader_V10_8C_InnerSkirtBalance']=float(getattr(settings, 'inner_skirt_balance_v108c', 0.16) if getattr(settings, 'build_series_lock_v108c', True) else 0.0)
    scene['SaberShader_V10_8C_TrimHold']=float(getattr(settings, 'trim_hold_v108c', 0.14) if getattr(settings, 'build_series_lock_v108c', True) else 0.0)
    scene['SaberShader_V10_8C1_DolorisClothSeparation']=float(getattr(settings, 'doloris_cloth_separation_v108c1', 0.18) if getattr(settings, 'build_final_micro_polish_v108c1', True) else 0.0)
    scene['SaberShader_V10_8C1_TransparencyRedHold']=float(getattr(settings, 'transparency_red_hold_v108c1', 0.22) if getattr(settings, 'build_final_micro_polish_v108c1', True) else 0.0)
    scene['SaberShader_V10_8C1_OblivionisSkirtContain']=float(getattr(settings, 'oblivionis_skirt_contain_v108c1', 0.24) if getattr(settings, 'build_final_micro_polish_v108c1', True) else 0.0)
    scene['SaberShader_V10_8C1_OblivionisCorsetCompact']=float(getattr(settings, 'oblivionis_corset_compact_v108c1', 0.16) if getattr(settings, 'build_final_micro_polish_v108c1', True) else 0.0)
