def _sabershader95_set_lineart_enabled(char_name, enabled):
    """Toggle the existing V9 Grease Pencil receiver without altering source
    meshes, Image Texture nodes, UVs or XDZR8 material routes."""
    gp = bpy.data.objects.get(f"SaberShader V9 • LineArt • {char_name}")
    if not gp or gp.type != 'GREASEPENCIL':
        return False
    gp.hide_viewport = not bool(enabled)
    gp.hide_render = not bool(enabled)
    gp['SaberShader_V9_5_CalibrationLineArtEnabled'] = bool(enabled)
    return True

def build_v95_calibration_system(settings):
    """V9.5 deterministic A/B visual calibration.

    The base XDZR8 material rebuild is unchanged. This mode only decides which
    optional artistic layers are evaluated, so their visual contribution can
    be compared without changing texture routes or UVs.
    """
    if not settings.calibration_mode:
        return None

    face = hair = shadow = lines = tertiary = 0

    if settings.calibration_face:

        if settings.build_face_corrections:
            face += build_v91_face_corrections('Doloris')
            face += build_v91_face_corrections('Oblivionis')
        face += build_v92_face_angle('Doloris', settings)
        face += build_v92_face_angle('Oblivionis', settings)
        face += build_v94_face_performance('Doloris', settings)
        face += build_v94_face_performance('Oblivionis', settings)
        face += build_v94_expression_corrections('Doloris', settings)
        face += build_v94_expression_corrections('Oblivionis', settings)

    if settings.calibration_hair:
        hair += build_v93_hair_ribbon('Doloris', settings.shot_profile)
        hair += build_v93_hair_ribbon('Oblivionis', settings.shot_profile)

    if settings.calibration_shadow:
        shadow += build_v92_artistic_lighting('Doloris', settings.shot_profile)
        shadow += build_v92_artistic_lighting('Oblivionis', settings.shot_profile)

    if settings.calibration_lines and not _sabershader105a1_lineart_is_quarantined():
        lines += build_v92_line_hierarchy('Doloris')
        lines += build_v92_line_hierarchy('Oblivionis')
        lines += build_v94_smart_line_art('Doloris', settings)
        lines += build_v94_smart_line_art('Oblivionis', settings)
        _sabershader95_set_lineart_enabled('Doloris', True)
        _sabershader95_set_lineart_enabled('Oblivionis', True)
    else:

        _sabershader95_set_lineart_enabled('Doloris', False)
        _sabershader95_set_lineart_enabled('Oblivionis', False)

    if settings.calibration_tertiary:
        tertiary += build_v93_tertiary_artist('Doloris', settings)
        tertiary += build_v93_tertiary_artist('Oblivionis', settings)

    scene = bpy.context.scene
    scene['SaberShader_V9_5_CalibrationMode'] = True
    scene['SaberShader_V9_5_CalibrationFace'] = bool(settings.calibration_face)
    scene['SaberShader_V9_5_CalibrationHair'] = bool(settings.calibration_hair)
    scene['SaberShader_V9_5_CalibrationShadows'] = bool(settings.calibration_shadow)
    scene['SaberShader_V9_5_CalibrationLines'] = bool(settings.calibration_lines)
    scene['SaberShader_V9_5_CalibrationTertiary'] = bool(settings.calibration_tertiary)
    return {'face': face, 'hair': hair, 'shadow': shadow, 'lines': lines, 'tertiary': tertiary}

SABERSHADER10_PREFIX = "SaberShader V10 • Shot Composer • "
SABERSHADER10_STYLE = {
    "MYGO": {
        "contrast": 0.025,
        "saturation": 0.985,
        "bloom": 0.060,
        "threshold": 1.30,
        "vignette": 0.055,
        "depth": 0.035,
    },
    "AVE": {
        "contrast": 0.065,
        "saturation": 0.970,
        "bloom": 0.095,
        "threshold": 1.18,
        "vignette": 0.085,
        "depth": 0.050,
    },
    "UNIVERSAL": {
        "contrast": 0.040,
        "saturation": 0.980,
        "bloom": 0.080,
        "threshold": 1.25,
        "vignette": 0.060,
        "depth": 0.040,
    },
}

def _sabershader10_tree(scene):
    tree = getattr(scene, 'compositing_node_group', None)
    if tree is None:
        tree = bpy.data.node_groups.new(
            name=f"SaberShader V10 • Compositor • {scene.name}",
            type='CompositorNodeTree'
        )
        scene.compositing_node_group = tree
    return tree

def _sabershader10_remove_generated_nodes(tree):
    for node in list(tree.nodes):
        if node.name.startswith(SABERSHADER10_PREFIX):
            tree.nodes.remove(node)

def _sabershader10_socket(node, name):
    return node.inputs.get(name) if node else None

def _sabershader10_set(node, name, value):
    sock = _sabershader10_socket(node, name)
    if sock is None:
        return False
    try:
        sock.default_value = value
        return True
    except (TypeError, ValueError):
        return False

def _sabershader10_find_v91_glare(tree):
    return tree.nodes.get("SaberShader V9.1 • Shoot • Selective Bloom")

def _sabershader10_find_v91_output(tree):

    return (tree.nodes.get("SaberShader V9.1 • Shoot • Group Output")
            or tree.nodes.get(SABERSHADER10_PREFIX + 'Group Output')
            or tree.nodes.get("Group Output"))

def _sabershader10_build_vignette(tree, image_socket, final_node, strength):

    ellipse = tree.nodes.new('CompositorNodeEllipseMask')
    ellipse.name = SABERSHADER10_PREFIX + 'Vignette Mask'
    ellipse.label = 'V10 • Soft vignette mask'
    ellipse.location = (final_node.location.x - 250, final_node.location.y - 430)
    _sabershader10_set(ellipse, 'Width', 0.92)
    _sabershader10_set(ellipse, 'Height', 0.86)

    blur = tree.nodes.new('CompositorNodeBlur')
    blur.name = SABERSHADER10_PREFIX + 'Vignette Blur'
    blur.label = 'V10 • Vignette feather'
    blur.location = (ellipse.location.x + 180, ellipse.location.y)
    _sabershader10_set(blur, 'Size X', 18)
    _sabershader10_set(blur, 'Size Y', 18)

    mix = tree.nodes.new('ShaderNodeMixRGB')
    mix.name = SABERSHADER10_PREFIX + 'Vignette Mix'
    mix.label = 'V10 • Final vignette'
    mix.blend_type = 'MULTIPLY'
    mix.location = (final_node.location.x + 220, final_node.location.y - 120)

    amount = max(0.0, min(0.5, float(strength)))
    mix.inputs['Color2'].default_value = (1.0 - amount, 1.0 - amount, 1.0 - amount, 1.0)

    links = tree.links
    links.new(ellipse.outputs.get('Mask'), blur.inputs.get('Image'))
    links.new(image_socket, mix.inputs.get('Color1'))
    links.new(blur.outputs.get('Image'), mix.inputs.get('Fac'))
    return mix

def build_v10_shot_composer(settings):
    if not getattr(settings, 'build_shot_composer', True):
        return 0

    scene = bpy.context.scene
    tree = _sabershader10_tree(scene)
    nodes, links = tree.nodes, tree.links
    profile = getattr(settings, 'shot_profile', 'AVE')
    style = SABERSHADER10_STYLE.get(profile, SABERSHADER10_STYLE['AVE'])
    _sabershader10_remove_generated_nodes(tree)

    source_node = _sabershader10_find_v91_glare(tree)
    if source_node is None:
        source_node = nodes.get('Render Layers')
    if source_node is None:
        source_node = nodes.new(type='CompositorNodeRLayers')
        source_node.name = 'Render Layers'
        source_node.scene = scene

    source_socket = source_node.outputs.get('Image')
    if source_socket is None:
        return 0

    exposure = nodes.new('CompositorNodeExposure')
    exposure.name = SABERSHADER10_PREFIX + 'Exposure'
    exposure.label = f'V10 • Exposure ({profile})'
    exposure.location = (0, 0)
    _sabershader10_set(exposure, 'Exposure', float(settings.final_exposure))

    contrast = nodes.new('CompositorNodeBrightContrast')
    contrast.name = SABERSHADER10_PREFIX + 'Contrast'
    contrast.label = 'V10 • Graphic contrast'
    contrast.location = (220, 0)
    _sabershader10_set(contrast, 'Bright', 0.0)
    _sabershader10_set(contrast, 'Contrast', float(settings.final_contrast if settings.final_contrast is not None else style['contrast']))

    hue = nodes.new('CompositorNodeHueSat')
    hue.name = SABERSHADER10_PREFIX + 'Saturation'
    hue.label = 'V10 • Saturation'
    hue.location = (440, 0)
    _sabershader10_set(hue, 'Hue', 0.5)
    _sabershader10_set(hue, 'Saturation', float(settings.final_saturation if settings.final_saturation is not None else style['saturation']))
    _sabershader10_set(hue, 'Value', 1.0)

    final_glare = nodes.new('CompositorNodeGlare')
    final_glare.name = SABERSHADER10_PREFIX + 'Final Glow'
    final_glare.label = 'V10 • Selective Glow'
    final_glare.location = (660, 0)
    _sabershader10_set(final_glare, 'Type', 'Fog Glow')
    _sabershader10_set(final_glare, 'Quality', 'High')
    _sabershader10_set(final_glare, 'Threshold', float(settings.final_bloom_threshold if settings.final_bloom_threshold is not None else style['threshold']))
    _sabershader10_set(final_glare, 'Size', 0.65)
    _sabershader10_set(final_glare, 'Strength', float(settings.final_bloom_strength if settings.final_bloom_strength is not None else style['bloom']))

    previous_socket = final_glare.outputs.get('Image')
    depth_mix = None
    if bool(getattr(settings, 'final_depth_grade', False)):
        rl = nodes.get('Render Layers')
        if rl is None:
            rl = nodes.new(type='CompositorNodeRLayers')
            rl.name = 'Render Layers'
            rl.scene = scene
        z = rl.outputs.get('Depth') or rl.outputs.get('Z')
        if z is not None:
            depth = nodes.new('CompositorNodeMapRange')
            depth.name = SABERSHADER10_PREFIX + 'Depth Mask'
            depth.label = 'V10 • Depth grade mask'
            depth.location = (650, -240)
            _sabershader10_set(depth, 'From Min', 2.0)
            _sabershader10_set(depth, 'From Max', 25.0)
            _sabershader10_set(depth, 'To Min', 0.0)
            _sabershader10_set(depth, 'To Max', 1.0)
            _sabershader10_set(depth, 'Clamp', True)
            links.new(z, depth.inputs.get('Value'))

            depth_strength = max(0.0, min(0.5, float(settings.final_depth_strength)))
            depth_weight = nodes.new('ShaderNodeMath')
            depth_weight.name = SABERSHADER10_PREFIX + 'Depth Strength'
            depth_weight.label = 'V10 • Depth strength'
            depth_weight.operation = 'MULTIPLY'
            depth_weight.location = (820, -300)
            _sabershader10_set(depth_weight, 'Value', depth_strength)
            links.new(depth.outputs.get('Value'), depth_weight.inputs.get('Value'))

            depth_mix = nodes.new('ShaderNodeMixRGB')
            depth_mix.name = SABERSHADER10_PREFIX + 'Depth Grade'
            depth_mix.label = 'V10 • Subtle depth tint'
            depth_mix.blend_type = 'MIX'
            depth_mix.location = (1040, -120)
            depth_mix.inputs['Color2'].default_value = (0.72, 0.77, 0.90, 1.0)
            links.new(previous_socket, depth_mix.inputs['Color1'])
            links.new(depth_weight.outputs.get('Value'), depth_mix.inputs['Fac'])
            previous_socket = depth_mix.outputs.get('Color')

    vignette = _sabershader10_build_vignette(tree, previous_socket, final_glare, float(settings.final_vignette))
    previous_socket = vignette.outputs.get('Color')

    group_out = _sabershader10_find_v91_output(tree)
    if group_out is None:
        group_out = nodes.new(type='NodeGroupOutput')
        group_out.name = SABERSHADER10_PREFIX + 'Group Output'
        group_out.location = (1280, 0)

    out_socket = group_out.inputs.get('Image')
    if out_socket is None:
        return 0

    for lk in list(out_socket.links):
        links.remove(lk)

    for node in (exposure, contrast, hue, final_glare, group_out):
        for lk in list(links):
            if lk.to_node == node:
                links.remove(lk)

    links.new(source_socket, exposure.inputs.get('Image'))
    links.new(exposure.outputs.get('Image'), contrast.inputs.get('Image'))
    links.new(contrast.outputs.get('Image'), hue.inputs.get('Image'))
    links.new(hue.outputs.get('Image'), final_glare.inputs.get('Image'))
    if depth_mix is not None:

        pass
    links.new(previous_socket, out_socket)

    scene['SaberShader_V10_ShotComposer'] = True
    scene['SaberShader_V10_Profile'] = profile
    scene['SaberShader_V10_Exposure'] = float(settings.final_exposure)
    scene['SaberShader_V10_Contrast'] = float(settings.final_contrast)
    scene['SaberShader_V10_Saturation'] = float(settings.final_saturation)
    scene['SaberShader_V10_BloomStrength'] = float(settings.final_bloom_strength)
    scene['SaberShader_V10_BloomThreshold'] = float(settings.final_bloom_threshold)
    scene['SaberShader_V10_DepthGrade'] = bool(settings.final_depth_grade)
    scene['SaberShader_V10_DepthStrength'] = float(settings.final_depth_strength)
    scene['SaberShader_V10_Vignette'] = float(settings.final_vignette)
    scene['SaberShader_V10_Workflow'] = 'Character + Line Art + Tertiary + Depth + Color Grade + Selective Glow + Final'

    scene.render.use_compositing = True
    return 1

