def _sabershader109_scene_collection(scene):
    col = bpy.data.collections.get(SABERSHADER109_COLLECTION)
    if col is None:
        col = bpy.data.collections.new(SABERSHADER109_COLLECTION)
    if not any(c == col for c in scene.collection.children):
        scene.collection.children.link(col)
    return col

def _sabershader109_link_object(col, obj):
    if obj is not None and col not in obj.users_collection:
        col.objects.link(obj)

def _sabershader109_quarantine_legacy_rigs():
    disabled = 0
    for obj in bpy.data.objects:
        if obj.type == 'LIGHT' and any(obj.name.startswith(prefix) for prefix in SABERSHADER109_LEGACY_PREFIXES):
            try: obj.data.energy = 0.0
            except Exception: pass
            try: obj.hide_render = True
            except Exception: pass
            disabled += 1
    return disabled

def _sabershader109_active_camera(scene):
    cam = getattr(scene, 'camera', None)
    if cam and cam.type == 'CAMERA': return cam
    for obj in scene.objects:
        if obj.type == 'CAMERA': return obj
    return None

def _sabershader109_bounds_center(obj):
    try:
        if obj.type == 'MESH' and getattr(obj, 'bound_box', None):
            pts = [obj.matrix_world @ Vector(corner) for corner in obj.bound_box]
            if pts:
                acc = Vector((0.0, 0.0, 0.0))
                for p in pts: acc += p
                return acc / float(len(pts))
    except Exception: pass
    try: return obj.matrix_world.translation.copy()
    except Exception: return Vector((0.0, 0.0, 0.0))

def _sabershader109_focus_objects_for_character(scene, token):
    out, seen = [], set()
    for obj in scene.objects:
        if obj.type not in {'MESH','ARMATURE','EMPTY','CURVE','SURFACE'}: continue
        key = norm(obj.name)
        good = token in key
        if not good and obj.type == 'MESH':
            for slot in getattr(obj, 'material_slots', []):
                mat = getattr(slot, 'material', None)
                n = getattr(mat, 'name', '') if mat else ''
                if token == 'doloris' and n.startswith('SaberShader_V8_Doloris_'): good = True; break
                if token == 'oblivionis' and n.startswith('SaberShader_V8_Oblivionis_'): good = True; break
        if good and obj.name not in seen:
            seen.add(obj.name); out.append(obj)
    return out

def _sabershader109_render_receivers(objects):
    return [obj for obj in objects if obj.type in {'MESH','CURVE','SURFACE','FONT','META'}]

def _sabershader109_focus_objects(scene):
    out, seen = [], set()
    for token in ('doloris','oblivionis'):
        for obj in _sabershader109_focus_objects_for_character(scene, token):
            if obj.name not in seen: seen.add(obj.name); out.append(obj)
    return out

def _sabershader109_center_from_objects(objs, fallback=None):
    if not objs: return fallback.copy() if fallback is not None else Vector((0,0,0))
    acc = Vector((0.0,0.0,0.0))
    for obj in objs: acc += _sabershader109_bounds_center(obj)
    return acc / float(len(objs))

def _sabershader109_focus_center(scene):
    objs = _sabershader109_focus_objects(scene)
    return _sabershader109_center_from_objects(objs, fallback=scene.cursor.location)

def _sabershader109_get_or_create_focus(col, label='Focus Target'):
    name = SABERSHADER109_PREFIX + label
    obj = bpy.data.objects.get(name)
    if obj is None or obj.type != 'EMPTY':
        obj = bpy.data.objects.new(name, None); obj.empty_display_type='PLAIN_AXES'; obj.empty_display_size=0.18
    _sabershader109_link_object(col, obj); obj.hide_render=True
    return obj

def _sabershader109_get_or_create_area_light(col, short_name):
    name = SABERSHADER109_PREFIX + short_name
    obj = bpy.data.objects.get(name)
    if obj is None or obj.type != 'LIGHT':
        data = bpy.data.lights.new(name=name, type='AREA'); obj = bpy.data.objects.new(name, data)
    _sabershader109_link_object(col, obj)
    try: obj.hide_render=False
    except Exception: pass
    return obj

def _sabershader109_ensure_track_to(obj, target):
    if obj is None or target is None: return
    con = next((c for c in obj.constraints if c.type=='TRACK_TO' and c.name==(SABERSHADER109_PREFIX+'Track To Focus')), None)
    if con is None:
        con = obj.constraints.new('TRACK_TO'); con.name = SABERSHADER109_PREFIX+'Track To Focus'
    con.target=target; con.track_axis='TRACK_NEGATIVE_Z'; con.up_axis='UP_Y'

def _sabershader109_apply_area_settings(light_obj, energy, size_xy, color, softness, diffuse_factor=1.0, specular_factor=1.0, use_shadow=True):
    if light_obj is None or light_obj.type != 'LIGHT': return
    data = light_obj.data; data.type='AREA'
    try: data.shape='RECTANGLE'
    except Exception: pass
    try: data.energy=max(0.0,float(energy))
    except Exception: pass
    try: data.color=tuple(float(c) for c in color[:3])
    except Exception: pass
    try:
        if hasattr(data,'diffuse_factor'): data.diffuse_factor=max(0.0,float(diffuse_factor))
        if hasattr(data,'specular_factor'): data.specular_factor=max(0.0,float(specular_factor))
    except Exception: pass
    sx=float(size_xy[0])*(0.70+0.60*float(softness)); sy=float(size_xy[1])*(0.70+0.60*float(softness))
    if hasattr(data,'size'): data.size=sx
    if hasattr(data,'size_y'): data.size_y=sy
    if hasattr(data,'spread'):
        try: data.spread=math.radians(150.0+20.0*float(softness))
        except Exception: pass
    try: data.use_shadow=bool(use_shadow)
    except Exception: pass

def _sabershader109_set_world_lift(scene, lift):
    world=scene.world
    if world is None: world=bpy.data.worlds.new('World'); scene.world=world
    world.use_nodes=True; nt=world.node_tree
    if nt is None: return
    bg=nt.nodes.get('Background') or nt.nodes.new('ShaderNodeBackground')
    color=max(0.0,min(0.10,float(lift)))
    try: bg.inputs['Color'].default_value=(color,color,color*1.05,1.0)
    except Exception: pass
    try: bg.inputs['Strength'].default_value=1.0
    except Exception: pass

def _sabershader109_clear_collection_objects(coll):
    if coll is None: return
    for obj in list(coll.objects):
        try: coll.objects.unlink(obj)
        except Exception: pass

def _sabershader109_assign_light_linking(light_obj, objects, label):
    receivers=_sabershader109_render_receivers(objects)
    if not receivers: return False
    try:
        ll=getattr(light_obj,'light_linking',None)
        receiver=getattr(ll,'receiver_collection',None) if ll else None
        if receiver is None and hasattr(bpy.ops.object,'light_linking_receiver_collection_new'):
            try:
                with bpy.context.temp_override(active_object=light_obj, object=light_obj, selected_editable_objects=[light_obj]):
                    bpy.ops.object.light_linking_receiver_collection_new()
                ll=getattr(light_obj,'light_linking',None); receiver=getattr(ll,'receiver_collection',None) if ll else None
            except Exception: receiver=None
        if receiver is None: return False
        try: receiver.name=SABERSHADER109_PREFIX+label+' Receivers'
        except Exception: pass
        _sabershader109_clear_collection_objects(receiver)
        for obj in receivers:
            try: receiver.objects.link(obj)
            except Exception: pass
        return True
    except Exception as exc:
        log(f'V10.9A4 Light Linking fallback for {light_obj.name}: {exc}')
        return False

def _sabershader109_soft_auto_tune_compositor(settings):
    if not getattr(settings,'auto_tune_shot_composer_v109a',True): return False
    profile=getattr(settings,'shot_profile','AVE')
    if profile=='AVE':

        settings.final_exposure=min(float(getattr(settings,'final_exposure',0.0)),0.008)
        settings.final_contrast=max(float(getattr(settings,'final_contrast',0.0)),0.05)
        settings.final_saturation=min(float(getattr(settings,'final_saturation',0.98)),0.97)
        settings.final_bloom_strength=min(float(getattr(settings,'final_bloom_strength',0.08)),0.065)
        settings.final_bloom_threshold=max(float(getattr(settings,'final_bloom_threshold',1.25)),1.27)
        settings.final_vignette=max(float(getattr(settings,'final_vignette',0.08)),0.09)
    return True

def build_v109a_shot_lighting(settings):
    if not getattr(settings,'build_shot_lighting_v109a',True): return 0
    scene=bpy.context.scene; cam=_sabershader109_active_camera(scene)
    if cam is None:
        log('V10.9A4 Final Lighting Cleanup: no active camera found; skipped'); scene['SaberShader_V10_9A4_ShotLighting']=False; return 0
    legacy_disabled=_sabershader109_quarantine_legacy_rigs()
