    focus.location=center; df.location=dc; of.location=oc
    q=cam.matrix_world.to_quaternion(); forward=(q@Vector((0,0,-1))).normalized(); right=(q@Vector((1,0,0))).normalized(); up=(q@Vector((0,1,0))).normalized()
    dist=max(2.5,min(18.0,(center-cam.matrix_world.translation).length or 6.0)); char_dist=max(1.6,min(8.0,dist*0.58))
    def place(a,d,s,h,b): return a-forward*(b*d)+right*(b*s)+up*(b*h)
    key=_sabershader109_get_or_create_area_light(col,'Key'); fill=_sabershader109_get_or_create_area_light(col,'Fill'); rim=_sabershader109_get_or_create_area_light(col,'Rim')
    key.location=place(center,style['key_depth'],style['key_side'],style['key_up'],dist); fill.location=place(center,style['fill_depth'],style['fill_side'],style['fill_up'],dist); rim.location=place(center,style['rim_depth'],style['rim_side'],style['rim_up'],dist)
