    osd=_sabershader109_get_or_create_area_light(col,'Oblivionis Side'); osd.location=place(oc,-0.03,0.31,0.20,char_dist); _sabershader109_apply_area_settings(osd,ke*float(getattr(settings,'oblivionis_side_ratio_v109a3',0.035)),(2.45,2.05),(0.85,0.90,1.0),max(0.0,softness-0.01),diffuse_factor=0.80,specular_factor=0.38,use_shadow=False)
    for obj,target in ((key,focus),(fill,focus),(rim,focus),(d,df),(orc,of),(osd,of)): _sabershader109_ensure_track_to(obj,target)
