        msg += f" | V9.2 art={v91['v92']['art']} line={v91['v92']['lines']} face={v91['v92']['face']} | V9.3 tertiary={v91['v93']['tertiary']} hair={v91['v93']['hair']} | V9.5 perf={v91['v94']['performance']} expr={v91['v94']['expressions']} deform={v91['v94']['deformation']} tertiary={v91['v94']['tertiary']} line={v91['v94']['lines']}"
